INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('11', '1raj', '1 Raja-Raja', 1, 1, 'Raja Daud telah tua dan lanjut umurnya, dan biarpun ia diselimuti, badannya tetap dingin.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 2, 'Lalu para pegawainya berkata kepadanya: "Hendaklah dicari bagi tuanku raja seorang perawan yang muda, untuk melayani dan merawat raja; biarlah ia berbaring di pangkuanmu, sehingga badan tuanku raja menjadi panas."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 3, 'Maka di seluruh daerah Israel dicarilah seorang gadis yang cantik, dan didapatlah Abisag, gadis Sunem, lalu dibawa kepada raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 4, 'Gadis itu amat cantik, dan ia menjadi perawat raja dan melayani dia, tetapi raja tidak bersetubuh dengan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 5, 'Lalu Adonia, anak Hagit, meninggikan diri dengan berkata: "Aku ini mau menjadi raja." Ia melengkapi dirinya dengan kereta-kereta dan orang-orang berkuda serta lima puluh orang yang berlari di depannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 6, 'Selama hidup Adonia ayahnya belum pernah menegor dia dengan ucapan: "Mengapa engkau berbuat begitu?" Iapun sangat elok perawakannya dan dia adalah anak pertama sesudah Absalom.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 7, 'Maka berundinglah ia dengan Yoab, anak Zeruya dan dengan imam Abyatar dan mereka menjadi pengikut dan pembantu Adonia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 8, 'Tetapi imam Zadok dan Benaya bin Yoyada dan nabi Natan dan Simei dan Rei dan para pahlawan Daud tidak memihak kepada Adonia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 9, 'Sesudah itu Adonia mempersembahkan domba, lembu dan ternak gemukan sebagai korban dekat batu Zohelet yang ada di samping En-Rogel, lalu mengundang semua saudaranya, anak-anak raja, dan semua orang Yehuda, pegawai-pegawai raja;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 10, 'tetapi nabi Natan dan Benaya dan para pahlawan dan Salomo, adiknya, tidak diundangnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 11, 'Lalu berkatalah Natan kepada Batsyeba, ibu Salomo: "Tidakkah engkau mendengar, bahwa Adonia anak Hagit, telah menjadi raja, sedang tuan kita Daud tidak mengetahuinya?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 12, 'Karena itu, baiklah kuberi nasihat kepadamu, supaya engkau dapat menyelamatkan yawamu dan nyawa anakmu Salomo.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 13, 'Pergilah masuk menghadap raja Daud dan katakan kepadanya: Bukankah tuanku sendiri, ya rajaku, telah bersumpah kepada hambamu ini: Anakmu Salomo, akan menjadi raja sesudah aku dan dialah yang akan duduk di atas takhtaku? Mengapakah sekarang Adonia menjadi raja?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 14, 'Dan selagi engkau berbicara di sana dengan raja, akupun akan masuk pula dan menyokong perkataanmu itu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 15, 'Jadi masuklah Batsyeba menghadap raja ke dalam kamarnya. Waktu itu raja sudah sangat tua dan Abisag, gadis Sunem itu, melayani raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 16, 'Lalu Batsyeba berlutut dan sujud menyembah kepada raja. Raja bertanya: "Ada yang kauingini?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 17, 'Lalu perempuan itu berkata kepadanya: "Tuanku sendiri telah bersumpah demi TUHAN, Allahmu, kepada hambamu ini: Anakmu Salomo akan menjadi raja sesudah aku, dan ia akan duduk di atas takhtaku.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 18, 'Tetapi sekarang, lihatlah, Adonia telah menjadi raja, sedang tuanku raja sendiri tidak mengetahuinya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 19, 'Ia telah menyembelih banyak lembu, ternak gemukan dan domba, dan telah mengundang semua anak raja dan imam Abyatar dan Yoab, panglima itu, tetapi hambamu Salomo tidak diundangnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 20, 'Dan kepadamulah, ya tuanku raja, tertuju mata seluruh orang Israel, supaya engkau memberitahukan kepada mereka siapa yang akan duduk di atas takhta tuanku raja sesudah tuanku.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 21, 'Nanti aku ini dan anakku Salomo dituduh bersalah segera sesudah tuanku raja mendapat perhentian bersama-sama dengan nenek moyangnya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 22, 'Selagi Batsyeba berbicara dengan raja, datanglah nabi Natan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 23, 'Diberitahukan kepada raja: "Itu ada nabi Natan." Masuklah ia menghadap raja, lalu sujud menyembah kepada raja dengan mukanya sampai ke tanah.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 24, 'Natan berkata: "Ya tuanku raja, tuanku sendirilah rupa-rupanya yang telah berkata: Adonia akan menjadi raja sesudah aku dan ia akan duduk di atas takhtaku!', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 25, 'Sebab pada hari ini ia telah menyembelih banyak lembu, ternak gemukan dan domba; ia mengundang semua anak raja, para panglima dan imam Abyatar, dan sesungguhnya mereka sedang makan minum di depannya sambil berseru: Hidup raja Adonia!', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 26, 'Tetapi hambamu ini, dan imam Zadok dan Benaya bin Yoyada dan hambamu Salomo tidak diundangnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 27, 'Jika hal ini terjadi dari pihak tuanku raja, maka engkau tidak memberitahu hamba-hambamu ini, siapa yang akan duduk di atas takhta tuanku raja sesudah tuanku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 28, 'Lalu raja Daud menjawab, katanya: "Panggillah Batsyeba." Perempuan itu masuk menghadap raja dan berdiri di depannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 29, 'Lalu raja bersumpah dan berkata: "Demi TUHAN yang hidup, yang telah membebaskan nyawaku dari segala kesesakan,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 30, 'pada hari ini aku akan melaksanakan apa yang kujanjikan kepadamu demi TUHAN, Allah Israel, dengan sumpah ini: Anakmu Salomo akan menjadi raja sesudah aku, dan dialah yang akan duduk di atas takhtaku menggantikan aku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 31, 'Lalu Batsyeba berlutut dengan mukanya sampai ke tanah; ia sujud menyembah kepada raja dan berkata: "Hidup tuanku raja Daud untuk selama-lamanya!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 32, 'Lagi kata raja Daud: "Panggillah imam Zadok, nabi Natan dan Benaya bin Yoyada." Mereka masuk menghadap raja,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 33, 'dan raja berkata kepada mereka: "Bawalah para pegawai tuanmu ini, naikkan anakku Salomo ke atas bagal betina kendaraanku sendiri, dan bawa dia ke Gihon.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 34, 'Imam Zadok dan nabi Natan harus mengurapi dia di sana menjadi raja atas Israel; kemudian kamu meniup sangkakala dan berseru: Hidup raja Salomo!', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 35, 'Sesudah itu kamu berjalan pulang dengan mengiring dia; lalu ia akan masuk dan duduk di atas takhtaku, sebab dialah yang harus naik takhta menggantikan aku, dan dialah yang kutunjuk menjadi raja atas Israel dan Yehuda."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 36, 'Lalu Benaya bin Yoyada menjawab raja: "Amin! Demikianlah kiranya firman TUHAN, Allah tuanku raja!', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 37, 'Seperti TUHAN menyertai tuanku raja, demikianlah kiranya Ia menyertai Salomo; semoga Ia membuat takhta Salomo lebih agung dari takhta tuanku raja Daud."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 38, 'Lalu pergilah imam Zadok, nabi Natan dan Benaya bin Yoyada, dengan orang Kreti dan orang Pleti, mereka menaikkan Salomo ke atas bagal betina raja Daud dan membawanya ke Gihon.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 39, 'Imam Zadok telah membawa tabung tanduk berisi minyak dari dalam kemah, lalu diurapinya Salomo. Kemudian sangkakala ditiup, dan seluruh rakyat berseru: "Hidup raja Salomo!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 40, 'Sesudah itu seluruh rakyat berjalan di belakangnya sambil membunyikan suling dan sambil bersukaria ramai-ramai, sampai seakan-akan bumi terbelah oleh suara mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 41, 'Hal itu kedengaran kepada Adonia dan kepada semua undangan yang bersama-sama dengan dia, ketika mereka baru habis makan. Ketika Yoab mendengar bunyi sangkakala itu, ia berkata: "Apakah sebabnya kota begitu ribut?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 42, 'Selagi ia berbicara, datanglah Yonatan anak imam Abyatar. Lalu Adonia berkata: "Masuklah, sebab engkau seorang kesatria dan tentulah engkau membawa kabar baik."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 43, 'Tetapi Yonatan menjawab Adonia: "Tidak! Tuan kita raja Daud telah mengangkat Salomo menjadi raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 44, 'Raja telah menyuruh supaya imam Zadok, dan nabi Natan dan Benaya bin Yoyada, dengan orang Kreti dan orang Pleti, menyertai Salomo dan mereka menaikkan dia ke atas bagal betina raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 45, 'Imam Zadok, dan nabi Natan mengurapi dia di Gihon menjadi raja, dan dari sana mereka sudah pulang dengan bersukaria, sehingga kota menjadi ribut, itulah bunyi yang kamu dengar tadi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 46, 'Salomo sekarang duduk di atas takhta kerajaan;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 47, 'juga pegawai-pegawai raja telah datang mengucap selamat kepada tuan kita raja Daud, dengan berkata: Kiranya Allahmu membuat nama Salomo lebih masyhur dari pada namamu dan takhtanya lebih agung dari pada takhtamu. Dan rajapun telah sujud menyembah di atas tempat tidurnya,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 48, 'dan beginilah katanya: Terpujilah TUHAN, Allah Israel, yang pada hari ini telah memberi seorang duduk di atas takhtaku yang aku sendiri masih boleh saksikan."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 49, 'Maka semua undangan Adonia itu terkejut, lalu bangkit dan masing-masing pergi menurut jalannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 50, 'Takutlah Adonia kepada Salomo, sebab itu ia segera pergi memegang tanduk-tanduk mezbah.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 51, 'Lalu diberitahukanlah kepada Salomo: "Ternyata Adonia takut kepada raja Salomo, dan ia telah memegang tanduk-tanduk mezbah, serta berkata: Biarlah raja Salomo lebih dahulu bersumpah mengenai aku, bahwa ia takkan membunuh hambanya ini dengan pedang."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 52, 'Lalu kata Salomo: "Jika ia berlaku sebagai kesatria, maka sehelai rambutpun dari kepalanya tidak akan jatuh ke bumi, tetapi jika ternyata ia bermaksud jahat, haruslah ia dibunuh."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 1, 53, 'Dan raja Salomo menyuruh orang menjemput dia dari mezbah itu. Ketika ia masuk, sujudlah ia menyembah kepada raja Salomo, lalu Salomo berkata kepadanya: "Pergilah ke rumahmu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 1, 'Ketika saat kematian Daud mendekat, ia berpesan kepada Salomo, anaknya:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 2, '"Aku ini akan menempuh jalan segala yang fana, maka kuatkanlah hatimu dan berlakulah seperti laki-laki.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 3, 'Lakukanlah kewajibanmu dengan setia terhadap TUHAN, Allahmu, dengan hidup menurut jalan yang ditunjukkan-Nya, dan dengan tetap mengikuti segala ketetapan, perintah, peraturan dan ketentuan-Nya, seperti yang tertulis dalam hukum Musa, supaya engkau beruntung dalam segala yang kaulakukan dan dalam segala yang kautuju,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 4, 'dan supaya TUHAN menepati janji yang diucapkan-Nya tentang aku, yakni: Jika anak-anakmu laki-laki tetap hidup di hadapan-Ku dengan setia, dengan segenap hati dan dengan segenap jiwa, maka keturunanmu takkan terputus dari takhta kerajaan Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 5, 'Dan lagi engkaupun mengetahui apa yang dilakukan kepadaku oleh Yoab, anak Zeruya, apa yang dilakukannya kepada kedua panglima Israel, yakni Abner bin Ner dan Amasa bin Yeter. Ia membunuh mereka dan menumpahkan darah dalam zaman damai seakan-akan ada perang, sehingga sabuk pinggangnya dan kasut kakinya berlumuran darah.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 6, 'Maka bertindaklah dengan bijaksana dan janganlah biarkan yang ubanan itu turun dengan selamat ke dalam dunia orang mati.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 7, 'Tetapi kepada anak-anak Barzilai, orang Gilead itu, haruslah kautunjukkan kemurahan hati. Biarlah mereka termasuk golongan yang mendapat makanan dari mejamu, sebab merekapun menunjukkan kesetiaannya dengan menyambut aku pada waktu aku melarikan diri dari depan kakakmu Absalom.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 8, 'Juga masih ada padamu Simei bin Gera, orang Benyamin, dari Bahurim. Dialah yang mengutuki aku dengan kutuk yang kejam pada waktu aku pergi ke Mahanaim, tetapi kemudian ia datang menyongsong aku di sungai Yordan dan aku telah bersumpah kepadanya demi TUHAN: Takkan kubunuh engkau dengan pedang!', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 9, 'Sekarang janganlah bebaskan dia dari hukuman, sebab engkau seorang yang bijaksana dan tahu apa yang harus kaulakukan kepadanya untuk membuat yang ubanan itu turun dengan berdarah ke dalam dunia orang mati."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 10, 'Kemudian Daud mendapat perhentian bersama-sama nenek moyangnya, dan ia dikuburkan di kota Daud.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 11, 'Dan Daud memerintah orang Israel selama empat puluh tahun; di Hebron ia memerintah tujuh tahun, dan di Yerusalem ia memerintah tiga puluh tiga tahun.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 12, 'Salomo duduk di atas takhta Daud, ayahnya, dan kerajaannya sangat kokoh.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 13, 'Pada suatu hari Adonia, anak Hagit, masuk menghadap Batsyeba, ibu Salomo, lalu perempuan itu berkata: "Apakah engkau datang dengan maksud damai?" Jawabnya: "Ya, damai!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 14, 'Kemudian katanya: "Ada sesuatu yang hendak kukatakan kepadamu." Jawab perempuan itu: "Katakanlah!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 15, 'Lalu katanya: "Engkau sendiri tahu bahwa akulah yang berhak atas kedudukan raja, dan bahwa seluruh Israel mengharapkan, supaya aku menjadi raja; tetapi sebaliknya kedudukan raja jatuh kepada adikku, sebab dari Tuhanlah ia mendapatnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 16, 'Dan sekarang, satu permintaan saja kusampaikan kepadamu; janganlah tolak permintaanku." Jawab perempuan itu kepadanya: "Katakanlah!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 17, 'Maka katanya: "Bicarakanlah kiranya dengan raja Salomo, sebab ia tidak akan menolak permintaanmu, supaya Abisag, gadis Sunem itu, diberikannya kepadaku menjadi isteriku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 18, 'Jawab Batsyeba: "Baik, aku akan membicarakan hal itu untuk engkau dengan raja."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 19, 'Batsyeba masuk menghadap raja Salomo untuk membicarakan hal itu untuk Adonia, lalu bangkitlah raja mendapatkannya serta tunduk menyembah kepadanya; kemudian duduklah ia di atas takhtanya dan ia menyuruh meletakkan kursi untuk bunda raja, lalu perempuan itu duduk di sebelah kanannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 20, 'Berkatalah perempuan itu: "Suatu permintaan kecil saja yang kusampaikan kepadamu, janganlah tolak permintaanku." Jawab raja kepadanya: "Mintalah, ya ibu, sebab aku tidak akan menolak permintaanmu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 21, 'Kata perempuan itu: "Biarlah Abisag, gadis Sunem itu, diberikan kepada kakakmu Adonia menjadi isterinya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 22, 'Tetapi raja Salomo menjawab ibunya: "Mengapa engkau meminta hanya Abisag, gadis Sunem itu, untuk Adonia? Minta jugalah untuknya kedudukan raja! Bukankah dia saudaraku yang lebih tua, dan di pihaknya ada imam Abyatar dan Yoab, anak Zeruya?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 23, 'Lalu bersumpahlah raja Salomo demi TUHAN: "Beginilah kiranya Allah menghukum aku, bahkan lebih dari pada itu, jika Adonia tidak membayarkan nyawanya dengan permintaan ini!', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 24, 'Oleh sebab itu, demi TUHAN yang hidup, yang menegakkan aku dan mendudukkan aku di atas takhta Daud, ayahku, dan yang membuat bagiku suatu keluarga seperti yang dijanjikan-Nya: pada hari ini juga Adonia harus dibunuh."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 25, 'Lalu raja Salomo menyerahkan hal itu kepada Benaya bin Yoyada; orang ini memancung dia sehingga mati.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 26, 'Dan kepada imam Abyatar raja berkata: "Pergilah ke Anatot, ke tanah milikmu, sebab engkau patut dihukum mati, tetapi pada hari ini aku tidak akan membunuh engkau, oleh karena engkau telah mengangkat tabut Tuhan ALLAH di depan Daud, ayahku, dan oleh karena engkau telah turut menderita dalam segala sengsara yang diderita ayahku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 27, 'Lalu Salomo memecat Abyatar dari jabatannya sebagai imam TUHAN. Dengan demikian Salomo memenuhi firman TUHAN yang telah dikatakan-Nya di Silo mengenai keluarga Eli.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 28, 'Ketika kabar itu sampai kepada Yoab?memang Yoab telah memihak kepada Adonia, sekalipun ia tidak memihak kepada Absalom?maka larilah Yoab ke kemah TUHAN, lalu memegang tanduk-tanduk mezbah.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 29, 'Kemudian diberitahukanlah kepada Salomo, bahwa Yoab sudah lari ke kemah TUHAN, dan telah ada di samping mezbah. Lalu Salomo menyuruh Benaya bin Yoyada: "Pergilah, pancung dia."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 30, 'Benaya masuk ke dalam kemah TUHAN serta berkata kepadanya: "Beginilah kata raja: Keluarlah." Jawabnya: "Tidak, sebab di sinilah aku mau mati." Lalu Benaya menyampaikan jawab itu kepada raja, katanya: "Beginilah kata Yoab dan beginilah jawabnya kepadaku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 31, 'Kata raja kepadanya: "Perbuatlah seperti yang dikatakannya; pancunglah dia dan kuburkanlah dia; dengan demikian engkau menjauhkan dari padaku dan dari pada kaumku noda darah yang ditumpahkan Yoab dengan tidak beralasan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 32, 'Dan TUHAN akan menanggungkan darahnya kepadanya sendiri, karena ia telah membunuh dua orang yang lebih benar dan lebih baik dari padanya. Ia membunuh mereka dengan pedang, dengan tidak diketahui ayahku Daud, yaitu Abner bin Ner, panglima Israel, dan Amasa bin Yeter, panglima Yehuda.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 33, 'Demikianlah darah mereka akan ditanggungkan kepada Yoab dan keturunannya untuk selama-lamanya, tetapi Daud dan keturunannya dan keluarganya dan takhtanya akan mendapat selamat dari pada TUHAN sampai selama-lamanya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 34, 'Maka berangkatlah Benaya bin Yoyada, lalu memancung dan membunuh Yoab, kemudian dia dikuburkan di rumahnya sendiri di padang gurun.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 35, 'Raja mengangkat Benaya bin Yoyada menggantikan Yoab menjadi kepala tentara; dan raja mengangkat imam Zadok menggantikan Abyatar.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 36, 'Kemudian raja menyuruh memanggil Simei, dan berkata kepadanya: "Dirikanlah bagimu sebuah rumah di Yerusalem, diamlah di sana, dan janganlah keluar dari sana ke mana-manapun.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 37, 'Sebab ketahuilah sungguh-sungguh, bahwa pada waktu engkau keluar dan menyeberangi sungai Kidron, pastilah engkau mati dibunuh dan darahmu akan ditanggungkan kepadamu sendiri."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 38, 'Lalu berkatalah Simei kepada raja: "Baiklah demikian! Seperti yang tuanku raja katakan, demikianlah akan dilakukan hambamu ini." Lalu Simei diam di Yerusalem beberapa waktu lamanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 39, 'Dan sesudah lewat tiga tahun, terjadilah bahwa dua orang hamba Simei lari kepada Akhis bin Maakha, raja Gat, lalu diberitahukan kepada Simei: "Ketahuilah, kedua orang hambamu ada di Gat."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 40, 'Maka berkemaslah Simei, dipelanainya keledainya, dan pergilah ia ke Gat, kepada Akhis, untuk mencari hambanya itu. Lalu Simei pulang dan membawa mereka dari Gat.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 41, 'Ketika diberitahukan kepada Salomo, bahwa tadinya Simei pergi dari Yerusalem ke Gat dan sekarang sudah pulang,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 42, 'maka raja menyuruh memanggil Simei dan berkata kepadanya: "Bukankah aku telah menyuruh engkau bersumpah demi TUHAN dan telah memperingatkan engkau, begini: Ketahuilah sungguh-sungguh, bahwa pada waktu engkau keluar dan pergi ke mana-manapun, pastilah engkau mati dibunuh! Dan engkau telah menjawab: Baiklah demikian, aku akan mentaatinya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 43, 'Mengapa engkau tidak menepati sumpah demi TUHAN itu dan juga perintah yang kuperintahkan kepadamu?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 44, 'Kemudian kata raja kepada Simei: "Engkau sendiri tahu dalam hatimu segala kejahatan yang kauperbuat kepada Daud, ayahku, maka TUHAN telah menanggungkan kejahatanmu itu kepadamu sendiri.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 45, 'Tetapi diberkatilah kiranya raja Salomo dan kokohlah takhta Daud di hadapan TUHAN sampai selama-lamanya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 2, 46, 'Raja memberi perintah kepada Benaya bin Yoyada, lalu keluarlah Benaya, dipancungnya Simei sehingga mati. Demikianlah kerajaan itu kokoh di tangan Salomo.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 1, 'Lalu Salomo menjadi menantu Firaun, raja Mesir; ia mengambil anak Firaun, dan membawanya ke kota Daud, sampai ia selesai mendirikan istananya dan rumah TUHAN dan tembok sekeliling Yerusalem.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 2, 'Hanya, bangsa itu masih mempersembahkan korban di bukit-bukit pengorbanan, sebab belum ada didirikan rumah untuk nama TUHAN sampai pada waktu itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 3, 'Dan Salomo menunjukkan kasihnya kepada TUHAN dengan hidup menurut ketetapan-ketetapan Daud, ayahnya; hanya, ia masih mempersembahkan korban sembelihan dan ukupan di bukit-bukit pengorbanan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 4, 'Pada suatu hari raja pergi ke Gibeon untuk mempersembahkan korban, sebab di situlah bukit pengorbanan yang paling besar; seribu korban bakaran dipersembahkan Salomo di atas mezbah itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 5, 'Di Gibeon itu TUHAN menampakkan diri kepada Salomo dalam mimpi pada waktu malam. Berfirmanlah Allah: "Mintalah apa yang hendak Kuberikan kepadamu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 6, 'Lalu Salomo berkata: "Engkaulah yang telah menunjukkan kasih setia-Mu yang besar kepada hamba-Mu Daud, ayahku, sebab ia hidup di hadapan-Mu dengan setia, benar dan jujur terhadap Engkau; dan Engkau telah menjamin kepadanya kasih setia yang besar itu dengan memberikan kepadanya seorang anak yang duduk di takhtanya seperti pada hari ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 7, 'Maka sekarang, ya TUHAN, Allahku, Engkaulah yang mengangkat hamba-Mu ini menjadi raja menggantikan Daud, ayahku, sekalipun aku masih sangat muda dan belum berpengalaman.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 8, 'Demikianlah hamba-Mu ini berada di tengah-tengah umat-Mu yang Kaupilih, suatu umat yang besar, yang tidak terhitung dan tidak terkira banyaknya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 9, 'Maka berikanlah kepada hamba-Mu ini hati yang faham menimbang perkara untuk menghakimi umat-Mu dengan dapat membedakan antara yang baik dan yanjahat, sebab siapakah yang sanggup menghakimi umat-Mu yang sangat besar ini?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 10, 'Lalu adalah baik di mata Tuhan bahwa Salomo meminta hal yang demikian.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 11, 'Jadi berfirmanlah Allah kepadanya: "Oleh karena engkau telah meminta hal yang demikian dan tidak meminta umur panjang atau kekayaan atau nyawa musuhmu, melainkan pengertian untuk memutuskan hukum,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 12, 'maka sesungguhnya Aku melakukan sesuai dengan permintaanmu itu, sesungguhnya Aku memberikan kepadamu hati yang penuh hikmat dan pengertian, sehingga sebelum engkau tidak ada seorangpun seperti engkau, dan sesudah engkau takkan bangkit seorangpun seperti engkau.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 13, 'Dan juga apa yang tidak kauminta Aku berikan kepadamu, baik kekayaan maupun kemuliaan, sehingga sepanjang umurmu takkan ada seorangpun seperti engkau di antara raja-raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 14, 'Dan jika engkau hidup menurut jalan yang Kutunjukkan dan tetap mengikuti segala ketetapan dan perintah-Ku, sama seperti ayahmu Daud, maka Aku akan memperpanjang umurmu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 15, 'Lalu terjagalah Salomo; ternyata ia bermimpi. Sekembalinya ke Yerusalem, berdirilah ia di hadapan tabut perjanjian Tuhan, dipersembahkannya korban-korban bakaran dan korban-korban keselamatan, kemudian ia mengadakan perjamuan bagi semua pegawainya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 16, 'Pada waktu itu masuklah dua orang perempuan sundal menghadap raja, lalu mereka berdiri di depannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 17, 'Kata perempuan yang satu: "Ya tuanku! aku dan perempuan ini diam dalam satu rumah, dan aku melahirkan anak, pada waktu dia ada di rumah itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 18, 'Kemudian pada hari ketiga sesudah aku, perempuan inipun melahirkan anak; kami sendirian, tidak ada orang luar bersama-sama kami dalam rumah, hanya kami berdua saja dalam rumah.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 19, 'Pada waktu malam anak perempuan ini mati, karena ia menidurinya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 20, 'Pada waktu tengah malam ia bangun, lalu mengambil anakku dari sampingku; sementara hambamu ini tidur, dibaringkannya anakku itu di pangkuannya, sedang anaknya yang mati itu dibaringkannya di pangkuanku.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 21, 'Ketika aku bangun pada waktu pagi untuk menyusui anakku, tampaklah anak itu sudah mati, tetapi ketika aku mengamat-amati dia pada waktu pagi itu, tampaklah bukan dia anak yang kulahirkan."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 22, 'Kata perempuan yang lain itu: "Bukan! anakkulah yang hidup dan anakmulah yang mati." Tetapi perempuan yang pertama berkata pula: "Bukan! anakmulah yang mati dan anakkulah yang hidup." Begitulah mereka bertengkar di depan raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 23, 'Lalu berkatalah raja: "Yang seorang berkata: Anakkulah yang hidup ini dan anakmulah yang mati. Yang lain berkata: Bukan! Anakmulah yang mati dan anakkulah yang hidup."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 24, 'Sesudah itu raja berkata: "Ambilkan aku pedang," lalu dibawalah pedang ke depan raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 25, 'Kata raja: "Penggallah anak yang hidup itu menjadi dua dan berikanlah setengah kepada yang satu dan yang setengah lagi kepada yang lain."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 26, 'Maka kata perempuan yang empunya anak yang hidup itu kepada raja, sebab timbullah belas kasihannya terhadap anaknya itu, katanya: "Ya tuanku! Berikanlah kepadanya bayi yang hidup itu, jangan sekali-kali membunuh dia." Tetapi yang lain itu berkata: "Supaya jangan untukku ataupun untukmu, penggallah!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 27, 'Tetapi raja menjawab, katanya: "Berikanlah kepadanya bayi yang hidup itu, jangan sekali-kali membunuh dia; dia itulah ibunya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 3, 28, 'Ketika seluruh orang Israel mendengar keputusan hukum yang diberikan raja, maka takutlah mereka kepada raja, sebab mereka melihat, bahwa hikmat dari pada Allah ada dalam hatinya untuk melakukan keadilan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 1, 'Maka Salomo menjadi raja atas seluruh Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 2, 'Inilah para pembesarnya: Azarya bin Zadok menjadi imam;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 3, 'Elihoref dan Ahia, anak-anak Sisa menjadi panitera negara; Yosafat bin Ahilud menjadi bendahara negara;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 4, 'Benaya bin Yoyada menjadi panglima; Zadok dan Abyatar menjadi imam.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 5, 'Azarya bin Natan mengawasi para kepala daerah; Zabut bin Natan, seorang imam, menjadi sahabat raja;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 6, 'Ahisar menjadi kepala istana; Adoniram bin Abda menjadi kepala rodi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 7, 'Salomo mempunyai dua belas orang kepala daerah atas seluruh Israel yang harus menjamin makanan raja dan seisi istananya: adalah tanggungan tiap-tiap kepala daerah untuk menjamin makanan selama sebulan dalam setahun.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 8, 'Inilah nama-nama mereka: Ben-Hur di pegunungan Efraim;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 9, 'Ben-Deker di Makas, di Saalbim, di Bet-Semes dan di Elon-Bet-Hanan;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 10, 'Ben-Hesed di Arubot; wilayahnya ialah Sokho dan seluruh tanah Hefer;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 11, 'Ben-Abinadab memegang seluruh tanah bukit Dor, dan Tafat binti Salomo menjadi isterinya;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 12, 'Baana bin Ahilud memegang Taanakh, Megido dan seluruh Bet-Sean yang di sebelah Sartan di sebelah hilir Yizreel, dari Bet-Sean sampai Abel-Mehola sampai ke seberang Yokmeam.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 13, 'Selanjutnya Ben-Geber di Ramot-Gilead; wilayahnya ialah Hawot-Yair yang di Gilead; Yair ialah anak Manasye. Juga wilayah Argob yang di Basan dipegangnya, enam puluh kota besar, berpagar tembok dan berpalang pintu tembaga;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 14, 'Ahinadab bin Ido memegang Mahanaim.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 15, 'Selanjutnya Ahimaas di Naftali; ia juga mengambil seorang anak Salomo menjadi isterinya, yakni Basmat.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 16, 'Selanjutnya Baana bin Husai di Asyer dan di Alot.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 17, 'Lalu Yosafat bin Paruah di Isakhar', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 18, 'dan Simei bin Ela di Benyamin.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 19, 'Geber bin Uri di tanah Gilead memegang tanah Sihon, raja orang Amori, dan tanah Og, raja Basan; dan dialah satu-satunya kepala daerah yang ada di tanah itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 20, 'Orang Yehuda dan orang Israel jumlahnya seperti pasir di tepi laut. Mereka makan dan minum serta bersukaria.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 21, 'Maka Salomo berkuasa atas segala kerajaan mulai dari sungai Efrat sampai negeri orang Filistin dan sampai ke tapal batas Mesir. Mereka menyampaikan upeti dan tetap takluk kepada Salomo seumur hidupnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 22, 'Adapun persediaan makanan yang diperlukan Salomo untuk sehari ialah tiga puluh kor tepung yang terbaik dan enam puluh kor tepung biasa,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 23, 'sepuluh ekor lembu gemukan dan dua puluh lembu gembalaan dan seratus ekor domba, belum terhitung rusa, kijang, rusa dandi dan gangsa piaraan,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 24, 'sebab ia berkuasa atas seluruh tanah di sebelah sini sungai Efrat, mulai dari Tifsah sampai ke Gaza, dan atas semua raja di sebelah sini sungai Efrat; ia dikaruniai damai di seluruh negerinya,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 25, 'sehingga orang Yehuda dan orang Israel diam dengan tenteram, masing-masing di bawah pohon anggur dan pohon aranya, dari Dan sampai Bersyeba seumur hidup Salomo.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 26, 'Lagipula Salomo mempunyai kuda empat puluh ribu kandang untuk kereta-keretanya dan dua belas ribu orang berkuda.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 27, 'Dan para kepala daerah itu menjamin makanan raja Salomo serta semua orang yang ikut makan dari meja raja Salomo. Mereka membawanya masing-masing dalam bulan gilirannya dengan tidak mengurangi sesuatu apapun.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 28, 'Jelai dan jerami untuk kuda-kuda biasa dan kuda-kuda teji dibawa mereka ke tempat yang semestinya, masing-masing menurut tanggungannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 29, 'Dan Allah memberikan kepada Salomo hikmat dan pengertian yang amat besar, serta akal yang luas seperti dataran pasir di tepi laut,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 30, 'sehingga hikmat Salomo melebihi hikmat segala bani Timur dan melebihi segala hikmat orang Mesir.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 31, 'Ia lebih bijaksana dari pada semua orang, dari pada Etan, orang Ezrahi itu, dan dari pada Heman, Kalkol dan Darda, anak-anak Mahol; sebab itu ia mendapat nama di antara segala bangsa sekelilingnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 32, 'Ia menggubah tiga ribu amsal, dan nyanyiannya ada seribu lima.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 33, 'Ia bersajak tentang pohon-pohonan, dari pohon aras yang di gunung Libanon sampai kepada hisop yang tumbuh pada dinding batu; ia berbicara juga tentang hewan dan tentang burung-burung dan tentang binatang melata dan tentang ikan-ikan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 4, 34, 'Maka datanglah orang dari segala bangsa mendengarkan hikmat Salomo, dan ia menerima upeti dari semua raja-raja di bumi, yang telah mendengar tentang hikmatnya itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 1, 'Hiram, raja Tirus, mengutus pegawai-pegawainya kepada Salomo, karena didengarnya, bahwa Salomo telah diurapi menjadi raja menggantikan ayahnya, sebab Hiram senantiasa bersahabat dengan Daud.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 2, 'Lalu Salomo mengutus orang kepada Hiram dengan pesan:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 3, '"Engkau tahu bahwa Daud, ayahku, tidak dapat mendirikan sebuah rumah bagi nama TUHAN, Allahnya, oleh karena musuh-musuhnya memerangi dia dari segala jurusan, sampai TUHAN menyerahkan mereka ke bawah telapak kakinya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 4, 'Tetapi sekarang, TUHAN, Allahku, telah mengaruniakan keamanan kepadaku di mana-mana, tidak ada lagi lawan dan tidak ada lagi malapetaka menimpa.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 5, 'Dan ketahuilah, aku berpikir-pikir hendak mendirikan sebuah rumah bagi nama TUHAN, Allahku, seperti yang dijanjikan TUHAN kepada Daud, ayahku, demikian: Anakmu yang hendak Kududukkan nanti di atas takhtamu menggantikan engkau, dialah yang akan mendirikan rumah itu bagi nama-Ku.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 6, 'Oleh sebab itu, perintahkanlah orang menebang bagiku pohon-pohon aras dari gunung Libanon, dan biarlah hamba-hambaku membantu hamba-hambamu, dan upah hamba-hambamu akan kubayar kepadamu seberapa juga kauminta, sebab engkau tahu, bahwa di antara kami tidak ada seorangpun yang pandai menebang pohon sama seperti orang Sidon."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 7, 'Maka segera sesudah Hiram mendengar pesan dari Salomo itu, ia sangat bersukacita serta berkata: "Terpujilah TUHAN pada hari ini, karena Ia telah memberikan kepada Daud seorang anak yang bijaksana untuk mengepalai bangsa yang besar ini."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 8, 'Lalu Hiram mengutus orang kepada Salomo mengatakan: "Aku telah mendengar pesan yang kausuruh sampaikan kepadaku. Tentang kayu aras dan kayu sanobar aku akan melakukan segala yang kaukehendaki.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 9, 'Hamba-hambaku akan membawanya turun dari gunung Libanon ke laut dan aku akan mengikatnya menjadi rakit-rakit di laut untuk dibawa sampai ke tempat yang akan kautunjukkan kepadaku; kemudian akan kusuruh bongkar semuanya di sana, sehingga engkau dapat mengangkutnya. Sementara itu engkau hendaknya menyediakan makanan bagi seisi istanaku seberapa yang kukehendaki."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 10, 'Demikianlah Hiram memberikan kayu aras dan kayu sanobar kepada Salomo seberapa yang dikehendakinya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 11, 'Lalu Salomo memberikan kepada Hiram dua puluh ribu kor gandum, bahan makanan bagi seisi istananya dan dua puluh kor minyak tumbuk; demikianlah diberikan Salomo kepada Hiram tahun demi tahun.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 12, 'Dan TUHAN memberikan hikmat kepada Salomo seperti yang dijanjikan-Nya kepadanya; maka damaipun ada antara Hiram dan Salomo, lalu mereka berdua mengadakan perjanjian.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 13, 'Raja Salomo mengerahkan orang rodi dari antara seluruh Israel, maka orang rodi itu ada tiga puluh ribu orang.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 14, 'Ia menyuruh mereka ke gunung Libanon, sepuluh ribu orang dalam sebulan berganti-ganti: selama sebulan mereka ada di Libanon, selama dua bulan di rumah. Adoniram menjadi kepala rodi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 15, 'Lagipula Salomo mempunyai tujuh puluh ribu kuli dan delapan puluh ribu tukang pahat di pegunungan,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 16, 'belum terhitung para mandur kepala Salomo yang mengepalai pekerjaan itu, yakni tiga ribu tiga ratus orang banyaknya, yang mengawasi rakyat yang mengerjakan pekerjaan itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 17, 'Dan raja memerintahkan supaya mereka melinggis batu yang besar, batu yang mahal-mahal untuk membuat dasar rumah itu dari batu pahat.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 5, 18, 'Maka tukang-tukang Salomo dan tukang-tukang Hiram serta orang-orang Gebal memahat dan menyediakan kayu dan batu untuk mendirikan rumah itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 1, 'Dan terjadilah pada tahun keempat ratus delapan puluh sesudah orang Israel keluar dari tanah Mesir, pada tahun keempat sesudah Salomo menjadi raja atas Israel, dalam bulan Ziw, yakni bulan yang kedua, maka Salomo mulai mendirikan rumah bagi TUHAN.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 2, 'Rumah yang didirikan raja Salomo bagi TUHAN itu enam puluh hasta panjangnya dan dua puluh hasta lebarnya dan tiga puluh hasta tingginya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 3, 'Balai di sebelah depan ruang besar rumah itu dua puluh hasta panjangnya, menurut lebar rumah itu, dan sepuluh hasta lebarnya ke sebelah depan rumah itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 4, 'Dibuatnya juga pada rumah itu jendela-jendela yang rapat bidainya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 5, 'Pada dinding rumah itu sekelilingnya didirikannya kamar tambahan, sekeliling ruang besar dan ruang belakang, dan seluruhnya dibuatnya bertingkat-tingkat.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 6, 'Tingkat bawah lima hasta lebarnya, yang tengah enam hasta dan yang ketiga tujuh hasta, sebab telah dibuatnya ceruk-ceruk pada rumah itu sekeliling sebelah luar, sehingga dinding rumah itu tidak usah dilobangi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 7, 'Pada waktu rumah itu didirikan, dipakailah batu-batu yang telah disiapkan di penggalian, sehingga tidak kedengaran palu atau kapak atau sesuatu perkakas besipun selama pembangunan rumah itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 8, 'Pintu tingkat bawah ada pada lambung kanan rumah itu, dan orang naik dengan tangga-tangga pilin ke tingkat tengah dan dari tingkat tengah ke tingkat yang ketiga.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 9, 'Setelah ia selesai mendirikan rumah itu, dibuatnyalah langit-langit rumah itu dari bingkai dan pemapan dari kayu aras.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 10, 'Dan setelah ia mendirikan kamar tambahan itu pada rumah itu sekeliling, yakni setiap tingkat lima hasta tingginya, maka rumah itu ditutupinya dengan kayu aras.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 11, 'Kemudian datanglah firman TUHAN kepada Salomo, demikian:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 12, '"Mengenai rumah yang sedang kaudirikan ini, jika engkau hidup menurut segala ketetapan-Ku dan melakukan segala peraturan-Ku dan tetap mengikuti segala perintah-Ku dan tidak menyimpang dari padanya, maka Aku akan menepati janji-Ku kepadamu yang telah Kufirmankan kepada Daud, ayahmu,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 13, 'yakni bahwa Aku akan diam di tengah-tengah orang Israel dan tidak hendak meninggalkan umat-Ku Israel."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 14, 'Setelah Salomo selesai mendirikan rumah itu,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 15, 'ia melapisi dinding rumah itu dari dalam dengan papan kayu aras; dari lantai sampai ke balok langit-langit dilapisinya dengan kayu aras, tetapi lantai rumah itu dilapisinya dengan papan kayu sanobar.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 16, 'Kemudian disekatnyalah dua puluh hasta bagian belakang rumah itu dengan papan kayu aras, dari lantai sampai ke balok-balok; lalu dibuatnyalah ruang itu menjadi ruang belakang, menjadi tempat maha kudus.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 17, 'Dan empat puluh hasta panjangnya ruang yang di depan ruang belakang itu, yakni ruang besar.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 18, 'Kayu aras sebelah dalam rumah itu berukirkan buah labu dan bunga mengembang; semuanya ditutupi kayu aras, tidak ada batu kelihatan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 19, 'Demikianlah dilengkapinya ruang belakang di dalam rumah itu, di sebelah dalam sekali, supaya di sana ditaruh tabut perjanjian TUHAN.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 20, 'Ruang belakang itu dua puluh hasta panjangnya dan dua puluh hasta lebarnya dan dua puluh hasta tingginya. Ia melapisinya dengan emas kertas, lalu ia membuat mezbah dari kayu aras di depannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 21, 'Sesudah Salomo melapisi rumah itu dari dalam dengan emas kertas, direntangkannyalah tabir pada rantai-rantai emas yang di depan ruang belakang itu, lalu ruang itu dilapisinya dengan emas.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 22, 'Seluruh rumah itu dilapisinya dengan emas, ya rumah itu seluruhnya; juga seluruh mezbah yang di depan ruang belakang itu dilapisinya dengan emas.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 23, 'Selanjutnya di dalam ruang belakang itu dibuatnya dua kerub dari kayu minyak, masing-masing sepuluh hasta tingginya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 24, 'Sayap yang satu dari kerub itu lima hasta panjangnya dan sayap yang lain juga lima hasta, sehingga dari ujung sayap yang satu sampai ke ujung sayap yang lain sepuluh hasta panjangnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 25, 'Juga kerub yang kedua adalah sepuluh hasta panjangnya; dan kedua kerub itu sama ukuran dan sama potongan badannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 26, 'Tinggi kerub yang satu sepuluh hasta dan demikian juga kerub yang kedua.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 27, 'Maka ditaruhnyalah kerub-kerub itu di tengah-tengah ruang yang di sebelah dalam sekali; kerub-kerub itu mengembangkan sayapnya, sehingga kerub yang satu menyentuh dinding dengan sayapnya dan kerub yang kedua menyentuh dinding yang lain, sedang sayap-sayap yang arah ke tengah rumah itu bersentuhan ujungnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 28, 'Dan kerub-kerub itu dilapisinya dengan emas.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 29, 'Dan pada segala dinding rumah itu berkeliling ia mengukir gambar kerub, pohon korma dan bunga mengembang, baik di ruang sebelah dalam maupun di ruang sebelah luar.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 30, 'Juga lantai rumah itu dilapisinya dengan emas, baik di ruang sebelah dalam maupun di ruang sebelah luar.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 31, 'Sebagai pintu masuk ke ruang belakang dibuatnyalah pintu dari kayu minyak; ambang dan tiangnya merupakan segi lima.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 32, 'Pada kedua daun pintu yang dari kayu minyak itu ia mengukir gambar kerub, pohon korma dan bunga mengembang, kemudian dilapisinya dengan emas; juga pada kerub dan pada pohon korma itu disalutkannya emas.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 33, 'Demikian juga untuk pintu masuk ke ruang besar itu dibuatnya tiang-tiang dari kayu minyak yang merupakan segi empat;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 34, 'dan dua pintu dari kayu sanobar; kedua papan pintu dari pintu yang satu dapat dilipat dan demikian juga kedua papan pintu yang lain.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 35, 'Lalu diukirnyalah padanya kerub, pohon korma dan bunga mengembang, kemudian dilapisinya pintu itu dengan emas pipih pada gambar ukiran itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 36, 'Ia mendirikan tembok pelataran dalam dari tiga jajar batu pahat dan dari satu jajar balok kayu aras.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 37, 'Dalam tahun yang keempat, dalam bulan Ziw, diletakkanlah dasar rumah TUHAN,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 6, 38, 'dan dalam tahun yang kesebelas, dalam bulan Bul, yaitu bulan kedelapan, selesailah rumah itu dengan segala bagian-bagiannya dan sesuai dengan segala rancangannya; jadi tujuh tahun lamanya ia mendirikan rumah itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 1, 'Salomo mendirikan istananya sampai tiga belas tahun lamanya, barulah selesai seluruh istananya itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 2, 'Ia mendirikan gedung "Hutan Libanon", seratus hasta panjangnya dan lima puluh hasta lebarnya dan tiga puluh hasta tingginya, disangga oleh tiga jajar tiang kayu aras dengan ganja kayu aras di atas tiang itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 3, 'Gedung itu ditutup dari atas dengan langit-langit kayu aras, di atas balok-balok melintang yang disangga oleh tiang-tiang itu, empat puluh lima jumlahnya, yakni lima belas sejajar.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 4, 'Ada pula tiga jajar jendela berbidai, jendela berhadapan dengan jendela, tiga kali.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 5, 'Dan semua pintu dan jendela segi empat bangunnya; jendela berhadapan dengan jendela, tiga kali.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 6, 'Ia membuat juga Balai Saka, lima puluh hasta panjangnya dan tiga puluh hasta lebarnya, dengan di sebelah depannya sebuah balai lagi yang bertiang dan bertangga di sebelah depannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 7, 'Dibuatnya juga Balai Singgasana, tempat ia memutuskan hukum, balai pengadilan, yang ditutupi dengan kayu aras dari lantai sampai ke balok langit-langit.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 8, 'Dan gedung kediamannya sendiri, di pelataran yang lain, lebih ke sebelah dalam lagi dari balai itu, adalah sama buatannya. Dan bagi anak Firaun, yang diambil Salomo menjadi isterinya, dibuatnya juga sebuah gedung sama dengan balai itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 9, 'Tembok dari semuanya ini dibuat dari batu yang mahal-mahal, yang sesuai dengan ukuran batu pahat digergaji dengan gergaji dari sebelah dalam dan dari sebelah luar, dari dasar sampai ke atas, dan juga dari tembok luar sampai kepada tembok pelataran besar.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 10, 'Bahkan dasar gedung-gedung itu dari batu yang mahal-mahal, batu yang besar-besar, batu yang sepuluh hasta dan batu yang delapan hasta.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 11, 'Di bagian atas ada batu yang mahal-mahal, berukuran batu pahat, dan kayu aras juga.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 12, 'Sekeliling pelataran besar ada tembok dari tiga jajar batu pahat dan satu jajar balok kayu aras; demikian juga sekeliling pelataran dalam rumah TUHAN dan balainya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 13, 'Kemudian raja Salomo menyuruh orang menjemput Hiram dari Tirus.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 14, 'Dia adalah anak seorang janda dari suku Naftali, sedang ayahnya orang Tirus, tukang tembaga; ia penuh dengan keahlian, pengertian dan pengetahuan untuk melakukan segala pekerjaan tembaga; ia datang kepada raja Salomo, lalu melakukan segala pekerjaan itu bagi raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 15, 'Ia membentuk dua tiang tembaga, tinggi tiang yang satu delapan belas hasta dan dapat dililit oleh tali yang dua belas hasta panjangnya; tiang yang kedua demikian juga.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 16, 'Dibuatnya juga dua ganja untuk ditaruh di kepala tiang-tiang itu, dari tembaga tuangan, tinggi ganja yang satu lima hasta dan tinggi ganja yang kedua lima hasta.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 17, 'Dibuatnya pula dua jala-jala untuk ganja yang ada di kepala tiang itu?jala-jala itu semacam kawat berpilin, semacam untaian rantai?satu jala-jala untuk ganja yang satu dan satu jala-jala untuk ganja yang kedua.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 18, 'Kemudian dibuatnya juga buah-buah delima, dua jajar berkeliling pada jala-jala yang satu, untuk menutupi ganja yang di ujung tiang itu, dan demikian pula dibuatnya pada ganja yang kedua.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 19, 'Dan ganja yang di kepala tiang dekat balai depan itu berbentuk bunga bakung, tingginya empat hasta,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 20, 'yakni ganja-ganja yang di atas kedua tiang itu, di sebelah atas sekali, lewat jala-jala yang meliliti perut ganja itu; dan buah-buah delima ada dua ratus berjajar berkeliling pada ganja yang satu, demikian juga pada yang kedua.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 21, 'Kemudian tiang-tiang itu didirikannya dekat balai ruang besar. Ketika ia mendirikan tiang kanan, ia menamainya Yakhin; ketika ia mendirikan tiang kiri, ia menamainya Boas.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 22, 'Dan setelah bentukan bunga bakung itu ditaruh di kepala tiang-tiang itu, maka siaplah pekerjaan membuat tiang-tiang itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 23, 'Kemudian dibuatnyalah "laut" tuangan yang sepuluh hasta dari tepi ke tepi, bundar keliling, lima hasta tingginya, dan yang dapat dililit berkeliling oleh tali yang tiga puluh hasta panjangnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 24, 'Dan di bawah tepinya ada gambar buah labu yang mengelilinginya sama sekali, sepuluh dalam sehasta, merangkum "laut" itu berkeliling; labu itu dua jajar, dituang setuangan dengan bejana itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 25, '"Laut" itu menumpang di atas dua belas lembu, tiga menghadap ke utara dan tiga menghadap ke barat, tiga menghadap ke selatan dan tiga menghadap ke timur; "laut" itu menumpang di atasnya, sedang segala buntut lembu itu menuju ke dalam.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 26, 'Tebal "laut" itu setapak tangan dan tepinya serupa tepi piala, seperti bunga bakung yang berkembang. "Laut" itu dapat memuat dua ribu bat air.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 27, 'Selanjutnya dibuatnya sepuluh kereta penopang dari tembaga, satu kereta empat hasta panjangnya, empat hasta lebarnya dan tiga hasta tingginya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 28, 'Beginilah bentuk kereta penopang itu: ada papan penutupnya dan papan itu diapit oleh bingkai.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 29, 'Dan pada papan penutup yang diapit oleh bingkai itu ada singa, lembu dan kerub, dan demikian juga pada bingkai itu; di sebelah atas dan di sebelah bawah singa dan lembu itu ada karangan-karangan bunga yang tergantung.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 30, 'Pada satu kereta penopang ada empat roda tembaga dengan poros tembaga; dan pada keempat penjurunya ada sangga untuk menyangga bejana pembasuhan; sangga-sangga itu dituang dan di sebelah luar setiap sangga ada karangan bunga.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 31, 'Dan mulut kereta penopang itu ada di sebelah dalam sangga-sangga itu, menonjol ke atas satu hasta; mulutnya itu bundar, buatannya sebagai tumpuan, dan dalamnya satu setengah hasta; juga pada mulutnya itu ada ukiran, tetapi papan-papan penutupnya empat persegi, jadi tidak bundar.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 32, 'Keempat roda itu ada di bawah papan penutup, dan tangan-tangan roda itu ada pada kereta penopang itu; dan tinggi satu roda ialah satu setengah hasta.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 33, 'Dan buatan roda itu seperti buatan roda kereta; tetapi tangan-tangannya, lingkarnya, jari-jarinya dan napnya, semuanya tuangan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 34, 'Keempat sangga pada keempat sudut setiap kereta penopang adalah seiras dengan kereta itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 35, 'Dan di sebelah atas kereta penopang itu ada leher bundar berkeliling, setengah hasta tingginya; di sebelah atas kereta itu ada pula topang-topang dan papan penutup yang seiras dengan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 36, 'Maka pada muka topang-topangnya itu dan pada papan-papan penutupnya diukirkannyalah kerub, singa dan pohon korma, masing-masing menurut tempat yang ada, dan karangan bunga sekeliling.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 37, 'Demikianlah dikerjakannya kesepuluh kereta penopang itu; tuangannya sama, ukurannya sama dan potongannya sama semuanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 38, 'Lagipula dibuatnya sepuluh bejana pembasuhan dari tembaga: setiap bejana dapat memuat empat puluh bat air, setiap bejana empat hasta besarnya dan ada satu bejana di atas setiap kereta dari kesepuluh kereta penopang itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 39, 'Lima kereta penopang ditaruhnya pada sisi kanan rumah itu dan lima pada sisi kirinya; tetapi "laut" itu ditaruhnya pada sisi kanan rumah itu, arah tenggara.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 40, 'Dan Hiram membuat juga kuali-kuali, penyodok-penyodok dan bokor-bokor penyiraman. Demikianlah Hiram menyelesaikan segala pekerjaan yang harus dilakukannya bagi raja Salomo di rumah TUHAN,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 41, 'yakni kedua tiang dengan kedua bulatan ganja yang di kepala tiang itu, dan kedua jala-jala yang menutup kedua bulatan ganja itu;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 42, 'keempat ratus buah delima untuk kedua jala-jala itu, dua jajar buah delima untuk satu jala-jala guna menutupi kedua bulatan ganja yang di atas tiang itu;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 43, 'kesepuluh kereta penopang dan kesepuluh bejana pembasuhan yang di atas kereta itu;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 44, '"laut" yang satu itu dan kedua belas lembu yang di bawah "laut" itu;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 45, 'kuali-kuali, penyodok-penyodok dan bokor-bokor penyiraman; segala perlengkapan yang dibuat Hiram bagi raja Salomo di rumah TUHAN itu adalah dari tembaga yang diupam.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 46, 'Raja menuang semuanya itu di Lembah Yordan di dalam tanah liat antara Sukot dan Sartan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 47, 'Dan Salomo membiarkan segala perlengkapan itu tidak ditimbang karena jumlahnya yang amat besar; berat tembaga itu tidaklah terhitung.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 48, 'Salomo membuat juga segala perlengkapan yang ada di rumah TUHAN, yakni mezbah emas dan meja emas tempat menaruh roti sajian;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 49, 'kandil-kandil dari emas murni, lima di sebelah kanan dan lima di sebelah kiri, di depan ruang belakang; kembang-kembangnya, lampu-lampunya dan sepit-sepitnya, dari emas;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 50, 'pasu-pasunya, pisau-pisaunya, bokor-bokor penyiramannya, cawan-cawannya dan perbaraan-perbaraannya, dari emas murni; engsel-engsel untuk pintu ruang dalam, yakni tempat maha kudus, dan engsel-engsel untuk pintu ruang besar Bait Suci, dari emas.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 7, 51, 'Maka genaplah segala pekerjaan yang dilakukan Salomo di rumah TUHAN itu. Kemudian Salomo memasukkan barang-barang kudus Daud, ayahnya, dan menaruh perak, emas dan barang-barang itu dalam perbendaharaan rumah TUHAN.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 1, 'Pada waktu itu raja Salomo menyuruh para tua-tua Israel dan semua kepala suku, yakni para pemimpin puak orang Israel, berkumpul di hadapannya di Yerusalem, untuk mengangkut tabut perjanjian TUHAN dari kota Daud, yaitu Sion.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 2, 'Maka pada hari raya di bulan Etanim, yakni bulan ketujuh, berkumpullah di hadapan raja Salomo semua orang Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 3, 'Setelah semua tua-tua Israel datang, maka imam-imam mengangkat tabut itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 4, 'Mereka mengangkut tabut TUHAN dan Kemah Pertemuan dan segala barang kudus yang ada dalam kemah itu; semuanya itu diangkut oleh imam-imam dan orang-orang Lewi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 5, 'Tetapi raja Salomo dan segenap umat Israel yang sudah berkumpul di hadapannya, berdiri bersama-sama dengan dia di depan tabut itu, dan mempersembahkan kambing domba dan lembu sapi yang tidak terhitung dan tidak terbilang banyaknya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 6, 'Kemudian imam-imam membawa tabut perjanjian TUHAN itu ke tempatnya, di ruang belakang rumah itu, di tempat maha kudus, tepat di bawah sayap kerub-kerub;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 7, 'sebab kerub-kerub itu mengembangkan kedua sayapnya di atas tempat tabut itu, sehingga kerub-kerub itu menudungi tabut serta kayu-kayu pengusungnya dari atas.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 8, 'Kayu-kayu pengusung itu demikian panjangnya, sehingga ujungnya kelihatan dari tempat kudus, yang di depan ruang belakang itu, tetapi tidak kelihatan dari luar; dan di situlah tempatnya sampai hari ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 9, 'Dalam tabut itu tidak ada apa-apa selain dari kedua loh batu yang diletakkan Musa ke dalamnya di gunung Horeb, yakni loh-loh batu bertuliskan perjanjian yang diadakan TUHAN dengan orang Israel pada waktu perjalanan mereka keluar dari tanah Mesir.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 10, 'Ketika imam-imam keluar dari tempat kudus, datanglah awan memenuhi rumah TUHAN,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 11, 'sehingga imam-imam tidak tahan berdiri untuk menyelenggarakan kebaktian oleh karena awan itu, sebab kemuliaan TUHAN memenuhi rumah TUHAN.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 12, 'Pada waktu itu berkatalah Salomo: "TUHAN telah menetapkan matahari di langit, tetapi Ia memutuskan untuk diam dalam kekelaman.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 13, 'Sekarang, aku telah mendirikan rumah kediaman bagi-Mu, tempat Engkau menetap selama-lamanya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 14, 'Kemudian berpalinglah raja lalu memberkati seluruh jemaah Israel, sedang segenap jemaah Israel berdiri.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 15, 'Ia berkata: "Terpujilah TUHAN, Allah Israel, yang telah menyelesaikan dengan tangan-Nya apa yang difirmankan-Nya dengan mulut-Nya kepada Daud, ayahku, demikian:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 16, 'Sejak Aku membawa umat-Ku Israel keluar dari Mesir, tidak ada kota yang Kupilih di antara segala suku Israel untuk mendirikan rumah di sana sebagai tempat kediaman nama-Ku, tetapi Aku telah memilih Daud untuk berkuasa atas umat-Ku Israel."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 17, 'Lalu raja melanjutkan: "Ketika Daud, ayahku bermaksud mendirikan rumah untuk nama TUHAN, Allah Israel,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 18, 'berfirmanlah TUHAN kepadanya: Engkau bermaksud mendirikan rumah untuk nama-Ku, dan maksudmu itu memanglah baik;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 19, 'hanya, bukanlah engkau yang akan mendirikan rumah itu, melainkan anak kandungmu yang akan lahir kelak, dialah yang akan mendirikan rumah itu untuk nama-Ku.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 20, 'Jadi TUHAN telah menepati janji yang telah diucapkan-Nya; aku telah bangkit menggantikan Daud, ayahku, dan telah duduk di atas takhta kerajaan Israel, seperti yang difirmankan TUHAN: aku telah mendirikan rumah ini untuk nama TUHAN, Allah Israel,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 21, 'dan telah menyediakan di sana tempat untuk tabut, yang memuat perjanjian yang telah diadakan TUHAN dengan nenek moyang kita, ketika mereka dibawa-Nya keluar dari tanah Mesir."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 22, 'Kemudian berdirilah Salomo di depan mezbah TUHAN di hadapan segenap jemaah Israel, ditadahkannyalah tangannya ke langit,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 23, 'lalu berkata: "Ya TUHAN, Allah Israel! Tidak ada Allah seperti Engkau di langit di atas dan di bumi di bawah; Engkau yang memelihara perjanjian dan kasih setia kepada hamba-hamba-Mu yang dengan segenap hatinya hidup di hadapan-Mu;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 24, 'Engkau yang tetap berpegang pada janji-Mu terhadap hamba-Mu Daud, ayahku, dan yang telah menggenapi dengan tangan-Mu apa yang Kaufirmankan dengan mulut-Mu, seperti yang terjadi pada hari ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 25, 'Maka sekarang, ya TUHAN, Allah Israel, peliharalah apa yang Kaujanjikan kepada hamba-Mu Daud, ayahku, dengan berkata: Keturunanmu takkan terputus di hadapan-Ku dan tetap akan duduk di atas takhta kerajaan Israel, asal anak-anakmu tetap hidup di hadapan-Ku sama seperti engkau hidup di hadapan-Ku.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 26, 'Maka sekarang, ya Allah Israel, biarlah kiranya menjadi nyata keteguhan janji yang telah Kauucapkan kepada hamba-Mu Daud, ayahku.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 27, 'Tetapi benarkah Allah hendak diam di atas bumi? Sesungguhnya langit, bahkan langit yang mengatasi segala langitpun tidak dapat memuat Engkau, terlebih lagi rumah yang kudirikan ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 28, 'Maka berpalinglah kepada doa dan permohonan hamba-Mu ini, ya TUHAN Allahku, dengarkanlah seruan dan doa yang hamba-Mu panjatkan di hadapan-Mu pada hari ini!', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 29, 'Kiranya mata-Mu terbuka terhadap rumah ini, siang dan malam, terhadap tempat yang Kaukatakan: nama-Ku akan tinggal di sana; dengarkanlah doa yang hamba-Mu panjatkan di tempat ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 30, 'Dan dengarkanlah permohonan hamba-Mu dan umat-Mu Israel yang mereka panjatkan di tempat ini; bahwa Engkau juga yang mendengarnya di tempat kediaman-Mu di sorga; dan apabila Engkau mendengarnya, maka Engkau akan mengampuni.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 31, 'Jika seseorang telah berdosa kepada temannya, lalu diwajibkan mengangkat sumpah dengan mengutuk dirinya, dan dia datang bersumpah ke depan mezbah-Mu di dalam rumah ini,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 32, 'maka Engkaupun kiranya mendengarkannya di sorga dan bertindak serta mengadili hamba-hamba-Mu, yakni menyatakan bersalah orang yang bersalah dengan menanggungkan perbuatannya kepada orang itu sendiri, tetapi menyatakan benar orang yang benar dengan memberi pembalasan kepadanya yang sesuai dengan kebenarannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 33, 'Apabila umat-Mu Israel terpukul kalah oleh musuhnya karena mereka berdosa kepada-Mu, kemudian mereka berbalik kepada-Mu dan mengakui nama-Mu, dan mereka berdoa dan memohon kepada-Mu di rumah ini,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 34, 'maka Engkaupun kiranya mendengarkannya di sorga dan mengampuni dosa umat-Mu Israel dan mengembalikan mereka ke tanah yang telah Kauberikan kepada nenek moyang mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 35, 'Apabila langit tertutup, sehingga tidak ada hujan, sebab mereka berdosa kepada-Mu, lalu mereka berdoa di tempat ini dan mengakui nama-Mu dan mereka berbalik dari dosanya, sebab Engkau telah menindas mereka,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 36, 'maka Engkaupun kiranya mendengarkannya di sorga dan mengampuni dosa hamba-hamba-Mu, umat-Mu Israel, ?karena Engkaulah yang menunjukkan kepada mereka jalan yang baik yang harus mereka ikuti?dan Engkau kiranya memberikan hujan kepada tanah-Mu yang telah Kauberikan kepada umat-Mu menjadi milik pusaka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 37, 'Apabila di negeri ini ada kelaparan, apabila ada penyakit sampar, hama dan penyakit gandum, belalang, atau belalang pelahap, apabila musuh menyesakkan mereka di salah satu kota mereka, apabila ada tulah atau penyakit apapun,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 38, 'lalu seseorang atau segenap umat-Mu Israel ini memanjatkan doa dan permohonan di rumah ini dengan menadahkan tangannya?karena mereka masing-masing mengenal apa yang merisaukan hatinya sendiri?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 39, 'maka Engkaupun kiranya mendengarkannya di sorga, tempat kediaman-Mu yang tetap, dan Engkau kiranya mengampuni, bertindak, dan membalaskan kepada setiap orang sesuai dengan segala kelakuannya, karena engkau mengenal hatinya?sebab Engkau sajalah yang mengenal hati semua anak manusia, ?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 40, 'supaya mereka takut akan Engkau selama mereka hidup di atas tanah yang telah Kauberikan kepada nenek moyang kami.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 41, 'Juga apabila seorang asing, yang tidak termasuk umat-Mu Israel, datang dari negeri jauh oleh karena nama-Mu, ?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 42, 'sebab orang akan mendengar tentang nama-Mu yang besar dan tentang tangan-Mu yang kuat dan lengan-Mu yang teracung?dan ia datang berdoa di rumah ini,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 43, 'maka Engkaupun kiranya mendengarkannya di sorga, tempat kediaman-Mu yang tetap, dan Engkau kiranya bertindak sesuai dengan segala yang diserukan kepada-Mu oleh orang asing itu, supaya segala bangsa di bumi mengenal nama-Mu, sehingga mereka takut akan Engkau sama seperti umat-Mu Israel dan sehingga mereka tahu, bahwa nama-Mu telah diserukan atas rumah yang telah kudirikan ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 44, 'Apabila umat-Mu keluar untuk berperang melawan musuhnya, ke arah manapun Engkau menyuruh mereka, dan apabila mereka berdoa kepada TUHAN dengan berkiblat ke kota yang telah Kaupilih dan ke rumah yang telah kudirikan bagi nama-Mu,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 45, 'maka Engkau kiranya mendengarkan di sorga doa dan permohonan mereka dan Engkau kiranya memberikan keadilan kepada mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 46, 'Apabila mereka berdosa kepada-Mu?karena tidak ada manusia yang tidak berdosa?dan Engkau murka kepada mereka dan menyerahkan mereka kepada musuh, sehingga mereka diangkut tertawan ke negeri musuh yang jauh atau yang dekat,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 47, 'dan apabila mereka sadar kembali dalam hatinya di negeri tempat mereka tertawan, dan mereka berbalik, dan memohon kepada-Mu di negeri orang-orang yang mengangkut mereka tertawan, dengan berkata: Kami telah berdosa, bersalah, dan berbuat fasik,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 48, 'apabila mereka berbalik kepada-Mu dengan segenap hatinya dan dengan segenap jiwanya di negeri musuh yang mengangkut mereka tertawan, dan apabila mereka berdoa kepada-Mu dengan berkiblat ke negeri mereka yang telah Kauberikan kepada nenek moyang mereka, ke kota yang telah Kaupilih dan ke rumah yang telah kudirikan bagi nama-Mu,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 49, 'maka Engkau kiranya mendengarkan di sorga, tempat kediaman-Mu yang tetap, kepada doa dan permohonan mereka dan Engkau kiranya memberikan keadilan kepada mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 50, 'Engkau kiranya mengampuni umat-Mu yang telah berdosa kepada-Mu, mengampuni segala pelanggaran yang dilakukan mereka kepada-Mu, dan kiranya Engkau membuat mereka menjadi kesayangan orang-orang yang mengangkut mereka tertawan, sehingga orang-orang itu menyayangi mereka,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 51, 'sebab mereka itu umat-Mu dan milik kepunyaan-Mu yang telah Kaubawa keluar dari Mesir dari tengah-tengah dapur peleburan besi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 52, 'Hendaklah mata-Mu terbuka terhadap permohonan hamba-Mu dan terhadap permohonan umat-Mu Israel dan hendaklah Engkau mendengarkan mereka seberapa kali mereka berseru kepada-Mu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 53, 'Sebab Engkaulah yang memisahkan mereka bagi-Mu menjadi milik kepunyaan-Mu dari antara segala bangsa di bumi, seperti yang telah Kaufirmankan dengan perantaraan Musa, hamba-Mu, pada waktu Engkau membawa nenek moyang kami keluar dari Mesir, ya Tuhan ALLAH!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 54, 'Ketika Salomo selesai memanjatkan segala doa dan permohonan itu kepada TUHAN, bangkitlah ia dari depan mezbah TUHAN setelah berlutut dengan menadahkan tangannya ke langit.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 55, 'Maka berdirilah ia dan memberkati segenap jemaah Israel dengan suara nyaring, katanya:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 56, '"Terpujilah TUHAN yang memberikan tempat perhentian kepada umat-Nya Israel tepat seperti yang difirmankan-Nya; dari segala yang baik, yang telah dijanjikan-Nya dengan perantaraan Musa, hamba-Nya, tidak ada satupun yang tidak dipenuhi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 57, 'Kiranya TUHAN, Allah kita, menyertai kita sebagaimana Ia telah menyertai nenek moyang kita, janganlah Ia meninggalkan kita dan janganlah Ia membuangkan kita,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 58, 'tetapi hendaklah dicondongkan-Nya hati kita kepada-Nya untuk hidup menurut segala jalan yang ditunjukkan-Nya, dan untuk tetap mengikuti segala perintah-Nya dan ketetapan-Nya dan peraturan-Nya yang telah diperintahkan-Nya kepada nenek moyang kita.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 59, 'Hendaklah perkataan yang telah kupohonkan tadi di hadapan TUHAN, dekat pada TUHAN, Allah kita, siang dan malam, supaya Ia memberikan keadilan kepada hamba-Nya dan kepada umat-Nya Israel menurut yang perlu pada setiap hari,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 8, 60, 'supaya segala bangsa di bumi tahu, bahwa Tuhanlah Allah, dan tidak ada yang lain,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 1, 'Ketika Salomo selesai mendirikan rumah TUHAN dan istana raja dan membuat segala yang diinginkannya,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 2, 'maka TUHAN menampakkan diri kepada Salomo untuk kedua kalinya seperti Ia sudah menampakkan diri kepadanya di Gibeon.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 3, 'Firman TUHAN kepadanya: "Telah Kudengar doa dan permohonanmu yang kausampaikan ke hadapan-Ku; Aku telah menguduskan rumah yang kaudirikan ini untuk membuat nama-Ku tinggal di situ sampai selama-lamanya, maka mata-Ku dan hati-Ku akan ada di situ sepanjang masa.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 4, 'Mengenai engkau, jika engkau hidup di hadapan-Ku sama seperti Daud, ayahmu, dengan tulus hati dan dengan benar, dan berbuat sesuai dengan segala yang Kuperintahkan kepadamu, dan jika engkau tetap mengikuti segala ketetapan dan peraturan-Ku,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 5, 'maka Aku akan meneguhkan takhta kerajaanmu atas Israel untuk selama-lamanya seperti yang telah Kujanjikan kepada Daud, ayahmu, dengan berkata: Keturunanmu takkan terputus dari takhta kerajaan Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 6, 'Tetapi jika kamu ini dan anak-anakmu berbalik dari pada-Ku dan tidak berpegang pada segala perintah dan ketetapan-Ku yang telah Kuberikan kepadamu, dan pergi beribadah kepada allah lain dan sujud menyembah kepadanya,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 7, 'maka Aku akan melenyapkan orang Israel dari atas tanah yang telah Kuberikan kepada mereka, dan rumah yang telah Kukuduskan bagi nama-Ku itu, akan Kubuang dari hadapan-Ku, maka Israel akan menjadi kiasan dan sindiran di antara segala bangsa.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 8, 'Dan rumah ini akan menjadi reruntuhan, sehingga setiap orang yang lewat akan tertegun, bersuit, dan berkata: Apakah sebabnya TUHAN berbuat yang demikian kepada negeri ini dan kepada rumah ini?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 9, 'Maka orang akan berkata: Sebab mereka meninggalkan TUHAN, Allah mereka, yang membawa nenek moyang mereka keluar dari tanah Mesir dan sebab mereka berpegang pada allah lain dan sujud menyembah kepadanya dan beribadah kepadanya. Itulah sebabnya TUHAN mendatangkan segala malapetaka ini ke atas mereka."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 10, 'Setelah lewat dua puluh tahun selesailah Salomo mendirikan kedua rumah itu, yakni rumah TUHAN dan istana raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 11, 'Oleh karena Hiram, raja Tirus, telah membantu Salomo dengan kayu aras, kayu sanobar, dan emas, sebanyak yang dikehendakinya, maka pada waktu itu raja Salomo memberikan kepada Hiram dua puluh kota di negeri Galilea.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 12, 'Tetapi ketika Hiram datang dari Tirus untuk melihat-lihat kota-kota yang diberikan Salomo kepadanya itu, maka semuanya kurang menyenangkan hatinya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 13, 'Sebab itu ia berkata: "Macam apakah kota-kota yang telah kauberikan kepadaku ini, hai saudaraku?" Maka orang menyebutkannya tanah Kabul sampai hari ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 14, 'Adapun Hiram telah mengirim kepada raja seratus dua puluh talenta emas.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 15, 'Beginilah hal orang-orang rodi yang telah dikerahkan oleh raja Salomo. Mereka dikerahkan untuk mendirikan rumah TUHAN, dan istana raja, dan Milo, dan tembok Yerusalem, dan juga untuk memperkuat Hazor, Megido dan Gezer.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 16, '?Sebab Firaun, raja Mesir, telah maju berperang dan merebut Gezer, lalu membakarnya dan membunuh orang-orang Kanaan yang diam di kota itu. Kemudian diberikannya kota itu sebagai hadiah kawin kepada anaknya, isteri Salomo,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 17, 'maka Salomo memperkuat Gezer?.Lagipula ada orang rodi yang dikerahkan di Bet-Horon Hilir,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 18, 'di Baalat, di Tamar di padang gurun, yang ada di negeri Yehuda,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 19, 'dan di segala kota perbekalan kepunyaan Salomo, di kota-kota tempat kereta, di kota-kota tempat orang berkuda dan di mana saja Salomo menginginkan mendirikan sesuatu di Yerusalem atau di gunung Libanon, atau di segenap negeri kekuasaannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 20, 'Semua orang yang masih tinggal dari orang Amori, orang Het, orang Feris, orang Hewi dan orang Yebus, yang tidak termasuk orang Israel,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 21, 'yakni mereka yang masih tinggal di negeri itu dari keturunan bangsa-bangsa itu dan yang tidak dapat ditumpas oleh orang Israel, merekalah yang dikerahkan Salomo untuk menjadi budak rodi; demikianlah mereka sampai hari ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 22, 'Tetapi orang Israel tidak ada yang dijadikan budak oleh Salomo, melainkan mereka menjadi prajurit, pegawai, pembesar, perwira, atau panglima atas pasukan kereta dan pasukan berkuda.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 23, 'Inilah pemimpin-pemimpin umum yang mengepalai pekerjaan Salomo: lima ratus lima puluh orang memerintah rakyat yang melakukan pekerjaan itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 24, 'Segera sesudah anak Firaun pindah dari kota Daud ke rumah yang telah didirikan Salomo baginya, Salomopun mendirikan Milo.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 25, 'Tiga kali setahun Salomo mempersembahkan korban-korban bakaran dan korban-korban keselamatan di atas mezbah yang didirikannya bagi TUHAN, dan ia membakar korban api-apiannya di hadapan TUHAN. Demikianlah ia menyelesaikan rumah itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 26, 'Raja Salomo membuat juga kapal-kapal di Ezion-Geber yang ada di dekat Elot, di tepi Laut Teberau, di tanah Edom.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 27, 'Dengan kapal-kapal itu Hiram mengirim anak buahnya, yaitu anak-anak kapal yang tahu tentang laut, menyertai anak buah Salomo.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 9, 28, 'Mereka sampai ke Ofir dan dari sana mereka mengambil empat ratus dua puluh talenta emas, yang mereka bawa kepada raja Salomo.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 1, 'Ketika ratu negeri Syeba mendengar kabar tentang Salomo, berhubung dengan nama TUHAN, maka datanglah ia hendak mengujinya dengan teka-teki.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 2, 'Ia datang ke Yerusalem dengan pasukan pengiring yang sangat besar, dengan unta-unta yang membawa rempah-rempah, sangat banyak emas dan batu permata yang mahal-mahal. Setelah ia sampai kepada Salomo, dikatakannyalah segala yang ada dalam hatinya kepadanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 3, 'Dan Salomo menjawab segala pertanyaan ratu itu; bagi raja tidak ada yang tersembunyi, yang tidak dapat dijawabnya untuk ratu itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 4, 'Ketika ratu negeri Syeba melihat segala hikmat Salomo dan rumah yang telah didirikannya,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 5, 'makanan di mejanya, cara duduk pegawai-pegawainya, cara pelayan-pelayannya melayani dan berpakaian, minumannya dan korban bakaran yang biasa dipersembahkannya di rumah TUHAN, maka tercenganglah ratu itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 6, 'Dan ia berkata kepada raja: "Benar juga kabar yang kudengar di negeriku tentang engkau dan tentang hikmatmu,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 7, 'tetapi aku tidak percaya perkataan-perkataan itu sampai aku datang dan melihatnya dengan mataku sendiri; sungguh setengahnyapun belum diberitahukan kepadaku; dalam hal hikmat dan kemakmuran, engkau melebihi kabar yang kudengar.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 8, 'Berbahagialah para isterimu, berbahagialah para pegawaimu ini yang selalu melayani engkau dan menyaksikan hikmatmu!', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 9, 'Terpujilah TUHAN, Allahmu, yang telah berkenan kepadamu sedemikian, hingga Ia mendudukkan engkau di atas takhta kerajaan Israel! Karena TUHAN mengasihi orang Israel untuk selama-lamanya, maka Ia telah mengangkat engkau menjadi raja untuk melakukan keadilan dan kebenaran."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 10, 'Lalu diberikannyalah kepada raja seratus dua puluh talenta emas, dan sangat banyak rempah-rempah dan batu permata yang mahal-mahal; tidak pernah datang lagi begitu banyak rempah-rempah seperti yang diberikan ratu negeri Syeba kepada raja Salomo itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 11, 'Lagipula kapal-kapal Hiram, yang mengangkut emas dari Ofir, membawa dari Ofir sangat banyak kayu cendana dan batu permata yang mahal-mahal.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 12, 'Raja mengerjakan kayu cendana itu menjadi langkan untuk rumah TUHAN dan untuk istana raja, dan juga menjadi kecapi dan gambus untuk para penyanyi; kayu cendana seperti itu tidak datang dan tidak kelihatan lagi sampai hari ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 13, 'Raja Salomo memberikan kepada ratu negeri Syeba segala yang dikehendakinya dan yang dimintanya, selain apa yang telah diberikannya kepadanya sebagaimana layak bagi raja Salomo. Lalu ratu itu berangkat pulang ke negerinya bersama-sama dengan pegawai-pegawainya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 14, 'Adapun emas, yang dibawa kepada Salomo dalam satu tahun ialah seberat enam ratus enam puluh enam talenta,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 15, 'belum terhitung yang didapat dari saudagar-saudagar dan dari pedagang-pedagang dan dari semua raja Arab dan bupati-bupati di negeri itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 16, 'Raja Salomo membuat dua ratus perisai besar dari emas tempaan, enam ratus syikal emas dipakainya untuk setiap perisai besar;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 17, 'ia membuat juga tiga ratus perisai kecil dari emas tempaan, tiga mina emas dipakainya untuk setiap perisai kecil; lalu raja menaruh semuanya itu di dalam gedung "Hutan Libanon".', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 18, 'Juga raja membuat takhta besar dari gading, yang disalutnya dengan emas tua.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 19, 'Takhta itu enam tingkatnya; pada takhta itu ada di sebelah belakang sebuah kepala bundar, dan pada kedua sisi tempat duduk ada kelek-kelek. Di samping kelek-kelek itu berdiri dua singa,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 20, 'sedang dua belas singa berdiri di atas keenam tingkat itu sebelah-menyebelah; belum pernah diperbuat yang demikian bagi sesuatu kerajaan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 21, 'Segala perkakas minuman raja Salomo dari emas dan segala barang di gedung "Hutan Libanon" itu dari emas murni; tidak ada barang perak, sebab orang menganggap perak tidak berharga pada zaman Salomo.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 22, 'Sebab di laut raja mempunyai kapal-kapal Tarsis bergabung dengan kapal-kapal Hiram; dan sekali tiga tahun kapal-kapal Tarsis itu datang membawa emas dan perak serta gading; juga kera dan burung merak.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 23, 'Raja Salomo melebihi semua raja di bumi dalam hal kekayaan dan hikmat.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 24, 'Seluruh bumi berikhtiar menghadap Salomo untuk menyaksikan hikmat yang telah ditaruh Allah di dalam hatinya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 25, 'Mereka datang masing-masing membawa persembahannya, yakni barang-barang perak dan barang-barang emas, pakaian, senjata, rempah-rempah, kuda dan bagal, dan begitulah tahun demi tahun.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 26, 'Salomo mengumpulkan juga kereta dan orang berkuda, sehingga ia mempunyai seribu empat ratus kereta dan dua belas ribu orang berkuda, yang semuanya ditempatkan dalam kota-kota kereta dan dekat raja di Yerusalem.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 27, 'Raja membuat banyaknya perak di Yerusalem sama seperti batu, dan banyaknya pohon kayu aras sama seperti pohon ara yang tumbuh di Daerah Bukit.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 28, 'Kuda untuk Salomo didatangkan dari Misraim dan dari Kewe; saudagar-saudagar raja membelinya dari Kewe dengan harga pasar.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 10, 29, 'Sebuah kereta yang didatangkan dari Misraim berharga sampai enam ratus syikal perak, dan seekor kuda sampai seratus lima puluh syikal; dan begitu juga melalui mereka dikeluarkan semuanya itu kepada semua raja orang Het dan kepada raja-raja Aram.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 1, 'Adapun raja Salomo mencintai banyak perempuan asing. Di samping anak Firaun ia mencintai perempuan-perempuan Moab, Amon, Edom, Sidon dan Het,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 2, 'padahal tentang bangsa-bangsa itu TUHAN telah berfirman kepada orang Israel: "Janganlah kamu bergaul dengan mereka dan merekapun janganlah bergaul dengan kamu, sebab sesungguhnya mereka akan mencondongkan hatimu kepada allah-allah mereka." Hati Salomo telah terpaut kepada mereka dengan cinta.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 3, 'Ia mempunyai tujuh ratus isteri dari kaum bangsawan dan tiga ratus gundik; isteri-isterinya itu menarik hatinya dari pada TUHAN.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 4, 'Sebab pada waktu Salomo sudah tua, isteri-isterinya itu mencondongkan hatinya kepada allah-allah lain, sehingga ia tidak dengan sepenuh hati berpaut kepada TUHAN, Allahnya, seperti Daud, ayahnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 5, 'Demikianlah Salomo mengikuti Asytoret, dewi orang Sidon, dan mengikuti Milkom, dewa kejijikan sembahan orang Amon,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 6, 'dan Salomo melakukan apa yang jahat di mata TUHAN, dan ia tidak dengan sepenuh hati mengikuti TUHAN, seperti Daud, ayahnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 7, 'Pada waktu itu Salomo mendirikan bukit pengorbanan bagi Kamos, dewa kejijikan sembahan orang Moab, di gunung di sebelah timur Yerusalem dan bagi Molokh, dewa kejijikan sembahan bani Amon.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 8, 'Demikian juga dilakukannya bagi semua isterinya, orang-orang asing itu, yang mempersembahkan korban ukupan dan korban sembelihan kepada allah-allah mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 9, 'Sebab itu TUHAN menunjukkan murka-Nya kepada Salomo, sebab hatinya telah menyimpang dari pada TUHAN, Allah Israel, yang telah dua kali menampakkan diri kepadanya,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 10, 'dan yang telah memerintahkan kepadanya dalam hal ini supaya jangan mengikuti allah-allah lain, akan tetapi ia tidak berpegang pada yang diperintahkan TUHAN.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 11, 'Lalu berfirmanlah TUHAN kepada Salomo: "Oleh karena begitu kelakuanmu, yakni engkau tidak berpegang pada perjanjian dan segala ketetapan-Ku yang telah Kuperintahkan kepadamu, maka sesungguhnya Aku akan mengoyakkan kerajaan itu dari padamu dan akan memberikannya kepada hambamu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 12, 'Hanya, pada waktu hidupmu ini Aku belum mau melakukannya oleh karena Daud, ayahmu; dari tangan anakmulah Aku akan mengoyakkannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 13, 'Namun demikian, kerajaan itu tidak seluruhnya akan Kukoyakkan dari padanya, satu suku akan Kuberikan kepada anakmu oleh karena hamba-Ku Daud dan oleh karena Yerusalem yang telah Kupilih."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 14, 'Kemudian TUHAN membangkitkan seorang lawan Salomo, yakni Hadad, orang Edom; ia dari keturunan raja Edom.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 15, 'Sesudah Daud memukul kalah orang Edom, maka panglima Yoab pergi menguburkan orang-orang yang mati terbunuh, lalu menewaskan semua laki-laki di Edom;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 16, 'enam bulan lamanya Yoab diam di sana dengan seluruh Israel, sampai dilenyapkannya semua laki-laki di Edom.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 17, 'Tetapi Hadad melarikan diri bersama-sama dengan beberapa orang Edom dari pegawai-pegawai ayahnya, dan mengungsi ke Mesir; adapun Hadad itu masih sangat muda.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 18, 'Mereka berangkat dari Midian, lalu sampai ke Paran; mereka membawa beberapa orang dari Paran, lalu mereka sampai ke Mesir kepada Firaun, raja Mesir. Ia ini memberikan rumah kepada Hadad, menentukan belanjanya dan menyerahkan sebidang tanah kepadanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 19, 'Hadad demikian disayangi Firaun, sehingga diberikannya kepadanya seorang isteri, yakni adik isterinya sendiri, adik permaisuri Tahpenes.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 20, 'Lalu adik Tahpenes itu melahirkan baginya seorang anak laki-laki, Genubat namanya, dan Tahpenes menyapih dia di istana Firaun, sehingga Genubat ada di istana Firaun di tengah-tengah anak-anak Firaun sendiri.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 21, 'Ketika didengar Hadad di Mesir, bahwa Daud telah mendapat perhentian bersama-sama dengan nenek moyangnya dan bahwa panglima Yoab sudah mati juga, maka berkatalah Hadad kepada Firaun: "Biarkanlah aku pergi ke negeriku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 22, 'Lalu bertanyalah Firaun kepadanya: "Tetapi kekurangan apakah engkau padaku ini, maka engkau tiba-tiba berniat pergi ke negerimu?" Jawabnya: "Aku tidak kekurangan apapun, namun demikian, biarkanlah juga aku pergi."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 23, 'Allah membangkitkan pula seorang lawan Salomo, yakni Rezon bin Elyada, yang telah melarikan diri dari tuannya, yakni Hadadezer, raja Zoba.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 24, 'Ia mengumpulkan orang-orang, lalu menjadi kepala gerombolan. Ketika Daud hendak membunuh mereka, maka pergilah mereka ke Damsyik; mereka diam di sana dan di situlah mereka mengangkat Rezon menjadi raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 25, 'Dialah yang menjadi lawan Israel sepanjang umur Salomo; ia mendatangkan malapetaka sama seperti Hadad. Ia muak akan orang Israel dan menjadi raja atas Aram.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 26, 'Juga Yerobeam bin Nebat, seorang Efraim dari Zereda, seorang pegawai Salomo, nama ibunya Zerua, seorang janda, memberontak terhadap raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 27, 'Inilah alasannya, mengapa ia memberontak terhadap raja: Salomo mendirikan Milo, dan ia menutup tembusan tembok kota Daud, ayahnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 28, 'Yerobeam adalah seorang tangkas; ketika Salomo melihat, bahwa orang muda itu seorang yang rajin bekerja, maka ditempatkannyalah dia mengawasi semua pekerja wajib dari keturunan Yusuf.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 29, 'Pada waktu itu, ketika Yerobeam keluar dari Yerusalem, nabi Ahia, orang Silo itu, mendatangi dia di jalan dengan berselubungkan kain baru. Dan hanya mereka berdua ada di padang.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 30, 'Ahia memegang kain baru yang di badannya, lalu dikoyakkannya menjadi dua belas koyakan;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 31, 'dan ia berkata kepada Yerobeam: "Ambillah bagimu sepuluh koyakan, sebab beginilah firman TUHAN, Allah Israel: Sesungguhnya Aku akan mengoyakkan kerajaan itu dari tangan Salomo dan akan memberikan kepadamu sepuluh suku.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 32, 'Tetapi satu suku akan tetap padanya oleh karena hamba-Ku Daud dan oleh karena Yerusalem, kota yang Kupilih itu dari segala suku Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 33, 'Sebabnya ialah karena ia telah meninggalkan Aku dan sujud menyembah kepada Asytoret, dewi orang Sidon, kepada Kamos, allah orang Moab dan kepada Milkom, allah bani Amon, dan ia tidak hidup menurut jalan yang Kutunjukkan dengan melakukan apa yang benar di mata-Ku dan dengan tetap mengikuti segala ketetapan dan peraturan-Ku, seperti Daud, ayahnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 34, 'Bukan dari tangannya akan Kuambil seluruh kerajaan itu; Aku akan membiarkan dia tetap menjadi raja seumur hidupnya, oleh karena hamba-Ku Daud yang telah Kupilih dan yang tetap mengikuti segala perintah dan ketetapan-Ku.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 35, 'Tetapi dari tangan anaknyalah Aku akan mengambil kerajaan itu dan akan memberikannya kepadamu, yakni sepuluh suku.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 36, 'Dan kepada anaknya akan Kuberikan satu suku, supaya hamba-Ku Daud selalu mempunyai keturunan di hadapan-Ku di Yerusalem, kota yang Kupilih bagi-Ku supaya nama-Ku tinggal di sana.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 37, 'Maka engkau ini akan Kuambil, supaya engkau memerintah atas segala yang dikehendaki hatimu dan menjadi raja atas Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 38, 'Dan jika engkau mendengarkan segala yang Kuperintahkan kepadamu dan hidup menurut jalan yang Kutunjukkan dan melakukan apa yang benar di mata-Ku dengan tetap mengikuti segala ketetapan dan perintah-Ku seperti yang telah dilakukan oleh hamba-Ku Daud, maka Aku akan menyertai engkau dan Aku akan membangunkan bagimu suatu keluarga yang teguh seperti yang Kubangunkan bagi Daud, dan Aku akan memberikan orang Israel kepadamu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 39, 'Dan untuk itu Aku akan merendahkan keturunan Daud, tetapi bukan untuk selamanya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 40, 'Lalu Salomo berikhtiar membunuh Yerobeam, tetapi Yerobeam bangkit dan melarikan diri ke Mesir, kepada Sisak, raja Mesir, dan di Mesirlah ia tinggal sampai Salomo mati.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 41, 'Selebihnya dari riwayat Salomo dan segala yang dilakukannya dan hikmatnya, bukankah semuanya itu tertulis dalam kitab riwayat Salomo?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 42, 'Lamanya Salomo memerintah di Yerusalem atas seluruh Israel ialah empat puluh tahun.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 11, 43, 'Kemudian Salomo mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di kota Daud, ayahnya. Maka Rehabeam, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 1, 'Kemudian Rehabeam pergi ke Sikhem, sebab seluruh Israel telah datang ke Sikhem untuk menobatkan dia menjadi raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 2, 'Segera sesudah hal itu kedengaran kepada Yerobeam bin Nebat?pada waktu itu dia masih ada di Mesir, sebab ia melarikan diri ke sana dari hadapan raja Salomo?maka kembalilah ia dari Mesir.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 3, 'Orang menyuruh memanggil dia, lalu datanglah Yerobeam dengan segenap jemaah Israel dan berkata kepada Rehabeam:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 4, '"Ayahmu telah memberatkan tanggungan kami, maka sekarang ringankanlah pekerjaan yang sukar yang dibebankan ayahmu dan tanggungan yang berat yang dipikulkannya kepada kami, supaya kami menjadi hambamu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 5, 'Tetapi ia menjawab mereka: "Pergilah sampai lusa, kemudian kembalilah kepadaku." Lalu pergilah rakyat itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 6, 'Sesudah itu Rehabeam meminta nasihat dari para tua-tua yang selama hidup Salomo mendampingi Salomo, ayahnya, katanya: "Apakah nasihatmu untuk menjawab rakyat itu?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 7, 'Mereka berkata: "Jika hari ini engkau mau menjadi hamba rakyat, mau mengabdi kepada mereka dan menjawab mereka dengan kata-kata yang baik, maka mereka menjadi hamba-hambamu sepanjang waktu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 8, 'Tetapi ia mengabaikan nasihat yang diberikan para tua-tua itu, lalu ia meminta nasihat kepada orang-orang muda yang sebaya dengan dia dan yang mendampinginya,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 9, 'katanya kepada mereka: "Apakah nasihatmu, supaya kita dapat menjawab rakyat yang mengatakan kepadaku: Ringankanlah tanggungan yang dipikulkan kepada kami oleh ayahmu?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 10, 'Lalu orang-orang muda yang sebaya dengan dia itu berkata: "Beginilah harus kaukatakan kepada rakyat yang telah berkata kepadamu: Ayahmu telah memberatkan tanggungan kami, tetapi engkau ini, berilah keringanan kepada kami?beginilah harus kaukatakan kepada mereka: Kelingkingku lebih besar dari pada pinggang ayahku!', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 11, 'Maka sekarang, ayahku telah membebankan kepada kamu tanggungan yang berat, tetapi aku akan menambah tanggungan kamu; ayahku telah menghajar kamu dengan cambuk, tetapi aku akan menghajar kamu dengan cambuk yang berduri besi."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 12, 'Pada hari lusanya datanglah Yerobeam dengan segenap rakyat kepada Rehabeam, seperti yang dikatakan raja: "Kembalilah kepadaku pada hari lusa."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 13, 'Raja menjawab rakyat itu dengan keras; ia telah mengabaikan nasihat yang diberikan para tua-tua kepadanya;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 14, 'ia mengatakan kepada mereka menurut nasihat orang-orang muda: "Ayahku telah memberatkan tanggungan kamu, tetapi aku akan menambah tanggunganmu itu; ayahku telah menghajar kamu dengan cambuk, tetapi aku akan menghajar kamu dengan cambuk yang berduri besi."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 15, 'Jadi raja tidak mendengarkan permintaan rakyat, sebab hal itu merupakan perubahan yang disebabkan TUHAN, supaya TUHAN menepati firman yang diucapkan-Nya dengan perantaraan Ahia, orang Silo, kepada Yerobeam bin Nebat.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 16, 'Setelah seluruh Israel melihat, bahwa raja tidak mendengarkan permintaan mereka, maka rakyat menjawab raja: "Bagian apakah kita dapat dari pada Daud? Kita tidak memperoleh warisan dari anak Isai itu! Ke kemahmu, hai orang Israel! Uruslah sekarang rumahmu sendiri, hai Daud!" Maka pergilah orang Israel ke kemahnya,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 17, 'sehingga Rehabeam menjadi raja hanya atas orang Israel yang diam di kota-kota Yehuda.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 18, 'Kemudian raja Rehabeam mengutus Adoram yang menjadi kepala rodi, tetapi seluruh Israel melontari dia dengan batu, sehingga mati, bahkan raja Rehabeam hampir-hampir tidak dapat menaiki keretanya untuk melarikan diri ke Yerusalem.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 19, 'Demikianlah mulanya orang Israel memberontak terhadap keluarga Daud sampai hari ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 20, 'Segera sesudah seluruh Israel mendengar, bahwa Yerobeam sudah pulang, maka mereka menyuruh memanggil dia ke pertemuan jemaah, lalu mereka menobatkan dia menjadi raja atas seluruh Israel. Tidak ada lagi yang mengikuti keluarga Daud selain dari suku Yehuda saja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 21, 'Ketika Rehabeam datang ke Yerusalem, ia mengumpulkan segenap kaum Yehuda dan suku Benyamin, seratus delapan puluh ribu teruna yang sanggup berperang untuk memerangi kaum Israel dengan maksud mengembalikan kerajaan itu kepada Rehabeam, anak Salomo.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 22, 'Tetapi datanglah firman Allah kepada Semaya, abdi Allah, demikian:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 23, '"Katakanlah kepada Rehabeam, anak Salomo, raja Yehuda, dan kepada segenap kaum Yehuda dan Benyamin dan kepada selebihnya dari bangsa itu:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 24, 'Beginilah firman TUHAN: Janganlah kamu maju dan janganlah kamu berperang melawan saudara-saudaramu, orang Israel. Pulanglah masing-masing ke rumahnya, sebab Akulah yang menyebabkan hal ini terjadi." Maka mereka mendengarkan firman TUHAN dan pergilah mereka pulang sesuai dengan firman TUHAN itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 25, 'Kemudian Yerobeam memperkuat Sikhem di pegunungan Efraim, lalu diam di sana. Ia keluar dari sana, lalu memperkuat Pnuel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 26, 'Maka berkatalah Yerobeam dalam hatinya: "Kini mungkin kerajaan itu kembali kepada keluarga Daud.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 27, 'Jika bangsa itu pergi mempersembahkan korban sembelihan di rumah TUHAN di Yerusalem, maka tentulah hati bangsa ini akan berbalik kepada tuan mereka, yaitu Rehabeam, raja Yehuda, kemudian mereka akan membunuh aku dan akan kembali kepada Rehabeam, raja Yehuda."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 28, 'Sesudah menimbang-nimbang, maka raja membuat dua anak lembu jantan dari emas dan ia berkata kepada mereka: "Sudah cukup lamanya kamu pergi ke Yerusalem. Hai Israel, lihatlah sekarang allah-allahmu, yang telah menuntun engkau keluar dari tanah Mesir."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 29, 'Lalu ia menaruh lembu yang satu di Betel dan yang lain ditempatkannya di Dan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 30, 'Maka hal itu menyebabkan orang berdosa, sebab rakyat pergi ke Betel menyembah patung yang satu dan ke Dan menyembah patung yang lain.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 31, 'Ia membuat juga kuil-kuil di atas bukit-bukit pengorbanan, dan mengangkat imam-imam dari kalangan rakyat yang bukan dari bani Lewi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 32, 'Kemudian Yerobeam menentukan suatu hari raya pada hari yang kelima belas bulan kedelapan, sama seperti hari raya yang di Yehuda, dan ia sendiri naik tangga mezbah itu. Begitulah dibuatnya di Betel, yakni ia mempersembahkan korban kepada anak-anak lembu yang telah dibuatnya itu, dan ia menugaskan di Betel imam-imam bukit pengorbanan yang telah diangkatnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 12, 33, 'Ia naik tangga mezbah yang dibuatnya di Betel itu pada hari yang kelima belas dalam bulan yang kedelapan, dalam bulan yang telah direncanakannya dalam hatinya sendiri; ia menentukan suatu hari raya bagi orang Israel dan ia naik tangga mezbah itu untuk membakar korban.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 1, 'Sedang Yerobeam berdiri di atas mezbah itu sambil membakar korban, maka atas perintah TUHAN datanglah seorang abdi Allah dari Yehuda ke Betel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 2, 'Lalu atas perintah TUHAN berserulah orang itu terhadap mezbah itu, katanya: "Hai mezbah, hai mezbah! Beginilah firman TUHAN: Bahwasanya seorang anak akan lahir pada keluarga Daud, Yosia namanya; ia akan menyembelih di atasmu imam-imam bukit pengorbanan yang membakar korban di atasmu, juga tulang-tulang manusia akan dibakar di atasmu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 3, 'Pada waktu itu juga ia memberitahukan suatu tanda ajaib, katanya: "Inilah tanda ajaib, bahwa TUHAN telah berfirman: Bahwasanya mezbah itu akan pecah, sehingga tercurah abu yang di atasnya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 4, 'Demi raja Yerobeam mendengar perkataan abdi Allah yang diserukannya terhadap mezbah di Betel itu, ia mengulurkan tangannya dari atas mezbah dan berkata: "Tangkaplah dia!" Tetapi tangan yang diulurkannya terhadap orang itu menjadi kejang, sehingga tidak dapat ditariknya kembali.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 5, 'Mezbah itupun pecahlah, sehingga abu yang di atasnya tercurah, sesuai dengan tanda ajaib yang diberitahukan abdi Allah itu atas perintah TUHAN.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 6, 'Lalu berbicaralah raja dan berkata kepada abdi Allah itu: "Mohonkanlah belas kasihan TUHAN, Allahmu, dan berdoalah untukku, supaya tanganku dapat kembali." Dan abdi Allah itu memohonkan belas kasihan TUHAN, maka tangan raja itu dapat kembali dan menjadi seperti semula.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 7, 'Kemudian berbicaralah raja kepada abdi Allah itu: "Marilah bersama-sama dengan aku ke rumah, segarkan badanmu, sesudah itu aku hendak memberikan suatu hadiah kepadamu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 8, 'Tetapi abdi Allah itu berkata kepada raja: "Sekalipun setengah dari istanamu kauberikan kepadaku, aku tidak mau singgah kepadamu; juga aku tidak mau makan roti atau minum air di tempat ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 9, 'Sebab beginilah diperintahkan kepadaku atas firman TUHAN: Jangan makan roti atau minum air dan jangan kembali melalui jalan yang telah kautempuh itu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 10, 'Lalu pergilah ia melalui jalan lain dan tidak kembali melalui jalan yang telah diambilnya untuk datang ke Betel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 11, 'Di Betel diam seorang nabi tua. Anak-anaknya datang menceritakan kepadanya segala perbuatan yang dilakukan abdi Allah pada hari itu di Betel. Mereka menceriterakan juga kepada ayah mereka perkataan yang dikatakannya kepada raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 12, 'Kemudian ayah mereka bertanya: "Dari jalan manakah ia pergi?" Lalu anak-anaknya menunjukkan kepadanya jalan yang diambil abdi Allah yang datang dari Yehuda itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 13, 'Ia berkata kepada anak-anaknya: "Pelanai keledai bagiku!" Mereka memelanai keledai baginya, lalu ia menunggangnya', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 14, 'dan pergi mengikuti abdi Allah itu dan mendapatinya duduk di bawah sebuah pohon besar. Ia bertanya kepadanya: "Engkaukah abdi Allah yang telah datang dari Yehuda?" Jawabnya: "Ya, akulah itu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 15, 'Katanya kepadanya: "Marilah bersama-sama aku ke rumah untuk makan roti."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 16, 'Tetapi jawabnya: "Aku tidak dapat kembali bersama-sama engkau dan singgah kepadamu; aku tidak dapat makan roti atau minum air bersama-sama engkau di tempat ini,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 17, 'sebab telah diperintahkan kepadaku atas firman TUHAN: Jangan makan roti atau minum air di sana. Jangan berjalan pulang melalui jalan yang telah kauambil itu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 18, 'Lalu jawabnya kepadanya: "Akupun seorang nabi juga seperti engkau, dan atas perintah TUHAN seorang malaikat telah berkata kepadaku: Bawa dia pulang bersama-sama engkau ke rumahmu, supaya ia makan roti dan minum air." Tetapi ia berbohong kepadanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 19, 'Kemudian orang itu kembali bersama-sama dia, lalu makan roti dan minum air di rumahnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 20, 'Sedang mereka duduk menghadapi meja, datanglah firman TUHAN kepada nabi yang telah membawa dia pulang.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 21, 'Ia berseru kepada abdi Allah yang telah datang dari Yehuda: "Beginilah firman TUHAN: Karena engkau telah memberontak terhadap titah TUHAN dan tidak berpegang pada segala perintah yang diperintahkan kepadamu oleh TUHAN, Allahmu,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 22, 'tetapi kembali dan makan roti dan minum air di tempat ini walaupun Ia telah berfirman kepadamu: Jangan makan roti atau minum air, ?maka mayatmu tidak akan masuk ke dalam kubur nenek moyangmu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 23, 'Setelah orang itu makan roti dan minum air, dipelanailah keledai baginya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 24, 'Orang itu pergi, tetapi di tengah jalan ia diserang seekor singa dan mati diterkam. Mayatnya tercampak di jalan dan keledai itu berdiri di sampingnya; singa itupun berdiri di samping mayat itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 25, 'Orang-orang yang lewat melihat mayat itu tercampak di jalan dan singa berdiri di sampingnya. Dan mereka menceriterakannya di kota tempat kediaman nabi tua itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 26, 'Ketika hal itu kedengaran kepada nabi yang telah membujuk dia berbalik kembali, ia berkata: "Dialah abdi Allah yang telah memberontak terhadap titah TUHAN. TUHAN menyerahkan dia kepada singa, yang mencabik dan membunuhnya sesuai dengan firman TUHAN yang diucapkan-Nya kepadanya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 27, 'Lalu berbicaralah ia kepada anak-anaknya: "Pelanailah keledai bagiku." Dan mereka memelanainya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 28, 'Kemudian ia pergi dan menemukan mayat orang itu tercampak di jalan, sedang keledai dan singa berdiri di sampingnya. Singa itu tidak memakan mayat itu dan tidak mencabik keledai itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 29, 'Nabi tua itu mengangkat mayat abdi Allah itu, menaruhnya ke atas keledai dan membawanya kembali ke kotanya sendiri untuk diratapi dan dikuburkan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 30, 'Mayat orang itu dikuburkannya di dalam kuburnya sendiri, maka diratapilah dia: "Wahai, saudaraku!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 31, 'Setelah ia menguburkannya, ia berkata kepada anak-anaknya: "Kalau aku mati, kuburkanlah aku dalam kubur ini bersama dengan abdi Allah itu, dan taruhlah tulang-tulangku di sisi tulang-tulangnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 32, 'Sebab perkataan yang atas perintah TUHAN telah diserukannya terhadap mezbah yang di Betel itu dan terhadap segala kuil di bukit-bukit pengorbanan yang di kota-kota Samaria akan betul-betul terjadi."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 33, 'Sesudah peristiwa inipun Yerobeam tidak berbalik dari kelakuannya yang jahat itu, tetapi mengangkat pula imam-imam dari kalangan rakyat untuk bukit-bukit pengorbanan. Siapa yang mau saja, ditahbiskannya menjadi imam untuk bukit-bukit pengorbanan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 13, 34, 'Dan tindakan itu menjadi dosa bagi keluarga Yerobeam, sehingga mereka dilenyapkan dan dipunahkan dari muka bumi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 1, 'Pada waktu itu Abia, anak Yerobeam, jatuh sakit.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 2, 'Lalu Yerobeam berkata kepada isterinya: "Berkemaslah! Menyamarlah, supaya jangan diketahui orang, bahwa engkau isteri Yerobeam, dan pergilah ke Silo. Bukankah di sana tinggal nabi Ahia! Dialah yang telah mengatakan tentang aku, bahwa aku akan menjadi raja atas bangsa ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 3, 'Bawalah sepuluh roti, kue kismis, dan sebuli-buli air madu, dan pergilah kepadanya. Dia akan memberitahukan kepadamu, apa yang akan terjadi dengan anak ini."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 4, 'Isteri Yerobeam berbuat demikian. Ia berkemas, pergi ke Silo dan masuk ke rumah Ahia. Ahia tidak dapat melihat lagi, sebab matanya sudah kabur karena ia sudah tua.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 5, 'Tetapi TUHAN telah berfirman kepada Ahia: "Bahwasanya isteri Yerobeam datang untuk menanyakan kepadamu perihal anaknya, sebab anak itu sedang sakit. Begini-begini harus kaukatakan kepadanya." Ketika perempuan itu masuk, berbuatlah ia seolah-olah ia orang lain.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 6, 'Tetapi segera sesudah Ahia mendengar bunyi langkah perempuan itu, sementara melangkah masuk pintu, berkatalah ia: "Masuklah, hai isteri Yerobeam! Mengapakah engkau berbuat seolah-olah engkau orang lain? Aku disuruh menyampaikan pesan yang keras kepadamu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 7, 'Pergilah, katakan kepada Yerobeam: Beginilah firman TUHAN, Allah Israel: Aku telah meninggikan engkau dari tengah-tengah bangsa itu, dan mengangkat engkau menjadi raja atas umat-Ku Israel;', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 8, 'Aku telah mengoyakkan kerajaan dari keluarga Daud dan memberikannya kepadamu, tetapi engkau tidak seperti hamba-Ku Daud yang tetap mentaati segala perintah-Ku dan mengikuti Aku dengan segenap hatinya dan hanya melakukan apa yang benar di mata-Ku.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 9, 'Sebab engkau telah melakukan perbuatan jahat lebih dari semua orang yang mendahului engkau dan telah membuat bagimu allah lain dan patung-patung tuangan, sehingga engkau menimbulkan sakit hati-Ku, bahkan engkau telah membelakangi Aku.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 10, 'Maka Aku akan mendatangkan malapetaka kepada keluarga Yerobeam. Aku akan melenyapkan dari pada Yerobeam setiap orang laki-laki, baik yang tinggi maupun yang rendah kedudukannya di Israel. Aku akan menyapu keluarga Yerobeam seperti orang menyapu tahi sampai habis.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 11, 'Setiap orang dari pada Yerobeam yang mati di kota akan dimakan anjing dan yang mati di padang akan dimakan burung yang di udara. Sebab TUHAN telah mengatakannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 12, 'Tetapi bangunlah dan pulang ke rumahmu. Pada saat kakimu melangkah masuk kota, anak itu akan mati.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 13, 'Seluruh Israel akan meratapi dia dan menguburkan dia, sebab hanya dialah dari pada keluarga Yerobeam yang akan mendapat kubur, sebab di antara keluarga Yerobeam hanya padanyalah terdapat sesuatu yang baik di mata TUHAN, Allah Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 14, 'Dan TUHAN akan membangkitkan bagi-Nya seorang raja atas Israel yang akan melenyapkan keluarga Yerobeam?seperti kenyataan sekarang ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 15, 'Kemudian TUHAN akan menghajar orang Israel, sehingga tergoyah-goyah seperti gelagah di air dan Ia akan menyentakkan mereka dari pada tanah yang baik ini yang telah diberikan-Nya kepada nenek moyang mereka; Ia akan menyerakkan mereka ke seberang sungai Efrat sana, oleh karena mereka telah membuat tiang-tiang berhala mereka dan dengan demikian menyakiti hati TUHAN.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 16, 'Ia akan lepas tangan terhadap orang Israel oleh karena dosa-dosa yang telah dilakukan Yerobeam dan yang mengakibatkan orang Israel berdosa pula."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 17, 'Sesudah itu bangkitlah isteri Yerobeam dan pergi, lalu sampailah ia ke Tirza. Pada saat ia masuk melangkahi ambang pintu rumah, matilah anak itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 18, 'Mereka menguburkannya, dan seluruh Israel meratapi dia sesuai dengan firman TUHAN yang diucapkan-Nya dengan perantaraan hamba-Nya, nabi Ahia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 19, 'Selebihnya dari riwayat Yerobeam, bagaimana ia berperang dan bagaimana ia memerintah, sesungguhnya semuanya itu tertulis dalam kitab sejarah raja-raja Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 20, 'Lamanya Yerobeam memerintah ada dua puluh dua tahun, kemudian ia mendapat perhentian bersama-sama dengan nenek moyangnya. Maka anaknya menjadi raja menggantikan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 21, 'Adapun Rehabeam, anak Salomo, ia memerintah di Yehuda. Rehabeam berumur empat puluh satu tahun pada waktu ia menjadi raja, dan tujuh belas tahun lamanya ia memerintah di Yerusalem, kota yang dipilih TUHAN dari antara segala suku Israel untuk membuat nama-Nya tinggal di sana. Nama ibunya ialah Naama, seorang perempuan Amon.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 22, 'Tetapi orang Yehuda melakukan apa yang jahat di mata TUHAN dan mereka menimbulkan cemburu-Nya dengan dosa yang diperbuat mereka, lebih dari pada segala yang dilakukan nenek moyang mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 23, 'Sebab merekapun juga mendirikan tempat-tempat pengorbanan dan tugu-tugu berhala dan tiang-tiang berhala di atas setiap bukit yang tinggi dan di bawah setiap pohon yang rimbun.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 24, 'Bahkan ada pelacuran bakti di negeri itu. Mereka berlaku sesuai dengan segala perbuatan keji bangsa-bangsa yang telah dihalau TUHAN dari orang Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 25, 'Tetapi pada tahun kelima zaman raja Rehabeam, majulah Sisak, raja Mesir, menyerang Yerusalem.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 26, 'Ia merampas barang-barang perbendaharaan rumah TUHAN dan barang-barang perbendaharaan rumah raja; semuanya dirampasnya. Ia merampas juga segala perisai emas yang dibuat Salomo.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 27, 'Sebagai gantinya raja Rehabeam membuat perisai-perisai tembaga, yang dipercayakannya kepada pemimpin-pemimpin bentara yang menjaga pintu istana raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 28, 'Setiap kali raja masuk ke rumah TUHAN, bentara-bentara membawa masuk perisai-perisai itu, dan mereka pula yang mengembalikannya ke kamar jaga para bentara.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 29, 'Selebihnya dari riwayat Rehabeam dan segala yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 30, 'Dan terus-menerus perang ada antara Rehabeam dan Yerobeam.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 14, 31, 'Kemudian Rehabeam mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di samping nenek moyangnya di kota Daud. Nama ibunya ialah Naama, seorang perempuan Amon. Maka Abiam, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 1, 'Dalam tahun kedelapan belas zaman raja Yerobeam bin Nebat menjadi rajalah Abiam atas Yehuda.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 2, 'Tiga tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Maakha, anak Abisalom.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 3, 'Abiam hidup dalam segala dosa yang telah dilakukan ayahnya sebelumnya, dan ia tidak dengan sepenuh hati berpaut kepada TUHAN, Allahnya, seperti Daud, moyangnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 4, 'Tetapi oleh karena Daud maka TUHAN, Allahnya, memberikan keturunan kepadanya di Yerusalem dengan mengangkat anaknya menggantikan dia dan dengan membiarkan Yerusalem berdiri,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 5, 'karena Daud telah melakukan apa yang benar di mata TUHAN dan tidak menyimpang dari segala yang diperintahkan-Nya kepadanya seumur hidupnya, kecuali dalam perkara Uria, orang Het itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 6, 'Dan ada perang antara Rehabeam dan Yerobeam, seumur hidupnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 7, 'Selebihnya dari riwayat Abiam dan segala yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda? Dan ada perang antara Abiam dan Yerobeam.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 8, 'Kemudian Abiam mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di kota Daud. Maka Asa, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 9, 'Dalam tahun kedua puluh zaman Yerobeam, raja Israel, Asa menjadi raja atas Yehuda.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 10, 'Empat puluh satu tahun lamanya ia memerintah di Yerusalem. Nama neneknya yang perempuan ialah Maakha, anak Abisalom.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 11, 'Asa melakukan apa yang benar di mata TUHAN seperti Daud, bapa leluhurnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 12, 'Ia menyingkirkan pelacuran bakti dari negeri itu dan menjauhkan segala berhala yang dibuat oleh nenek moyangnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 13, 'Bahkan ia memecat Maakha, neneknya, dari pangkat ibu suri, karena neneknya itu membuat patung Asyera yang keji. Asa merobohkan patung yang keji itu dan membakarnya di lembah Kidron.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 14, 'Sekalipun bukit-bukit pengorbanan tidak dijauhkan, namun Asa berpaut kepada TUHAN dengan segenap hatinya sepanjang umurnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 15, 'Ia membawa persembahan-persembahan kudus ayahnya dan persembahan-persemba kudusnya sendiri ke rumah TUHAN, yakni emas dan perak serta barang-barang lain.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 16, 'Dan ada perang antara Asa dan Baesa, raja Israel, sepanjang umur mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 17, 'Baesa, raja Israel, maju berperang melawan Yehuda, dan ia memperkuat Rama, dengan maksud mencegah lalu lintas kepada Asa, raja Yehuda.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 18, 'Tetapi Asa mengambil segala emas dan perak yang masih tinggal dalam perbendaharaan rumah TUHAN dan dalam perbendaharaan rumah raja dan menyerahkannya kepada pegawainya. Kemudian raja Asa mengutus mereka kepada Benhadad bin Tabrimon bin Hezion, raja Aram yang diam di Damsyik, dengan membawa pesan:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 19, '"Ada perjanjian antara aku dan engkau, antara ayahku dan ayahmu. Di sini kukirim kepadamu suatu bingkisan, yakni emas dan perak. Marilah, batalkanlah perjanjianmu dengan Baesa, raja Israel, supaya ia undur dari padaku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 20, 'Lalu Benhadad mendengarkan permintaan raja Asa; ia menyuruh panglima-panglimanya menyerang kota-kota Israel dan ia mengalahkan Iyon, Dan, Abel-Bet-Maakha dan seluruh Kinerot serta seluruh tanah Naftali.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 21, 'Segera sesudah Baesa mendengar hal itu, ia berhenti memperkuat Rama dan ia menetap di Tirza.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 22, 'Tetapi raja Asa mengerahkan segenap orang Yehuda, seorangpun tiada yang terkecuali; mereka harus mengangkat batu dan kayu yang dipergunakan Baesa untuk memperkuat Rama. Raja Asa mempergunakannya untuk memperkuat Geba-Benyamin dan Mizpa.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 23, 'Selebihnya dari seluruh riwayat Asa dan segala kepahlawanannya dan segala yang dilakukannya dan kota-kota yang diperkuatnya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda? Tetapi pada masa tuanya ia menderita sakit pada kedua kakinya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 24, 'Kemudian Asa mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di samping nenek moyangnya di kota Daud, bapa leluhurnya. Maka Yosafat, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 25, 'Nadab, anak Yerobeam, menjadi raja atas Israel dalam tahun kedua zaman Asa, raja Yehuda. Ia memerintah atas Israel dua tahun lamanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 26, 'Ia melakukan apa yang jahat di mata TUHAN, serta hidup menurut tingkah laku ayahnya dan menurut dosa ayahnya, yang mengakibatkan orang Israel berdosa pula.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 27, 'Dan Baesa bin Ahia, dari kaum Isakhar, mengadakan persepakatan melawan dia. Baesa menewaskan dia di Gibeton yang termasuk wilayah orang Filistin, sedang Nadab dan seluruh Israel mengepung Gibeton itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 28, 'Baesa membunuh dia dalam tahun ketiga zaman Asa, raja Yehuda, dan menjadi raja menggantikan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 29, 'Segera sesudah ia menjadi raja, ia membunuh seluruh keluarga Yerobeam; tidak ada yang bernafas yang ditinggalkannya hidup dari pada Yerobeam, sampai dipunahkannya semuanya, sesuai dengan firman TUHAN yang diucapkan-Nya dengan perantaraan hamba-Nya Ahia, orang Silo itu,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 30, 'oleh karena dosa-dosa yang telah dilakukan Yerobeam, yang mengakibatkan orang Israel berdosa pula, oleh sebab sakit hati yang ditimbulkannya pada TUHAN, Allah Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 31, 'Selebihnya dari riwayat Nadab dan segala yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 32, 'Dan ada perang antara Asa dan Baesa, raja Israel, sepanjang umur mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 33, 'Dalam tahun ketiga zaman Asa, raja Yehuda, Baesa bin Ahia menjadi raja atas seluruh Israel di Tirza. Ia memerintah dua puluh empat tahun lamanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 15, 34, 'Ia melakukan apa yang jahat di mata TUHAN serta hidup menurut tingkah laku Yerobeam dan menurut dosanya yang mengakibatkan orang Israel berdosa pula.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 1, 'Kemudian datanglah firman TUHAN kepada Yehu bin Hanani melawan Baesa, bunyinya:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 2, '"Oleh karena engkau telah Kutinggikan dari debu dan Kuangkat menjadi raja atas umat-Ku Israel, tetapi engkau telah hidup seperti Yerobeam dan telah menyuruh umat-Ku Israel berdosa, sehingga mereka menimbulkan sakit hati-Ku dengan dosa mereka,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 3, 'maka sesungguhnya Aku akan menyapu bersih Baesa dan keluarganya, kemudian Aku akan membuat keluargamu seperti keluarga Yerobeam bin Nebat.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 4, 'Siapa yang mati dari pada Baesa di kota, akan dimakan anjing dan yang mati dari padanya di padang akan dimakan burung yang di udara."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 5, 'Selebihnya dari riwayat Baesa dan apa yang dilakukannya dan kepahlawanannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 6, 'Kemudian Baesa mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di Tirza. Maka Ela, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 7, 'Juga dengan perantaraan nabi Yehu bin Hanani firman TUHAN telah datang melawan Baesa dan melawan keluarganya, baik karena segala yang jahat yang telah dilakukannya di mata TUHAN, sehingga ia menimbulkan sakit hati TUHAN dengan perbuatan tangannya, dan dengan demikian menjadi sama seperti keluarga Yerobeam, maupun oleh karena ia telah membunuh Yerobeam.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 8, 'Dalam tahun kedua puluh enam zaman Asa, raja Yehuda, Ela, anak Baesa, menjadi raja atas Israel di Tirza. Ia memerintah dua tahun lamanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 9, 'Zimri, pegawainya yang menjadi panglima atas setengah dari pasukan kereta, mengadakan persepakatan melawan dia. Ketika ia minum-minum sampai mabuk di Tirza, di rumah Arza yang menjadi kepala istana di Tirza,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 10, 'datanglah Zimri, lalu membunuh dia dalam tahun kedua puluh tujuh zaman Asa, raja Yehuda, dan ia menjadi raja menggantikan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 11, 'Pada waktu ia menjadi raja itu, segera sesudah ia duduk di atas takhtanya, ia membunuh seluruh keluarga Baesa. Tidak ada seorang laki-lakipun dari padanya yang ditinggalkannya hidup, juga kaumnya, dan teman-temannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 12, 'Demikianlah Zimri memunahkan seluruh keluarga Baesa, sesuai dengan firman TUHAN yang diucapkan-Nya kepada Baesa dengan perantaraan nabi Yehu,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 13, 'oleh karena segala dosa yang telah dilakukan Baesa dan Ela, anaknya, yang mengakibatkan orang Israel berdosa pula, sehingga mereka menimbulkan sakit hati TUHAN, Allah Israel, dengan dewa-dewa kesia-siaan mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 14, 'Selebihnya dari riwayat Ela dan segala yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 15, 'Dalam tahun kedua puluh tujuh zaman Asa, raja Yehuda, Zimri menjadi raja. Ia memerintah tujuh hari lamanya di Tirza, sedang rakyat berkemah mengepung Gibeton yang termasuk wilayah orang Filistin.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 16, 'Setelah rakyat yang berkemah itu mendengar orang mengatakan: "Zimri telah mengadakan persepakatan, dan iapun telah membunuh raja," maka pada hari itu juga, di tempat perkemahan, seluruh Israel menobatkan Omri, panglima tentara, menjadi raja atas Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 17, 'Kemudian Omri dengan seluruh Israel maju dari Gibeton, dan mereka mengepung Tirza.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 18, 'Segera sesudah Zimri melihat, bahwa kota itu telah direbut, masuklah ia ke dalam puri istana raja, lalu membakar istana raja itu sedang ia sendiri ada di dalamnya, dan ia mati,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 19, 'oleh karena dosa-dosa yang telah dilakukannya dengan melakukan apa yang jahat di mata TUHAN serta hidup menurut tingkah laku Yerobeam dan menurut dosa Yerobeam yang mengakibatkan orang Israel berdosa pula.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 20, 'Selebihnya dari riwayat Zimri dan persepakatan yang diadakannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 21, 'Pada waktu itu bangsa Israel terbagi dua. Sebagian dari bangsa itu mengikuti Tibni bin Ginat, dan bermaksud mengangkat dia menjadi raja, dan sebagian lagi mengikuti Omri.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 22, 'Tetapi rakyat yang mengikuti Omri lebih kuat dari pada rakyat yang mengikuti Tibni bin Ginat. Sesudah Tibni mati, maka Omri menjadi raja.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 23, 'Dalam tahun ketiga puluh satu zaman Asa, raja Yehuda, Omri menjadi raja atas Israel dan ia memerintah dua belas tahun lamanya. Di Tirza ia memerintah enam tahun lamanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 24, 'Kemudian ia membeli gunung Samaria dari pada Semer dengan dua talenta perak. Ia mendirikan suatu kota di gunung itu dan menamainya Samaria, menurut nama Semer, pemilik gunung itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 25, 'Omri melakukan apa yang jahat di mata TUHAN dan ia melakukan kejahatan lebih dari pada segala orang yang mendahuluinya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 26, 'Ia hidup menurut segala tingkah laku Yerobeam bin Nebat dan menurut dosa Yerobeam yang mengakibatkan orang Israel berdosa pula, sehingga mereka menimbulkan sakit hati TUHAN, Allah Israel, dengan dewa-dewa kesia-siaan mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 27, 'Selebihnya dari riwayat Omri, apa yang dilakukannya dan kepahlawanannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 28, 'Kemudian Omri mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di Samaria. Maka Ahab, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 29, 'Ahab, anak Omri, menjadi raja atas Israel dalam tahun ketiga puluh delapan zaman Asa, raja Yehuda. Dan Ahab bin Omri memerintah dua puluh dua tahun lamanya atas Israel di Samaria.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 30, 'Ahab bin Omri melakukan apa yang jahat di mata TUHAN lebih dari pada semua orang yang mendahuluinya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 31, 'Seakan-akan belum cukup ia hidup dalam dosa-dosa Yerobeam bin Nebat, maka ia mengambil pula Izebel, anak Etbaal, raja orang Sidon, menjadi isterinya, sehingga ia pergi beribadah kepada Baal dan sujud menyembah kepadanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 32, 'Kemudian ia membuat mezbah untuk Baal itu di kuil Baal yang didirikannya di Samaria.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 33, 'Sesudah itu Ahab membuat patung Asyera, dan Ahab melanjutkan bertindak demikian, sehingga ia menimbulkan sakit hati TUHAN, Allah Israel, lebih dari semua raja-raja Israel yang mendahuluinya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 16, 34, 'Pada zamannya itu Hiel, orang Betel, membangun kembali Yerikho. Dengan membayarkan nyawa Abiram, anaknya yang sulung, ia meletakkan dasar kota itu, dan dengan membayarkan nyawa Segub, anaknya yang bungsu, ia memasang pintu gerbangnya, sesuai dengan firman TUHAN yang diucapkan-Nya dengan perantaraan Yosua bin Nun.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 1, 'Lalu berkatalah Elia, orang Tisbe, dari Tisbe-Gilead, kepada Ahab: "Demi Tuhan yang hidup, Allah Israel, yang kulayani, sesungguhnya tidak akan ada embun atau hujan pada tahun-tahun ini, kecuali kalau kukatakan."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 2, 'Kemudian datanglah firman TUHAN kepadanya:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 3, '"Pergilah dari sini, berjalanlah ke timur dan bersembunyilah di tepi sungai Kerit di sebelah timur sungai Yordan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 4, 'Engkau dapat minum dari sungai itu, dan burung-burung gagak telah Kuperintahkan untuk memberi makan engkau di sana."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 5, 'Lalu ia pergi dan ia melakukan seperti firman TUHAN; ia pergi dan diam di tepi sungai Kerit di sebelah timur sungai Yordan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 6, 'Pada waktu pagi dan petang burung-burung gagak membawa roti dan daging kepadanya, dan ia minum dari sungai itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 7, 'Tetapi sesudah beberapa waktu, sungai itu menjadi kering, sebab hujan tiada turun di negeri itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 8, 'Maka datanglah firman TUHAN kepada Elia:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 9, '"Bersiaplah, pergi ke Sarfat yang termasuk wilayah Sidon, dan diamlah di sana. Ketahuilah, Aku telah memerintahkan seorang janda untuk memberi engkau makan."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 10, 'Sesudah itu ia bersiap, lalu pergi ke Sarfat. Setelah ia sampai ke pintu gerbang kota itu, tampaklah di sana seorang janda sedang mengumpulkan kayu api. Ia berseru kepada perempuan itu, katanya: "Cobalah ambil bagiku sedikit air dalam kendi, supaya aku minum."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 11, 'Ketika perempuan itu pergi mengambilnya, ia berseru lagi: "Cobalah ambil juga bagiku sepotong roti."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 12, 'Perempuan itu menjawab: "Demi TUHAN, Allahmu, yang hidup, sesungguhnya tidak ada roti padaku sedikitpun, kecuali segenggam tepung dalam tempayan dan sedikit minyak dalam buli-buli. Dan sekarang aku sedang mengumpulkan dua tiga potong kayu api, kemudian aku mau pulang dan mengolahnya bagiku dan bagi anakku, dan setelah kami memakannya, maka kami akan mati."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 13, 'Tetapi Elia berkata kepadanya: "Janganlah takut, pulanglah, buatlah seperti yang kaukatakan, tetapi buatlah lebih dahulu bagiku sepotong roti bundar kecil dari padanya, dan bawalah kepadaku, kemudian barulah kaubuat bagimu dan bagi anakmu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 14, 'Sebab beginilah firman TUHAN, Allah Israel: Tepung dalam tempayan itu tidak akan habis dan minyak dalam buli-buli itupun tidak akan berkurang sampai pada waktu TUHAN memberi hujan ke atas muka bumi."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 15, 'Lalu pergilah perempuan itu dan berbuat seperti yang dikatakan Elia; maka perempuan itu dan dia serta anak perempuan itu mendapat makan beberapa waktu lamanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 16, 'Tepung dalam tempayan itu tidak habis dan minyak dalam buli-buli itu tidak berkurang seperti firman TUHAN yang diucapkan-Nya dengan perantaraan Elia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 17, 'Sesudah itu anak dari perempuan pemilik rumah itu jatuh sakit dan sakitnya itu sangat keras sampai tidak ada nafasnya lagi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 18, 'Kata perempuan itu kepada Elia: "Apakah maksudmu datang ke mari, ya abdi Allah? Singgahkah engkau kepadaku untuk mengingatkan kesalahanku dan untuk menyebabkan anakku mati?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 19, 'Kata Elia kepadanya: "Berikanlah anakmu itu kepadaku." Elia mengambilnya dari pangkuan perempuan itu dan membawanya naik ke kamarnya di atas, dan membaringkan anak itu di tempat tidurnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 20, 'Sesudah itu ia berseru kepada TUHAN, katanya: "Ya TUHAN, Allahku! Apakah Engkau menimpakan kemalangan ini atas janda ini juga, yang menerima aku sebagai penumpang, dengan membunuh anaknya?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 21, 'Lalu ia mengunjurkan badannya di atas anak itu tiga kali, dan berseru kepada TUHAN, katanya: "Ya TUHAN, Allahku! Pulangkanlah kiranya nyawa anak ini ke dalam tubuhnya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 22, 'TUHAN mendengarkan permintaan Elia itu, dan nyawa anak itu pulang ke dalam tubuhnya, sehingga ia hidup kembali.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 23, 'Elia mengambil anak itu; ia membawanya turun dari kamar atas ke dalam rumah dan memberikannya kepada ibunya. Kata Elia: "Ini anakmu, ia sudah hidup!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 17, 24, 'Kemudian kata perempuan itu kepada Elia: "Sekarang aku tahu, bahwa engkau abdi Allah dan firman TUHAN yang kauucapkan itu adalah benar."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 1, 'Dan sesudah beberapa lama, datanglah firman TUHAN kepada Elia dalam tahun yang ketiga: "Pergilah, perlihatkanlah dirimu kepada Ahab, sebab Aku hendak memberi hujan ke atas muka bumi."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 2, 'Lalu pergilah Elia memperlihatkan diri kepada Ahab. Adapun kelaparan itu berat di Samaria.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 3, 'Sebab itu Ahab telah memanggil Obaja yang menjadi kepala istana. Obaja itu seorang yang sungguh-sungguh takut akan TUHAN.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 4, 'Karena pada waktu Izebel melenyapkan nabi-nabi TUHAN, Obaja mengambil seratus orang nabi, lalu menyembunyikan mereka lima puluh lima puluh sekelompok dalam gua dan mengurus makanan dan minuman mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 5, 'Ahab berkata kepada Obaja: "Jelajahilah negeri ini dan pergi ke segala mata air dan ke semua sungai; barangkali kita menemukan rumput, sehingga kita dapat menyelamatkan kuda dan bagal, dan tidak usah kita memotong seekorpun dari hewan itu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 6, 'Lalu mereka membagi-bagi tanah itu untuk menjelajahinya. Ahab pergi seorang diri ke arah yang satu dan Obaja pergi ke arah yang lain.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 7, 'Sedang Obaja di tengah jalan, ia bertemu dengan Elia. Setelah mengenali dia, ia sujud serta bertanya: "Engkaukah ini, hai tuanku Elia?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 8, 'Jawab Elia kepadanya: "Benar! Pergilah, katakan kepada tuanmu: Elia ada."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 9, 'Tetapi jawab Obaja: "Apakah dosa yang telah kuperbuat, maka engkau hendak menyerahkan hambamu ini kepada Ahab, supaya aku dibunuhnya?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 10, 'Demi TUHAN, Allahmu, yang hidup, sesungguhnya tidak ada bangsa atau kerajaan, yang tidak didatangi suruhan tuanku Ahab untuk mencari engkau. Dan apabila orang berkata: Ia tidak ada, maka ia menyuruh kerajaan atau bangsa itu bersumpah, bahwa engkau tidak ditemukan di sana.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 11, 'Dan sekarang engkau berkata: Pergilah, katakan kepada tuanmu: Elia ada.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 12, 'Mungkin terjadi, apabila aku sudah pergi dari padamu, Roh TUHAN mengangkat engkau ke tempat yang tidak kuketahui. Kalau aku sampai kepada Ahab untuk memberitahukannya dan engkau tidak didapatinya, tentulah ia akan membunuh aku, padahal hambamu ini dari sejak kecil takut akan TUHAN.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 13, 'Tidakkah diberitahukan kepada tuanku apa yang telah kulakukan pada waktu Izebel membunuh nabi-nabi TUHAN, bagaimana aku menyembunyikan seratus orang nabi-nabi TUHAN dalam gua, lima puluh lima puluh sekelompok dan mengurus makanan dan minuman mereka?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 14, 'Dan sekarang, mengapa engkau ini berkata: Pergilah, katakan kepada tuanmu: Elia ada! Ia pasti akan membunuh aku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 15, 'Jawab Elia: "Demi TUHAN semesta alam yang hidup, yang kulayani, sesungguhnya hari ini juga aku akan memperlihatkan diri kepadanya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 16, 'Lalu pergilah Obaja menemui Ahab dan memberitahukan hal itu kepadanya. Kemudian Ahab pergi menemui Elia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 17, 'Segera sesudah Ahab melihat Elia, ia berkata kepadanya: "Engkaukah itu, yang mencelakakan Israel?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 18, 'Jawab Elia kepadanya: "Bukan aku yang mencelakakan Israel, melainkan engkau ini dan kaum keluargamu, sebab kamu telah meninggalkan perintah-perintah TUHAN dan engkau ini telah mengikuti para Baal.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 19, 'Sebab itu, suruhlah mengumpulkan seluruh Israel ke gunung Karmel, juga nabi-nabi Baal yang empat ratus lima puluh orang itu dan nabi-nabi Asyera yang empat ratus itu, yang mendapat makan dari meja istana Izebel."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 20, 'Ahab mengirim orang ke seluruh Israel dan mengumpulkan nabi-nabi itu ke gunung Karmel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 21, 'Lalu Elia mendekati seluruh rakyat itu dan berkata: "Berapa lama lagi kamu berlaku timpang dan bercabang hati? Kalau TUHAN itu Allah, ikutilah Dia, dan kalau Baal, ikutilah dia." Tetapi rakyat itu tidak menjawabnya sepatah katapun.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 22, 'Lalu Elia berkata kepada rakyat itu: "Hanya aku seorang diri yang tinggal sebagai nabi TUHAN, padahal nabi-nabi Baal itu ada empat ratus lima puluh orang banyaknya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 23, 'Namun, baiklah diberikan kepada kami dua ekor lembu jantan; biarlah mereka memilih seekor lembu, memotong-motongnya, menaruhnya ke atas kayu api, tetapi mereka tidak boleh menaruh api. Akupun akan mengolah lembu yang seekor lagi, meletakkannya ke atas kayu api dan juga tidak akan menaruh api.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 24, 'Kemudian biarlah kamu memanggil nama allahmu dan akupun akan memanggil nama TUHAN. Maka allah yang menjawab dengan api, dialah Allah!" Seluruh rakyat menyahut, katanya: "Baiklah demikian!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 25, 'Kemudian Elia berkata kepada nabi-nabi Baal itu: "Pilihlah seekor lembu dan olahlah itu dahulu, karena kamu ini banyak. Sesudah itu panggillah nama allahmu, tetapi kamu tidak boleh menaruh api."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 26, 'Mereka mengambil lembu yang diberikan kepada mereka, mengolahnya dan memanggil nama Baal dari pagi sampai tengah hari, katanya: "Ya Baal, jawablah kami!" Tetapi tidak ada suara, tidak ada yang menjawab. Sementara itu mereka berjingkat-jingkat di sekeliling mezbah yang dibuat mereka itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 27, 'Pada waktu tengah hari Elia mulai mengejek mereka, katanya: "Panggillah lebih keras, bukankah dia allah? Mungkin ia merenung, mungkin ada urusannya, mungkin ia bepergian; barangkali ia tidur, dan belum terjaga."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 28, 'Maka mereka memanggil lebih keras serta menoreh-noreh dirinya dengan pedang dan tombak, seperti kebiasaan mereka, sehingga darah bercucuran dari tubuh mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 29, 'Sesudah lewat tengah hari, mereka kerasukan sampai waktu mempersembahkan korban petang, tetapi tidak ada suara, tidak ada yang menjawab, tidak ada tanda perhatian.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 30, 'Kata Elia kepada seluruh rakyat itu: "Datanglah dekat kepadaku!" Maka mendekatlah seluruh rakyat itu kepadanya. Lalu ia memperbaiki mezbah TUHAN yang telah diruntuhkan itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 31, 'Kemudian Elia mengambil dua belas batu, menurut jumlah suku keturunan Yakub. ?Kepada Yakub ini telah datang firman TUHAN: "Engkau akan bernama Israel." ?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 32, 'Ia mendirikan batu-batu itu menjadi mezbah demi nama TUHAN dan membuat suatu parit sekeliling mezbah itu yang dapat memuat dua sukat benih.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 33, 'Ia menyusun kayu api, memotong lembu itu dan menaruh potongan-potongannya di atas kayu api itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 34, 'Sesudah itu ia berkata: "Penuhilah empat buyung dengan air, dan tuangkan ke atas korban bakaran dan ke atas kayu api itu!" Kemudian katanya: "Buatlah begitu untuk kedua kalinya!" Dan mereka berbuat begitu untuk kedua kalinya. Kemudian katanya: "Buatlah begitu untuk ketiga kalinya!" Dan mereka berbuat begitu untuk ketiga kalinya,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 35, 'sehingga air mengalir sekeliling mezbah itu; bahkan parit itupun penuh dengan air.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 36, 'Kemudian pada waktu mempersembahkan korban petang, tampillah nabi Elia dan berkata: "Ya TUHAN, Allah Abraham, Ishak dan Israel, pada hari ini biarlah diketahui orang, bahwa Engkaulah Allah di tengah-tengah Israel dan bahwa aku ini hamba-Mu dan bahwa atas firman-Mulah aku melakukan segala perkara ini.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 37, 'Jawablah aku, ya TUHAN, jawablah aku, supaya bangsa ini mengetahui, bahwa Engkaulah Allah, ya TUHAN, dan Engkaulah yang membuat hati mereka tobat kembali."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 38, 'Lalu turunlah api TUHAN menyambar habis korban bakaran, kayu api, batu dan tanah itu, bahkan air yang dalam parit itu habis dijilatnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 39, 'Ketika seluruh rakyat melihat kejadian itu, sujudlah mereka serta berkata: "TUHAN, Dialah Allah! TUHAN, Dialah Allah!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 40, 'Kata Elia kepada mereka: "Tangkaplah nabi-nabi Baal itu, seorangpun dari mereka tidak boleh luput." Setelah ditangkap, Elia membawa mereka ke sungai Kison dan menyembelih mereka di sana.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 41, 'Kemudian berkatalah Elia kepada Ahab: "Pergilah, makanlah dan minumlah, sebab bunyi derau hujan sudah kedengaran."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 42, 'Lalu Ahab pergi untuk makan dan minum. Tetapi Elia naik ke puncak gunung Karmel, lalu ia membungkuk ke tanah, dengan mukanya di antara kedua lututnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 43, 'Setelah itu ia berkata kepada bujangnya: "Naiklah ke atas, lihatlah ke arah laut." Bujang itu naik ke atas, ia melihat dan berkata: "Tidak ada apa-apa." Kata Elia: "Pergilah sekali lagi." Demikianlah sampai tujuh kali.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 44, 'Pada ketujuh kalinya berkatalah bujang itu: "Wah, awan kecil sebesar telapak tangan timbul dari laut." Lalu kata Elia: "Pergilah, katakan kepada Ahab: Pasang keretamu dan turunlah, jangan sampai engkau terhalang oleh hujan."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 45, 'Maka dalam sekejap mata langit menjadi kelam oleh awan badai, lalu turunlah hujan yang lebat. Ahab naik kereta lalu pergi ke Yizreel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 18, 46, 'Tetapi kuasa TUHAN berlaku atas Elia. Ia mengikat pinggangnya dan berlari mendahului Ahab sampai ke jalan yang menuju Yizreel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 1, 'Ketika Ahab memberitahukan kepada Izebel segala yang dilakukan Elia dan perihal Elia membunuh semua nabi itu dengan pedang,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 2, 'maka Izebel menyuruh seorang suruhan mengatakan kepada Elia: "Beginilah kiranya para allah menghukum aku, bahkan lebih lagi dari pada itu, jika besok kira-kira pada waktu ini aku tidak membuat nyawamu sama seperti nyawa salah seorang dari mereka itu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 3, 'Maka takutlah ia, lalu bangkit dan pergi menyelamatkan nyawanya; dan setelah sampai ke Bersyeba, yang termasuk wilayah Yehuda, ia meninggalkan bujangnya di sana.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 4, 'Tetapi ia sendiri masuk ke padang gurun sehari perjalanan jauhnya, lalu duduk di bawah sebuah pohon arar. Kemudian ia ingin mati, katanya: "Cukuplah itu! Sekarang, ya TUHAN, ambillah nyawaku, sebab aku ini tidak lebih baik dari pada nenek moyangku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 5, 'Sesudah itu ia berbaring dan tidur di bawah pohon arar itu. Tetapi tiba-tiba seorang malaikat menyentuh dia serta berkata kepadanya: "Bangunlah, makanlah!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 6, 'Ketika ia melihat sekitarnya, maka pada sebelah kepalanya ada roti bakar, dan sebuah kendi berisi air. Lalu ia makan dan minum, kemudian berbaring pula.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 7, 'Tetapi malaikat TUHAN datang untuk kedua kalinya dan menyentuh dia serta berkata: "Bangunlah, makanlah! Sebab kalau tidak, perjalananmu nanti terlalu jauh bagimu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 8, 'Maka bangunlah ia, lalu makan dan minum, dan oleh kekuatan makanan itu ia berjalan empat puluh hari empat puluh malam lamanya sampai ke gunung Allah, yakni gunung Horeb.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 9, 'Di sana masuklah ia ke dalam sebuah gua dan bermalam di situ. Maka firman TUHAN datang kepadanya, demikian: "Apakah kerjamu di sini, hai Elia?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 10, 'Jawabnya: "Aku bekerja segiat-giatnya bagi TUHAN, Allah semesta alam, karena orang Israel meninggalkan perjanjian-Mu, meruntuhkan mezbah-mezbah-Mu dan membunuh nabi-nabi-Mu dengan pedang; hanya aku seorang dirilah yang masih hidup dan mereka ingin mencabut nyawaku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 11, 'Lalu firman-Nya: "Keluarlah dan berdiri di atas gunung itu di hadapan TUHAN!" Maka TUHAN lalu! Angin besar dan kuat, yang membelah gunung-gunung dan memecahkan bukit-bukit batu, mendahului TUHAN. Tetapi tidak ada TUHAN dalam angin itu. Dan sesudah angin itu datanglah gempa. Tetapi tidak ada TUHAN dalam gempa itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 12, 'Dan sesudah gempa itu datanglah api. Tetapi tidak ada TUHAN dalam api itu. Dan sesudah api itu datanglah bunyi angin sepoi-sepoi basa.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 13, 'Segera sesudah Elia mendengarnya, ia menyelubungi mukanya dengan jubahnya, lalu pergi ke luar dan berdiri di pintu gua itu. Maka datanglah suara kepadanya yang berbunyi: "Apakah kerjamu di sini, hai Elia?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 14, 'Jawabnya: "Aku bekerja segiat-giatnya bagi TUHAN, Allah semesta alam, karena orang Israel meninggalkan perjanjian-Mu, meruntuhkan mezbah-mezbah-Mu dan membunuh nabi-nabi-Mu dengan pedang; hanya aku seorang dirilah yang masih hidup, dan mereka ingin mencabut nyawaku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 15, 'Firman TUHAN kepadanya: "Pergilah, kembalilah ke jalanmu, melalui padang gurun ke Damsyik, dan setelah engkau sampai, engkau harus mengurapi Hazael menjadi raja atas Aram.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 16, 'Juga Yehu, cucu Nimsi, haruslah kauurapi menjadi raja atas Israel, dan Elisa bin Safat, dari Abel-Mehola, harus kauurapi menjadi nabi menggantikan engkau.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 17, 'Maka siapa yang terluput dari pedang Hazael akan dibunuh oleh Yehu; dan siapa yang terluput dari pedang Yehu akan dibunuh oleh Elisa.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 18, 'Tetapi Aku akan meninggalkan tujuh ribu orang di Israel, yakni semua orang yang tidak sujud menyembah Baal dan yang mulutnya tidak mencium dia."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 19, 'Setelah Elia pergi dari sana, ia bertemu dengan Elisa bin Safat yang sedang membajak dengan dua belas pasang lembu, sedang ia sendiri mengemudikan yang kedua belas. Ketika Elia lalu dari dekatnya, ia melemparkan jubahnya kepadanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 20, 'Lalu Elisa meninggalkan lembu itu dan berlari mengikuti Elia, katanya: "Biarkanlah aku mencium ayahku dan ibuku dahulu, lalu aku akan mengikuti engkau." Jawabnya kepadanya: "Baiklah, pulang dahulu, dan ingatlah apa yang telah kuperbuat kepadamu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 19, 21, 'Lalu berbaliklah ia dari pada Elia, ia mengambil pasangan lembu itu, menyembelihnya dan memasak dagingnya dengan bajak lembu itu sebagai kayu api; ia memberikan daging itu kepada orang-orangnya, kemudian makanlah mereka. Sesudah itu bersiaplah ia, lalu mengikuti Elia dan menjadi pelayannya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 1, 'Benhadad, raja Aram, mengumpulkan seluruh tentaranya, tiga puluh dua orang raja bersama-sama dia beserta kuda dan kereta. Lalu ia maju, ia mengepung Samaria dan memeranginya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 2, 'Kemudian ia mengirim utusan ke kota itu, kepada Ahab, raja Israel,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 3, 'dengan pesan: "Beginilah pesan Benhadad: Emasmu dan perakmu adalah milikku, dan juga isteri-isteri dan anak-anakmu yang cantik-cantik adalah milikku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 4, 'Raja Israel menjawab, katanya: "Seperti bicaramu itulah, ya tuanku raja. Aku ini dengan segala yang ada padaku adalah milikmu!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 5, 'Sesudah itu utusan-utusan itu kembali dan berkata: "Beginilah pesan Benhadad: Memang aku telah menyuruh orang kepadamu mengatakan: Emas dan perakmu, isteri-isteri dan anak-anakmu harus kauserahkan kepadaku,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 6, 'tetapi besok kira-kira pada waktu ini, aku akan menyuruh pegawai-pegawaiku kepadamu dan mereka akan menggeledah rumahmu dan rumah pegawai-pegawaimu, maka segala yang mereka lihat dan ingini akan mereka ambil dan mereka bawa."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 7, 'Lalu raja Israel memanggil semua tua-tua negeri itu dan berkata: "Camkanlah, orang ini mengikhtiarkan kecelakaan kita, sebab ia telah menyuruh orang kepadaku meminta isteri-isteriku, anak-anakku, emas dan perakku, dan aku tidak menolak memberikannya kepadanya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 8, 'Lalu kata semua tua-tua dan segenap rakyat itu kepadanya: "Jangan dengarkan, jangan luluskan!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 9, 'Sebab itu ia berkata kepada utusan-utusan Benhadad: "Katakanlah kepada tuanku raja: Segala yang pertama kali kausuruhkan kepada hambamu ini, aku akan melakukannya, tetapi tuntutan yang kemudian ini tidak dapat kupenuhi." Lalu pergilah utusan-utusan itu dan menyampaikan jawab itu kepada Benhadad.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 10, 'Benhadad menyuruh orang kepada Ahab dengan pesan: "Beginilah kiranya para allah menghukum aku, bahkan lebih lagi dari pada itu, jika rakyat yang mengikut aku masih dapat menjemput segenggam penuh debu puing Samaria!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 11, 'Tetapi raja Israel menjawab, katanya: "Katakanlah! Orang yang baru menyandangkan pedang janganlah memegahkan diri seperti orang yang sudah menanggalkannya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 12, 'Segera sesudah Benhadad mendengar perkataan itu, pada waktu ia sedang minum-minum dengan raja-raja di pondok, berkatalah ia kepada pegawai-pegawainya: "Aturlah barisanmu," lalu mereka mengatur barisannya melawan kota itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 13, 'Tetapi tiba-tiba tampillah seorang nabi kepada Ahab, raja Israel, serta berkata: "Beginilah firman TUHAN: Sudahkah kaulihat semua orang yang sangat ramai itu? Bahwasanya pada hari ini Aku akan menyerahkan mereka ke dalam tanganmu, supaya engkau tahu, bahwa Akulah TUHAN."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 14, 'Lalu bertanyalah Ahab: "Dengan bantuan siapa?" Jawabnya: "Beginilah firman TUHAN: Dengan bantuan orang-orang muda pengiring kepala-kepala daerah." Tanyanya pula: "Siapakah yang akan memulai perang?" Jawabnya: "Engkau!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 15, 'Kemudian ia menghitung jumlah orang-orang muda pengiring kepala-kepala daerah itu. Ada dua ratus tiga puluh dua orang banyaknya dan sesudah mereka itu ia menghitung jumlah seluruh rakyat, yakni segenap orang Israel. Ada tujuh ribu orang banyaknya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 16, 'Lalu mereka maju menyerang pada waktu tengah hari, sementara Benhadad minum-minum sampai mabuk di pondoknya, bersama dengan ketiga puluh dua raja yang membantunya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 17, 'Ketika orang-orang muda pengiring kepala-kepala daerah itu maju menyerang lebih dahulu, maka Benhadad menyuruh orang menyelidiknya, dan mereka memberitahukan kepadanya, demikian: "Ada orang-orang maju menyerang dari Samaria."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 18, 'Lalu katanya: "Entah mereka datang dengan maksud damai, entah dengan maksud perang, tangkaplah mereka hidup-hidup!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 19, 'Sementara itu keluarlah mereka itu dari dalam kota, yakni orang-orang muda pengiring kepala-kepala daerah dan juga tentara yang mengikuti mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 20, 'Lalu mereka masing-masing membunuh lawan yang dihadapinya, sehingga orang Aram itu melarikan diri dan dikejar oleh orang Israel. Tetapi Benhadad, raja Aram dapat meluputkan diri dengan naik kuda, beserta sejumlah orang berkuda.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 21, 'Juga raja Israel maju, lalu memusnahkan kuda dan kereta itu dan mendatangkan kekalahan yang besar kepada orang Aram.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 22, 'Lalu tampillah nabi itu kepada raja Israel dan berkata kepadanya: "Baiklah, kuatkanlah hatimu, pertimbangkan dan pikirkanlah apa yang harus kauperbuat, sebab pada pergantian tahun raja Aram akan maju menyerang engkau."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 23, 'Pegawai-pegawai raja Aram berkata kepadanya: "Allah mereka ialah allah gunung; itulah sebabnya mereka lebih kuat dari pada kita. Tetapi apabila kita berperang melawan mereka di tanah rata, pastilah kita lebih kuat dari pada mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 24, 'Bertindaklah begini: Pecatlah raja-raja itu masing-masing dari kedudukannya, dan angkatlah bupati-bupati menggantikan mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 25, 'Lalu kerahkanlah tentara sebanyak tentara yang telah gugur dari pihakmu itu, demikian pula kuda dan kereta sebanyak yang dahulu. Marilah kita berperang melawan mereka di tanah rata, pastilah kita lebih kuat dari pada mereka." Raja mendengarkan usul mereka, dan bertindak demikian.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 26, 'Dalam tahun yang berikutnya Benhadad memeriksa barisan orang Aram, lalu ia maju ke Afek untuk berperang melawan orang Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 27, 'Orang Israelpun memeriksa barisannya dan setelah dibekali mereka berangkat menghadapi orang Aram. Orang Israel berkemah di hadapan mereka seperti dua kawanan kambing, sedang orang Aram telah datang membanjiri negeri itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 28, 'Maka tampillah abdi Allah dan berkata kepada raja Israel: "Beginilah firman TUHAN: Oleh karena orang Aram itu telah berkata: TUHAN ialah allah gunung dan bukan allah dataran, maka Aku akan menyerahkan seluruh tentara yang besar itu ke dalam tanganmu, supaya kamu tahu, bahwa Akulah TUHAN."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 29, 'Tujuh hari lamanya mereka berkemah berhadap-hadapan. Tetapi pada hari yang ketujuh mulailah pertempuran, dan pada suatu hari orang Israel menewaskan seratus ribu orang berjalan kaki dari orang Aram itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 30, 'Orang-orang yang masih tinggal melarikan diri ke Afek, ke dalam kota, tetapi temboknya roboh menimpa kedua puluh tujuh ribu orang yang masih tinggal itu. Sementara itu Benhadad melarikan diri dan masuk ke kota, dan bersembunyi dari satu kamar ke kamar yang lain.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 31, 'Lalu berkatalah pegawai-pegawainya kepadanya: "Ketahuilah, kami telah mendengar, bahwa raja-raja kaum Israel itu adalah raja-raja pemurah. Marilah kita menaruh kain kabung pada pinggang kita dan tali pada kepala kita, dan dengan demikian keluar menghadap raja Israel; barangkali ia akan menyelamatkan nyawamu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 32, 'Lalu mereka melilitkan kain kabung pada pinggang mereka dan tali pada kepala mereka, kemudian mereka pergi menghadap raja Israel sambil berkata: "Hambamu Benhadad berkata: Kiranya tuanku membiarkan aku hidup." Jawabnya: "Masih hidupkah dia? Dia saudaraku."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 33, 'Orang-orang itu menganggap hal itu sebagai tanda yang baik, maka segeralah mereka berpegang pada perkataannya itu, lalu berkata: "Memang saudaramu Benhadad!" Sesudah itu berkatalah Ahab: "Pergilah, ambil dia!" Jadi keluarlah Benhadad mendapatkan dia, lalu diajak naik ke atas kereta.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 34, 'Kata Benhadad kepadanya: "Kota-kota yang telah diambil bapaku dari pihak bapamu akan kukembalikan; engkau boleh juga membuat pasar bagimu di Damsyik, seperti yang dibuat bapaku di Samaria." "Dan aku sendiri," kata Ahab, "akan membiarkan engkau pergi dengan perjanjian." Lalu ia mengadakan perjanjian dengan dia dan membiarkannya pergi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 35, 'Seorang dari rombongan nabi berkata kepada temannya atas perintah TUHAN: "Pukullah aku!" Tetapi orang itu menolak memukulnya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 36, 'Lalu ia berkata kepadanya: "Oleh sebab engkau tidak mendengarkan suara TUHAN, ketahuilah, apabila engkau pergi dari padaku, seekor singa akan menerkam engkau." Dan ketika orang itu pergi dari padanya, maka seekor singa bertemu dengan dia, lalu menerkam dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 37, 'Kemudian nabi itu bertemu dengan orang lain, lalu ia berkata: "Pukullah aku!" Orang itu memukul dan melukai dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 38, 'Sesudah itu nabi itu pergi dan berdiri menantikan raja di jalan, sambil menyamar dengan membubuh kain pembalut pada matanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 39, 'Pada waktu raja lewat, ia mengadukan halnya kepada raja, katanya: "Ketika hambamu ini maju ke tengah pertempuran, tiba-tiba ada seorang meninggalkan barisan dan membawa seorang kepadaku sambil berkata: Jagalah orang ini, jika ia hilang dengan cara bagaimanapun juga, maka nyawamu adalah ganti nyawanya, atau engkau harus membayar setalenta perak.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 40, 'Ketika hambamu ini repot sana sini, orang itu menghilang." Kemudian raja Israel itu berkata kepadanya: "Begitu jugalah hukumanmu, engkau sendiri telah menetapkannya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 41, 'Lalu segeralah ia membuka kain pembalut itu dari matanya, sehingga raja Israel mengenali dia sebagai seorang dari rombongan nabi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 42, 'Kata nabi itu kepadanya: "Beginilah firman TUHAN: Oleh karena engkau telah membiarkan lolos orang yang dikhususkan bagi-Ku untuk ditumpas, maka nyawamu adalah ganti nyawanya dan rakyatmu ganti rakyatnya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 20, 43, 'Lalu raja Israel pergi ke istananya dengan kesal hati dan gusar, maka sampailah ia di Samaria.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 1, 'Sesudah itu terjadilah hal yang berikut. Nabot, orang Yizreel, mempunyai kebun anggur di Yizreel, di samping istana Ahab, raja Samaria.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 2, 'Berkatalah Ahab kepada Nabot: "Berikanlah kepadaku kebun anggurmu itu, supaya kujadikan kebun sayur, sebab letaknya dekat rumahku. Aku akan memberikan kepadamu kebun anggur yang lebih baik dari pada itu sebagai gantinya, atau jikalau engkau lebih suka, aku akan membayar harganya kepadamu dengan uang."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 3, 'Jawab Nabot kepada Ahab: "Kiranya TUHAN menghindarkan aku dari pada memberikan milik pusaka nenek moyangku kepadamu!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 4, 'Lalu masuklah Ahab ke dalam istananya dengan kesal hati dan gusar karena perkataan yang dikatakan Nabot, orang Yizreel itu, kepadanya: "Tidak akan kuberikan kepadamu milik pusaka nenek moyangku." Maka berbaringlah ia di tempat tidurnya dan menelungkupkan mukanya dan tidak mau makan.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 5, 'Lalu datanglah Izebel, isterinya, dan berkata kepadanya: "Apa sebabnya hatimu kesal, sehingga engkau tidak makan?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 6, 'Lalu jawabnya kepadanya: "Sebab aku telah berkata kepada Nabot, orang Yizreel itu: Berikanlah kepadaku kebun anggurmu dengan bayaran uang atau jika engkau lebih suka, aku akan memberikan kebun anggur kepadamu sebagai gantinya. Tetapi sahutnya: Tidak akan kuberikan kepadamu kebun anggurku itu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 7, 'Kata Izebel, isterinya, kepadanya: "Bukankah engkau sekarang yang memegang kuasa raja atas Israel? Bangunlah, makanlah dan biarlah hatimu gembira! Aku akan memberikan kepadamu kebun anggur Nabot, orang Yizreel itu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 8, 'Kemudian ia menulis surat atas nama Ahab, memeteraikannya dengan meterai raja, lalu mengirim surat itu kepada tua-tua dan pemuka-pemuka yang diam sekota dengan Nabot.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 9, 'Dalam surat itu ditulisnya demikian: "Maklumkanlah puasa dan suruhlah Nabot duduk paling depan di antara rakyat.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 10, 'Suruh jugalah dua orang dursila duduk menghadapinya, dan mereka harus naik saksi terhadap dia, dengan mengatakan: Engkau telah mengutuk Allah dan raja. Sesudah itu bawalah dia ke luar dan lemparilah dia dengan batu sampai mati."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 11, 'Orang-orang sekotanya, yakni tua-tua dan pemuka-pemuka, yang diam di kotanya itu, melakukan seperti yang diperintahkan Izebel kepada mereka, seperti yang tertulis dalam surat yang dikirimkannya kepada mereka.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 12, 'Mereka memaklumkan puasa dan menyuruh Nabot duduk paling depan di antara rakyat.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 13, 'Kemudian datanglah dua orang, yakni orang-orang dursila itu, lalu duduk menghadapi Nabot. Orang-orang dursila itu naik saksi terhadap Nabot di depan rakyat, katanya: "Nabot telah mengutuk Allah dan raja." Sesudah itu mereka membawa dia ke luar kota, lalu melempari dia dengan batu sampai mati.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 14, 'Setelah itu mereka menyuruh orang kepada Izebel mengatakan: "Nabot sudah dilempari sampai mati."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 15, 'Segera sesudah Izebel mendengar, bahwa Nabot sudah dilempari sampai mati, berkatalah Izebel kepada Ahab: "Bangunlah, ambillah kebun anggur Nabot, orang Yizreel itu, menjadi milikmu, karena Nabot yang menolak memberikannya kepadamu dengan bayaran uang, sudah tidak hidup lagi; ia sudah mati."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 16, 'Segera sesudah Ahab mendengar, bahwa Nabot sudah mati, ia bangun dan pergi ke kebun anggur Nabot, orang Yizreel itu, untuk mengambil kebun itu menjadi miliknya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 17, 'Tetapi datanglah firman TUHAN kepada Elia, orang Tisbe itu, bunyinya:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 18, '"Bangunlah, pergilah menemui Ahab, raja Israel yang di Samaria. Ia telah pergi ke kebun anggur Nabot untuk mengambil kebun itu menjadi miliknya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 19, 'Katakanlah kepadanya, demikian: Beginilah firman TUHAN: Engkau telah membunuh serta merampas juga! Katakan pula kepadanya: Beginilah firman TUHAN: Di tempat anjing telah menjilat darah Nabot, di situ jugalah anjing akan menjilat darahmu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 20, 'Kata Ahab kepada Elia: "Sekarang engkau mendapat aku, hai musuhku?" Jawabnya: "Memang sekarang aku mendapat engkau, karena engkau sudah memperbudak diri dengan melakukan apa yang jahat di mata TUHAN.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 21, 'Sesungguhnya, Aku akan mendatangkan malapetaka kepadamu, Aku akan menyapu engkau dan melenyapkan setiap orang laki-laki dari keluarga Ahab, baik yang tinggi maupun yang rendah kedudukannya di Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 22, 'Dan Aku akan memperlakukan keluargamu sama seperti keluarga Yerobeam bin Nebat dan seperti keluarga Baesa bin Ahia, oleh karena engkau menimbulkan sakit hati-Ku, dan oleh karena engkau mengakibatkan orang Israel berbuat dosa.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 23, 'Juga mengenai Izebel TUHAN telah berfirman: Anjing akan memakan Izebel di tembok luar Yizreel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 24, 'Siapa dari keluarga Ahab yang mati di kota akan dimakan anjing dan yang mati di padang akan dimakan burung di udara."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 25, 'Sesungguhnya tidak pernah ada orang seperti Ahab yang memperbudak diri dengan melakukan apa yang jahat di mata TUHAN, karena ia telah dibujuk oleh Izebel, isterinya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 26, 'Bahkan ia telah berlaku sangat keji dengan mengikuti berhala-berhala, tepat seperti yang dilakukan oleh orang Amori yang telah dihalau TUHAN dari depan orang Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 27, 'Segera sesudah Ahab mendengar perkataan itu, ia mengoyakkan pakaiannya, mengenakan kain kabung pada tubuhnya dan berpuasa. Bahkan ia tidur dengan memakai kain kabung, dan berjalan dengan langkah lamban.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 28, 'Lalu datanglah firman TUHAN kepada Elia, orang Tisbe itu:', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 21, 29, '"Sudahkah kaulihat, bahwa Ahab merendahkan diri di hadapan-Ku? Oleh karena ia telah merendahkan diri di hadapan-Ku, maka Aku tidak akan mendatangkan malapetaka dalam zamannya; barulah dalam zaman anaknya Aku akan mendatangkan malapetaka atas keluarganya."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 1, 'Tiga tahun lamanya orang tinggal aman dengan tidak ada perang antara Aram dan Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 2, 'Pada tahun yang ketiga pergilah Yosafat, raja Yehuda, kepada raja Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 3, 'Berkatalah raja Israel kepada pegawai-pegawainya: "Tahukah kamu, bahwa Ramot-Gilead sebenarnya milik kita? Tetapi kita tinggal diam saja dan tidak merebutnya dari tangan raja negeri Aram."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 4, 'Lalu katanya kepada Yosafat: "Maukah engkau pergi bersama-sama aku untuk memerangi Ramot-Gilead?" Jawab Yosafat kepada raja Israel: "Kita sama-sama, aku dan engkau, rakyatku dan rakyatmu, kudaku dan kudamu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 5, 'Tetapi Yosafat berkata kepada raja Israel: "Baiklah tanyakan dahulu firman TUHAN."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 6, 'Lalu raja Israel mengumpulkan para nabi, kira-kira empat ratus orang banyaknya, kemudian bertanyalah ia kepada mereka: "Apakah aku boleh pergi berperang melawan Ramot-Gilead atau aku membatalkannya?" Jawab mereka: "Majulah! Tuhan akan menyerahkannya ke dalam tangan raja."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 7, 'Tetapi Yosafat bertanya: "Tidak adakah lagi di sini seorang nabi TUHAN, supaya dengan perantaraannya kita dapat meminta petunjuk?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 8, 'Jawab raja Israel kepada Yosafat: "Masih ada seorang lagi yang dengan perantaraannya dapat diminta petunjuk TUHAN. Tetapi aku membenci dia, sebab tidak pernah ia menubuatkan yang baik tentang aku, melainkan malapetaka. Orang itu ialah Mikha bin Yimla." Kata Yosafat: "Janganlah raja berkata demikian."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 9, 'Kemudian raja Israel memanggil seorang pegawai istana, katanya: "Jemputlah Mikha bin Yimla dengan segera!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 10, 'Sementara raja Israel dan Yosafat, raja Yehuda, duduk masing-masing di atas takhtanya dengan pakaian kebesaran, di suatu tempat pengirikan di depan pintu gerbang Samaria, sedang semua nabi itu bernubuat di depan mereka,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 11, 'maka Zedekia bin Kenaana membuat tanduk-tanduk besi, lalu berkata: "Beginilah firman TUHAN: Dengan ini engkau akan menanduk Aram sampai engkau menghabiskan mereka."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 12, 'Juga semua nabi itu bernubuat demikian, katanya: "Majulah ke Ramot-Gilead, dan engkau akan beruntung; TUHAN akan menyerahkannya ke dalam tangan raja."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 13, 'Suruhan yang pergi memanggil Mikha itu, berkata kepadanya: "Ketahuilah, nabi-nabi itu sudah sepakat meramalkan yang baik bagi raja, hendaklah engkau juga berbicara seperti salah seorang dari pada mereka dan meramalkan yang baik."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 14, 'Tetapi Mikha menjawab: "Demi TUHAN yang hidup, sesungguhnya, apa yang akan difirmankan TUHAN kepadaku, itulah yang akan kukatakan."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 15, 'Setelah ia sampai kepada raja, bertanyalah raja kepadanya: "Mikha, apakah kami boleh pergi berperang melawan Ramot-Gilead atau kami membatalkannya?" Jawabnya kepadanya: "Majulah dan engkau akan beruntung, sebab TUHAN akan menyerahkannya ke dalam tangan raja."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 16, 'Tetapi raja berkata kepadanya: "Sampai berapa kali aku menyuruh engkau bersumpah, supaya engkau mengatakan kepadaku tidak lain dari kebenaran demi nama TUHAN?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 17, 'Lalu jawabnya: "Telah kulihat seluruh Israel bercerai-berai di gunung-gunung seperti domba-domba yang tidak mempunyai gembala, sebab itu TUHAN berfirman: Mereka ini tidak punya tuan; baiklah masing-masing pulang ke rumahnya dengan selamat."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 18, 'Kemudian raja Israel berkata kepada Yosafat: "Bukankah telah kukatakan kepadamu: Tidak pernah ia menubuatkan yang baik tentang aku, melainkan hanya malapetaka?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 19, 'Kata Mikha: "Sebab itu dengarkanlah firman TUHAN. Aku telah melihat TUHAN sedang duduk di atas takhta-Nya dan segenap tentara sorga berdiri di dekat-Nya, di sebelah kanan-Nya dan di sebelah kiri-Nya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 20, 'Dan TUHAN berfirman: Siapakah yang akan membujuk Ahab untuk maju berperang, supaya ia tewas di Ramot-Gilead? Maka yang seorang berkata begini, yang lain berkata begitu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 21, 'Kemudian tampillah suatu roh, lalu berdiri di hadapan TUHAN. Ia berkata: Aku ini akan membujuknya. TUHAN bertanya kepadanya: Dengan apa?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 22, 'Jawabnya: Aku akan keluar dan menjadi roh dusta dalam mulut semua nabinya. Ia berfirman: Biarlah engkau membujuknya, dan engkau akan berhasil pula. Keluarlah dan perbuatlah demikian!', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 23, 'Karena itu, sesungguhnya TUHAN telah menaruh roh dusta ke dalam mulut semua nabimu ini, sebab TUHAN telah menetapkan untuk menimpakan malapetaka kepadamu."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 24, 'Sesudah itu tampillah Zedekia bin Kenaana, ditamparnyalah pipi Mikha serta berkata: "Mana boleh Roh TUHAN pindah dari padaku untuk berbicara kepadamu?"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 25, 'Tetapi Mikha menjawab: "Sesungguhnya engkau akan melihatnya pada hari engkau lari dari satu kamar ke kamar yang lain untuk menyembunyikan diri."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 26, 'Berkatalah raja Israel: "Tangkaplah Mikha, bawa dia kembali kepada Amon, penguasa kota, dan kepada Yoas, anak raja,', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 27, 'dan katakan: Beginilah titah raja: Masukkan orang ini dalam penjara dan beri dia makan roti dan minum air serba sedikit sampai aku pulang dengan selamat."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 28, 'Tetapi jawab Mikha: "Jika benar-benar engkau pulang dengan selamat, tentulah TUHAN tidak berfirman dengan perantaraanku!" Lalu disambungnya: "Dengarlah, hai bangsa-bangsa sekalian!"', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 29, 'Sesudah itu majulah raja Israel dengan Yosafat, raja Yehuda, ke Ramot-Gilead.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 30, 'Raja Israel berkata kepada Yosafat: "Aku akan menyamar dan masuk pertempuran, tetapi engkau, pakailah pakaian kebesaranmu." Lalu menyamarlah raja Israel, kemudian masuk ke pertempuran.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 31, 'Adapun raja negeri Aram telah memberi perintah kepada para panglima pasukan keretanya, tiga puluh dua orang banyaknya, demikian: "Janganlah kamu berperang melawan sembarang orang, melainkan melawan raja Israel saja."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 32, 'Segera sesudah para panglima pasukan kereta itu melihat Yosafat, mereka berkata: "Itu pasti raja Israel!" Lalu majulah mereka untuk menyerang dia, tetapi Yosafat berteriak.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 33, 'Segera sesudah para panglima pasukan kereta itu melihat, bahwa dia bukanlah raja Israel, maka undurlah mereka dari padanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 34, 'Tetapi seseorang menarik panahnya dan menembak dengan sembarangan saja dan mengenai raja Israel di antara sambungan baju zirahnya. Kemudian ia berkata kepada pengemudi keretanya: "Putar! Bawa aku keluar dari pertempuran, sebab aku sudah luka."', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 35, 'Tetapi pertempuran itu bertambah seru pada hari itu, dan raja tetap ditopang berdiri di dalam kereta berhadapan dengan orang Aram itu, sampai ia mati pada waktu petang. Darahnya mengalir dari lukanya ke dalam palung kereta.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 36, 'Kira-kira pada waktu matahari terbenam terdengarlah teriakan di sepanjang barisan tentara itu: "Masing-masing ke kotanya, masing-masing ke negerinya!', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 37, 'Raja sudah mati!" Maka pulanglah mereka ke Samaria, lalu mereka menguburkan raja di Samaria.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 38, 'Ketika kereta itu dicuci di tepi telaga Samaria, maka darah raja dijilat anjing, sedang perempuan-perempuan sundal mandi di tempat itu, sesuai dengan firman TUHAN yang telah diucapkan-Nya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 39, 'Selebihnya dari riwayat Ahab dan segala yang dilakukannya serta istana gading dan segala kota yang didirikannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 40, 'Demikianlah Ahab mendapat perhentian bersama-sama dengan nenek moyangnya. Maka Ahazia, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 41, 'Yosafat, anak Asa, menjadi raja atas Yehuda dalam tahun keempat zaman Ahab, raja Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 42, 'Yosafat berumur tiga puluh lima tahun pada waktu ia menjadi raja dan dua puluh lima tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Azuba, anak Silhi.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 43, 'Ia hidup mengikuti jejak Asa, ayahnya; ia tidak menyimpang dari padanya dan melakukan apa yang benar di mata TUHAN. (22-44) Hanya bukit-bukit pengorbanan tidak dijauhkan. Orang masih mempersembahkan dan membakar korban di bukit-bukit itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 44, '(22-45) Dan Yosafat hidup dalam damai dengan raja Israel.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 45, '(22-46) Selebihnya dari riwayat Yosafat dan kepahlawanan yang dilakukannya dan bagaimana ia berperang, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 46, '(22-47) Dan sisa pelacuran bakti yang masih tinggal dalam zaman Asa, ayahnya, dihapuskannya dari negeri itu.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 47, '(22-48) Tidak ada raja di Edom, karena itu yang menjadi raja ialah seorang kepala daerah.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 48, '(22-49) Yosafat membuat kapal-kapal Tarsis untuk pergi ke Ofir mengambil emas, tetapi kapal-kapal itu tidak jadi pergi ke sana, sebab kapal-kapal itu pecah di Ezion-Geber.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 49, '(22-50) Pada waktu itu Ahazia, anak Ahab, berkata kepada Yosafat: "Baiklah anak buahku pergi bersama-sama anak buahmu dengan kapal-kapal itu." Tetapi Yosafat tidak mau.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 50, '(22-51) Kemudian Yosafat mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di samping nenek moyangnya di kota Daud, bapa leluhurnya. Maka Yoram, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 51, '(22-52) Ahazia, anak Ahab, menjadi raja atas Israel di Samaria dalam tahun ketujuh belas zaman Yosafat, raja Yehuda, dan ia memerintah atas Israel dua tahun lamanya.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 52, '(22-53) Ia melakukan apa yang jahat di mata TUHAN dan hidup menurut kelakuan ayahnya dan ibunya dan Yerobeam bin Nebat, yang telah mengakibatkan orang Israel berdosa.', 'id', 'TB'),
  ('11', '1raj', '1 Raja-Raja', 22, 53, '(22-54) Ia beribadah kepada Baal dan sujud menyembah kepadanya dan dengan demikian ia menimbulkan sakit hati TUHAN, Allah Israel, tepat seperti yang dilakukan ayahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 1, 'Sesudah Ahab mati, maka memberontaklah Moab terhadap Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 2, 'Pada suatu hari jatuhlah Ahazia dari kisi-kisi kamar atasnya yang ada di Samaria, lalu menjadi sakit. Kemudian dikirimnyalah utusan-utusan dengan pesan: "Pergilah, mintalah petunjuk kepada Baal-Zebub, allah di Ekron, apakah aku akan sembuh dari penyakit ini."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 3, 'Tetapi berfirmanlah Malaikat TUHAN kepada Elia, orang Tisbe itu: "Bangunlah, berangkatlah menemui utusan-utusan raja Samaria dan katakan kepada mereka: Apakah tidak ada Allah di Israel, sehingga kamu ini pergi untuk meminta petunjuk kepada Baal-Zebub, allah di Ekron?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 4, 'Sebab itu beginilah firman TUHAN: Engkau tidak akan bangun lagi dari tempat tidur, di mana engkau berbaring, sebab engkau pasti akan mati." Lalu pergilah Elia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 5, 'Sesudah utusan-utusan itu kembali kepada raja, berkatalah ia kepada mereka: "Mengapa kamu kembali?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 6, 'Jawab mereka kepadanya: "Ada seorang datang menemui kami dan berkata kepada kami: Pergilah, kembalilah kepada raja yang telah menyuruh kamu, dan katakanlah kepadanya: Beginilah firman TUHAN: Apakah tidak ada Allah di Israel, sehingga engkau menyuruh meminta petunjuk kepada Baal-Zebub, allah di Ekron? Sebab itu engkau tidak akan bangun lagi dari tempat tidur di mana engkau berbaring, sebab engkau pasti akan mati."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 7, 'Lalu bertanyalah ia kepada mereka: "Bagaimanakah rupa orang yang telah datang menemui kamu itu dan yang mengatakan perkataan ini kepadamu?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 8, 'Jawab mereka kepadanya: "Seorang yang memakai pakaian bulu, dan ikat pinggang kulit terikat pada pinggangnya." Maka berkatalah ia: "Itu Elia, orang Tisbe!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 9, 'Sesudah itu disuruhnyalah kepada Elia seorang perwira dengan kelima puluh anak buahnya. Orang itu naik menjumpai Elia yang sedang duduk di atas puncak bukit. Berkatalah orang itu kepadanya: "Hai abdi Allah, raja bertitah: Turunlah!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 10, 'Tetapi Elia menjawab, katanya kepada perwira itu: "Kalau benar aku abdi Allah, biarlah turun api dari langit memakan engkau habis dengan kelima puluh anak buahmu." Maka turunlah api dari langit memakan dia habis dengan kelima puluh anak buahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 11, 'Kemudian raja menyuruh pula kepadanya seorang perwira yang lain dengan kelima puluh anak buahnya. Lalu orang itu berkata kepada Elia: "Hai abdi Allah, beginilah titah raja: Segeralah turun!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 12, 'Tetapi Elia menjawab mereka: "Kalau benar aku abdi Allah, biarlah turun api dari langit memakan engkau habis dengan kelima puluh anak buahmu!" Maka turunlah api Allah dari langit memakan dia habis dengan kelima puluh anak buahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 13, 'Kemudian raja menyuruh pula seorang perwira yang ketiga dengan kelima puluh anak buahnya. Lalu naiklah perwira yang ketiga itu dan sesudah sampai, berlututlah ia di depan Elia, serta memohon belas kasihan kepadanya, katanya: "Ya abdi Allah, biarlah kiranya nyawaku dan nyawa kelima puluh orang hamba-hambamu ini berharga di matamu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 14, 'Bukankah api sudah turun dari langit memakan habis kedua perwira yang dahulu dengan kelima puluh anak buah mereka? Tetapi sekarang biarlah nyawaku berharga di matamu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 15, 'Maka berfirmanlah Malaikat TUHAN kepada Elia: "Turunlah bersama-sama dia, janganlah takut kepadanya!" Lalu bangunlah Elia dan turun bersama-sama dia menghadap raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 16, 'Berkatalah Elia kepada raja: "Beginilah firman TUHAN: Oleh karena engkau telah mengirim utusan-utusan untuk meminta petunjuk kepada Baal-Zebub, allah di Ekron, seolah-olah tidak ada Allah di Israel untuk ditanyakan firman-Nya, maka sebab itu engkau tidak akan bangun lagi dari tempat tidur, di mana engkau berbaring, sebab engkau pasti akan mati."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 17, 'Maka matilah raja sesuai dengan firman TUHAN yang dikatakan oleh Elia. Maka Yoram menjadi raja menggantikan dia dalam tahun kedua zaman Yoram bin Yosafat, raja Yehuda, sebab Ahazia tidak mempunyai anak laki-laki.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 1, 18, 'Selebihnya dari riwayat Ahazia, apa yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 1, 'Menjelang saatnya TUHAN hendak menaikkan Elia ke sorga dalam angin badai, Elia dan Elisa sedang berjalan dari Gilgal.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 2, 'Berkatalah Elia kepada Elisa: "Baiklah tinggal di sini, sebab TUHAN menyuruh aku ke Betel." Tetapi Elisa menjawab: "Demi TUHAN yang hidup dan demi hidupmu sendiri, sesungguhnya aku tidak akan meninggalkan engkau." Lalu pergilah mereka ke Betel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 3, 'Pada waktu itu keluarlah rombongan nabi yang ada di Betel mendapatkan Elisa, lalu berkatalah mereka kepadanya: "Sudahkah engkau tahu, bahwa pada hari ini tuanmu akan diambil dari padamu oleh TUHAN terangkat ke sorga?" Jawabnya: "Aku juga tahu, diamlah!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 4, 'Berkatalah Elia kepadanya: "Hai Elisa, baiklah tinggal di sini, sebab TUHAN menyuruh aku ke Yerikho." Tetapi jawabnya: "Demi TUHAN yang hidup dan demi hidupmu sendiri, sesungguhnya aku tidak akan meninggalkan engkau." Lalu sampailah mereka di Yerikho.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 5, 'Pada waktu itu mendekatlah rombongan nabi yang ada di Yerikho kepada Elisa serta berkata kepadanya: "Sudahkah engkau tahu, bahwa pada hari ini tuanmu akan diambil dari padamu oleh TUHAN terangkat ke sorga?" Jawabnya: "Aku juga tahu, diamlah!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 6, 'Berkatalah Elia kepadanya: "Baiklah tinggal di sini, sebab TUHAN menyuruh aku ke sungai Yordan." Jawabnya: "Demi TUHAN yang hidup dan demi hidupmu sendiri, sesungguhnya aku tidak akan meninggalkan engkau." Lalu berjalanlah keduanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 7, 'Lima puluh orang dari rombongan nabi itu ikut berjalan, tetapi mereka berdiri memandang dari jauh, ketika keduanya berdiri di tepi sungai Yordan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 8, 'Lalu Elia mengambil jubahnya, digulungnya, dipukulkannya ke atas air itu, maka terbagilah air itu ke sebelah sini dan ke sebelah sana, sehingga menyeberanglah keduanya dengan berjalan di tanah yang kering.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 9, 'Dan sesudah mereka sampai di seberang, berkatalah Elia kepada Elisa: "Mintalah apa yang hendak kulakukan kepadamu, sebelum aku terangkat dari padamu." Jawab Elisa: "Biarlah kiranya aku mendapat dua bagian dari rohmu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 10, 'Berkatalah Elia: "Yang kauminta itu adalah sukar. Tetapi jika engkau dapat melihat aku terangkat dari padamu, akan terjadilah kepadamu seperti yang demikian, dan jika tidak, tidak akan terjadi."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 11, 'Sedang mereka berjalan terus sambil berkata-kata, tiba-tiba datanglah kereta berapi dengan kuda berapi memisahkan keduanya, lalu naiklah Elia ke sorga dalam angin badai.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 12, 'Ketika Elisa melihat itu, maka berteriaklah ia: "Bapaku, bapaku! Kereta Israel dan orang-orangnya yang berkuda!" Kemudian tidak dilihatnya lagi, lalu direnggutkannya pakaiannya dan dikoyakkannya menjadi dua koyakan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 13, 'Sesudah itu dipungutnya jubah Elia yang telah terjatuh, lalu ia berjalan hendak pulang dan berdiri di tepi sungai Yordan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 14, 'Ia mengambil jubah Elia yang telah terjatuh itu, dipukulkannya ke atas air itu sambil berseru: "Di manakah TUHAN, Allah Elia?" Ia memukul air itu, lalu terbagi ke sebelah sini dan ke sebelah sana, maka menyeberanglah Elisa.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 15, 'Ketika rombongan nabi yang dari Yerikho itu melihat dia dari jauh, mereka berkata: "Roh Elia telah hinggap pada Elisa." Mereka datang menemui dia, lalu sujudlah mereka kepadanya sampai ke tanah.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 16, 'Mereka berkata: "Coba lihat! Di antara hamba-hambamu ini ada lima puluh orang laki-laki, orang-orang tangkas. Biarlah mereka itu pergi mencari tuanmu, jangan-jangan ia diangkat oleh Roh TUHAN dan dilemparkan-Nya ke atas salah satu gunung atau ke dalam salah satu lembah." Elisa menjawab: "Janganlah suruh pergi!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 17, 'Tetapi ketika mereka mendesak-desak dia sampai memalukan, maka berkatalah ia: "Suruhlah pergi!" Mereka menyuruh lima puluh orang. Orang-orang ini mencari tiga hari lamanya, tetapi tidak bertemu dengan Elia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 18, 'Ketika mereka kembali kepada Elisa yang masih tinggal di kota Yerikho, berkatalah ia kepada mereka: "Bukankah telah kukatakan kepadamu: Jangan pergi?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 19, 'Berkatalah penduduk kota itu kepada Elisa: "Cobalah lihat! Letaknya kota ini baik, seperti tuanku lihat, tetapi airnya tidak baik dan di negeri ini sering ada keguguran bayi."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 20, 'Jawabnya: "Ambillah sebuah pinggan baru bagiku dan taruhlah garam ke dalamnya." Maka mereka membawa pinggan itu kepadanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 21, 'Kemudian pergilah ia ke mata air mereka dan melemparkan garam itu ke dalamnya serta berkata: "Beginilah firman TUHAN: Telah Kusehatkan air ini, maka tidak akan terjadi lagi olehnya kematian atau keguguran bayi."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 22, 'Demikianlah air itu menjadi sehat sampai hari ini sesuai dengan firman yang telah disampaikan Elisa.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 23, 'Elisa pergi dari sana ke Betel. Dan sedang ia mendaki, maka keluarlah anak-anak dari kota itu, lalu mencemoohkan dia serta berseru kepadanya: "Naiklah botak, naiklah botak!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 24, 'Lalu berpalinglah ia ke belakang, dan ketika ia melihat mereka, dikutuknyalah mereka demi nama TUHAN. Maka keluarlah dua ekor beruang dari hutan, lalu mencabik-cabik dari mereka empat puluh dua orang anak.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 2, 25, 'Dari sana pergilah ia ke gunung Karmel dan dari sana pula kembalilah ia ke Samaria.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 1, 'Yoram, anak Ahab, menjadi raja di Samaria atas Israel dalam tahun kedelapan belas zaman Yosafat, raja Yehuda, dan ia memerintah dua belas tahun lamanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 2, 'Ia melakukan apa yang jahat di mata TUHAN, tetapi bukan seperti ayahnya dan seperti ibunya: ia menjauhkan tugu berhala Baal yang didirikan ayahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 3, 'Namun demikian, ia masih berpaut kepada dosa Yerobeam bin Nebat yang mengakibatkan orang Israel berdosa pula; ia tidak menjauhinya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 4, 'Mesa, raja Moab, adalah seorang peternak domba; sebagai upeti ia membayar kepada raja Israel seratus ribu anak domba dan bulu dari seratus ribu domba jantan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 5, 'Tetapi segera sesudah Ahab mati, memberontaklah raja Moab terhadap raja Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 6, 'Keluarlah raja Yoram pada waktu itu dari Samaria, lalu ia memeriksa barisan seluruh orang Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 7, 'Selanjutnya ia menyuruh orang kepada Yosafat, raja Yehuda, dengan pesan: "Raja Moab telah memberontak terhadap aku! Maukah engkau bersama-sama aku berperang melawan Moab?" Jawabnya: "Aku akan maju. Kita sama-sama, aku dan engkau, rakyatku dan rakyatmu, kudaku dan kudamu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 8, 'Lagi ia bertanya: "Melalui jalan manakah kita akan maju?" Jawabnya: "Melalui padang gurun Edom!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 9, 'Maka berjalanlah raja Israel dan raja Yehuda dan raja Edom. Tetapi sesudah mereka berkeliling tujuh hari perjalanan jauhnya, maka tidak terdapat air untuk tentara dan untuk hewan yang mengikuti mereka.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 10, 'Lalu berkatalah raja Israel: "Wahai, TUHAN telah memanggil ketiga raja ini untuk menyerahkan mereka ke dalam tangan Moab!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 11, 'Tetapi bertanyalah Yosafat: "Tidak adakah di sini seorang nabi TUHAN, supaya dengan perantaraannya kita meminta petunjuk TUHAN?" Lalu salah seorang pegawai raja Israel menjawab, katanya: "Di sini ada Elisa bin Safat, yang dahulu melayani Elia."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 12, 'Berkatalah Yosafat: "Memang padanya ada firman TUHAN." Sesudah itu pergilah raja Israel dan Yosafat dan raja Edom kepada Elisa.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 13, 'Tetapi berkatalah Elisa kepada raja Israel: "Apakah urusanku dengan engkau? Pergilah kepada para nabi ayahmu dan kepada para nabi ibumu." Jawab raja Israel kepadanya: "Jangan begitu, sebab TUHAN memanggil ketiga raja ini untuk menyerahkan mereka ke dalam tangan orang Moab!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 14, 'Berkatalah Elisa: "Demi TUHAN semesta alam yang hidup, yang di hadapan-Nya aku menjadi pelayan: jika tidak karena Yosafat, raja Yehuda, maka sesungguhnya aku ini tidak akan memandang dan melihat kepadamu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 15, 'Maka sekarang, jemputlah bagiku seorang pemetik kecapi." Pada waktu pemetik kecapi itu bermain kecapi, maka kekuasaan TUHAN meliputi dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 16, 'Kemudian berkatalah ia: "Beginilah firman TUHAN: Biarlah di lembah ini dibuat parit-parit,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 17, 'sebab beginilah firman TUHAN: Kamu tidak akan mendapat angin dan hujan, namun lembah ini akan penuh dengan air, sehingga kamu serta ternak sembelihan dan hewan pengangkut dapat minum.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 18, 'Dan itupun adalah perkara ringan di mata TUHAN; juga orang Moab akan diserahkan-Nya ke dalam tanganmu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 19, 'Kamu akan memusnahkan segala kota yang berkubu dan segala kota pilihan; kamu akan menumbangkan segala pohon yang baik; kamu akan menutup segala mata air dan kamu akan merusakkan segala ladang yang baik dengan batu-batu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 20, 'Keesokan harinya ketika orang mempersembahkan korban, datanglah dengan tiba-tiba air dari arah Edom, lalu penuhlah negeri itu dengan air.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 21, 'Ketika didengar seluruh orang Moab, bahwa ketiga raja itu telah maju memerangi mereka, maka dikerahkanlah semua orang yang masih sanggup menyandang pedang, bahkan orang-orang yang lebih tua juga, kemudian mereka ditempatkan di tepi perbatasan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 22, 'Keesokan harinya pagi-pagi, ketika matahari bersinar atas permukaan air itu, tampaklah kepada orang Moab itu, bahwa air di sebelah depannya merah seperti darah.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 23, 'Lalu berserulah mereka: "Itu darah! Tentulah raja-raja itu telah berbunuh-bunuhan, yang seorang membunuh yang lain. Maka sekarang, marilah menjarah, hai orang-orang Moab!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 24, 'Tetapi ketika mereka sampai ke perkemahan orang Israel, maka bangkitlah orang Israel itu, lalu memukul orang-orang Moab, sehingga mereka lari dari situ. Dan makin jauhlah mereka menerobos ke dalam Moab sambil menewaskan orang-orang Moab itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 25, 'Mereka meruntuhkan kota-kota dan menutupi setiap ladang yang baik dengan batu, karena setiap orang melemparkan batu ke atasnya. Mereka menutup segala mata air dan menumbangkan segala pohon yang baik, sampai hanya Kir-Hareset saja yang ditinggalkan, tetapi kota ini ditembaki oleh orang-orang pengumban dari segala penjuru.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 26, 'Ketika raja Moab melihat, bahwa peperangan itu terlalu berat baginya, diambilnyalah tujuh ratus orang pemegang pedang bersama-sama dia untuk menerobos ke jurusan raja Edom, tetapi tidak berhasil.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 3, 27, 'Kemudian ia mengambil anaknya yang sulung yang akan menjadi raja menggantikan dia, lalu mempersembahkannya sebagai korban bakaran di atas pagar tembok. Tetapi kegusaran besar menimpa orang Israel, sehingga mereka berangkat meninggalkan dia dan pulang ke negeri mereka.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 1, 'Salah seorang dari isteri-isteri para nabi mengadukan halnya kepada Elisa, sambil berseru: "Hambamu, suamiku, sudah mati dan engkau ini tahu, bahwa hambamu itu takut akan TUHAN. Tetapi sekarang, penagih hutang sudah datang untuk mengambil kedua orang anakku menjadi budaknya."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 2, 'Jawab Elisa kepadanya: "Apakah yang dapat kuperbuat bagimu? Beritahukanlah kepadaku apa-apa yang kaupunya di rumah." Berkatalah perempuan itu: "Hambamu ini tidak punya sesuatu apapun di rumah, kecuali sebuah buli-buli berisi minyak."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 3, 'Lalu berkatalah Elisa: "Pergilah, mintalah bejana-bejana dari luar, dari pada segala tetanggamu, bejana-bejana kosong, tetapi jangan terlalu sedikit.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 4, 'Kemudian masuklah, tutuplah pintu sesudah engkau dan anak-anakmu masuk, lalu tuanglah minyak itu ke dalam segala bejana. Mana yang penuh, angkatlah!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 5, 'Pergilah perempuan itu dari padanya; ditutupnyalah pintu sesudah ia dan anak-anaknya masuk; dan anak-anaknya mendekatkan bejana-bejana kepadanya, sedang ia terus menuang.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 6, 'Ketika bejana-bejana itu sudah penuh, berkatalah perempuan itu kepada anaknya: "Dekatkanlah kepadaku sebuah bejana lagi," tetapi jawabnya kepada ibunya: "Tidak ada lagi bejana." Lalu berhentilah minyak itu mengalir.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 7, 'Kemudian pergilah perempuan itu memberitahukannya kepada abdi Allah, dan orang ini berkata: "Pergilah, juallah minyak itu, bayarlah hutangmu, dan hiduplah dari lebihnya, engkau serta anak-anakmu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 8, 'Pada suatu hari Elisa pergi ke Sunem. Di sana tinggal seorang perempuan kaya yang mengundang dia makan. Dan seberapa kali ia dalam perjalanan, singgahlah ia ke sana untuk makan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 9, 'Berkatalah perempuan itu kepada suaminya: "Sesungguhnya aku sudah tahu bahwa orang yang selalu datang kepada kita itu adalah abdi Allah yang kudus.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 10, 'Baiklah kita membuat sebuah kamar atas yang kecil yang berdinding batu, dan baiklah kita menaruh di sana baginya sebuah tempat tidur, sebuah meja, sebuah kursi dan sebuah kandil, maka apabila ia datang kepada kita, ia boleh masuk ke sana."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 11, 'Pada suatu hari datanglah ia ke sana, lalu masuklah ia ke kamar atas itu dan tidur di situ.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 12, 'Kemudian berkatalah ia kepada Gehazi, bujangnya: "Panggillah perempuan Sunem itu." Lalu dipanggilnyalah perempuan itu dan dia berdiri di depan Gehazi.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 13, 'Elisa telah berkata kepada Gehazi: "Cobalah katakan kepadanya: Sesungguhnya engkau telah sangat bersusah-susah seperti ini untuk kami. Apakah yang dapat kuperbuat bagimu? Adakah yang dapat kubicarakan tentang engkau kepada raja atau kepala tentara?" Jawab perempuan itu: "Aku ini tinggal di tengah-tengah kaumku!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 14, 'Kemudian berkatalah Elisa: "Apakah yang dapat kuperbuat baginya?" Jawab Gehazi: "Ah, ia tidak mempunyai anak, dan suaminya sudah tua."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 15, 'Lalu berkatalah Elisa: "Panggillah dia!" Dan sesudah dipanggilnya, berdirilah perempuan itu di pintu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 16, 'Berkatalah Elisa: "Pada waktu seperti ini juga, tahun depan, engkau ini akan menggendong seorang anak laki-laki." Tetapi jawab perempuan itu: "Janganlah tuanku, ya abdi Allah, janganlah berdusta kepada hambamu ini!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 17, 'Mengandunglah perempuan itu, lalu melahirkan seorang anak laki-laki pada waktu seperti itu juga, pada tahun berikutnya, seperti yang dikatakan Elisa kepadanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 18, 'Setelah anak itu menjadi besar, pada suatu hari keluarlah ia mendapatkan ayahnya, di antara penyabit-penyabit gandum.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 19, 'Tiba-tiba menjeritlah ia kepada ayahnya: "Aduh kepalaku, kepalaku!" Lalu kata ayahnya kepada seorang bujang: "Angkatlah dia dan bawa kepada ibunya!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 20, 'Diangkatnyalah dia, dibawanya pulang kepada ibunya. Duduklah dia di pangkuan ibunya sampai tengah hari, tetapi sesudah itu matilah dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 21, 'Lalu naiklah perempuan itu, dibaringkannyalah dia di atas tempat tidur abdi Allah itu, ditutupnyalah pintu dan pergi, sehingga anak itu saja di dalam kamar.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 22, 'Sesudah itu ia memanggil suaminya serta berkata: "Suruh kepadaku salah seorang bujang dengan membawa seekor keledai betina; aku mau pergi dengan segera kepada abdi Allah itu, dan akan terus pulang."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 23, 'Berkatalah suaminya: "Mengapakah pada hari ini engkau hendak pergi kepadanya? Padahal sekarang bukan bulan baru dan bukan hari Sabat." Jawab perempuan itu: "Jangan kuatir."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 24, 'Dipelanainyalah keledai itu dan berkatalah ia kepada bujangnya: "Tuntunlah dan majulah, jangan tahan-tahan aku dalam perjalananku, kecuali apabila kukatakan kepadamu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 25, 'Demikianlah perempuan itu berangkat dan pergi kepada abdi Allah di gunung Karmel. Segera sesudah abdi Allah melihat dia dari jauh, berkatalah ia kepada Gehazi, bujangnya: "Lihat, perempuan Sunem itu datang!', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 26, 'Larilah menyongsongnya dan katakanlah kepadanya: Selamatkah engkau, selamatkah suamimu, selamatkah anak itu?" Jawab perempuan itu: "Selamat!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 27, 'Dan sesudah ia sampai ke gunung itu, dipegangnyalah kaki abdi Allah itu, tetapi Gehazi mendekat hendak mengusir dia. Lalu berkatalah abdi Allah: "Biarkanlah dia, hatinya pedih! TUHAN menyembunyikan hal ini dari padaku, tidak memberitahukannya kepadaku."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 28, 'Lalu berkatalah perempuan itu: "Adakah kuminta seorang anak laki-laki dari pada tuanku? Bukankah telah kukatakan: Jangan aku diberi harapan kosong?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 29, 'Maka berkatalah Elisa kepada Gehazi: "Ikatlah pinggangmu, bawalah tongkatku di tanganmu dan pergilah. Apabila engkau bertemu dengan seseorang, janganlah beri salam kepadanya dan apabila seseorang memberi salam kepadamu, janganlah balas dia, kemudian taruhlah tongkatku ini di atas anak itu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 30, 'Tetapi berkatalah ibu anak itu: "Demi TUHAN yang hidup dan demi hidupmu sendiri, sesungguhnya aku tidak akan meninggalkan engkau." Lalu bangunlah Elisa dan berjalan mengikuti perempuan itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 31, 'Adapun Gehazi telah berjalan mendahului mereka dan telah menaruh tongkat di atas anak itu, tetapi tidak ada suara, dan tidak ada tanda hidup. Lalu kembalilah ia menemui Elisa serta memberitahukan kepadanya, katanya: "Anak itu tidak bangun!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 32, 'Dan ketika Elisa masuk ke rumah, ternyata anak itu sudah mati dan terbaring di atas tempat tidurnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 33, 'Sesudah ia masuk, ditutupnyalah pintu, sehingga ia sendiri dengan anak itu di dalam kamar, kemudian berdoalah ia kepada TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 34, 'Lalu ia membaringkan dirinya di atas anak itu dengan mulutnya di atas mulut anak itu, dan matanya di atas mata anak itu, serta telapak tangannya di atas telapak tangan anak itu; dan karena ia meniarap di atas anak itu, maka menjadi panaslah badan anak itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 35, 'Sesudah itu ia berdiri kembali dan berjalan dalam rumah itu sekali ke sana dan sekali ke sini, kemudian meniarap pulalah ia di atas anak itu. Maka bersinlah anak itu sampai tujuh kali, lalu membuka matanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 36, 'Kemudian Elisa memanggil Gehazi dan berkata: "Panggillah perempuan Sunem itu!" Dipanggilnyalah dia, lalu datanglah ia kepadanya, maka berkatalah Elisa: "Angkatlah anakmu ini!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 37, 'Masuklah perempuan itu, lalu tersungkur di depan kaki Elisa dan sujud menyembah dengan mukanya sampai ke tanah. Kemudian diangkatnyalah anaknya, lalu keluar.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 38, 'Elisa kembali ke Gilgal pada waktu ada kelaparan di negeri itu. Dan ketika pada suatu kali rombongan nabi duduk di depannya, berkatalah ia kepada bujangnya: "Taruhlah kuali yang paling besar di atas api dan masaklah sesuatu makanan bagi rombongan nabi itu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 39, 'Lalu keluarlah seorang dari mereka ke ladang untuk mengumpulkan sayur-sayuran; ia menemui pohon sulur-suluran liar dan memetik dari padanya labu liar, serangkul penuh dalam jubahnya. Sesudah ia pulang, teruslah ia mengiris-irisnya ke dalam kuali masakan tadi, sebab mereka tidak mengenalnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 40, 'Kemudian dicedoklah dari masakan tadi bagi orang-orang itu untuk dimakan dan segera sesudah mereka memakannya, berteriaklah mereka serta berkata: "Maut ada dalam kuali itu, hai abdi Allah!" Dan tidak tahan mereka memakannya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 41, 'Tetapi berkatalah Elisa: "Ambillah tepung!" Dilemparkannyalah itu ke dalam kuali serta berkata: "Cedoklah sekarang bagi orang-orang ini, supaya mereka makan!" Maka tidak ada lagi sesuatu bahaya dalam kuali itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 42, 'Datanglah seseorang dari Baal-Salisa dengan membawa bagi abdi Allah roti hulu hasil, yaitu dua puluh roti jelai serta gandum baru dalam sebuah kantong. Lalu berkatalah Elisa: "Berilah itu kepada orang-orang ini, supaya mereka makan."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 43, 'Tetapi pelayannya itu berkata: "Bagaimanakah aku dapat menghidangkan ini di depan seratus orang?" Jawabnya: "Berikanlah kepada orang-orang itu, supaya mereka makan, sebab beginilah firman TUHAN: Orang akan makan, bahkan akan ada sisanya."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 4, 44, 'Lalu dihidangkannyalah di depan mereka, maka makanlah mereka dan ada sisanya, sesuai dengan firman TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 1, 'Naaman, panglima raja Aram, adalah seorang terpandang di hadapan tuannya dan sangat disayangi, sebab oleh dia TUHAN telah memberikan kemenangan kepada orang Aram. Tetapi orang itu, seorang pahlawan tentara, sakit kusta.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 2, 'Orang Aram pernah keluar bergerombolan dan membawa tertawan seorang anak perempuan dari negeri Israel. Ia menjadi pelayan pada isteri Naaman.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 3, 'Berkatalah gadis itu kepada nyonyanya: "Sekiranya tuanku menghadap nabi yang di Samaria itu, maka tentulah nabi itu akan menyembuhkan dia dari penyakitnya."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 4, 'Lalu pergilah Naaman memberitahukan kepada tuannya, katanya: "Begini-beginilah dikatakan oleh gadis yang dari negeri Israel itu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 5, 'Maka jawab raja Aram: "Baik, pergilah dan aku akan mengirim surat kepada raja Israel." Lalu pergilah Naaman dan membawa sebagai persembahan sepuluh talenta perak dan enam ribu syikal emas dan sepuluh potong pakaian.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 6, 'Ia menyampaikan surat itu kepada raja Israel, yang berbunyi: "Sesampainya surat ini kepadamu, maklumlah kiranya, bahwa aku menyuruh kepadamu Naaman, pegawaiku, supaya engkau menyembuhkan dia dari penyakit kustanya."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 7, 'Segera sesudah raja Israel membaca surat itu, dikoyakkannyalah pakaiannya serta berkata: "Allahkah aku ini yang dapat mematikan dan menghidupkan, sehingga orang ini mengirim pesan kepadaku, supaya kusembuhkan seorang dari penyakit kustanya? Tetapi sesungguhnya, perhatikanlah dan lihatlah, ia mencari gara-gara terhadap aku."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 8, 'Segera sesudah didengar Elisa, abdi Allah itu, bahwa raja Israel mengoyakkan pakaiannya, dikirimnyalah pesan kepada raja, bunyinya: "Mengapa engkau mengoyakkan pakaianmu? Biarlah ia datang kepadaku, supaya ia tahu bahwa ada seorang nabi di Israel."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 9, 'Kemudian datanglah Naaman dengan kudanya dan keretanya, lalu berhenti di depan pintu rumah Elisa.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 10, 'Elisa menyuruh seorang suruhan kepadanya mengatakan: "Pergilah mandi tujuh kali dalam sungai Yordan, maka tubuhmu akan pulih kembali, sehingga engkau menjadi tahir."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 11, 'Tetapi pergilah Naaman dengan gusar sambil berkata: "Aku sangka bahwa setidak-tidaknya ia datang ke luar dan berdiri memanggil nama TUHAN, Allahnya, lalu menggerak-gerakkan tangannya di atas tempat penyakit itu dan dengan demikian menyembuhkan penyakit kustaku!', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 12, 'Bukankah Abana dan Parpar, sungai-sungai Damsyik, lebih baik dari segala sungai di Israel? Bukankah aku dapat mandi di sana dan menjadi tahir?" Kemudian berpalinglah ia dan pergi dengan panas hati.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 13, 'Tetapi pegawai-pegawainya datang mendekat serta berkata kepadanya: "Bapak, seandainya nabi itu menyuruh perkara yang sukar kepadamu, bukankah bapak akan melakukannya? Apalagi sekarang, ia hanya berkata kepadamu: Mandilah dan engkau akan menjadi tahir."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 14, 'Maka turunlah ia membenamkan dirinya tujuh kali dalam sungai Yordan, sesuai dengan perkataan abdi Allah itu. Lalu pulihlah tubuhnya kembali seperti tubuh seorang anak dan ia menjadi tahir.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 15, 'Kemudian kembalilah ia dengan seluruh pasukannya kepada abdi Allah itu. Setelah sampai, tampillah ia ke depan Elisa dan berkata: "Sekarang aku tahu, bahwa di seluruh bumi tidak ada Allah kecuali di Israel. Karena itu terimalah kiranya suatu pemberian dari hambamu ini!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 16, 'Tetapi Elisa menjawab: "Demi TUHAN yang hidup, yang di hadapan-Nya aku menjadi pelayan, sesungguhnya aku tidak akan menerima apa-apa." Dan walaupun Naaman mendesaknya supaya menerima sesuatu, ia tetap menolak.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 17, 'Akhirnya berkatalah Naaman: "Jikalau demikian, biarlah diberikan kepada hambamu ini tanah sebanyak muatan sepasang bagal, sebab hambamu ini tidak lagi akan mempersembahkan korban bakaran atau korban sembelihan kepada allah lain kecuali kepada TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 18, 'Dan kiranya TUHAN mengampuni hambamu ini dalam perkara yang berikut: Apabila tuanku masuk ke kuil Rimon untuk sujud menyembah di sana, dan aku menjadi pengapitnya, sehingga aku harus ikut sujud menyembah dalam kuil Rimon itu, kiranya TUHAN mengampuni hambamu ini dalam hal itu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 19, 'Maka berkatalah Elisa kepadanya: "Pergilah dengan selamat!" Setelah Naaman berjalan tidak berapa jauh dari padanya,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 20, 'berpikirlah Gehazi, bujang Elisa, abdi Allah: "Sesungguhnya tuanku terlalu menyegani Naaman, orang Aram ini, dengan tidak menerima persembahan yang dibawanya. Demi TUHAN yang hidup, sesungguhnya aku akan berlari mengejar dia dan akan menerima sesuatu dari padanya."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 21, 'Lalu Gehazi mengejar Naaman dari belakang. Ketika Naaman melihat ada orang berlari-lari mengejarnya, turunlah ia dengan segera dari atas kereta untuk mendapatkan dia dan berkata: "Selamat!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 22, 'Jawabnya: "Selamat! Tuanku Elisa menyuruh aku mengatakan: Baru saja datang kepadaku dua orang muda dari pegunungan Efraim dari antara rombongan nabi. Baiklah berikan kepada mereka setalenta perak dan dua potong pakaian."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 23, 'Naaman berkata: "Silakan, ambillah dua talenta." Naaman mendesak dia, dan membungkus dua talenta perak dalam dua pundi-pundi dan dua potong pakaian, lalu memberikannya kepada dua bujangnya; mereka ini mengangkut semuanya di depan Gehazi.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 24, 'Setelah mereka sampai ke bukit, disambutnyalah dari tangan mereka, disimpannya di rumah, dan disuruhnya kedua orang itu pergi, maka pergilah mereka.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 25, 'Baru saja Gehazi masuk dan tampil ke depan tuannya, berkatalah Elisa kepadanya: "Dari mana, Gehazi?" Jawabnya: "Hambamu ini tidak pergi ke mana-mana!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 26, 'Tetapi kata Elisa kepadanya: "Bukankah hatiku ikut pergi, ketika orang itu turun dari atas keretanya mendapatkan engkau? Maka sekarang, engkau telah menerima perak dan dengan itu dapat memperoleh kebun-kebun, kebun zaitun, kebun anggur, kambing domba, lembu sapi, budak laki-laki dan budak perempuan,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 5, 27, 'tetapi penyakit kusta Naaman akan melekat kepadamu dan kepada anak cucumu untuk selama-lamanya." Maka keluarlah Gehazi dari depannya dengan kena kusta, putih seperti salju.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 1, 'Pada suatu hari berkatalah rombongan nabi kepada Elisa: "Cobalah lihat, tempat tinggal kami di dekatmu ini adalah terlalu sesak bagi kami.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 2, 'Baiklah kami pergi ke sungai Yordan dan masing-masing mengambil satu balok dari sana, supaya kami membuat tempat tinggal untuk kami." Jawab Elisa: "Pergilah!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 3, 'Lalu berkatalah seorang: "Silakan, ikutlah dengan hamba-hambamu ini." Jawabnya: "Baik aku akan ikut."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 4, 'Maka ikutlah ia dengan mereka. Setelah mereka sampai di sungai Yordan, merekapun menebang pohon-pohon.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 5, 'Dan terjadilah, ketika seorang sedang menumbangkan sebatang pohon, jatuhlah mata kapaknya ke dalam air. Lalu berteriak-teriaklah ia: "Wahai tuanku! Itu barang pinjaman!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 6, 'Tetapi berkatalah abdi Allah: "Ke mana jatuhnya?" Lalu orang itu menunjukkan tempat itu kepadanya. Kemudian Elisa memotong sepotong kayu, lalu dilemparkannya ke sana, maka timbullah mata kapak itu dibuatnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 7, 'Lalu katanya: "Ambillah." Orang itu mengulurkan tangannya dan mengambilnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 8, 'Raja negeri Aram sedang berperang melawan Israel. Ia berunding dengan pegawai-pegawainya, lalu katanya: "Ke tempat ini dan itu haruslah kamu turun menghadang."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 9, 'Tetapi abdi Allah menyuruh orang kepada raja Israel mengatakan: "Awas, jangan lewat dari tempat itu, sebab orang Aram sudah turun menghadang ke sana."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 10, 'Sebab itu raja Israel menyuruh orang-orang ke tempat yang disebutkan abdi Allah kepadanya. Demikianlah Elisa memperingatkan kepadanya, supaya berawas-awas di sana, bukan sekali dua kali saja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 11, 'Lalu mengamuklah hati raja Aram tentang hal itu, maka dipanggilnyalah pegawai-pegawainya, katanya kepada mereka: "Tidakkah dapat kamu memberitahukan kepadaku siapa dari kita memihak kepada raja Israel?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 12, 'Tetapi berkatalah salah seorang pegawainya: "Tidak tuanku raja, melainkan Elisa, nabi yang di Israel, dialah yang memberitahukan kepada raja Israel tentang perkataan yang diucapkan oleh tuanku di kamar tidurmu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 13, 'Berkatalah raja: "Pergilah melihat, di mana dia, supaya aku menyuruh orang menangkap dia." Lalu diberitahukanlah kepadanya: "Dia ada di Dotan."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 14, 'Maka dikirimnyalah ke sana kuda serta kereta dan tentara yang besar. Sampailah mereka pada waktu malam, lalu mengepung kota itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 15, 'Ketika pelayan abdi Allah bangun pagi-pagi dan pergi ke luar, maka tampaklah suatu tentara dengan kuda dan kereta ada di sekeliling kota itu. Lalu berkatalah bujangnya itu kepadanya: "Celaka tuanku! Apakah yang akan kita perbuat?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 16, 'Jawabnya: "Jangan takut, sebab lebih banyak yang menyertai kita dari pada yang menyertai mereka."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 17, 'Lalu berdoalah Elisa: "Ya TUHAN: Bukalah kiranya matanya, supaya ia melihat." Maka TUHAN membuka mata bujang itu, sehingga ia melihat. Tampaklah gunung itu penuh dengan kuda dan kereta berapi sekeliling Elisa.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 18, 'Ketika orang-orang Aram itu turun mendatangi dia, berdoalah Elisa kepada TUHAN: "Butakanlah kiranya mata orang-orang ini." Maka dibutakan-Nyalah mata mereka, sesuai dengan doa Elisa.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 19, 'Kemudian berkatalah Elisa kepada mereka: "Bukan ini jalannya dan bukan ini kotanya. Ikutlah aku, maka aku akan mengantarkan kamu kepada orang yang kamu cari." Lalu diantarkannya mereka ke Samaria.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 20, 'Segera sesudah mereka sampai ke Samaria berkatalah Elisa: "Ya TUHAN, bukalah mata orang-orang ini, supaya mereka melihat." Lalu TUHAN membuka mata mereka, sehingga mereka melihat, dan heran, mereka ada di tengah-tengah Samaria.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 21, 'Lalu bertanyalah raja Israel kepada Elisa, tatkala melihat mereka: "Kubunuhkah mereka, bapak?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 22, 'Tetapi jawabnya: "Jangan! Biasakah kaubunuh yang kautawan dengan pedangmu dan dengan panahmu? Tetapi hidangkanlah makanan dan minuman di depan mereka, supaya mereka makan dan minum, lalu pulang kepada tuan mereka."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 23, 'Disediakannyalah bagi mereka jamuan yang besar, maka makan dan minumlah mereka. Sesudah itu dibiarkannyalah mereka pulang kepada tuan mereka. Sejak itu tidak ada lagi gerombolan-gerombolan Aram memasuki negeri Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 24, 'Sesudah itu Benhadad, raja Aram, menghimpunkan seluruh tentaranya, lalu maju mengepung Samaria.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 25, 'Maka terjadilah kelaparan hebat di Samaria selama mereka mengepungnya, sehingga sebuah kepala keledai berharga delapan puluh syikal perak dan seperempat kab tahi merpati berharga lima syikal perak.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 26, 'Suatu kali ketika raja Israel berjalan di atas tembok, datanglah seorang perempuan mengadukan halnya kepada raja, sambil berseru: "Tolonglah, ya tuanku raja!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 27, 'Jawabnya: "Jika TUHAN tidak menolong engkau, dengan apakah aku dapat menolong engkau? Dengan hasil pengirikankah atau hasil pemerasan anggur?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 28, 'Kemudian bertanyalah raja kepadanya: "Ada apa?" Jawab perempuan itu: "Perempuan ini berkata kepadaku: Berilah anakmu laki-laki, supaya kita makan dia pada hari ini, dan besok akan kita makan anakku laki-laki.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 29, 'Jadi kami memasak anakku dan memakan dia. Tetapi ketika aku berkata kepadanya pada hari berikutnya: Berilah anakmu, supaya kita makan dia, maka perempuan ini menyembunyikan anaknya."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 30, 'Tatkala raja mendengar perkataan perempuan itu, dikoyakkannyalah pakaiannya; dan sedang ia berjalan di atas tembok, kelihatanlah kepada orang banyak, bahwa ia memakai kain kabung pada kulit tubuhnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 31, 'Lalu berkatalah raja: "Beginilah kiranya Allah menghukum aku, bahkan lebih dari pada itu, jika masih tinggal kepala Elisa bin Safat di atas tubuhnya pada hari ini."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 32, 'Adapun Elisa, duduk-duduk di rumahnya, dan para tua-tua duduk bersama-sama dia. Raja menyuruh seorang berjalan mendahuluinya, tetapi sebelum suruhan itu sampai kepada Elisa, Elisa sudah berkata kepada para tua-tua itu: "Tahukah kamu, bahwa si pembunuh itu menyuruh orang untuk memenggal kepalaku? Awas-awaslah, apabila suruhan itu datang, segeralah tutup pintu dan tahanlah dia supaya orang itu jangan masuk. Bukankah sudah kedengaran bunyi langkah tuannya di belakangnya?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 6, 33, 'Selagi ia berbicara dengan mereka, datanglah raja mendapatkan dia. Berkatalah raja kepadanya: "Sesungguhnya, malapetaka ini adalah dari pada TUHAN. Mengapakah aku berharap kepada TUHAN lagi?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 1, 'Lalu berkatalah Elisa: "Dengarlah firman TUHAN. Beginilah firman TUHAN: Besok kira-kira waktu ini sesukat tepung yang terbaik akan berharga sesyikal dan dua sukat jelai akan berharga sesyikal di pintu gerbang Samaria."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 2, 'Tetapi perwira, yang menjadi ajudan raja, menjawab abdi Allah, katanya: "Sekalipun TUHAN membuat tingkap-tingkap di langit, masakan hal itu mungkin terjadi?" Jawab abdi Allah: "Sesungguhnya, engkau akan melihatnya dengan matamu sendiri, tetapi tidak akan makan apa-apa dari padanya."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 3, 'Empat orang yang sakit kusta ada di depan pintu gerbang. Berkatalah yang seorang kepada yang lain: "Mengapakah kita duduk-duduk di sini sampai mati?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 4, 'Jika kita berkata: Baiklah kita masuk ke kota, padahal dalam kota ada kelaparan, kita akan mati di sana. Dan jika kita tinggal di sini, kita akan mati juga. Jadi sekarang, marilah kita menyeberang ke perkemahan tentara Aram. Jika mereka membiarkan kita hidup, kita akan hidup, dan jika mereka mematikan kita, kita akan mati."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 5, 'Lalu pada waktu senja bangkitlah mereka masuk ke tempat perkemahan orang Aram. Tetapi ketika mereka sampai ke pinggir tempat perkemahan orang Aram itu, tampaklah tidak ada orang di sana.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 6, 'Sebab TUHAN telah membuat tentara Aram itu mendengar bunyi kereta, bunyi kuda, bunyi tentara yang besar, sehingga berkatalah yang seorang kepada yang lain: "Sesungguhnya raja Israel telah mengupah raja-raja orang Het dan raja-raja orang Misraim melawan kita, supaya mereka menyerang kita."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 7, 'Karena itu bangkitlah mereka melarikan diri pada waktu senja dengan meninggalkan kemah dan kuda dan keledai mereka serta tempat perkemahan itu dengan begitu saja; mereka melarikan diri menyelamatkan nyawanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 8, 'Ketika orang-orang yang sakit kusta itu sampai ke pinggir tempat perkemahan, masuklah mereka ke dalam sebuah kemah, lalu makan dan minum. Sesudah itu mereka mengangkut dari sana emas dan perak dan pakaian, kemudian pergilah mereka menyembunyikannya. Lalu datanglah mereka kembali, masuk ke dalam kemah yang lain dan mengangkut juga barang-barang dari sana, kemudian pergilah mereka menyembunyikannya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 9, 'Lalu berkatalah yang seorang kepada yang lain: "Tidak patut yang kita lakukan ini. Hari ini ialah hari kabar baik, tetapi kita ini tinggal diam saja. Apabila kita menanti sampai terang pagi, maka hukuman akan menimpa kita. Jadi sekarang, marilah kita pergi menghadap untuk memberitahukan hal itu ke istana raja."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 10, 'Mereka pergi, lalu berseru kepada penunggu pintu gerbang kota dan menceritakan kepada orang-orang itu, katanya: "Kami sudah masuk ke tempat perkemahan orang Aram, dan ternyata tidak ada orang di sana, dan tidak ada suara manusia kedengaran, hanya ada kuda dan keledai tertambat dan kemah-kemah ditinggalkan dengan begitu saja."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 11, 'Para penunggu pintu gerbang menyerukan dan memberitahukan hal itu ke istana raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 12, 'Sekalipun masih malam, raja bangun juga, lalu berkata kepada para pegawainya: "Baiklah kuterangkan kepadamu apa maksud orang Aram itu terhadap kita. Mereka tahu bahwa kita ini menderita kelaparan, sebab itu mereka keluar dari tempat perkemahan untuk menyembunyikan diri di padang, sambil berpikir: Apabila orang Israel keluar dari dalam kota, kita akan menangkap mereka hidup-hidup, kemudian kita masuk ke dalam kota."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 13, 'Lalu salah seorang pegawainya menjawab: "Baiklah kita ambil lima ekor dari kuda yang masih tinggal di dalam kota ini; tentulah keadaannya seperti seluruh khalayak ramai Israel yang sudah habis mati itu! Biarlah kita suruh saja orang pergi, supaya kita lihat."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 14, 'Sesudah itu mereka mengambil dua kereta kuda, kemudian raja menyuruh mereka menyusul tentara Aram sambil berkata: "Pergilah melihatnya!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 15, 'Lalu pergilah mereka menyusul orang-orang itu sampai ke sungai Yordan, dan tampaklah seluruh jalan itu penuh dengan pakaian dan perkakas yang dilemparkan oleh orang Aram pada waktu mereka lari terburu-buru. Kemudian pulanglah suruhan-suruhan itu dan menceritakan hal itu kepada raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 16, 'Maka keluarlah penduduk kota itu menjarah tempat perkemahan orang Aram. Karena itu sesukat tepung yang terbaik berharga sesyikal dan dua sukat jelai berharga sesyikal, sesuai dengan firman TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 17, 'Adapun raja telah menempatkan perwira yang menjadi ajudannya itu mengawasi pintu gerbang, tetapi rakyat menginjak-injak dia di pintu gerbang, lalu ia mati sesuai dengan perkataan abdi Allah yang mengatakannya pada waktu raja datang mendapatkan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 18, 'Dan terjadi juga seperti yang dikatakan abdi Allah itu kepada raja: "Dua sukat jelai akan berharga sesyikal dan sesukat tepung yang terbaik akan berharga sesyikal, besok kira-kira waktu ini di pintu gerbang Samaria."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 19, 'Pada waktu itu si perwira menjawab abdi Allah itu: "Sekalipun TUHAN membuat tingkap-tingkap di langit, masakan hal itu mungkin terjadi?", tetapi Elisa berkata: "Sesungguhnya engkau akan melihatnya dengan matamu sendiri, tetapi tidak akan makan apa-apa dari padanya."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 7, 20, 'Demikianlah terjadi kepada orang itu: Rakyat menginjak-injak dia di pintu gerbang, lalu matilah ia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 1, 'Elisa telah berbicara kepada perempuan yang anaknya dihidupkannya kembali, katanya: "Berkemaslah dan pergilah bersama-sama dengan keluargamu, dan tinggallah di mana saja engkau dapat menetap sebagai pendatang, sebab TUHAN telah mendatangkan kelaparan, yang pasti menimpa negeri ini tujuh tahun lamanya."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 2, 'Lalu berkemaslah perempuan itu dan dilakukannyalah seperti perkataan abdi Allah itu. Ia pergi bersama-sama dengan keluarganya, lalu tinggal menetap sebagai pendatang di negeri orang Filistin tujuh tahun lamanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 3, 'Dan setelah lewat ketujuh tahun itu, pulanglah perempuan itu dari negeri orang Filistin. Kemudian ia pergi mengadukan perihal rumahnya dan ladangnya kepada raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 4, 'Raja sedang berbicara kepada Gehazi, bujang abdi Allah itu, katanya: "Cobalah ceritakan kepadaku tentang segala perbuatan besar yang dilakukan Elisa."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 5, 'Sedang ia menceritakan kepada raja tentang Elisa menghidupkan anak yang sudah mati itu, tampaklah perempuan yang anaknya dihidupkan itu datang mengadukan perihal rumahnya dan ladangnya kepada raja. Lalu berkatalah Gehazi: "Ya tuanku raja! Inilah perempuan itu dan inilah anaknya yang dihidupkan Elisa."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 6, 'Lalu raja bertanya-tanya, dan perempuan itu menceritakan semuanya kepadanya. Kemudian raja menugaskan seorang pegawai istana menyertai perempuan itu dengan pesan: "Pulangkanlah segala miliknya dan segala hasil ladang itu sejak ia meninggalkan negeri ini sampai sekarang."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 7, 'Elisa masuk ke Damsyik, dan pada waktu itu Benhadad, raja Aram, sedang sakit. Ketika dikabarkan kepada raja: "Sudah datang abdi Allah ke mari,"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 8, 'berkatalah ia kepada Hazael: "Ambillah persembahan, pergilah menyongsong abdi Allah itu dan mintalah petunjuk TUHAN dengan perantaraannya: Sembuhkah aku dari penyakit ini?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 9, 'Lalu pergilah Hazael menyongsong dia, diambilnyalah persembahan berupa segala barang yang indah-indah dari Damsyik, sebanyak muatan empat puluh ekor unta. Sesudah sampai, tampillah ia ke depan Elisa dan berkata: "Anakmu Benhadad, raja Aram, menyuruh aku menanyakan kepadamu: Apakah aku akan sembuh dari penyakit ini?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 10, 'Jawab Elisa kepadanya: "Pergilah, katakanlah kepadanya: Pastilah engkau sembuh. Namun demikian, TUHAN telah memperlihatkan kepadaku, bahwa ia pasti mati dibunuh."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 11, 'Elisa menatap dengan lama ke depan, lalu menangislah abdi Allah itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 12, 'Hazael berkata: "Mengapa tuanku menangis?" Jawab Elisa: "Sebab aku tahu bagaimana malapetaka yang akan kaulakukan kepada orang Israel: kotanya yang berkubu akan kaucampakkan ke dalam api, terunanya akan kaubunuh dengan pedang, bayinya akan kauremukkan dan perempuannya yang mengandung akan kaubelah."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 13, 'Sesudah itu berkatalah Hazael: "Tetapi apakah hambamu ini, yang tidak lain dari anjing saja, sehingga ia dapat melakukan hal sehebat itu?" Jawab Elisa: "TUHAN telah memperlihatkan kepadaku, bahwa engkau akan menjadi raja atas Aram."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 14, 'Lalu ia pergi dan meninggalkan Elisa dan setelah ia sampai kepada tuannya, berkatalah raja kepadanya: "Apakah dikatakan Elisa kepadamu?" Jawabnya: "Ia berkata kepadaku, bahwa pastilah engkau sembuh."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 15, 'Tetapi keesokan harinya ia mengambil sehelai selimut yang telah dicelupkannya ke dalam air dan membentangkannya ke atas muka raja. Jadi matilah raja, dan Hazael menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 16, 'Dalam tahun kelima zaman Yoram, anak Ahab raja Israel?pada waktu itu Yosafat adalah raja Yehuda?Yoram, anak Yosafat raja Yehuda menjadi raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 17, 'Ia berumur tiga puluh dua tahun pada waktu ia menjadi raja dan delapan tahun lamanya ia memerintah di Yerusalem.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 18, 'Ia hidup menurut kelakuan raja-raja Israel seperti yang dilakukan keluarga Ahab, sebab yang menjadi isterinya adalah anak Ahab. Ia melakukan apa yang jahat di mata TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 19, 'Namun demikian, TUHAN tidak mau memusnahkan Yehuda oleh karena Daud, hamba-Nya, sesuai dengan yang dijanjikan-Nya kepada Daud, bahwa Ia hendak memberikan keturunan kepadanya dan kepada anak-anaknya untuk selama-lamanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 20, 'Pada zamannya memberontaklah Edom dan melepaskan diri dari kekuasaan Yehuda dan mereka mengangkat seorang raja atas mereka sendiri.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 21, 'Maka majulah Yoram ke Zair bersama-sama dengan seluruh keretanya; pada waktu malam bangunlah ia, lalu bersama-sama dengan para panglima pasukan kereta ia menerobos barisan orang Edom yang mengepung dia, tetapi rakyatnya melarikan diri pulang ke kemahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 22, 'Demikianlah Edom memberontak dan terlepas dari kekuasaan Yehuda sampai sekarang ini. Lalu Libnapun memberontak pada masa itu juga.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 23, 'Selebihnya dari riwayat Yoram dan segala yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 24, 'Kemudian Yoram mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di samping nenek moyangnya di kota Daud. Maka Ahazia, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 25, 'Dalam tahun kedua belas zaman Yoram, anak Ahab raja Israel, Ahazia, anak Yoram raja Yehuda, menjadi raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 26, 'Ia berumur dua puluh dua tahun pada waktu ia menjadi raja dan setahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Atalya, cucu Omri raja Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 27, 'Ia hidup menurut kelakuan keluarga Ahab dan ia melakukan apa yang jahat di mata TUHAN sama seperti keluarga Ahab, sebab ia adalah seorang menantu dari keluarga itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 28, 'Ia pergi bersama-sama Yoram bin Ahab untuk berperang melawan Hazael, raja Aram, di Ramot-Gilead. Tetapi orang-orang Aram melukai Yoram.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 8, 29, 'Kemudian pulanglah raja Yoram ke Yizreel, supaya diobati luka-lukanya yang ditimbulkan orang Aram di Rama pada waktu ia berperang melawan Hazael, raja Aram. Dan Ahazia, anak Yoram raja Yehuda, pergi menjenguk Yoram bin Ahab di Yizreel, karena dia sakit.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 1, 'Kemudian nabi Elisa memanggil salah seorang dari rombongan nabi dan berkata kepadanya: "Ikatlah pinggangmu, bawalah buli-buli berisi minyak ini dan pergilah ke Ramot-Gilead.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 2, 'Apabila engkau sampai ke sana, carilah Yehu bin Yosafat bin Nimsi; masuklah, ajak dia bangkit dari tengah-tengah temannya dan bawalah dia ke ruang dalam.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 3, 'Kemudian ambillah buli-buli berisi minyak itu, lalu tuangkan isinya ke atas kepalanya dan katakan: Beginilah firman TUHAN: Telah Kuurapi engkau menjadi raja atas Israel! Sesudah itu bukalah pintu, larilah dan jangan berlambat-lambat."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 4, 'Lalu nabi muda itu pergi ke Ramot-Gilead.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 5, 'Setelah ia sampai, maka tampaklah panglima-panglima tentara sedang duduk berkumpul. Lalu ia berkata: "Ada pesan kubawa untukmu, ya panglima!" Yehu bertanya: "Untuk siapa dari kami sekalian?" Jawabnya: "Untukmu, ya panglima!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 6, 'Lalu bangkitlah Yehu dan masuk ke dalam rumah. Nabi muda itu menuang minyak ke atas kepala Yehu serta berkata kepadanya: "Beginilah firman TUHAN, Allah Israel: Telah Kuurapi engkau menjadi raja atas umat TUHAN, yaitu orang Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 7, 'Maka engkau akan membunuh keluarga tuanmu Ahab dan dengan demikian Aku membalaskan kepada Izebel darah hamba-hamba-Ku, nabi-nabi itu, bahkan darah semua hamba TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 8, 'Dan segenap keluarga Ahab akan binasa; dan Aku akan melenyapkan dari pada Ahab setiap orang laki-laki, baik yang tinggi maupun yang rendah kedudukannya di Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 9, 'Dan Aku akan memperlakukan keluarga Ahab sama seperti keluarga Yerobeam bin Nebat dan sama seperti keluarga Baesa bin Ahia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 10, 'Izebel akan dimakan anjing di kebun di luar Yizreel dengan tidak ada orang yang menguburkannya." Kemudian nabi itu membuka pintu, lalu lari.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 11, 'Apabila Yehu keluar mendapatkan pegawai-pegawai tuannya, berkatalah seorang kepadanya: "Apa kabar? Mengapa orang gila itu datang kepadamu?" Jawabnya kepada mereka: "Kamu sendiri mengenal orang itu dengan omongannya!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 12, 'Tetapi mereka berkata: "Dusta! Cobalah beritahukan kepada kami!" Lalu katanya: "Begini-beginilah dikatakannya kepadaku: Demikianlah firman TUHAN: Telah Kuurapi engkau menjadi raja atas Israel."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 13, 'Segeralah mereka masing-masing mengambil pakaiannya dan membentangkannya di hadapan kakinya begitu saja di atas tangga, kemudian mereka meniup sangkakala serta berseru: "Yehu raja!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 14, 'Demikianlah Yehu bin Yosafat bin Nimsi mengadakan persepakatan melawan Yoram. ?Adapun Yoram sedang berjaga-jaga di Ramot-Gilead, bersama-sama dengan segenap orang Israel menghadapi Hazael, raja Aram.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 15, 'Tetapi raja Yoram sendiri telah pulang ke Yizreel, supaya luka-lukanya diobati, yang ditimbulkan orang Aram pada waktu ia berperang melawan Hazael, raja Aram. ?Yehu berkata: "Jika kamu sudah setuju, janganlah biarkan siapapun meloloskan diri dari kota untuk memberitahukan hal itu ke Yizreel."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 16, 'Kemudian Yehu naik kereta dan pergi ke Yizreel, sebab Yoram berbaring sakit di sana. Juga Ahazia, raja Yehuda, datang menjenguk Yoram.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 17, 'Ketika jaga yang sedang berdiri di atas menara di Yizreel, melihat pasukan Yehu datang, berserulah ia: "Ada kulihat suatu pasukan." Berkatalah Yoram: "Ambillah seorang penunggang kuda, suruhlah ia menemui mereka serta menanyakan: apakah ini kabar damai?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 18, 'Lalu pergilah penunggang kuda itu untuk menemuinya dan berkata: "Beginilah tanya raja: apakah ini kabar damai?" Jawab Yehu: "Damai? Bukan urusanmu! Baliklah, ikutlah aku!" Dan jaga itu memberitahukan: "Suruhan sudah sampai kepada mereka, tetapi ia tidak pulang."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 19, 'Disuruhnyalah penunggang kuda yang kedua dan setelah sampai kepada mereka berkatalah ia: "Beginilah tanya raja: apakah ini kabar damai?" Jawab Yehu: "Damai? Bukan urusanmu! Baliklah, ikutlah aku!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 20, 'Dan jaga itu memberitahukan: "Sudah sampai ia kepada mereka, tetapi ia tidak pulang! Dan cara memacunya adalah seperti cara Yehu, cucu Nimsi, memacu, sebab ia memacu seperti orang gila."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 21, 'Sesudah itu berkatalah Yoram: "Pasanglah kereta!", lalu orang memasang keretanya. Maka keluarlah Yoram, raja Israel, dan Ahazia, raja Yehuda, masing-masing naik keretanya; mereka keluar menemui Yehu, lalu menjumpai dia di kebun Nabot, orang Yizreel itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 22, 'Tatkala Yoram melihat Yehu, bertanyalah ia: "Apakah ini kabar damai, hai Yehu?" Jawabnya: "Bagaimana ada damai, selama sundal dan orang sihir ibumu Izebel begitu banyak!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 23, 'Segera Yoram berputar dan mau melarikan diri sambil berseru kepada Ahazia: "Itu tipu, Ahazia!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 24, 'Tetapi Yehu menarik busurnya dengan sepenuh kekuatannya, lalu memanah Yoram di antara kedua bahunya, sehingga anak panah itu menembus jantungnya, maka rebahlah ia di dalam keretanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 25, 'Kemudian berkatalah Yehu kepada Bidkar, perwiranya: "Angkat dan lemparkanlah mayatnya ke kebun Nabot, orang Yizreel itu, sebab ketahuilah, bahwa pada waktu aku dan engkau berdampingan menunggang kuda mengikuti Ahab, ayahnya, maka TUHAN telah mengucapkan terhadap dia hukuman ini:', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 26, 'Sesungguhnya, Aku telah melihat darah Nabot dan darah anak-anaknya tadi malam, demikianlah firman TUHAN, maka Aku akan membalaskannya kepadamu di kebun ini, demikianlah firman TUHAN. Oleh sebab itu angkat dan lemparkanlah mayatnya ke kebun ini, sesuai dengan firman TUHAN."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 27, 'Ketika Ahazia, raja Yehuda, melihat itu, maka iapun melarikan diri ke arah Bet-Hagan, tetapi Yehu mengejarnya sambil berkata: "Panahlah dia juga!" Maka mereka memanah dia di atas keretanya di pendakian ke Gur dekat Yibleam. Ia lari ke Megido dan mati di sana.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 28, 'Para pegawainya mengangkut mayatnya ke Yerusalem, lalu mereka menguburkan dia dalam kuburnya sendiri, di samping nenek moyangnya di kota Daud.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 29, 'Adapun Ahazia menjadi raja atas Yehuda dalam tahun kesebelas zaman Yoram bin Ahab.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 30, 'Sampailah Yehu ke Yizreel. Ketika Izebel mendengar itu, ia mencalak matanya, dihiasinyalah kepalanya, lalu ia menjenguk dari jendela.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 31, 'Pada waktu Yehu masuk pintu gerbang, berserulah Izebel: "Bagaimana, selamatkah Zimri, pembunuh tuannya itu?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 32, 'Yehu mengangkat kepalanya melihat ke jendela itu dan berkata: "Siapa yang di pihakku? Siapa?" Dan ketika dua tiga orang pegawai istana menjenguk kepadanya,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 33, 'ia berseru: "Jatuhkanlah dia!" Mereka menjatuhkan dia, sehingga darahnya memercik ke dinding dan ke kuda; mayatnyapun terinjak-injak.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 34, 'Yehu masuk ke dalam, lalu makan dan minum. Kemudian ia berkata: "Baiklah urus mayat orang yang terkutuk itu dan kuburkanlah dia, sebab ia memang anak raja."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 35, 'Mereka pergi untuk menguburkannya, tetapi mereka tidak menjumpai mayatnya, hanya kepala dan kedua kaki dan kedua telapak tangannya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 36, 'Mereka kembali memberitahukannya kepada Yehu, lalu ia berkata: "Memang begitulah firman TUHAN yang diucapkan-Nya dengan perantaraan hamba-Nya, Elia, orang Tisbe itu: Di kebun di luar Yizreel akan dimakan anjing daging Izebel;', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 9, 37, 'maka mayat Izebel akan terhampar di kebun di luar Yizreel seperti pupuk di ladang, sehingga tidak ada orang yang dapat berkata: Inilah Izebel."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 1, 'Ahab mempunyai tujuh puluh orang anak laki-laki di Samaria. Yehu menulis surat, dan mengirimnya ke Samaria, kepada pembesar kota itu, kepada para tua-tua dan kepada para pengasuh anak-anak Ahab, bunyinya:', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 2, '"Sekarang, segera sesudah surat ini sampai kepadamu, kamu yang mempunyai anak-anak tuanmu di bawah pengawasanmu, lagipula mempunyai kereta dan kuda dan kota yang berkubu serta senjata,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 3, 'maka pilihlah seorang yang terbaik dan yang paling tepat dari antara anak-anak tuanmu, lalu dudukkanlah dia di atas takhta ayahnya, kemudian berperanglah membela keluarga tuanmu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 4, 'Tetapi mereka sangat takut dan berkata: "Sedangkan kedua raja itu tidak dapat bertahan menghadapinya, bagaimana mungkin kita ini dapat bertahan?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 5, 'Sebab itu kepala istana dan kepala kota, juga para tua-tua dan para pengasuh mengirim pesan kepada Yehu, bunyinya: "Kami ini hamba-hambamu dan segala yang kaukatakan kepada kami akan kami lakukan; kami tidak hendak mengangkat seseorang menjadi raja; lakukanlah apa yang baik menurut pemandanganmu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 6, 'Kemudian Yehu menulis surat untuk kedua kalinya kepada mereka, bunyinya: "Jika kamu memihak kepadaku dan mau menurut perkataanku, ambillah kepala anak-anak tuanmu dan datanglah kepadaku besok kira-kira waktu ini ke Yizreel." Adapun ketujuh puluh anak raja itu tinggal bersama-sama orang-orang besar di kota itu, yang mendidik mereka.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 7, 'Tatkala surat itu sampai kepada mereka, mereka mengambil anak-anak raja itu, menyembelih ketujuh puluh orang itu, menaruh kepala orang-orang itu ke dalam keranjang dan mengirimkan semuanya kepada Yehu di Yizreel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 8, 'Ketika suruhan datang memberitahukan kepadanya: "Telah dibawa orang kepala anak-anak raja itu," berkatalah Yehu: "Susunlah semuanya menjadi dua timbunan di depan pintu gerbang sampai pagi."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 9, 'Pada paginya keluarlah Yehu, berdirilah ia, lalu berkata kepada segenap orang banyak: "Kamu ini tidak bersalah. Memang akulah yang telah mengadakan persepakatan melawan tuanku dan telah membunuh dia; tetapi semua orang ini, siapakah yang membunuh mereka?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 10, 'Ketahuilah sekarang, bahwa firman TUHAN yang telah diucapkan TUHAN tentang keluarga Ahab, tidak ada yang tidak dipenuhi, TUHAN telah melakukan apa yang difirmankan-Nya dengan perantaraan Elia, hamba-Nya."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 11, 'Lalu Yehu membunuh semua orang yang masih tinggal dari keluarga Ahab yang di Yizreel, juga semua orang besarnya, orang-orang kepercayaannya dan imam-imamnya; tidak ada padanya seorangpun yang ditinggalkan Yehu hidup.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 12, 'Kemudian bangkitlah Yehu pergi ke Samaria. Di jalan dekat Bet-Eked, perkampungan para gembala,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 13, 'bertemulah ia dengan sanak saudara Ahazia, raja Yehuda, lalu ia bertanya: "Siapakah kamu ini?" Jawab mereka: "Kami adalah sanak saudara Ahazia dan kami datang untuk memberi salam kepada anak-anak raja dan anak-anak ibu suri."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 14, 'Berkatalah Yehu: "Tangkaplah mereka hidup-hidup!" Lalu ditangkaplah mereka hidup-hidup dan disembelih dekat perigi Bet-Eked, empat puluh dua orang, dan tidak ada seorangpun ditinggalkannya hidup dari pada mereka.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 15, 'Setelah pergi dari sana, bertemulah ia dengan Yonadab bin Rekhab yang datang menyongsong dia. Ia memberi salam kepadanya serta berkata: "Apakah hatimu jujur kepadaku seperti hatiku terhadap engkau?" Jawab Yonadab: "Ya!" "Jika ya, berilah tanganmu!" Maka diberinyalah tangannya, lalu Yehu mengajak dia naik ke sampingnya ke dalam kereta.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 16, 'Berkatalah Yehu: "Marilah bersama-sama aku, supaya engkau melihat bagaimana giatku untuk TUHAN." Demikianlah Yehu membawa dia dalam keretanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 17, 'Setelah Yehu sampai di Samaria, maka ia membunuh semua orang yang masih tinggal dari keluarga Ahab di Samaria; ia memunahkannya, sesuai dengan firman yang diucapkan TUHAN kepada Elia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 18, 'Kemudian Yehu mengumpulkan seluruh rakyat, lalu berkata kepada mereka: "Adapun Ahab masih kurang beribadah kepada Baal, tetapi Yehu mau lebih hebat beribadah kepadanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 19, 'Oleh sebab itu, panggillah menghadap aku semua nabi Baal, semua orang yang beribadah kepadanya dan semua imamnya, seorangpun tidak boleh tidak hadir, sebab aku hendak mempersembahkan korban yang besar kepada Baal. Setiap orang yang tidak hadir tidak akan tinggal hidup." Tetapi perbuatan ini adalah akal Yehu supaya ia membinasakan orang-orang yang beribadah kepada Baal.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 20, 'Selanjutnya Yehu berkata: "Tentukanlah hari raya perkumpulan kudus bagi Baal!" Lalu mereka memaklumkannya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 21, 'Yehu mengirim orang ke seluruh Israel, maka datanglah seluruh orang yang beribadah kepada Baal, tidak seorangpun yang ketinggalan. Lalu masuklah semuanya ke dalam rumah Baal, sehingga rumah itu penuh sesak dari ujung ke ujung.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 22, 'Kemudian berkatalah Yehu kepada orang yang mengepalai gudang pakaian: "Keluarkanlah pakaian untuk setiap orang yang beribadah kepada Baal!" Maka dikeluarkannyalah pakaian bagi mereka.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 23, 'Sesudah itu masuklah Yehu dan Yonadab bin Rekhab ke dalam rumah Baal, lalu berkatalah ia kepada orang-orang penyembah Baal di situ: "Periksalah dan lihatlah, supaya jangan ada di antara kamu di sini seorangpun dari hamba-hamba TUHAN, melainkan hanya orang-orang yang beribadah kepada Baal."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 24, 'Lalu masuklah mereka untuk mempersembahkan korban sembelihan dan korban bakaran. Adapun Yehu telah menempatkan delapan puluh orang di luar dan telah berkata: "Siapa yang membiarkan lolos seorangpun dari orang-orang yang kuserahkan ke dalam tanganmu, nyawanyalah ganti nyawa orang itu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 25, 'Setelah Yehu selesai mempersembahkan korban bakaran, berkatalah ia kepada bentara-bentara dan kepada perwira-perwira: "Masuklah, bunuhlah mereka, seorangpun tidak boleh lolos!" Maka dibunuhlah mereka dengan mata pedang, lalu mayatnya dibuang; kemudian masuklah bentara-bentara dan perwira-perwira itu ke gedung rumah Baal.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 26, 'Mereka mengeluarkan tiang berhala rumah Baal itu, lalu dibakar.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 27, 'Mereka merobohkan tugu berhala Baal itu, merobohkan juga rumah Baal, dan membuatnya menjadi jamban; begitulah sampai hari ini.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 28, 'Demikianlah Yehu memunahkan Baal dari Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 29, 'Hanya, Yehu tidak menjauh dari dosa-dosa Yerobeam bin Nebat, yang mengakibatkan orang Israel berdosa pula, yakni dosa penyembahan anak-anak lembu emas yang di Betel dan yang di Dan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 30, 'Berfirmanlah TUHAN kepada Yehu: "Oleh karena engkau telah berbuat baik dengan melakukan apa yang benar di mata-Ku, dan telah berbuat kepada keluarga Ahab tepat seperti yang dikehendaki hati-Ku, maka anak-anakmu akan duduk di atas takhta Israel sampai keturunan yang keempat."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 31, 'Tetapi Yehu tidak tetap hidup menurut hukum TUHAN, Allah Israel, dengan segenap hatinya; ia tidak menjauh dari dosa-dosa Yerobeam yang mengakibatkan orang Israel berdosa pula.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 32, 'Pada zaman itu mulailah TUHAN menggunting daerah Israel, sebab Hazael mengalahkan mereka di seluruh daerah Israel', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 33, 'di sebelah timur sungai Yordan dengan merebut seluruh tanah Gilead, tanah orang Gad, orang Ruben dan orang Manasye, mulai dari Aroer yang di tepi sungai Arnon, baik Gilead maupun Basan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 34, 'Selebihnya dari riwayat Yehu dan segala yang dilakukannya dan segala kepahlawanannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 35, 'Kemudian Yehu mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di Samaria, maka Yoahas, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 10, 36, 'Adapun lamanya Yehu menjadi raja atas Israel di Samaria adalah dua puluh delapan tahun.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 1, 'Ketika Atalya, ibu Ahazia, melihat bahwa anaknya sudah mati, maka bangkitlah ia membinasakan semua keturunan raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 2, 'Tetapi Yoseba, anak perempuan raja Yoram, saudara perempuan Ahazia, mengambil Yoas bin Ahazia, menculik dia dari tengah-tengah anak-anak raja yang hendak dibunuh itu, memasukkan dia dengan inang penyusunya ke dalam gudang tempat tidur, dan menyembunyikan dia terhadap Atalya, sehingga dia tidak dibunuh.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 3, 'Maka tinggallah dia enam tahun lamanya bersama-sama perempuan itu dengan bersembunyi di rumah TUHAN, sementara Atalya memerintah negeri.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 4, 'Dalam tahun yang ketujuh Yoyada mengundang para kepala pasukan seratus dari orang Kari dan dari pasukan bentara penunggu. Disuruhnyalah mereka datang kepadanya di rumah TUHAN, lalu diikatnya perjanjian dengan mereka dengan menyuruh mereka bersumpah di rumah TUHAN. Kemudian diperlihatkannyalah anak raja itu kepada mereka.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 5, 'Sesudah itu ia memerintahkan kepada mereka: "Inilah yang harus kamu lakukan: sepertiga dari kamu, yakni yang selesai bertugas pada hari Sabat di sini, tetapi mengawal di istana raja?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 6, 'sepertiga lagi ada di pintu gerbang Sur dan sepertiga pula di pintu gerbang di belakang para bentara penunggu?haruslah mengawal di istana;', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 7, 'dan kedua regu dari pada kamu, yakni semua orang yang bertugas di sini pada hari Sabat dan mengawal di rumah TUHAN,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 8, 'haruslah mengelilingi raja dari segala penjuru, masing-masing dengan senjatanya di tangannya, dan siapa yang mendatangi barisan haruslah mati dibunuh. Dan baiklah kamu menyertai raja setiap kali ia keluar atau masuk."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 9, 'Para kepala pasukan seratus itu melakukan tepat seperti yang diperintahkan imam Yoyada. Masing-masing mengambil orang-orangnya yang selesai bertugas pada hari Sabat bersama-sama dengan orang-orang yang masuk bertugas pada hari itu, lalu datanglah mereka kepada imam Yoyada.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 10, 'Imam memberikan kepada para kepala pasukan seratus itu tombak-tombak dan perisai-perisai kepunyaan raja Daud yang ada di rumah TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 11, 'Kemudian para bentara itu, masing-masing dengan senjatanya di tangannya, mengambil tempatnya di lambung kanan sampai ke lambung kiri rumah itu, dengan mengelilingi mezbah dan rumah itu untuk melindungi raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 12, 'Sesudah itu Yoyada membawa anak raja itu ke luar, mengenakan jejamang kepadanya dan memberikan hukum Allah kepadanya. Mereka menobatkan dia menjadi raja serta mengurapinya, dan sambil bertepuk tangan berserulah mereka: "Hiduplah raja!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 13, 'Ketika Atalya mendengar suara bentara-bentara penunggu dan rakyat, pergilah ia mendapatkan rakyat itu ke dalam rumah TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 14, 'Lalu dilihatnyalah raja berdiri dekat tiang menurut kebiasaan, sedang para pemimpin dengan para pemegang nafiri ada dekat raja. Dan seluruh rakyat negeri bersukaria sambil meniup nafiri. Maka Atalya mengoyakkan pakaiannya sambil berseru: "Khianat, khianat!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 15, 'Tetapi imam Yoyada memerintahkan para kepala pasukan seratus, yakni orang-orang yang mengepalai tentara, katanya kepada mereka: "Bawalah dia keluar dari barisan! Siapa yang memihak kepadanya bunuhlah dengan pedang!" Sebab tadinya imam itu telah berkata: "Janganlah ia dibunuh di rumah TUHAN!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 16, 'Lalu mereka menangkap perempuan itu. Pada waktu ia masuk ke istana raja dengan melalui pintu bagi kuda, dibunuhlah dia di situ.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 17, 'Kemudian Yoyada mengikat perjanjian antara TUHAN dengan raja dan rakyat, bahwa mereka menjadi umat TUHAN; juga antara raja dengan rakyat.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 18, 'Sesudah itu masuklah seluruh rakyat negeri ke rumah Baal, lalu merobohkannya; mereka memecahkan sama sekali mezbah-mezbahnya dan patung-patung dan membunuh Matan, imam Baal, di depan mezbah-mezbah itu. Kemudian imam Yoyada mengangkat penjaga-penjaga untuk rumah TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 19, 'Sesudah itu ia mengajak para kepala pasukan seratus orang-orang Kari dan para bentara penunggu dan seluruh rakyat negeri, lalu mereka membawa raja turun dari rumah TUHAN; mereka masuk ke istana raja melalui pintu gerbang para bentara; kemudian duduklah raja di atas takhta kerajaan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 20, 'Bersukarialah seluruh rakyat negeri dan amanlah kota itu, setelah Atalya mati dibunuh dengan pedang di istana raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 11, 21, 'Yoas berumur tujuh tahun pada waktu ia menjadi raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 1, 'Dalam tahun ketujuh zaman Yehu, Yoas menjadi raja dan empat puluh tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Zibya, dari Bersyeba.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 2, 'Yoas melakukan apa yang benar di mata TUHAN seumur hidupnya, selama imam Yoyada mengajar dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 3, 'Namun demikian, bukit-bukit pengorbanan tidaklah dijauhkan. Bangsa itu masih mempersembahkan dan membakar korban di bukit-bukit itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 4, 'Berkatalah Yoas kepada para imam: "Segala uang yang dibawa ke dalam rumah TUHAN sebagai persembahan kudus, yakni uang masuk untuk pencatatan jiwa, uang tebusan jiwa menurut penilaian yang berlaku untuk seseorang, dan segala uang yang dibawa ke dalam rumah TUHAN karena dorongan hati seseorang,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 5, 'baiklah para imam sendiri menerimanya, masing-masing dari kenalannya, dan memakainya untuk memperbaiki yang rusak pada rumah itu, di mana saja terdapat kerusakan."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 6, 'Tetapi dalam tahun kedua puluh tiga zaman raja Yoas para imam belum juga memperbaiki kerusakan rumah itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 7, 'Sebab itu raja Yoas memanggil imam Yoyada, dan imam-imam lain serta berkata kepada mereka: "Mengapa kamu tidak perbaiki kerusakan rumah itu? Maka sekarang, tidak boleh lagi kamu menerima uang dari kenalan-kenalanmu, tetapi serahkanlah itu untuk memperbaiki kerusakan rumah itu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 8, 'Lalu setujulah para imam itu untuk tidak menerima uang dari rakyat, tetapi merekapun tidak usah lagi memperbaiki kerusakan rumah itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 9, 'Kemudian imam Yoyada mengambil sebuah peti, membuat lobang pada tutupnya dan menaruhnya di samping mezbah, di sebelah kanan apabila orang masuk ke rumah TUHAN. Para imam penjaga pintu menaruh ke dalamnya segala uang yang dibawa orang ke dalam rumah TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 10, 'Dan apabila dilihat mereka bahwa sudah banyak uang dalam peti itu, maka datanglah panitera raja beserta imam besar, lalu membungkus dan menghitung uang yang terdapat dalam rumah TUHAN itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 11, 'Mereka menyerahkan jumlah uang yang ditentukan ke tangan para pekerja yang diangkat mengawasi rumah TUHAN, dan mereka ini membayarkannya kepada tukang-tukang kayu, kepada tukang-tukang bangunan yang mengerjakan rumah TUHAN itu,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 12, 'kepada tukang-tukang tembok dan kepada tukang-tukang pemahat batu; mereka memakainya juga bagi pembelian kayu dan batu pahat untuk memperbaiki rumah TUHAN dan bagi segala pengeluaran untuk memperbaiki rumah itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 13, 'Tetapi untuk rumah TUHAN tidaklah dibuat pasu perak, pisau, bokor penyiraman, nafiri, atau sesuatu perkakas emas dan perak dari uang yang telah dibawa ke dalam rumah TUHAN itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 14, 'Melainkan mereka menyerahkannya kepada para pekerja, supaya dipakai memperbaiki rumah TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 15, 'Mereka kemudian tidak mengadakan perhitungan dengan orang-orang yang diserahi uang itu untuk memberikannya kepada tukang-tukang, sebab mereka bekerja dengan jujur.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 16, 'Tetapi uang korban penebus salah dan uang korban penghapus dosa tidaklah dibawa ke dalam rumah TUHAN; semuanya itu adalah bagian para imam.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 17, 'Pada waktu itu majulah Hazael, raja Aram, diperanginyalah Gat dan direbutnya. Kemudian Hazael berniat menyerang Yerusalem,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 18, 'tetapi Yoas, raja Yehuda, mengambil segala persembahan kudus yang telah dikuduskan oleh para leluhurnya yakni Yosafat, Yoram dan Ahazia, raja-raja Yehuda, dan persembahan-persembahan kudusnya sendiri, juga segala emas yang terdapat dalam perbendaharaan rumah TUHAN dan istana raja. Dikirimkannyalah semuanya itu kepada Hazael, raja Aram, maka tidak jadi lagi Hazael menyerang Yerusalem.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 19, 'Selebihnya dari riwayat Yoas dan segala yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 20, 'Pegawai-pegawainya bangkit mengadakan persepakatan, lalu membunuh Yoas di rumah Milo yang letaknya di penurunan ke Sila.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 12, 21, 'Yozakar, anak Simeat, dan Yozabad, anak Somer, ialah pegawai-pegawainya yang membunuh dia. Lalu ia dikuburkan di samping nenek moyangnya di kota Daud, maka Amazia, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 1, 'Dalam tahun kedua puluh tiga zaman Yoas bin Ahazia, raja Yehuda, Yoahas, anak Yehu, menjadi raja atas Israel di Samaria; ia memerintah tujuh belas tahun lamanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 2, 'Ia melakukan apa yang jahat di mata TUHAN, dan ia hidup menuruti dosa Yerobeam bin Nebat, yang mengakibatkan orang Israel berdosa pula. Ia tidak menjauhinya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 3, 'Sebab itu bangkitlah murka TUHAN terhadap Israel, lalu diserahkan-Nyalah mereka ke dalam tangan Hazael, raja Aram, dan ke dalam tangan Benhadad, anak Hazael, selama zaman itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 4, 'Tetapi kemudian Yoahas memohon belas kasihan TUHAN, dan TUHAN mendengarkan dia, sebab Ia telah melihat, bagaimana beratnya orang Israel ditindas oleh raja Aram.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 5, '?TUHAN memberikan kepada orang Israel seorang penolong, sehingga mereka lepas dari tangan Aram dan dapat duduk di kemah-kemah mereka seperti yang sudah-sudah.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 6, 'Hanya mereka tidak menjauh dari dosa-dosa keluarga Yerobeam, yang mengakibatkan orang Israel berdosa pula, melainkan mereka terus hidup dalam dosa itu. Juga patung Asyera masih berdiri di Samaria. ?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 7, 'Sebab tidak ada laskar ditinggalkan pada Yoahas, selain dari lima puluh orang berkuda dan sepuluh kereta dan sepuluh ribu orang berjalan kaki, sebab raja Aram telah membinasakan mereka dan meniupkan mereka seperti abu pengirikan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 8, 'Selebihnya dari riwayat Yoahas dan segala yang dilakukannya dan kepahlawanannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 9, 'Kemudian Yoahas mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di Samaria. Maka Yoas, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 10, 'Dalam tahun ketiga puluh tujuh zaman Yoas, raja Yehuda, Yoas anak Yoahas, menjadi raja atas Israel di Samaria. Ia memerintah enam belas tahun lamanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 11, 'Ia melakukan apa yang jahat di mata TUHAN. Ia tidak menjauh dari segala dosa yang disuruh Yerobeam bin Nebat dilakukan orang Israel, tetapi terus hidup dalam dosa itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 12, 'Selebihnya dari riwayat Yoas dan segala yang dilakukannya dan kepahlawanannya, bagaimana ia berperang melawan Amazia, raja Yehuda, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 13, 'Setelah Yoas mendapat perhentian bersama-sama dengan nenek moyangnya, maka duduklah Yerobeam di atas takhta ayahnya. Dan Yoas dikuburkan di Samaria di samping raja Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 14, 'Ketika Elisa menderita sakit yang menyebabkan kematiannya, datanglah Yoas, raja Israel, kepadanya dan menangis oleh karena dia, katanya: "Bapaku, bapaku! Kereta Israel dan orang-orangnya yang berkuda!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 15, 'Berkatalah Elisa kepadanya: "Ambillah busur dan anak-anak panah!" Lalu diambillah busur dan anak-anak panah.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 16, 'Berkatalah ia kepada raja Israel: "Tariklah busurmu!" Lalu ia menarik busurnya, tetapi Elisa menaruh tangannya di atas tangan raja,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 17, 'serta berkata: "Bukalah jendela yang di sebelah timur!" Dan ketika dibukanya, berkatalah Elisa: "Panahlah!" Lalu dipanahnya. Kemudian berkatalah Elisa: "Itulah anak panah kemenangan dari pada TUHAN, anak panah kemenangan terhadap Aram. Engkau akan mengalahkan Aram di Afek sampai habis lenyap."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 18, 'Sesudah itu berkatalah ia: "Ambillah anak-anak panah itu!" Lalu diambilnya. Setelah diambilnya, berkatalah Elisa kepada raja Israel: "Pukulkanlah itu ke tanah!" Lalu dipukulkannya tiga kali, kemudian ia berhenti.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 19, 'Tetapi gusarlah abdi Allah itu kepadanya serta berkata: "Seharusnya engkau memukul lima atau enam kali! Dengan berbuat demikian engkau akan memukul Aram sampai habis lenyap. Tetapi sekarang, hanya tiga kali saja engkau akan memukul Aram."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 20, 'Sesudah itu matilah Elisa, lalu ia dikuburkan. Adapun gerombolan Moab sering memasuki negeri itu pada pergantian tahun.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 21, 'Pada suatu kali orang sedang menguburkan mayat. Ketika mereka melihat gerombolan datang, dicampakkan merekalah mayat itu ke dalam kubur Elisa, lalu pergi. Dan demi mayat itu kena kepada tulang-tulang Elisa, maka hiduplah ia kembali dan bangun berdiri.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 22, 'Hazael, raja Aram, menindas orang Israel sepanjang umur Yoahas.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 23, 'Tetapi TUHAN mengasihani serta menyayangi mereka, dan Ia berpaling kepada mereka oleh karena perjanjian-Nya dengan Abraham, Ishak dan Yakub, jadi Ia tidak mau memusnahkan mereka dan belum membuang mereka pada waktu itu dari hadapan-Nya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 24, 'Kemudian matilah Hazael, raja Aram, maka Benhadad, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 13, 25, 'Yoas bin Yoahas merebut kembali dari tangan Benhadad bin Hazael kota-kota yang dalam peperangan direbut Benhadad dari tangan Yoahas, ayah Yoas. Tiga kali Yoas mengalahkan dia dan mendapat kembali kota-kota Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 1, 'Dalam tahun kedua zaman Yoas bin Yoahas, raja Israel, Amazia, anak Yoas raja Yehuda menjadi raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 2, 'Ia berumur dua puluh lima tahun pada waktu ia menjadi raja dan dua puluh sembilan tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Yoadan, dari Yerusalem.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 3, 'Ia melakukan apa yang benar di mata TUHAN, hanya bukan seperti Daud, bapa leluhurnya. Ia berbuat tepat seperti yang diperbuat Yoas, ayahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 4, 'Namun demikian, bukit-bukit pengorbanan tidaklah dijauhkan. Bangsa itu masih mempersembahkan dan membakar korban di bukit-bukit itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 5, 'Segera sesudah kuasa kerajaan itu kokoh di tangannya, dibunuhnyalah pegawai-pegawainya yang telah membunuh raja, yaitu ayahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 6, 'Tetapi anak-anak para pembunuh itu tidak dihukum mati olehnya, seperti yang tertulis dalam kitab Taurat Musa, di mana TUHAN telah memberi perintah: "Janganlah ayah dihukum mati karena anaknya, janganlah juga anak dihukum mati karena ayahnya, melainkan setiap orang harus dihukum mati karena dosanya sendiri."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 7, 'Ia mengalahkan Edom di Lembah Asin, sepuluh ribu orang banyaknya, dan merebut Sela dalam peperangan itu, lalu dinamainyalah kota itu Yokteel; begitulah sampai hari ini.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 8, 'Pada waktu itu Amazia menyuruh utusan kepada Yoas bin Yoahas bin Yehu, raja Israel, mengatakan: "Mari kita mengadu tenaga!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 9, 'Tetapi Yoas, raja Israel, menyuruh orang kepada Amazia, raja Yehuda, mengatakan: "Rumput duri yang di gunung Libanon mengirim pesan kepada pohon aras yang di gunung Libanon, bunyinya: Berikanlah anakmu perempuan kepada anakku laki-laki menjadi isterinya. Tetapi binatang-binatang hutan yang ada di gunung Libanon itu berjalan lewat dari sana, lalu menginjak rumput duri itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 10, 'Memang engkau telah mengalahkan Edom, sebab itu engkau menjadi tinggi hati. Cukuplah bagimu mendapat kehormatan itu dan tinggallah di rumahmu. Untuk apa engkau menantang malapetaka, sehingga engkau jatuh dan Yehuda bersama-sama engkau?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 11, 'Tetapi Amazia tidak mau mendengarkan, sebab itu majulah Yoas, raja Israel, lalu mengadu tenagalah mereka, ia dan Amazia, raja Yehuda, di Bet-Semes yang termasuk wilayah Yehuda.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 12, 'Yehuda terpukul kalah oleh Israel, sehingga masing-masing lari ke kemahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 13, 'Yoas, raja Israel menangkap Amazia, raja Yehuda, anak Yoas bin Ahazia, di Bet-Semes. Lalu Yoas masuk ke Yerusalem, dan membongkar tembok Yerusalem dari Pintu Gerbang Efraim sampai ke Pintu Gerbang Sudut, empat ratus hasta panjangnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 14, 'Sesudah itu ia mengambil segala emas dan perak dan segala perkakas yang terdapat dalam rumah TUHAN dan dalam perbendaharaan istana raja, juga orang-orang sandera, kemudian pulanglah ia ke Samaria.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 15, 'Selebihnya dari riwayat Yoas, apa yang dilakukannya dan kepahlawanannya dan bagaimana ia berperang melawan Amazia, raja Yehuda, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 16, 'Kemudian Yoas mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di Samaria di samping raja-raja Israel. Maka Yerobeam, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 17, 'Amazia bin Yoas, raja Yehuda, masih hidup lima belas tahun lamanya sesudah matinya Yoas bin Yoahas, raja Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 18, 'Selebihnya dari riwayat Amazia, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 19, 'Di Yerusalem orang mengadakan persepakatan melawan dia, sebab itu larilah ia ke Lakhis. Tetapi mereka menyuruh mengejar dia ke Lakhis, lalu dibunuhlah dia di sana.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 20, 'Diangkutlah dia dengan kuda, lalu dikuburkan di Yerusalem di samping nenek moyangnya di kota Daud.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 21, 'Segenap bangsa Yehuda mengambil Azarya, yang masih berumur enam belas tahun dan mengangkat dia menjadi raja menggantikan ayahnya, Amazia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 22, 'Ia memperkuat Elat dan mengembalikannya kepada Yehuda, sesudah raja mendapat perhentian bersama-sama dengan nenek moyangnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 23, 'Dalam tahun kelima belas zaman Amazia bin Yoas, raja Yehuda, Yerobeam, anak Yoas, raja Israel, menjadi raja di Samaria. Ia memerintah empat puluh satu tahun lamanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 24, 'Ia melakukan apa yang jahat di mata TUHAN. Ia tidak menjauh dari segala dosa Yerobeam bin Nebat, yang mengakibatkan orang Israel berdosa pula.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 25, 'Ia mengembalikan daerah Israel, dari jalan masuk ke Hamat sampai ke Laut Araba sesuai dengan firman TUHAN, Allah Israel, yang telah diucapkan-Nya dengan perantaraan hamba-Nya, nabi Yunus bin Amitai dari Gat-Hefer.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 26, 'Sebab TUHAN telah melihat betapa pahitnya kesengsaraan orang Israel itu: sudah habis lenyap baik yang tinggi maupun yang rendah kedudukannya, dan tidak ada penolong bagi orang Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 27, 'Tetapi TUHAN tidak mengatakan bahwa Ia akan menghapuskan nama Israel dari kolong langit; jadi Ia menolong mereka dengan perantaraan Yerobeam bin Yoas.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 28, 'Selebihnya dari riwayat Yerobeam dan segala yang dilakukannya dan kepahlawanannya, bagaimana ia berperang, dan bagaimana ia mengembalikan Damsyik dan Hamat-Yehuda ke dalam Israel, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 14, 29, 'Kemudian Yerobeam mendapat perhentian bersama-sama dengan nenek moyangnya, raja-raja Israel. Maka Zakharia, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 1, 'Dalam tahun kedua puluh tujuh zaman Yerobeam, raja Israel, Azarya, anak Amazia raja Yehuda menjadi raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 2, 'Ia berumur enam belas tahun pada waktu ia menjadi raja dan lima puluh dua tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Yekholya, dari Yerusalem.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 3, 'Ia melakukan apa yang benar di mata TUHAN, tepat seperti yang dilakukan Amazia, ayahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 4, 'Namun demikian, bukit-bukit pengorbanan tidaklah dijauhkan. Bangsa itu masih mempersembahkan dan membakar korban di bukit-bukit itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 5, 'Maka TUHAN menimpakan tulah kepada raja, sehingga ia sakit kusta sampai hari kematiannya, dan tinggal dalam sebuah rumah pengasingan. Dan Yotam, anak raja, mengepalai istana dan menjalankan pemerintahan atas rakyat negeri itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 6, 'Selebihnya dari riwayat Azarya, dan segala yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 7, 'Kemudian Azarya mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di samping nenek moyangnya di kota Daud. Maka Yotam, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 8, 'Dalam tahun ketiga puluh delapan zaman Azarya, raja Yehuda, Zakharia, anak Yerobeam, menjadi raja atas Israel di Samaria. Ia memerintah enam bulan lamanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 9, 'Ia melakukan apa yang jahat di mata TUHAN seperti yang telah dilakukan oleh nenek moyangnya. Ia tidak menjauh dari dosa-dosa Yerobeam bin Nebat, yang mengakibatkan orang Israel berdosa pula.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 10, 'Salum bin Yabesh mengikat persepakatan melawan dia, membunuh dia di Yibleam, kemudian menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 11, 'Selebihnya dari riwayat Zakharia, sesungguhnya semuanya itu tertulis dalam kitab sejarah raja-raja Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 12, 'Bukankah begini firman TUHAN yang diucapkan-Nya kepada Yehu: "Anak-anakmu sampai kepada keturunan yang keempat akan duduk di atas takhta Israel!" Dan terjadilah demikian.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 13, 'Salum bin Yabesh menjadi raja dalam tahun yang ketiga puluh sembilan zaman Uzia, raja Yehuda. Ia memerintah sebulan lamanya di Samaria.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 14, 'Sesudah itu majulah Menahem bin Gadi dari Tirza, lalu sampai ke Samaria. Ia membunuh Salum bin Yabesh di Samaria, kemudian menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 15, 'Selebihnya dari riwayat Salum dan persepakatan yang diadakannya, sesungguhnya semuanya itu tertulis dalam kitab sejarah raja-raja Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 16, 'Pada waktu itu, dengan mulai dari Tirza, Menahem memusnahkan Tifsah dan semua orang yang ada di dalamnya serta daerahnya, sebab orang tidak membuka pintu kota baginya. Maka dimusnahkannyalah kota itu dan dibelahnya semua perempuannya yang mengandung.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 17, 'Dalam tahun ketiga puluh sembilan zaman Azarya, raja Yehuda, Menahem bin Gadi menjadi raja atas Israel. Ia memerintah sepuluh tahun lamanya di Samaria.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 18, 'Ia melakukan apa yang jahat di mata TUHAN. Sepanjang umurnya ia tidak menjauh dari dosa-dosa Yerobeam bin Nebat, yang mengakibatkan orang Israel berdosa pula.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 19, 'Pul, raja Asyur, datang menyerang negeri itu, lalu Menahem memberi seribu talenta perak kepada Pul, supaya dibantunya dia mengokohkan kerajaan itu di tangannya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 20, 'Menahem mengeluarkan uang ini atas beban Israel dan atas beban semua orang yang kaya raya untuk diberikan kepada raja Asyur: lima puluh syikal perak dari setiap orang. Lalu pulanglah raja Asyur dan ia tidak tinggal di sana, di negeri itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 21, 'Selebihnya dari riwayat Menahem dan segala yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Israel?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 22, 'Kemudian Menahem mendapat perhentian bersama-sama dengan nenek moyangnya. Maka Pekahya, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 23, 'Dalam tahun kelima puluh zaman Azarya, raja Yehuda, Pekahya, anak Menahem, menjadi raja atas Israel di Samaria. Ia memerintah dua tahun lamanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 24, 'Ia melakukan apa yang jahat di mata TUHAN. Ia tidak menjauh dari dosa-dosa Yerobeam bin Nebat, yang mengakibatkan orang Israel berdosa pula.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 25, 'Lalu perwiranya, yakni Pekah bin Remalya, mengadakan persepakatan melawan dia dan membunuh dia di Samaria di puri istana raja; beserta dia ada Argob dan Arye serta lima puluh orang dari bani Gilead; dibunuhnyalah Pekahya, kemudian menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 26, 'Selebihnya dari riwayat Pekahya dan segala yang dilakukannya, sesungguhnya semuanya itu tertulis dalam kitab sejarah raja-raja Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 27, 'Dalam tahun kelima puluh dua zaman Azarya, raja Yehuda, Pekah bin Remalya menjadi raja atas orang Israel di Samaria. Ia memerintah dua puluh tahun lamanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 28, 'Ia melakukan apa yang jahat di mata TUHAN. Ia tidak menjauh dari dosa-dosa Yerobeam bin Nebat, yang mengakibatkan orang Israel berdosa pula.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 29, 'Dalam zaman Pekah, raja Israel, datanglah Tiglat-Pileser, raja Asyur; direbutnyalah Iyon, Abel-Bet-Maakha, Yanoah, Kedesh dan Hazor, Gilead dan Galilea, seluruh tanah Naftali, lalu diangkutnyalah penduduknya ke Asyur ke dalam pembuangan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 30, 'Hosea bin Ela mengadakan persepakatan melawan Pekah bin Remalya; dibunuhnyalah dia, kemudian dia menjadi raja menggantikannya dalam tahun kedua puluh zaman Yotam bin Uzia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 31, 'Selebihnya dari riwayat Pekah dan segala yang dilakukannya, sesungguhnya semuanya itu tertulis dalam kitab sejarah raja-raja Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 32, 'Dalam tahun kedua zaman Pekah bin Remalya, raja Israel, Yotam, anak Uzia raja Yehuda menjadi raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 33, 'Ia berumur dua puluh lima tahun pada waktu ia menjadi raja dan enam belas tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Yerusa, anak Zadok.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 34, 'Ia melakukan apa yang benar di mata TUHAN, tepat seperti yang dilakukan Uzia, ayahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 35, 'Namun demikian, bukit-bukit pengorbanan tidaklah dijauhkan. Bangsa itu masih mempersembahkan dan membakar korban di bukit-bukit itu. Ia mendirikan Pintu Gerbang Tinggi di rumah TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 36, 'Selebihnya dari riwayat Yotam, apa yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 37, 'Mulai zaman itu TUHAN menyuruh Rezin, raja Aram, dan Pekah bin Remalya, menyerang Yehuda.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 15, 38, 'Kemudian Yotam mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di samping nenek moyangnya di kota Daud, bapa leluhurnya. Maka Ahas, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 1, 'Dalam tahun ketujuh belas zaman Pekah bin Remalya, Ahas anak Yotam raja Yehuda menjadi raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 2, 'Ahas berumur dua puluh tahun pada waktu ia menjadi raja dan enam belas tahun lamanya ia memerintah di Yerusalem. Ia tidak melakukan apa yang benar di mata TUHAN, Allahnya, seperti Daud, bapa leluhurnya,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 3, 'tetapi ia hidup menurut kelakuan raja-raja Israel, bahkan dia mempersembahkan anaknya sebagai korban dalam api, sesuai dengan perbuatan keji bangsa-bangsa yang telah dihalau TUHAN dari depan orang Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 4, 'Ia mempersembahkan dan membakar korban di bukit-bukit pengorbanan dan di atas tempat-tempat yang tinggi dan di bawah setiap pohon yang rimbun.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 5, 'Pada waktu itu majulah Rezin, raja Aram, dan Pekah bin Remalya, raja Israel, untuk memerangi Yerusalem. Dan mereka mengepung Ahas, tetapi mereka tidak dapat mengalahkan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 6, 'Pada masa itu Rezin, raja Aram, mengembalikan Elat kepada Edom, lalu ia mengusir orang-orang Yehuda dari Elat. Datanglah orang-orang Edom ke Elat dan diam di sana sampai hari ini.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 7, 'Ahas menyuruh utusan-utusan kepada Tiglat-Pileser, raja Asyur, mengatakan: "Aku ini hambamu dan anakmu. Majulah dan selamatkanlah aku dari tangan raja Aram dan dari tangan raja Israel, yang telah bangkit menyerang aku."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 8, 'Ahas mengambil perak dan emas yang terdapat dalam rumah TUHAN dan dalam perbendaharaan istana raja, dan mengirimnya kepada raja Asyur sebagai persembahan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 9, 'Maka raja Asyur mendengarkan permintaannya dan maju melawan Damsyik, merebutnya dan mengangkut penduduknya tertawan ke Kir, tetapi Rezin dibunuhnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 10, 'Sesudah itu pergilah raja Ahas menemui Tiglat-Pileser, raja Asyur, ke Damsyik. Setelah raja Ahas melihat mezbah yang ada di Damsyik, dikirimnyalah kepada imam Uria ukuran dan bagan mezbah itu, menurut buatannya yang tepat.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 11, 'Lalu imam Uria mendirikan mezbah; tepat seperti keterangan yang dikirimkan raja Ahas dari Damsyik, demikianlah dibuat imam Uria menjelang datangnya raja Ahas dari Damsyik.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 12, 'Setelah raja pulang dari Damsyik, maka raja melihat mezbah itu. Lalu mendekatlah raja kepada mezbah itu, naik ke atasnya,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 13, 'membakar korban bakarannya dan korban sajiannya, mencurahkan korban curahannya di atas mezbah itu, dan menyiramkan darah korban keselamatannya kepadanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 14, 'Tetapi ia menyuruh menggeser mezbah tembaga yang ada di hadapan TUHAN dari depan rumah TUHAN, dari antara mezbah baru dengan rumah itu, dan menaruhnya di sebelah utara mezbah baru itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 15, 'Kemudian raja Ahas memerintahkan kepada imam Uria: "Bakarlah di atas mezbah besar itu korban bakaran pagi dan korban sajian petang, juga korban bakaran dan korban sajian raja, lagi korban bakaran dan korban sajian dan korban-korban curahan seluruh rakyat negeri; dan siramkanlah kepadanya segenap darah korban bakaran dan segenap darah korban sembelihan; tetapi mezbah tembaga itu adalah urusanku."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 16, 'Lalu imam Uria melakukan tepat seperti yang diperintahkan raja Ahas.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 17, 'Sesudah itu raja Ahas memotong papan penutup kereta penopang dan menyingkirkan bejana pembasuhan dari atasnya, juga "laut" itu diturunkannya dari atas lembu tembaga yang mendukungnya dan ditaruhnya di atas alas batu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 18, 'Selanjutnya, demi raja Asyur, disingkirkannya dari rumah TUHAN serambi tertutup untuk hari Sabat yang telah didirikan pada rumah TUHAN, juga pintu masuk untuk raja yang di sebelah luar.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 19, 'Selebihnya dari riwayat Ahas dan apa yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 16, 20, 'Kemudian Ahas mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di samping nenek moyangnya di kota Daud. Maka Hizkia, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 1, 'Dalam tahun kedua belas zaman Ahas, raja Yehuda, Hosea bin Ela menjadi raja di Samaria atas Israel. Ia memerintah sembilan tahun lamanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 2, 'Ia melakukan apa yang jahat di mata TUHAN, tetapi bukan seperti raja-raja Israel yang mendahului dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 3, 'Salmaneser, raja Asyur maju melawan dia; Hosea takluk kepadanya serta membayar upeti.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 4, 'Tetapi kedapatanlah oleh raja Asyur, bahwa di pihak Hosea ada persepakatan, karena Hosea telah mengirimkan utusan-utusan kepada So, raja Mesir, dan tidak mempersembahkan lagi upeti kepada raja Asyur, seperti biasanya tahun demi tahun; sebab itu raja Asyur menangkap dia dan membelenggu dia dalam penjara.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 5, 'Kemudian majulah raja Asyur menjelajah seluruh negeri itu, ia menyerang Samaria dan mengepungnya tiga tahun lamanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 6, 'Dalam tahun kesembilan zaman Hosea maka raja Asyur merebut Samaria. Ia mengangkut orang-orang Israel ke Asyur ke dalam pembuangan dan menyuruh mereka tinggal di Halah, di tepi sungai Habor, yakni sungai negeri Gozan, dan di kota-kota orang Madai.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 7, 'Hal itu terjadi, karena orang Israel telah berdosa kepada TUHAN, Allah mereka, yang telah menuntun mereka dari tanah Mesir dari kekuasaan Firaun, raja Mesir, dan karena mereka telah menyembah allah lain,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 8, 'dan telah hidup menurut adat istiadat bangsa-bangsa yang telah dihalau TUHAN dari depan orang Israel, dan menurut ketetapan yang telah dibuat raja-raja Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 9, 'Dan orang Israel telah menjalankan hal-hal yang tidak patut terhadap TUHAN, Allah mereka. Mereka mendirikan bukit-bukit pengorbanan di manapun mereka diam, baik dekat menara penjagaan maupun di kota yang berkubu;', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 10, 'mereka mendirikan tugu-tugu berhala dan tiang-tiang berhala di atas setiap bukit yang tinggi dan di bawah setiap pohon yang rimbun;', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 11, 'di sana di atas segala bukit itu mereka membakar korban seperti bangsa-bangsa yang telah diangkut TUHAN tertawan dari depan mereka; mereka melakukan hal-hal yang jahat sehingga mereka menimbulkan sakit hati TUHAN;', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 12, 'mereka beribadah kepada berhala-berhala, walaupun TUHAN telah berfirman kepada mereka: "Janganlah kamu berbuat seperti itu!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 13, 'TUHAN telah memperingatkan kepada orang Israel dan kepada orang Yehuda dengan perantaraan semua nabi dan semua tukang tilik: "Berbaliklah kamu dari pada jalan-jalanmu yang jahat itu dan tetaplah ikuti segala perintah dan ketetapan-Ku, sesuai dengan segala undang-undang yang telah Kuperintahkan kepada nenek moyangmu dan yang telah Kusampaikan kepada mereka dengan perantaraan hamba-hamba-Ku, para nabi."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 14, 'Tetapi mereka tidak mau mendengarkan, melainkan mereka menegarkan tengkuknya seperti nenek moyangnya yang tidak percaya kepada TUHAN, Allah mereka.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 15, 'Mereka menolak ketetapan-Nya dan perjanjian-Nya, yang telah diadakan dengan nenek moyang mereka, juga peraturan-peraturan-Nya yang telah diperingatkan-Nya kepada mereka; mereka mengikuti dewa kesia-siaan, sehingga mereka mengikuti bangsa-bangsa yang di sekeliling mereka, walaupun TUHAN telah memerintahkan kepada mereka: janganlah berbuat seperti mereka itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 16, 'Mereka telah meninggalkan segala perintah TUHAN, Allah mereka, dan telah membuat dua anak lembu tuangan; juga mereka membuat patung Asyera, sujud menyembah kepada segenap tentara langit dan beribadah kepada Baal.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 17, 'Tambahan pula mereka mempersembahkan anak-anaknya sebagai korban dalam api dan melakukan tenung dan telaah dan memperbudak diri dengan melakukan yang jahat di mata TUHAN, sehingga mereka menimbulkan sakit hati-Nya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 18, 'Sebab itu TUHAN sangat murka kepada Israel, dan menjauhkan mereka dari hadapan-Nya; tidak ada yang tinggal kecuali suku Yehuda saja. ?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 19, 'Juga Yehuda tidak berpegang pada perintah TUHAN, Allah mereka, tetapi mereka hidup menurut ketetapan yang telah dibuat Israel,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 20, 'jadi TUHAN menolak segenap keturunan Israel: Ia menindas mereka dan menyerahkan mereka ke dalam tangan perampok-perampok, sampai habis mereka dibuang-Nya dari hadapan-Nya. ?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 21, 'Ketika Ia mengoyakkan Israel dari pada keluarga Daud, maka mereka mengangkat Yerobeam bin Nebat menjadi raja, tetapi Yerobeam membuat orang Israel menyimpang dari pada mengikuti TUHAN dan mengakibatkan mereka melakukan dosa yang besar.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 22, 'Demikianlah orang Israel hidup menurut segala dosa yang telah dilakukan Yerobeam; mereka tidak menjauhinya,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 23, 'sampai TUHAN menjauhkan orang Israel dari hadapan-Nya seperti yang telah difirmankan-Nya dengan perantaraan semua hamba-Nya, para nabi. Orang Israel diangkut dari tanahnya ke Asyur ke dalam pembuangan. Demikianlah sampai hari ini.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 24, 'Raja Asyur mengangkut orang dari Babel, dari Kuta, dari Awa, dari Hamat dan Sefarwaim, lalu menyuruh mereka diam di kota-kota Samaria menggantikan orang Israel; maka orang-orang itupun menduduki Samaria dan diam di kota-kotanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 25, 'Pada mulanya waktu mereka diam di sana tidaklah mereka takut kepada TUHAN, sebab itu TUHAN melepaskan singa-singa ke antara mereka yang membunuh beberapa orang di antara mereka.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 26, 'Lalu berkatalah orang kepada raja Asyur: "Bangsa-bangsa yang tuanku angkut tertawan dan yang tuanku suruh diam di kota-kota Samaria tidaklah mengenal hukum beribadah kepada Allah negeri itu, sebab itu dilepaskan-Nyalah singa-singa ke antara mereka yang sesungguhnya membunuh mereka, oleh karena mereka tidak mengenal hukum beribadah kepada Allah negeri itu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 27, 'Lalu raja Asyur memberi perintah: "Suruhlah pergi ke sana salah seorang imam yang telah kamu angkut dari sana ke dalam pembuangan. Biarlah ia pergi dan diam di sana dan mengajarkan kepada mereka hukum beribadah kepada Allah negeri itu!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 28, 'Salah seorang imam yang telah mereka angkut dari Samaria ke dalam pembuangan pergi dan diam di Betel. Ia mengajarkan kepada mereka bagaimana seharusnya berbakti kepada TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 29, 'Tetapi setiap bangsa itu telah membuat allahnya sendiri dan menempatkannya di kuil di atas bukit-bukit pengorbanan, yang dibuat oleh orang-orang Samaria; setiap bangsa bertindak demikian di kota-kota yang mereka diami:', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 30, 'orang-orang Babel membuat patung Sukot-Benot, orang-orang Kuta membuat patung Nergal, orang-orang Hamat membuat patung Asima,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 31, 'dan orang-orang Awa membuat patung Nibhas dan Tartak. Orang-orang Sefarwaim membakar anak-anak mereka sebagai korban bagi Adramelekh dan Anamelekh, para allah di Sefarwaim.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 32, 'Di samping itu mereka berbakti kepada TUHAN dan mengangkat dari kalangan mereka imam untuk bukit-bukit pengorbanan, maka orang-orang inilah yang melakukan ibadah bagi mereka di kuil di atas bukit-bukit pengorbanan itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 33, 'Mereka berbakti kepada TUHAN, tetapi dalam pada itu mereka beribadah kepada allah mereka sesuai dengan adat bangsa-bangsa yang dari antaranya mereka diangkut tertawan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 34, 'Sampai hari ini mereka berbuat sesuai dengan adat yang dahulu. Mereka tidak berbakti kepada TUHAN dan tidak berbuat sesuai dengan ketetapan, hukum, undang-undang dan perintah yang diperintahkan TUHAN kepada anak-anak Yakub yang telah dinamai-Nya Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 35, 'TUHAN telah mengadakan perjanjian dengan mereka dan memberi perintah kepada mereka: "Janganlah berbakti kepada allah lain, janganlah sujud menyembah kepadanya, janganlah beribadah kepadanya dan janganlah mempersembahkan korban kepadanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 36, 'Tetapi TUHAN yang menuntun kamu dari tanah Mesir dengan kekuatan yang besar dan dengan tangan yang teracung, kepada-Nyalah kamu harus berbakti, kepada-Nyalah kamu harus sujud menyembah dan mempersembahkan korban.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 37, 'Tetapi kamu harus berpegang kepada ketetapan-ketetapan, peraturan-peratur hukum dan perintah yang telah ditulis-Nya bagimu dengan melakukannya senantiasa dengan setia, dan janganlah kamu berbakti kepada allah-allah lain.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 38, 'Janganlah kamu melupakan perjanjian yang telah Kuadakan dengan kamu dan janganlah kamu berbakti kepada allah lain,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 39, 'melainkan kepada TUHAN, Allahmu, kamu harus berbakti, maka Ia akan melepaskan kamu dari tangan semua musuhmu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 40, 'Tetapi mereka tidak mau mendengarkan, melainkan mereka berbuat sesuai dengan adat mereka yang dahulu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 17, 41, 'Demikianlah bangsa-bangsa ini berbakti kepada TUHAN, tetapi dalam pada itu mereka beribadah juga kepada patung-patung mereka; baik anak-anak mereka maupun cucu cicit mereka melakukan seperti yang telah dilakukan nenek moyang mereka, sampai hari ini.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 1, 'Maka dalam tahun ketiga zaman Hosea bin Ela, raja Israel, Hizkia, anak Ahas raja Yehuda menjadi raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 2, 'Ia berumur dua puluh lima tahun pada waktu ia menjadi raja dan dua puluh sembilan tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Abi, anak Zakharia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 3, 'Ia melakukan apa yang benar di mata TUHAN, tepat seperti yang dilakukan Daud, bapa leluhurnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 4, 'Dialah yang menjauhkan bukit-bukit pengorbanan dan yang meremukkan tugu-tugu berhala dan yang menebang tiang-tiang berhala dan yang menghancurkan ular tembaga yang dibuat Musa, sebab sampai pada masa itu orang Israel memang masih membakar korban bagi ular itu yang namanya disebut Nehustan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 5, 'Ia percaya kepada TUHAN, Allah Israel, dan di antara semua raja-raja Yehuda, baik yang sesudah dia maupun yang sebelumnya, tidak ada lagi yang sama seperti dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 6, 'Ia berpaut kepada TUHAN, tidak menyimpang dari pada mengikuti Dia dan ia berpegang pada perintah-perintah TUHAN yang telah diperintahkan-Nya kepada Musa.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 7, 'Maka TUHAN menyertai dia; ke manapun juga ia pergi berperang, ia beruntung. Ia memberontak kepada raja Asyur dan tidak lagi takluk kepadanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 8, 'Dialah yang mengalahkan orang Filistin sampai ke Gaza dan memusnahkan daerahnya, baik menara-menara penjagaan maupun kota-kota yang berkubu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 9, 'Dalam tahun keempat zaman raja Hizkia?itulah tahun ketujuh zaman Hosea bin Ela, raja Israel?majulah Salmaneser, raja Asyur, menyerang Samaria dan mengepungnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 10, 'Direbutlah itu sesudah lewat tiga tahun; dalam tahun keenam zaman Hizkia?itulah tahun kesembilan zaman Hosea, raja Israel?direbutlah Samaria.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 11, 'Raja Asyur mengangkut orang Israel ke dalam pembuangan ke Asyur dan menempatkan mereka di Halah, pada sungai Habor, yakni sungai negeri Gozan, dan di kota-kota orang Madai,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 12, 'oleh karena mereka tidak mau mendengarkan suara TUHAN, Allah mereka, dan melanggar perjanjian-Nya, yakni segala yang diperintahkan oleh Musa, hamba TUHAN; mereka tidak mau mendengarkannya dan tidak mau melakukannya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 13, 'Dalam tahun keempat belas zaman raja Hizkia majulah Sanherib, raja Asyur, menyerang segala kota berkubu negeri Yehuda, lalu merebutnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 14, 'Hizkia, raja Yehuda, mengutus orang kepada raja Asyur di Lakhis dengan pesan: "Aku telah berbuat dosa; undurlah dari padaku; apapun yang kaubebankan kepadaku akan kupikul." Kemudian raja Asyur membebankan kepada Hizkia, raja Yehuda, tiga ratus talenta perak dan tiga puluh talenta emas.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 15, 'Hizkia memberikan segala perak yang terdapat dalam rumah TUHAN dan dalam perbendaharaan istana raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 16, 'Pada waktu itu Hizkia mengerat emas dari pintu-pintu dan dari jenang-jenang pintu bait TUHAN, yang telah dilapis oleh Hizkia, raja Yehuda; diberikannyalah semuanya kepada raja Asyur.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 17, 'Sesudah itu raja Asyur mengirim panglima, kepala istana dan juru minuman agung dari Lakhis kepada raja Hizkia di Yerusalem disertai suatu tentara yang besar. Mereka maju dan sampai ke Yerusalem. Setelah mereka maju dan sampai di situ, mereka mengambil tempat dekat saluran kolam atas yang di jalan raja pada Padang Tukang Penatu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 18, 'Dan ketika mereka memanggil-manggil kepada raja, keluarlah mendapatkan mereka Elyakim bin Hilkia, kepala istana, dan Sebna, panitera negara, serta Yoah bin Asaf, bendahara negara.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 19, 'Lalu berkatalah juru minuman agung kepada mereka: "Baiklah katakan kepada Hizkia: Beginilah kata raja agung, raja Asyur: Kepercayaan macam apakah yang kaupegang ini?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 20, 'Kaukira bahwa hanya ucapan bibir saja dapat merupakan siasat dan kekuatan untuk perang! Sekarang, kepada siapa engkau berharap, maka engkau memberontak terhadap aku?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 21, 'Sesungguhnya, engkau berharap kepada tongkat bambu yang patah terkulai itu, yaitu Mesir, yang akan menusuk dan menembus tangan orang yang bertopang kepadanya. Begitulah keadaan Firaun, raja Mesir, bagi semua orang yang berharap kepadanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 22, 'Dan apabila kamu berkata kepadaku: Kami berharap kepada TUHAN, Allah kami, ?bukankah Dia itu yang bukit-bukit pengorbanan-Nya dan mezbah-mezbah-Nya telah dijauhkan oleh Hizkia sambil berkata kepada Yehuda dan Yerusalem: Di depan mezbah yang di Yerusalem inilah kamu harus sujud menyembah!', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 23, 'Maka sekarang, baiklah bertaruh dengan tuanku, raja Asyur: Aku akan memberikan dua ribu ekor kuda kepadamu, jika engkau sanggup memberikan dari pihakmu orang-orang yang mengendarainya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 24, 'Bagaimanakah mungkin engkau memukul mundur satu orang perwira tuanku yang paling kecil? Padahal engkau berharap kepada Mesir dalam hal kereta dan orang-orang berkuda!', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 25, 'Sekarangpun, adakah di luar kehendak TUHAN aku maju melawan tempat ini untuk memusnahkannya? TUHAN telah berfirman kepadaku: Majulah menyerang negeri itu dan musnahkanlah itu!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 26, 'Lalu berkatalah Elyakim bin Hilkia, Sebna dan Yoah kepada juru minuman agung: "Silakan berbicara dalam bahasa Aram kepada hamba-hambamu ini, sebab kami mengerti; tetapi janganlah berbicara dengan kami dalam bahasa Yehuda sambil didengar oleh rakyat yang ada di atas tembok."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 27, 'Tetapi juru minuman agung berkata kepada mereka: "Adakah tuanku mengutus aku untuk mengucapkan perkataan-perkataan ini hanya kepada tuanmu dan kepadamu saja? Bukankah juga kepada orang-orang yang duduk di atas tembok, yang memakan tahinya dan meminum air kencingnya bersama-sama dengan kamu?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 28, 'Kemudian berdirilah juru minuman agung dan berserulah ia dengan suara nyaring dalam bahasa Yehuda. Ia berkata: "Dengarlah perkataan raja agung, raja Asyur!', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 29, 'Beginilah kata raja: Janganlah Hizkia memperdayakan kamu, sebab ia tidak sanggup melepaskan kamu dari tanganku!', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 30, 'Janganlah Hizkia mengajak kamu berharap kepada TUHAN dengan mengatakan: Tentulah TUHAN akan melepaskan kita; dan kota ini tidak akan diserahkan ke dalam tangan raja Asyur.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 31, 'Janganlah dengarkan Hizkia, sebab beginilah kata raja Asyur: Adakanlah perjanjian penyerahan dengan aku dan datanglah ke luar kepadaku, maka setiap orang dari padamu akan makan dari pohon anggurnya dan dari pohon aranya serta minum dari sumurnya,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 32, 'sampai aku datang dan membawa kamu ke suatu negeri seperti negerimu ini, suatu negeri yang bergandum dan berair anggur, suatu negeri yang beroti dan berkebun anggur, suatu negeri yang berpohon zaitun, berminyak dan bermadu; dengan demikian kamu hidup dan tidak mati. Tetapi janganlah dengarkan Hizkia, sebab ia membujuk kamu dengan mengatakan: TUHAN akan melepaskan kita!', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 33, 'Apakah pernah para allah bangsa-bangsa melepaskan negerinya masing-masing dari tangan raja Asyur?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 34, 'Di manakah para allah negeri Hamat dan Arpad? Di manakah para allah negeri Sefarwaim, Hena dan Iwa? Apakah mereka telah melepaskan Samaria dari tanganku?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 35, 'Siapakah di antara semua allah negeri-negeri yang telah melepaskan negeri mereka dari tanganku, sehingga TUHAN sanggup melepaskan Yerusalem dari tanganku?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 36, 'Tetapi rakyat itu berdiam diri dan tidak menjawab dia sepatah katapun, sebab ada perintah raja, bunyinya: "Jangan kamu menjawab dia!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 18, 37, 'Kemudian pergilah Elyakim bin Hilkia, kepala istana, dan Sebna, panitera negara, dan Yoah bin Asaf, bendahara negara, menghadap Hizkia, dengan pakaian yang dikoyakkan, lalu memberitahukan kepadanya perkataan juru minuman agung.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 1, 'Segera sesudah raja Hizkia mendengar itu, dikoyakkannyalah pakaiannya dan diselubunginyalah badannya dengan kain kabung, lalu masuklah ia ke rumah TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 2, 'Disuruhnyalah juga Elyakim, kepala istana, Sebna, panitera negara, dan yang tua-tua di antara para imam, dengan berselubungkan kain kabung, kepada nabi Yesaya bin Amos.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 3, 'Berkatalah mereka kepadanya: "Beginilah kata Hizkia: Hari ini hari kesesakan, hari hukuman dan penistaan; sebab sudah datang waktunya untuk melahirkan anak, tetapi tidak ada kekuatan untuk melahirkannya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 4, 'Mungkin TUHAN, Allahmu, sudah mendengar segala perkataan juru minuman agung yang telah diutus oleh raja Asyur, tuannya, untuk mencela Allah yang hidup, sehingga TUHAN, Allahmu, mau memberi hukuman karena perkataan-perkataan yang telah didengar-Nya. Maka baiklah engkau menaikkan doa untuk sisa yang masih tinggal ini!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 5, 'Ketika pegawai-pegawai raja Hizkia sampai kepada Yesaya,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 6, 'berkatalah Yesaya kepada mereka: "Beginilah kamu katakan kepada tuanmu: Beginilah firman TUHAN: Janganlah engkau takut terhadap perkataan yang kaudengar yang telah diucapkan oleh budak-budak raja Asyur untuk menghujat Aku.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 7, 'Sesungguhnya, Aku akan menyuruh suatu roh masuk di dalamnya, sehingga ia mendengar suatu kabar dan pulang ke negerinya; Aku akan membuat dia mati rebah oleh pedang di negerinya sendiri."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 8, 'Ketika juru minuman agung pulang, didapatinyalah raja Asyur berperang melawan Libna; sebab sudah didengarnya bahwa raja telah berangkat dari Lakhis.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 9, 'Dalam pada itu raja mendengar tentang Tirhaka, raja Etiopia, berita yang demikian: "Sesungguhnya, ia telah keluar berperang melawan engkau," maka disuruhnyalah kembali utusan-utusan kepada Hizkia dengan pesan:', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 10, '"Beginilah harus kamu katakan kepada Hizkia, raja Yehuda: Janganlah Allahmu yang kaupercayai itu memperdayakan engkau dengan menjanjikan: Yerusalem tidak akan diserahkan ke tangan raja Asyur.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 11, 'Sesungguhnya, engkau ini telah mendengar tentang yang dilakukan raja-raja Asyur kepada segala negeri, yakni bahwa mereka telah menumpasnya; masakan engkau ini akan dilepaskan?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 12, 'Sudahkah para allah dari bangsa-bangsa, yang telah dimusnahkan oleh nenek moyangku, dapat melepaskan mereka, yakni Gozan, Haran, Rezef dan bani Eden yang di Telasar?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 13, 'Di manakah raja negeri Hamat dan Arpad, raja kota Sefarwaim, raja negeri Hena dan Iwa?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 14, 'Hizkia menerima surat itu dari tangan para utusan, lalu membacanya; kemudian pergilah ia ke rumah TUHAN dan membentangkan surat itu di hadapan TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 15, 'Hizkia berdoa di hadapan TUHAN dengan berkata: "Ya TUHAN, Allah Israel, yang bertakhta di atas kerubim! Hanya Engkau sendirilah Allah segala kerajaan di bumi; Engkaulah yang menjadikan langit dan bumi.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 16, 'Sendengkanlah telinga-Mu, ya TUHAN, dan dengarlah; bukalah mata-Mu, ya TUHAN, dan lihatlah; dengarlah perkataan Sanherib yang telah dikirimnya untuk mengaibkan Allah yang hidup.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 17, 'Ya TUHAN, memang raja-raja Asyur telah memusnahkan bangsa-bangsa dan negeri-negeri mereka', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 18, 'dan menaruh para allah mereka ke dalam api, sebab mereka bukanlah Allah, hanya buatan tangan manusia, kayu dan batu; sebab itu dapat dibinasakan orang.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 19, 'Maka sekarang, ya TUHAN, Allah kami, selamatkanlah kiranya kami dari tangannya, supaya segala kerajaan di bumi mengetahui, bahwa hanya Engkau sendirilah Allah, ya TUHAN."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 20, 'Lalu Yesaya bin Amos menyuruh orang kepada Hizkia mengatakan: "Beginilah firman TUHAN, Allah Israel: Apa yang telah kaudoakan kepada-Ku mengenai Sanherib, raja Asyur, telah Kudengar.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 21, 'Inilah firman yang telah diucapkan TUHAN mengenai dia: Anak dara, yaitu puteri Sion, telah menghina engkau, telah mengolok-olokkan engkau; dan puteri Yerusalem telah geleng-geleng kepala di belakangmu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 22, 'Siapakah yang engkau cela dan engkau hujat? Terhadap siapakah engkau menyaringkan suaramu, dan memandang dengan sombong? Terhadap Yang Mahakudus Allah Israel!', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 23, 'Dengan perantaraan utusan-utusanmu engkau telah mencela Tuhan, dan engkau telah berkata: Dengan banyaknya keretaku aku naik ke tempat-tempat tinggi di pegunungan, ke tempat yang paling jauh di gunung Libanon; aku telah menebang pohon-pohon arasnya yang tinggi besar, pohon-pohon sanobarnya yang terpilih; aku telah masuk ke tempat permalaman yang paling ujung, ke hutan pohon-pohonannya yang lebat.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 24, 'Aku ini telah menggali air dan telah minum air asing, dan aku telah mengeringkan dengan telapak kakiku segala sungai di Mesir.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 25, 'Bukankah telah kaudengar, bahwa Aku telah menentukannya dari jauh hari, dan telah merancangnya pada zaman purbakala? Sekarang Aku mewujudkannya, bahwa engkau membuat sunyi senyap kota-kota yang berkubu menjadi timbunan batu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 26, 'Sedang penduduknya yang tak berdaya menjadi terkejut dan malu; mereka menjadi seperti tumbuh-tumbuhan di padang dan seperti rumput hijau, seperti rumput di atas sotoh, atau gandum yang layu sebelum ia masak.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 27, 'Aku tahu, jika engkau bangun atau duduk jika keluar atau masuk, atau jika engkau mengamuk terhadap Aku.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 28, 'Oleh karena engkau telah mengamuk terhadap Aku, dan kata-kata keangkuhanmu telah naik sampai ke telinga-Ku, maka Aku akan menaruh kelikir-Ku pada hidungmu dan kekang-Ku pada bibirmu, dan Aku akan memulangkan engkau melalui jalan, dari mana engkau datang.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 29, 'Dan inilah yang akan menjadi tanda bagimu, hai Hizkia: Dalam tahun ini orang makan apa yang tumbuh sendiri, dan dalam tahun yang kedua, apa yang tumbuh dari tanaman yang pertama, tetapi dalam tahun yang ketiga, menaburlah kamu, menuai, membuat kebun anggur dan memakan buahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 30, 'Dan orang-orang yang terluput di antara kaum Yehuda, yaitu orang-orang yang masih tertinggal, akan berakar pula ke bawah dan menghasilkan buah ke atas.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 31, 'Sebab dari Yerusalem akan keluar orang-orang yang tertinggal dan dari gunung Sion orang-orang yang terluput; giat cemburu TUHAN semesta alam akan melakukan hal ini.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 32, 'Sebab itu beginilah firman TUHAN mengenai raja Asyur: Ia tidak akan masuk ke kota ini dan tidak akan menembakkan panah ke sana; juga ia tidak akan mendatanginya dengan perisai dan tidak akan menimbun tanah menjadi tembok untuk mengepungnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 33, 'Melalui jalan, dari mana ia datang, ia akan pulang, tetapi ke kota ini ia tidak akan masuk, demikianlah firman TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 34, 'Dan Aku akan memagari kota ini untuk menyelamatkannya, oleh karena Aku dan oleh karena Daud, hamba-Ku."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 35, 'Maka pada malam itu keluarlah Malaikat TUHAN, lalu dibunuh-Nyalah seratus delapan puluh lima ribu orang di dalam perkemahan Asyur. Keesokan harinya pagi-pagi tampaklah, semuanya bangkai orang-orang mati belaka!', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 36, 'Sebab itu berangkatlah Sanherib, raja Asyur, dan pulang, lalu tinggallah ia di Niniwe.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 19, 37, 'Pada suatu kali ketika ia sujud menyembah di dalam kuil Nisrokh, allahnya, maka Adramelekh dan Sarezer, anak-anaknya, membunuh dia dengan pedang, dan mereka meloloskan diri ke tanah Ararat. Kemudian Esarhadon, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 1, 'Pada hari-hari itu Hizkia jatuh sakit dan hampir mati. Lalu datanglah nabi Yesaya bin Amos, dan berkata kepadanya: "Beginilah firman TUHAN: Sampaikanlah pesan terakhir kepada keluargamu, sebab engkau akan mati, tidak akan sembuh lagi."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 2, 'Lalu Hizkia memalingkan mukanya ke arah dinding dan ia berdoa kepada TUHAN:', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 3, '"Ah TUHAN, ingatlah kiranya, bahwa aku telah hidup di hadapan-Mu dengan setia dan dengan tulus hati dan bahwa aku telah melakukan apa yang baik di mata-Mu." Kemudian menangislah Hizkia dengan sangat.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 4, 'Tetapi Yesaya belum lagi keluar dari pelataran tengah, tiba-tiba datanglah firman TUHAN kepadanya:', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 5, '"Baliklah dan katakanlah kepada Hizkia, raja umat-Ku: Beginilah firman TUHAN, Allah Daud, bapa leluhurmu: Telah Kudengar doamu dan telah Kulihat air matamu; sesungguhnya Aku akan menyembuhkan engkau; pada hari yang ketiga engkau akan pergi ke rumah TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 6, 'Aku akan memperpanjang hidupmu lima belas tahun lagi dan Aku akan melepaskan engkau dan kota ini dari tangan raja Asyur; Aku akan memagari kota ini oleh karena Aku dan oleh karena Daud, hamba-Ku."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 7, 'Kemudian berkatalah Yesaya: "Ambillah sebuah kue ara!" Lalu orang mengambilnya dan ditaruh pada barah itu, maka sembuhlah ia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 8, 'Sebelum itu Hizkia telah berkata kepada Yesaya: "Apakah yang akan menjadi tanda bahwa TUHAN akan menyembuhkan aku dan bahwa aku akan pergi ke rumah TUHAN pada hari yang ketiga?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 9, 'Yesaya menjawab: "Inilah yang akan menjadi tanda bagimu dari TUHAN, bahwa TUHAN akan melakukan apa yang telah dijanjikan-Nya: Akan majukah bayang-bayang itu sepuluh tapak atau akan mundur sepuluh tapak?"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 10, 'Hizkia berkata: "Itu perkara ringan bagi bayang-bayang itu untuk memanjang sepuluh tapak! Sebaliknya, biarlah bayang-bayang itu mundur ke belakang sepuluh tapak."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 11, 'Lalu berserulah nabi Yesaya kepada TUHAN, maka dibuat-Nyalah bayang-bayang itu mundur ke belakang sepuluh tapak, yang sudah dijalani bayang-bayang itu pada penunjuk matahari buatan Ahas.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 12, 'Pada waktu itu Merodakh-Baladan bin Baladan, raja Babel, menyuruh orang membawa surat dan pemberian kepada Hizkia, sebab telah didengarnya bahwa Hizkia sakit tadinya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 13, 'Hizkia bersukacita atas kedatangan mereka, lalu diperlihatkannyalah kepada mereka segenap gedung harta bendanya, emas dan perak, rempah-rempah dan minyak yang berharga, gedung persenjataannya dan segala yang terdapat dalam perbendaharaannya. Tidak ada barang yang tidak diperlihatkan Hizkia kepada mereka di istananya dan di seluruh daerah kekuasaannya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 14, 'Kemudian datanglah nabi Yesaya kepada raja Hizkia dan bertanya kepadanya: "Apakah yang telah dikatakan orang-orang ini? Dan dari manakah mereka datang?" Jawab Hizkia: "Mereka datang dari negeri yang jauh, dari Babel!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 15, 'Lalu tanyanya lagi: "Apakah yang telah dilihat mereka di istanamu?" Jawab Hizkia: "Semua yang ada di istanaku telah mereka lihat. Tidak ada barang yang tidak kuperlihatkan kepada mereka di perbendaharaanku."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 16, 'Lalu Yesaya berkata kepada Hizkia: "Dengarkanlah firman TUHAN!', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 17, 'Sesungguhnya, suatu masa akan datang, bahwa segala yang ada dalam istanamu dan yang disimpan oleh nenek moyangmu sampai hari ini akan diangkut ke Babel. Tidak ada barang yang akan ditinggalkan, demikianlah firman TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 18, 'Dan dari keturunanmu yang akan kauperoleh, akan diambil orang untuk menjadi sida-sida di istana raja Babel."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 19, 'Hizkia menjawab kepada Yesaya: "Sungguh baik firman TUHAN yang engkau ucapkan itu!" Tetapi pikirnya: "Asal ada damai dan keamanan seumur hidupku!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 20, 'Selebihnya dari riwayat Hizkia, segala kepahlawanannya dan bagaimana ia membuat kolam dan saluran air dan mengalirkan air ke dalam kota, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 20, 21, 'Kemudian Hizkia mendapat perhentian bersama-sama dengan nenek moyangnya. Maka Manasye, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 1, 'Manasye berumur dua belas tahun pada waktu ia menjadi raja dan lima puluh lima tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Hefzibah.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 2, 'Ia melakukan apa yang jahat di mata TUHAN, sesuai dengan perbuatan keji bangsa-bangsa yang telah dihalau TUHAN dari depan orang Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 3, 'Ia mendirikan kembali bukit-bukit pengorbanan yang telah dimusnahkan oleh Hizkia, ayahnya; ia membangun mezbah-mezbah untuk Baal, membuat patung Asyera seperti yang dilakukan Ahab, raja Israel, dan sujud menyembah kepada segenap tentara langit dan beribadah kepadanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 4, 'Ia mendirikan mezbah-mezbah di rumah TUHAN, walaupun sehubungan dengan rumah itu TUHAN telah berfirman: "Di Yerusalem Aku akan menaruh nama-Ku!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 5, 'Dan ia mendirikan juga mezbah-mezbah bagi segenap tentara langit di kedua pelataran rumah TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 6, 'Bahkan, ia mempersembahkan anaknya sebagai korban dalam api, melakukan ramal dan telaah, dan menghubungi para pemanggil arwah dan para pemanggil roh peramal. Ia melakukan banyak yang jahat di mata TUHAN, sehingga ia menimbulkan sakit hati-Nya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 7, 'Ia menaruh juga patung Asyera yang telah dibuatnya dalam rumah, walaupun sehubungan dengan rumah itu TUHAN telah berfirman kepada Daud dan kepada Salomo, anaknya: "Dalam rumah ini dan di Yerusalem, yang telah Kupilih dari antara segala suku Israel, Aku akan menaruh nama-Ku untuk selama-lamanya!', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 8, 'Aku tidak akan membiarkan bangsa Israel lagi dibawa keluar dari tanah yang telah Kuberikan kepada nenek moyang mereka, asal saja mereka tetap berbuat tepat seperti yang telah Kuperintahkan kepada mereka dan tepat menurut hukum yang telah diperintahkan kepada mereka oleh hamba-Ku Musa."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 9, 'Tetapi mereka tidak mau mendengarkan, dan Manasye menyesatkan mereka, sehingga mereka melakukan yang jahat lebih dari pada bangsa-bangsa yang telah dipunahkan TUHAN dari hadapan orang Israel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 10, 'Kemudian berfirmanlah TUHAN dengan perantaraan para hamba-Nya, yakni para nabi:', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 11, '"Oleh karena Manasye, raja Yehuda, telah melakukan kekejian-kekejian ini, berbuat jahat lebih dari pada segala yang telah dilakukan oleh orang Amori yang mendahului dia, dan dengan berhala-berhalanya ia telah mengakibatkan orang Yehuda berdosa pula,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 12, 'sebab itu beginilah firman TUHAN, Allah Israel: Sesungguhnya Aku akan mendatangkan malapetaka atas Yerusalem dan Yehuda, sehingga setiap orang yang mendengarnya akan bising kedua telinganya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 13, 'Dan Aku akan merentangkan atas Yerusalem tali pengukur sama seperti atas Samaria dan tali unting-unting sama seperti atas keluarga Ahab; dan Aku akan menghapuskan Yerusalem seperti orang menghapus pinggan, yakni habis dihapus, dibalikkan pula menungging.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 14, 'Aku akan membuangkan sisa milik pusaka-Ku dan akan menyerahkan mereka ke dalam tangan musuh-musuh mereka, sehingga mereka menjadi jarahan dan menjadi rampasan bagi semua musuh mereka,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 15, 'oleh karena mereka telah melakukan apa yang jahat di mata-Ku dan dengan demikian mereka menimbulkan sakit hati-Ku, mulai dari hari nenek moyang mereka keluar dari Mesir sampai hari ini."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 16, 'Lagipula Manasye mencurahkan darah orang yang tidak bersalah sedemikian banyak, hingga dipenuhinya Yerusalem dari ujung ke ujung, belum termasuk dosa-dosanya yang mengakibatkan orang Yehuda berdosa pula dengan berbuat apa yang jahat di mata TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 17, 'Selebihnya dari riwayat Manasye, segala yang dilakukannya dan dosa-dosa yang diperbuatnya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 18, 'Kemudian Manasye mendapat perhentian bersama-sama dengan nenek moyangnya, dan ia dikuburkan di taman istananya, di taman Uza. Maka Amon, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 19, 'Amon berumur dua puluh dua tahun pada waktu ia menjadi raja dan dua tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Mesulemet binti Harus, dari Yotba.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 20, 'Ia melakukan apa yang jahat di mata TUHAN seperti yang telah dilakukan Manasye, ayahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 21, 'Ia hidup sama seperti ayahnya dahulu sambil beribadah kepada berhala-berhala yang disembah oleh ayahnya dan sujud menyembah kepada mereka.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 22, 'Ia meninggalkan TUHAN, Allah nenek moyangnya dan tidak hidup menurut kehendak TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 23, 'Dan pegawai-pegawai Amon mengadakan persepakatan melawan dia dan membunuh raja di istananya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 24, 'Tetapi rakyat negeri itu membunuh semua orang yang mengadakan persepakatan melawan raja Amon; dan rakyat negeri itu mengangkat Yosia, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 25, 'Selebihnya dari riwayat Amon, apa yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 21, 26, 'Kemudian ia dikuburkan dalam kuburnya di taman Uza. Maka Yosia, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 1, 'Yosia berumur delapan tahun pada waktu ia menjadi raja dan tiga puluh satu tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Yedida binti Adaya, dari Bozkat.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 2, 'Ia melakukan apa yang benar di mata TUHAN dan hidup sama seperti Daud, bapa leluhurnya, dan tidak menyimpang ke kanan atau ke kiri.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 3, 'Dalam tahun yang kedelapan belas zaman raja Yosia maka raja menyuruh Safan bin Azalya bin Mesulam, panitera itu, ke rumah TUHAN, katanya:', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 4, '"Pergilah kepada imam besar Hilkia; suruhlah ia menyerahkan seluruh uang yang telah dibawa ke dalam rumah TUHAN yang telah dikumpulkan dari pihak rakyat oleh penjaga-penjaga pintu;', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 5, 'baiklah itu diberikan mereka ke tangan para pekerja yang diangkat untuk mengawasi rumah TUHAN, supaya diberikan kepada tukang-tukang yang ada di rumah TUHAN untuk memperbaiki kerusakan rumah itu,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 6, 'yaitu kepada tukang-tukang kayu, tukang-tukang bangunan dan tukang-tukang tembok, juga bagi pembelian kayu dan batu pahat untuk memperbaiki rumah itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 7, 'Tetapi tidak usahlah mengadakan perhitungan dengan mereka mengenai uang yang diberikan ke tangan mereka, sebab mereka bekerja dengan jujur."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 8, 'Berkatalah imam besar Hilkia, kepada Safan, panitera itu: "Telah kutemukan kitab Taurat itu di rumah TUHAN!" Lalu Hilkia memberikan kitab itu kepada Safan, dan Safan terus membacanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 9, 'Kemudian Safan, panitera itu, masuk menghadap raja, disampaikannyalah kabar tentang itu kepada raja: "Hamba-hambamu ini telah mengambil seluruh uang yang terdapat di rumah TUHAN dan memberikannya ke tangan para pekerja yang diangkat mengawasi rumah itu."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 10, 'Safan, panitera itu, memberitahukan juga kepada raja: "Imam Hilkia telah memberikan kitab kepadaku," lalu Safan membacakannya di depan raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 11, 'Segera sesudah raja mendengar perkataan kitab Taurat itu, dikoyakkannyalah pakaiannya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 12, 'Kemudian raja memberi perintah kepada imam Hilkia, kepada Ahikam bin Safan, kepada Akhbor bin Mikha, kepada Safan, panitera itu, dan kepada Asaya, hamba raja, katanya:', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 13, '"Pergilah, mintalah petunjuk TUHAN bagiku, bagi rakyat dan bagi seluruh Yehuda, tentang perkataan kitab yang ditemukan ini, sebab hebat kehangatan murka TUHAN yang bernyala-nyala terhadap kita, oleh karena nenek moyang kita tidak mendengarkan perkataan kitab ini dengan berbuat tepat seperti yang tertulis di dalamnya."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 14, 'Maka pergilah imam Hilkia, Ahikam, Akhbor, Safan dan Asaya kepada nabiah Hulda, isteri seorang yang mengurus pakaian-pakaian, yaitu Salum bin Tikwa bin Harhas; nabiah itu tinggal di Yerusalem, di perkampungan baru. Mereka memberitakan semuanya kepadanya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 15, 'Perempuan itu menjawab mereka: "Beginilah firman TUHAN, Allah Israel! Katakanlah kepada orang yang menyuruh kamu kepada-Ku!', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 16, 'Beginilah firman TUHAN: Sesungguhnya Aku akan mendatangkan malapetaka atas tempat ini dan atas penduduknya, yakni segala perkataan kitab yang telah dibaca oleh raja Yehuda;', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 17, 'karena mereka meninggalkan Aku dan membakar korban kepada allah lain dengan maksud menimbulkan sakit hati-Ku dengan segala pekerjaan tangan mereka; sebab itu kehangatan murka-Ku akan bernyala-nyala terhadap tempat ini dengan tidak padam-padam.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 18, 'Tetapi kepada raja Yehuda, yang telah menyuruh kamu untuk meminta petunjuk TUHAN, harus kamu katakan demikian: Beginilah firman TUHAN, Allah Israel: Mengenai perkataan yang telah kaudengar itu,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 19, 'oleh karena engkau sudah menyesal dan engkau merendahkan diri di hadapan TUHAN pada waktu engkau mendengar hukuman yang Kufirmankan terhadap tempat ini dan terhadap penduduknya, bahwa mereka akan mendahsyatkan dan menjadi kutuk, dan oleh karena engkau mengoyakkan pakaianmu dan menangis di hadapan-Ku, Akupun telah mendengarnya, demikianlah firman TUHAN,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 22, 20, 'sebab itu, sesungguhnya Aku akan mengumpulkan engkau kepada nenek moyangmu, dan engkau akan dikebumikan ke dalam kuburmu dengan damai, dan matamu tidak akan melihat segala malapetaka yang akan Kudatangkan atas tempat ini." Lalu mereka menyampaikan jawab itu kepada raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 1, 'Sesudah itu raja menyuruh orang mengumpulkan semua tua-tua Yehuda dan Yerusalem.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 2, 'Kemudian pergilah raja ke rumah TUHAN dan bersama-sama dia semua orang Yehuda dan semua penduduk Yerusalem, para imam, para nabi dan seluruh orang awam, dari yang kecil sampai yang besar. Dengan didengar mereka ia membacakan segala perkataan dari kitab perjanjian yang ditemukan di rumah TUHAN itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 3, 'Sesudah itu berdirilah raja dekat tiang dan diadakannyalah perjanjian di hadapan TUHAN untuk hidup dengan mengikuti TUHAN, dan tetap menuruti perintah-perintah-Nya, peraturan-peraturan-Nya dan ketetapan-ketetapan-Nya dengan segenap hati dan dengan segenap jiwa dan untuk menepati perkataan perjanjian yang tertulis dalam kitab itu. Dan seluruh rakyat turut mendukung perjanjian itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 4, 'Raja memberi perintah kepada imam besar Hilkia dan kepada para imam tingkat dua dan kepada para penjaga pintu untuk mengeluarkan dari bait TUHAN segala perkakas yang telah dibuat untuk Baal dan Asyera dan untuk segala tentara langit, lalu dibakarnyalah semuanya itu di luar kota Yerusalem di padang-padang Kidron, dan diangkutnyalah abunya ke Betel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 5, 'Ia memberhentikan para imam dewa asing yang telah diangkat oleh raja-raja Yehuda untuk membakar korban di bukit pengorbanan di kota-kota Yehuda dan di sekitar Yerusalem, juga orang-orang yang membakar korban untuk Baal, untuk dewa matahari, untuk dewa bulan, untuk rasi-rasi bintang dan untuk segenap tentara langit.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 6, 'Dibawanyalah tiang-tiang berhala dari rumah TUHAN ke luar kota Yerusalem, ke sungai Kidron, lalu dibakarnya di situ dan ditumbuknya halus-halus menjadi abu, kemudian dicampakkannyalah abunya ke atas kuburan rakyat jelata.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 7, 'Ia merobohkan petak-petak pelacuran bakti yang ada di rumah TUHAN, tempat orang-orang perempuan bertenun sarung untuk Asyera.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 8, 'Disuruhnyalah datang semua imam dari kota-kota Yehuda, lalu ia menajiskan bukit-bukit pengorbanan, tempat para imam itu membakar korban, dari Geba sampai Bersyeba; dirobohkannya pula bukit-bukit pengorbanan di pintu-pintu gerbang yang ada dekat lobang pintu gerbang Yosua, penguasa kota itu, yang ada pada sebelah kiri kalau orang memasuki pintu gerbang kota itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 9, 'Tetapi para imam bukit-bukit pengorbanan itu tidak boleh naik ke mezbah TUHAN di Yerusalem, hanya mereka boleh memakan roti yang tidak beragi di tengah-tengah saudara-saudara mereka.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 10, 'Ia menajiskan juga Tofet yang ada di lembah Ben-Hinom, supaya jangan orang mempersembahkan anak-anaknya sebagai korban dalam api untuk dewa Molokh.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 11, 'Dibuangnyalah kuda-kuda yang ditaruh oleh raja-raja Yehuda untuk dewa matahari di pintu masuk ke rumah TUHAN, dekat bilik Natan-Melekh, pegawai istana, yang tinggal di gedung samping; juga kereta-kereta dewa matahari dibakarnya dengan api.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 12, 'Mezbah-mezbah, yang ada di atas sotoh, tempat peranginan Ahas, yang dibuat oleh raja-raja Yehuda, dan mezbah-mezbah, yang dibuat Manasye di kedua pelataran rumah TUHAN, dirobohkan oleh raja, dan diremukkan di sana, lalu dicampakkannya abunya ke sungai Kidron.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 13, 'Bukit-bukit pengorbanan yang ada di sebelah timur Yerusalem di sebelah selatan bukit Kebusukan dan yang didirikan oleh Salomo, raja Israel, untuk Asytoret, dewa kejijikan sembahan orang Sidon, dan untuk Kamos, dewa kejijikan sembahan Moab, dan untuk Milkom, dewa kekejian sembahan orang Amon, dinajiskan oleh raja.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 14, 'Ia memecahkan tugu-tugu berhala dan menebang tiang-tiang berhala, lalu ditimbuninya tempat-tempat itu penuh dengan tulang-tulang manusia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 15, 'Juga mezbah yang ada di Betel, bukit pengorbanan yang dibuat oleh Yerobeam bin Nebat yang mengakibatkan orang Israel berdosa, mezbah dan bukit pengorbanan itupun dirobohkannya dan batu-batunya dipecahkannya, lalu ditumbuknya halus-halus menjadi abu, dan dibakarnyalah tiang berhala.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 16, 'Dan ketika Yosia berpaling, dilihatnyalah kuburan-kuburan yang ada di gunung di sana, lalu menyuruh orang mengambil tulang-tulang dari kuburan-kuburan itu, membakarnya di atas mezbah dan menajiskannya, sesuai dengan firman TUHAN yang telah diserukan oleh abdi Allah yang telah menyerukan hal-hal ini.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 17, 'Ia berkata: "Apakah tanda keramat yang kulihat ini?" Lalu orang-orang di kota itu menjawab dia: "Itulah kuburan abdi Allah yang sudah datang dari Yehuda dan yang telah menyerukan segala hal yang telah kaulakukan terhadap mezbah Betel ini!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 18, 'Lalu katanya: "Biarkanlah itu, janganlah ada orang yang menjamah tulang-tulangnya!" Jadi mereka tidak mengganggu tulang-tulangnya dan tulang-tulang nabi yang telah datang dari Samaria itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 19, 'Juga segala kuil di bukit-bukit pengorbanan yang di kota-kota Samaria yang dibuat oleh raja-raja Israel untuk menimbulkan sakit hati TUHAN, dijauhkan oleh Yosia dan dalam hal ini ia bertindak tepat seperti tindakannya di Betel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 20, 'Ia menyembelih di atas mezbah-mezbah itu semua imam bukit-bukit pengorbanan yang ada di sana dan dibakarnya tulang-tulang manusia di atasnya, lalu pulanglah ia ke Yerusalem.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 21, 'Kemudian raja memberi perintah kepada seluruh bangsa itu: "Rayakanlah Paskah bagi TUHAN, Allahmu, seperti yang tertulis dalam kitab perjanjian ini!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 22, 'Sebab tidak pernah lagi dirayakan Paskah seperti itu sejak zaman para hakim yang memerintah atas Israel dan sepanjang zaman raja-raja Israel dan raja-raja Yehuda.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 23, 'Tetapi barulah dalam tahun kedelapan belas zaman raja Yosia Paskah ini dirayakan bagi TUHAN di Yerusalem.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 24, 'Para pemanggil arwah, dan para pemanggil roh peramal, juga terafim, berhala-berhala dan segala dewa kejijikan yang terlihat di tanah Yehuda dan di Yerusalem, dihapuskan oleh Yosia dengan maksud menepati perkataan Taurat yang tertulis dalam kitab yang telah didapati oleh imam Hilkia di rumah TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 25, 'Sebelum dia tidak ada raja seperti dia yang berbalik kepada TUHAN dengan segenap hatinya, dengan segenap jiwanya dan dengan segenap kekuatannya, sesuai dengan segala Taurat Musa; dan sesudah dia tidak ada bangkit lagi yang seperti dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 26, 'Tetapi TUHAN tidak beralih dari murka-Nya yang sangat bernyala-nyala itu yang telah bangkit terhadap Yehuda oleh karena segala sakit hati-Nya yang ditimbulkan Manasye.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 27, 'Lalu berfirmanlah TUHAN: "Juga orang Yehuda akan Kujauhkan dari hadapan-Ku seperti Aku menjauhkan orang Israel, dan Aku akan membuang kota yang Kupilih ini, yakni Yerusalem, dan rumah ini, walaupun Aku telah berfirman tentangnya: Nama-Ku akan tinggal di sana!"', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 28, 'Selebihnya dari riwayat Yosia dan segala yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 29, 'Dalam zamannya itu majulah Firaun Nekho, raja Mesir, melawan raja Asyur di tepi sungai Efrat; raja Yosia pergi menghadapi dia; tetapi Firaun membunuhnya di Megido, segera sesudah ia melihatnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 30, 'Pegawai-pegawainya mengangkut mayatnya dengan kereta dari Megido dan membawanya ke Yerusalem, kemudian mereka menguburkannya dalam kuburnya sendiri. Maka rakyat negeri itu menjemput Yoahas, anak Yosia, mengurapi dia dan mengangkat dia menjadi raja menggantikan ayahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 31, 'Yoahas berumur dua puluh tiga tahun pada waktu ia menjadi raja dan tiga bulan lamanya ia memerintah di Yerusalem. Nama ibunya ialah Hamutal binti Yeremia, dari Libna.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 32, 'Ia melakukan apa yang jahat di mata TUHAN tepat seperti yang dilakukan oleh nenek moyangnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 33, 'Firaun Nekho mengurung dia di Ribla, di tanah Hamat, supaya jangan ia memerintah di Yerusalem; lagi Firaun membebankan kepada negeri itu denda sebesar seratus talenta perak dan sepuluh talenta emas.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 34, 'Firaun Nekho mengangkat Elyakim, anak Yosia, menjadi raja menggantikan Yosia, ayahnya, dan menukar namanya dengan Yoyakim. Tetapi Yoahas dibawanya; Yoahas tiba di Mesir dan mati di sana.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 35, 'Yoyakim memberi emas dan perak itu kepada Firaun, tetapi ia menarik pajak dari negeri supaya dapat memberi uang itu, sesuai dengan titah Firaun. Ia menagih emas dan perak itu dari rakyat negeri, dari setiap orang menurut jumlah ketetapan pajaknya, untuk memberikannya kepada Firaun Nekho.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 36, 'Yoyakim berumur dua puluh lima tahun pada waktu ia menjadi raja dan sebelas tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Zebuda binti Pedaya, dari Ruma.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 23, 37, 'Ia melakukan apa yang jahat di mata TUHAN tepat seperti yang dilakukan oleh nenek moyangnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 1, 'Dalam zamannya majulah berperang Nebukadnezar, raja Babel, lalu Yoyakim menjadi takluk kepadanya tiga tahun lamanya; tetapi kemudian Yoyakim berbalik dan memberontak terhadap dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 2, 'TUHAN menyuruh gerombolan-gerombolan Kasdim, gerombolan-gerombolan Aram, gerombolan-gerombolan Moab dan gerombolan-gerombolan bani Amon melawan Yoyakim; Ia menyuruh mereka melawan Yehuda untuk membinasakannya sesuai dengan firman TUHAN yang diucapkan-Nya dengan perantaraan para hamba-Nya, yaitu para nabi.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 3, 'Sungguh, hal itu terjadi kepada Yehuda sesuai dengan titah TUHAN untuk menjauhkan mereka dari hadapan-Nya oleh karena dosa-dosa Manasye, setimpal dengan segala yang dilakukannya,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 4, 'dan juga oleh karena darah orang yang tidak bersalah yang telah ditumpahkannya, sebab ia telah membuat Yerusalem penuh dengan darah orang yang tidak bersalah, dan TUHAN tidak mau mengampuninya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 5, 'Selebihnya dari riwayat Yoyakim dan segala yang dilakukannya, bukankah semuanya itu tertulis dalam kitab sejarah raja-raja Yehuda?', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 6, 'Kemudian Yoyakim mendapat perhentian bersama-sama dengan nenek moyangnya, maka Yoyakhin, anaknya, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 7, 'Raja Mesir tidak lagi keluar berperang dari negerinya, sebab raja Babel telah merebut segala yang termasuk wilayah raja Mesir mulai dari sungai Mesir sampai ke sungai Efrat.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 8, 'Yoyakhin berumur delapan belas tahun pada waktu ia menjadi raja dan tiga bulan lamanya ia memerintah di Yerusalem. Nama ibunya ialah Nehusta binti Elnatan, dari Yerusalem.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 9, 'Ia melakukan apa yang jahat di mata TUHAN tepat seperti yang dilakukan ayahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 10, 'Pada waktu itu majulah orang-orang Nebukadnezar, raja Babel, menyerang Yerusalem dan kota itu dikepung.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 11, 'Juga Nebukadnezar, raja Babel, datang menyerang kota itu, sedang orang-orangnya mengepungnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 12, 'Lalu keluarlah Yoyakhin, raja Yehuda, mendapatkan raja Babel, ia sendiri, ibunya, pegawai-pegawainya, para pembesarnya dan pegawai-pegawai istananya. Raja Babel menangkap dia pada tahun yang kedelapan dari pemerintahannya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 13, 'Ia mengeluarkan dari sana segala barang perbendaharaan rumah TUHAN dan barang-barang perbendaharaan istana raja; juga dikeratnya emas dari segala perkakas emas yang dibuat oleh Salomo, raja Israel, di bait TUHAN seperti yang telah difirmankan TUHAN.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 14, 'Ia mengangkut seluruh penduduk Yerusalem ke dalam pembuangan, semua panglima dan semua pahlawan yang gagah perkasa, sepuluh ribu orang tawanan, juga semua tukang dan pandai besi; tidak ada yang ditinggalkan kecuali orang-orang lemah dari rakyat negeri.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 15, 'Ia mengangkut Yoyakhin ke dalam pembuangan ke Babel, juga ibunda raja, isteri-isteri raja, pegawai-pegawai istananya dan orang-orang berkuasa di negeri itu dibawanya sebagai orang buangan dari Yerusalem ke Babel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 16, 'Semua orang yang gagah perkasa, tujuh ribu orang banyaknya, para tukang dan para pandai besi, seribu orang banyaknya, sekalian pahlawan yang sanggup berperang, dibawa oleh raja Babel sebagai orang buangan ke Babel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 17, 'Kemudian raja Babel mengangkat Matanya, paman Yoyakhin, menjadi raja menggantikan dia dan menukar namanya menjadi Zedekia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 18, 'Zedekia berumur dua puluh satu tahun pada waktu ia menjadi raja dan sebelas tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Hamutal binti Yeremia, dari Libna.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 19, 'Ia melakukan apa yang jahat di mata TUHAN tepat seperti yang dilakukan Yoyakim.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 24, 20, 'Sebab oleh karena murka Tuhanlah terjadi hal itu terhadap Yerusalem dan Yehuda, yakni bahwa Ia sampai membuang mereka dari hadapan-Nya. Zedekia memberontak terhadap raja Babel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 1, 'Maka pada tahun kesembilan dari pemerintahannya, dalam bulan yang kesepuluh, pada tanggal sepuluh bulan itu, datanglah Nebukadnezar, raja Babel, dengan segala tentaranya menyerang Yerusalem. Ia berkemah mengepungnya dan mendirikan tembok pengepungan sekelilingnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 2, 'Demikianlah kota itu terkepung sampai tahun yang kesebelas zaman raja Zedekia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 3, 'Pada tanggal sembilan bulan yang keempat, ketika kelaparan sudah merajalela di kota itu dan tidak ada lagi makanan pada rakyat negeri itu,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 4, 'maka dibelah oranglah tembok kota itu dan semua tentara melarikan diri malam-malam melalui pintu gerbang antara kedua tembok yang ada di dekat taman raja, sekalipun orang Kasdim mengepung kota itu sekeliling. Mereka lari menuju ke Araba-Yordan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 5, 'Tetapi tentara Kasdim mengejar raja dari belakang dan mencapai dia di dataran Yerikho; segala tentaranya telah berserak-serak meninggalkan dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 6, 'Mereka menangkap raja dan membawa dia kepada raja Babel di Ribla, yang menjatuhkan hukuman atas dia.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 7, 'Orang menyembelih anak-anak Zedekia di depan matanya, kemudian dibutakannyalah mata Zedekia, lalu dia dibelenggu dengan rantai tembaga dan dibawa ke Babel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 8, 'Dalam bulan yang kelima pada tanggal tujuh bulan itu?itulah tahun kesembilan belas zaman raja Nebukadnezar, raja Babel?datanglah Nebuzaradan, kepala pasukan pengawal, pegawai raja Babel, ke Yerusalem.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 9, 'Ia membakar rumah TUHAN, rumah raja dan semua rumah di Yerusalem; semua rumah orang-orang besar dibakarnya dengan api.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 10, 'Tembok sekeliling kota Yerusalem dirobohkan oleh semua tentara Kasdim yang ada bersama-sama dengan kepala pasukan pengawal itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 11, 'Sisa-sisa rakyat yang masih tinggal di kota itu dan para pembelot yang menyeberang ke pihak raja Babel dan sisa-sisa khalayak ramai diangkut ke dalam pembuangan oleh Nebuzaradan, kepala pasukan pengawal itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 12, 'Hanya beberapa orang miskin dari negeri itu ditinggalkan oleh kepala pasukan pengawal itu untuk menjadi tukang-tukang kebun anggur dan peladang-peladang.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 13, 'Juga tiang-tiang tembaga yang ada di rumah TUHAN dan kereta penopang dan "laut" tembaga yang ada di rumah TUHAN dipecahkan oleh orang Kasdim dan tembaganya diangkut mereka ke Babel.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 14, 'Kuali-kuali, penyodok-penyodok, pisau-pisau dan cawan-cawan dan segala perkakas tembaga yang dipakai untuk menyelenggarakan kebaktian, diambil mereka,', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 15, 'juga perbaraan-perbaraan dan bokor-bokor penyiraman, baik segala yang dari emas maupun segala yang dari perak, diambil oleh kepala pasukan pengawal itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 16, 'Adapun kedua tiang, "laut" yang satu itu, kereta penopang yang dibuat oleh Salomo untuk rumah TUHAN, tiada tertimbang tembaga segala perkakas ini.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 17, 'Delapan belas hasta tingginya tiang yang satu, dan di atasnya ada ganja dari tembaga; tinggi ganja itu tiga hasta dan jala-jala dan buah-buah delima ada di atas ganja itu sekeliling, semuanya itu tembaga. Dan seperti itu juga tiang yang kedua, disertai jala-jala.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 18, 'Lalu kepala pasukan pengawal itu menangkap Seraya, imam kepala, dan Zefanya, imam tingkat dua dan ketiga orang penjaga pintu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 19, 'Dari kota itu ditangkapnya seorang pegawai istana yang diangkat mengepalai tentara, dan lima orang pelayan pribadi raja yang terdapat di kota itu, dan panitera panglima tentara yang mengerahkan rakyat negeri menjadi tentara, dan enam puluh orang dari rakyat negeri yang terdapat di kota itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 20, 'Nebuzaradan, kepala pasukan pengawal, menangkap mereka dan membawa mereka kepada raja Babel, di Ribla.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 21, 'Lalu raja Babel menyuruh membunuh mereka di Ribla, di tanah Hamat. Demikianlah orang Yehuda diangkut ke dalam pembuangan dari tanahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 22, 'Tentang rakyat yang masih tinggal di tanah Yehuda yang ditinggalkan oleh Nebukadnezar, raja Babel, diangkatnyalah atas mereka Gedalya bin Ahikam bin Safan.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 23, 'Ketika semua panglima tentara dengan orang-orangnya mendengar bahwa raja Babel telah mengangkat Gedalya, maka pergilah mereka kepada Gedalya, ke Mizpa, yaitu Ismael bin Netanya, Yohanan bin Kareah, Seraya bin Tanhumet, orang Netofa itu, dan Yaazanya, anak seorang Maakha, bersama dengan anak buahnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 24, 'Lalu bersumpahlah Gedalya kepada mereka dan anak buah mereka, katanya kepada mereka: "Janganlah kamu takut terhadap pegawai-pegawai orang Kasdim itu; tinggallah di negeri ini dan takluklah kepada raja Babel, maka keadaanmu akan menjadi baik."', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 25, 'Tetapi dalam bulan yang ketujuh datanglah Ismael bin Netanya bin Elisama, seorang yang asalnya dari keturunan raja, dan sepuluh orang bersama-sama dengan dia; mereka membunuh Gedalya dan orang-orang Yehuda dan orang-orang Kasdim yang ada bersama-sama dengan dia di Mizpa.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 26, 'Maka bangkitlah seluruh rakyat, dari yang kecil sampai yang besar, serta panglima-panglima tentara, lalu larilah mereka ke Mesir, sebab mereka takut terhadap orang Kasdim itu.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 27, 'Kemudian dalam tahun ketiga puluh tujuh sesudah Yoyakhin, raja Yehuda dibuang, dalam bulan yang kedua belas, pada tanggal dua puluh tujuh bulan itu, maka Ewil-Merodakh, raja Babel, dalam tahun ia menjadi raja, menunjukkan belas kasihannya kepada Yoyakhin, raja Yehuda, dengan melepaskannya dari penjara.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 28, 'Ewil-Merodakh berbicara baik-baik dengan dia dan memberi kedudukan kepadanya lebih tinggi dari pada kedudukan raja-raja yang bersama-sama dengan dia di Babel;', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 29, 'ia boleh mengganti pakaian penjaranya dan boleh selalu makan roti di hadapan raja selama hidupnya.', 'id', 'TB'),
  ('12', '2raj', '2 Raja-Raja', 25, 30, 'Dan tentang belanjanya, raja selalu memberikannya kepadanya, sekadar yang perlu tiap-tiap hari, selama hidupnya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 1, 'Adam, Set, Enos,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 2, 'Kenan, Mahalaleel, Yared,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 3, 'Henokh, Metusalah, Lamekh,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 4, 'Nuh, Sem, Ham dan Yafet.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 5, 'Keturunan Yafet ialah Gomer, Magog, Madai, Yawan, Tubal, Mesekh dan Tiras.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 6, 'Keturunan Gomer ialah Askenas, Difat dan Togarma.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 7, 'Keturunan Yawan ialah Elisa, Tarsis, orang Kitim dan orang Rodanim.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 8, 'Keturunan Ham ialah Kush, Misraim, Put dan Kanaan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 9, 'Keturunan Kush ialah Seba, Hawila, Sabta, Raema dan Sabtekha; keturunan Raema ialah Syeba dan Dedan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 10, 'Kush memperanakkan Nimrod; dialah orang yang mula-mula sekali berkuasa di bumi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 11, 'Misraim memperanakkan orang Ludim, orang Anamim, orang Lehabim, orang Naftuhim,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 12, 'orang Patrusim, orang Kasluhim?dari mereka inilah berasal orang Filistin?dan orang Kaftorim.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 13, 'Kanaan memperanakkan Sidon, anak sulungnya dan Het,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 14, 'serta orang Yebusi, orang Amori, orang Girgasi,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 15, 'orang Hewi, orang Arki, orang Sini,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 16, 'orang Arwadi, orang Semari dan orang Hamati.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 17, 'Keturunan Sem ialah Elam, Asyur, Arpakhsad, Lud, Aram, Us, Hul, Geter dan Mesekh.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 18, 'Arpakhsad memperanakkan Selah, dan Selah memperanakkan Eber.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 19, 'Bagi Eber lahir dua anak laki-laki; nama yang seorang ialah Peleg, sebab dalam zamannya penduduk bumi terbagi, dan nama adiknya ialah Yoktan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 20, 'Yoktan memperanakkan Almodad, Selef, Hazar-Mawet, Yerah,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 21, 'Hadoram, Uzal, Dikla,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 22, 'Ebal, Abimael, Syeba,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 23, 'Ofir, Hawila dan Yobab; itulah semuanya anak-anak Yoktan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 24, 'Sem, Arpakhsad, Selah,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 25, 'Eber, Peleg, Rehu,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 26, 'Serug, Nahor, Terah,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 27, 'Abram, itulah Abraham.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 28, 'Anak-anak Abraham ialah Ishak dan Ismael.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 29, 'Inilah keturunan mereka: anak sulung Ismael ialah Nebayot, lalu Kedar, Adbeel, Mibsam,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 30, 'Misyma, Duma, Masa, Hadad, Tema,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 31, 'Yetur, Nafish dan Kedma; mereka itulah anak-anak Ismael.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 32, 'Keturunan Ketura, gundik Abraham: perempuan itu melahirkan Zimran, Yoksan, Medan, Midian, Isybak dan Suah. Anak-anak Yoksan ialah Syeba dan Dedan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 33, 'Anak-anak Midian ialah: Efa, Efer, Hanokh, Abida dan Eldaa. Itulah semuanya keturunan Ketura.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 34, 'Abraham memperanakkan Ishak. Anak-anak Ishak ialah Esau dan Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 35, 'Anak-anak Esau ialah Elifas, Rehuel, Yeush, Yaelam dan Korah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 36, 'Anak-anak Elifas ialah Teman, Omar, Zefi, Gaetam, Kenas, Timna dan Amalek.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 37, 'Anak-anak Rehuel ialah Nahat, Zerah, Syama dan Miza.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 38, 'Anak-anak Seir ialah Lotan, Syobal, Zibeon, Ana, Disyon, Ezer dan Disyan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 39, 'Anak-anak Lotan ialah Hori dan Homam; adik perempuan Lotan ialah Timna.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 40, 'Anak-anak Syobal ialah Alyan, Manahat, Ebal, Syefi dan Onam; anak-anak Zibeon ialah Aya dan Ana.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 41, 'Keturunan Ana ialah Disyon; anak-anak Disyon ialah Hamran, Esyban, Yitran dan Keran.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 42, 'Anak-anak Ezer ialah Bilhan, Zaawan dan Yaakan. Anak-anak Disyan ialah Us dan Aran.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 43, 'Inilah raja-raja yang memerintah di tanah Edom, sebelum seorang raja dari orang Israel memerintah: Bela bin Beor, dan kotanya bernama Dinhaba.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 44, 'Setelah Bela mati, Yobab bin Zerah, dari Bozra, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 45, 'Setelah Yobab mati, Husyam, dari negeri orang Teman, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 46, 'Setelah Husyam mati, Hadad bin Bedad menjadi raja menggantikan dia; dialah yang memukul kalah orang Midian di daerah Moab, dan kotanya bernama Awit.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 47, 'Setelah Hadad mati, Samla, dari Masyreka menjadi raja menggantikan dia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 48, 'Setelah Samla mati, Saul, dari Rehobot-Sungai, menjadi raja menggantikan dia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 49, 'Setelah Saul mati, Baal-Hanan bin Akhbor menjadi raja menggantikan dia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 50, 'Setelah Baal-Hanan mati, Hadad menjadi raja menggantikan dia, dan kotanya bernama Pahi dan isterinya bernama Mehetabeel binti Matred binti Mezahab.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 51, 'Setelah Hadad mati, maka yang menjadi kepala-kepala kaum di Edom ialah kepala kaum Timna, kepala kaum Alya, kepala kaum Yetet,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 52, 'kepala kaum Oholibama, kepala kaum Ela, kepala kaum Pinon,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 53, 'kepala kaum Kenas, kepala kaum Teman, kepala kaum Mibzar,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 1, 54, 'kepala kaum Magdiel dan kepala kaum Iram. Itulah kepala-kepala kaum di Edom.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 1, 'Inilah anak-anak Israel: Ruben, Simeon, Lewi, Yehuda, Isakhar, Zebulon,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 2, 'Dan, Yusuf, Benyamin, Naftali, Gad dan Asyer.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 3, 'Anak-anak Yehuda ialah Er, Onan dan Syela, tiga orang, yang lahir bagi dia dari anak perempuan Syua perempuan Kanaan itu. Tetapi Er, anak sulung Yehuda itu, adalah jahat di mata TUHAN, maka Ia membunuhnya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 4, 'Tamar, menantu perempuan Yehuda, melahirkan baginya Peres dan Zerah. Semuanya anak-anak Yehuda ada lima orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 5, 'Anak-anak Peres ialah Hezron dan Hamul.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 6, 'Anak-anak Zerah ialah Zimri, Etan, Heman, Kalkol dan Dara. Semuanya lima orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 7, 'Keturunan Karmi ialah Ahar, yang mencelakakan orang Israel karena ia tidak taat dalam hal barang-barang yang dikhususkan itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 8, 'Keturunan Etan ialah Azarya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 9, 'Anak-anak yang lahir bagi Hezron ialah Yerahmeel, Ram dan Khelubai.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 10, 'Ram memperanakkan Aminadab, dan Aminadab memperanakkan Nahason, pemimpin bani Yehuda.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 11, 'Nahason memperanakkan Salma dan Salma memperanakkan Boas.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 12, 'Boas memperanakkan Obed dan Obed memperanakkan Isai.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 13, 'Isai memperanakkan Eliab, anak sulungnya, dan Abinadab, anak yang kedua, Simea, anak yang ketiga,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 14, 'Netaneel, anak yang keempat, Radai, anak yang kelima,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 15, 'Ozem, anak yang keenam, dan Daud, anak yang ketujuh;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 16, 'saudara-saudara perempuan mereka ialah Zeruya dan Abigail. Anak-anak Zeruya ialah Abisai, Yoab dan Asael, tiga orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 17, 'Abigail melahirkan Amasa dan ayah Amasa ialah Yeter, orang Ismael itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 18, 'Kaleb bin Hezron memperanakkan Yeriot dari Azuba, isterinya; dan inilah anak-anak perempuan itu: Yesyer, Sobab dan Ardon.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 19, 'Sesudah Azuba mati, Kaleb mengawini Efrat yang melahirkan Hur baginya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 20, 'Hur memperanakkan Uri dan Uri memperanakkan Bezaleel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 21, 'Sesudah itu Hezron menghampiri anak perempuan Makhir, bapa Gilead. Ia mengawini perempuan itu ketika ia berumur enam puluh tahun. Perempuan itu melahirkan Segub baginya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 22, 'Segub memperanakkan Yair yang mempunyai dua puluh tiga perkampungan di tanah Gilead.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 23, 'Tetapi Gesur dan Aram merebut Hawot-Yair dari pada mereka, juga Kenat dan tempat-tempat jajahannya, enam puluh perkampungan. Itulah semuanya keturunan Makhir, bapa Gilead.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 24, 'Sesudah Hezron mati, Kaleb menghampiri Efrata?dia adalah isteri Hezron, ayahnya?maka perempuan itu melahirkan baginya Asyhur, bapa Tekoa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 25, 'Anak-anak Yerahmeel, anak sulung Hezron, ialah Ram, anak sulung, Buna, Oren, Ozem dan Ahia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 26, 'Tetapi Yerahmeel mempunyai seorang isteri lain, bernama Atara; dialah ibu Onam.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 27, 'Anak-anak Ram, anak sulung Yerahmeel, ialah Maas, Yamin dan Eker.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 28, 'Anak-anak Onam ialah Samai dan Yada, dan anak-anak Samai ialah Nadab dan Abisur.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 29, 'Nama isteri Abisur ialah Abihail yang melahirkan Ahban dan Molid baginya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 30, 'Anak-anak Nadab ialah Seled dan Apaim; Seled mati dengan tidak mempunyai anak.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 31, 'Keturunan Apaim ialah Yisei, dan keturunan Yisei ialah Sesan, dan keturunan Sesan ialah Ahlai.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 32, 'Anak-anak Yada, adik Samai, ialah Yeter dan Yonatan; Yeter mati dengan tidak mempunyai anak.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 33, 'Anak-anak Yonatan ialah Pelet dan Zaza. Itulah keturunan Yerahmeel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 34, 'Sesan tidak mempunyai anak laki-laki, hanya anak-anak perempuan; tetapi Sesan mempunyai seorang budak laki-laki, orang Mesir, yang bernama Yarha.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 35, 'Jadi Sesan memberi anaknya kepada Yarha, budaknya itu, menjadi isteri, lalu perempuan itu melahirkan Atai baginya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 36, 'Atai memperanakkan Natan, dan Natan memperanakkan Zabad.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 37, 'Zabad memperanakkan Eflal, dan Eflal memperanakkan Obed.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 38, 'Obed memperanakkan Yehu, dan Yehu memperanakkan Azarya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 39, 'Azarya memperanakkan Heles, dan Heles memperanakkan Elasa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 40, 'Elasa memperanakkan Sismai, dan Sismai memperanakkan Salum.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 41, 'Salum memperanakkan Yekamya, dan Yekamya memperanakkan Elisama.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 42, 'Keturunan Kaleb, adik Yerahmeel, ialah Mesa, anak sulungnya, bapa Zif, dan anak-anak Maresa, bapa Hebron.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 43, 'Anak-anak Hebron ialah Korah, Tapuah, Rekem dan Sema.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 44, 'Sema memperanakkan Raham, bapa Yorkeam, dan Rekem memperanakkan Samai.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 45, 'Anak Samai ialah Maon, dan Maon ialah bapa Bet-Zur.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 46, 'Efa, gundik Kaleb, melahirkan Haran, Moza dan Gazes; Haran memperanakkan Gazes.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 47, 'Anak-anak Yohdai ialah Regem, Yotam, Gesan, Pelet, Efa dan Saaf.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 48, 'Gundik Kaleb, yakni Maakha, melahirkan Seber dan Tirhana.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 49, 'Perempuan itu melahirkan juga Saaf, bapa Madmana, dan Sewa, bapa Makhbena dan bapa Gibea; anak perempuan Kaleb ialah Akhsa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 50, 'Itulah keturunan Kaleb. Anak-anak Hur, anak sulung Efrata, ialah Sobal, bapa Kiryat-Yearim,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 51, 'Salma, bapa Betlehem dan Haref, bapa Bet-Gader.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 52, 'Sobal, bapa Kiryat-Yearim, mempunyai keturunan, yakni Haroe dan setengah orang Menuhot.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 53, 'Dan kaum-kaum Kiryat-Yearim ialah orang Yetri, orang Puti, orang Sumati dan orang Misrai; dari mereka inilah berasal orang Zora dan orang Esytaol.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 54, 'Keturunan Salma ialah Betlehem, orang Netofa, Atarot-Bet-Yoab dan setengah orang Manahti, yakni orang Zori.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 2, 55, 'Dan kaum-kaum para ahli surat, yang diam di Yabes, ialah orang Tirati, orang Simati, dan orang Sukhati. Mereka itulah orang Keni keturunan Hamat bapa keluarga Rekhab.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 1, 'Inilah anak-anak Daud yang lahir bagi dia di Hebron; anak sulung ialah Amnon, dari Ahinoam, perempuan Yizreel; anak yang kedua ialah Daniel, dari Abigail, perempuan Karmel;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 2, 'anak yang ketiga ialah Absalom, anak Maakha, yakni anak perempuan Talmai, raja Gesur; anak yang keempat ialah Adonia, anak Hagit;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 3, 'anak yang kelima ialah Sefaca, dari Abital; anak yang keenam ialah Yitream, dari Egla, isterinya itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 4, 'Enam orang lahir bagi dia di Hebron, di mana ia memerintah tujuh tahun enam bulan lamanya; dan tiga puluh tiga tahun lamanya ia memerintah di Yerusalem.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 5, 'Inilah yang lahir bagi dia di Yerusalem: Simea, Sobab, Natan dan Salomo, empat orang dari Batsyua binti Amiel,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 6, 'lalu Yibhar, Elisama, Elifelet,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 7, 'Nogah, Nefeg, Yafia,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 8, 'Elisama, Elyada dan Elifelet, sembilan orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 9, 'Semuanya itu anak-anak Daud, belum terhitung anak-anak dari gundik-gundik. Tamar ialah saudara perempuan mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 10, 'Keturunan Salomo ialah Rehabeam; anak orang ini ialah Abia; anak orang ini ialah Asa; anak orang ini ialah Yosafat;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 11, 'anak orang ini ialah Yoram; anak orang ini ialah Ahazia; anak orang ini ialah Yoas;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 12, 'anak orang ini ialah Amazia; anak orang ini ialah Azarya; anak orang ini ialah Yotam;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 13, 'anak orang ini ialah Ahas; anak orang ini ialah Hizkia; anak orang ini ialah Manasye;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 14, 'anak orang ini ialah Amon; anak orang ini ialah Yosia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 15, 'Anak-anak Yosia: anak sulung ialah Yohanan, anak yang kedua ialah Yoyakim, anak yang ketiga ialah Zedekia dan anak yang keempat ialah Salum.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 16, 'Keturunan Yoyakim ialah Yekhonya, anaknya itu, dan anak orang ini ialah Zedekia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 17, 'Anak-anak Yekhonya, orang kurungan itu, ialah Sealtiel, anaknya,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 18, 'lalu Malkhiram, Pedaya, Syenasar, Yekamya, Hosama dan Nedabya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 19, 'Anak-anak Pedaya ialah Zerubabel dan Simei, dan anak-anak Zerubabel ialah Mesulam dan Hananya; Selomit ialah saudara perempuan mereka;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 20, 'lalu Hasuba, Ohel, Berekhya, Hasaja dan Yusab-Hesed, lima orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 21, 'Anak-anak Hananya ialah Pelaca dan Yesaya; anak orang ini ialah Refaya; anak orang ini ialah Arnan; anak orang ini ialah Obaja, dan anak orang ini ialah Sekhanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 22, 'Anak-anak Sekhanya ialah Semaya, dan anak-anak Semaya ialah Hatus, Yigal, Bariah, Nearya dan Safat, enam orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 23, 'Anak-anak Nearya ialah Elyoenai, Hizkia, dan Azrikam, tiga orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 3, 24, 'Anak-anak Elyoenai ialah Hodawya, Elyasib, Pelaya, Akub, Yohanan, Delaya dan Anani, tujuh orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 1, 'Anak-anak Yehuda ialah Peres, Hezron, Karmi, Hur dan Syobal.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 2, 'Reaya, anak Syobal, memperanakkan Yahat, dan Yahat memperanakkan Ahumai dan Lahad. Itulah kaum-kaum orang Zora.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 3, 'Inilah anak-anak Etam: Yizreel, Isma dan Idbas; nama saudara perempuan mereka ialah Hazelelponi;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 4, 'lalu Pnuel, bapa Gedor, dan Ezer, bapa Husa. Itulah keturunan Hur, anak sulung Efrata, bapa Betlehem.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 5, 'Asyur, bapa Tekoa, mempunyai dua isteri, yakni Hela dan Naara.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 6, 'Naara melahirkan baginya Ahuzam, Hefer, Temeni dan orang Ahastari. Itulah anak-anak Naara.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 7, 'Anak-anak Hela ialah Zeret, Yezohar dan Etnan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 8, 'Kos memperanakkan Anub, Hazobeba dan kaum-kaum Aharhel bin Harum.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 9, 'Yabes lebih dimuliakan dari pada saudara-saudaranya; nama Yabes itu diberi ibunya kepadanya sebab katanya: "Aku telah melahirkan dia dengan kesakitan."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 10, 'Yabes berseru kepada Allah Israel, katanya: "Kiranya Engkau memberkati aku berlimpah-limpah dan memperluas daerahku, dan kiranya tangan-Mu menyertai aku, dan melindungi aku dari pada malapetaka, sehingga kesakitan tidak menimpa aku!" Dan Allah mengabulkan permintaannya itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 11, 'Kelub, saudara Suha, memperanakkan Mehir, dialah ayah Eston;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 12, 'dan Eston memperanakkan Bet-Rafa, Paseah dan Tehina, bapa Ir-Nahas. Itulah orang-orang Rekha.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 13, 'Anak-anak Kenas ialah Otniel dan Seraya; dan anak-anak Otniel ialah Hatat dan Meonotai;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 14, 'dan Meonotai memperanakkan Ofra. Seraya memperanakkan Yoab, bapa Lembah Tukang-tukang, karena mereka adalah tukang-tukang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 15, 'Anak-anak Kaleb bin Yefune ialah Iru, Ela dan Naam; dan keturunan Ela ialah Kenas.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 16, 'Anak-anak Yehaleleel ialah Zif, Zifa, Tireya dan Asareel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 17, 'Anak-anak Ezra ialah Yeter, Mered, Efer dan Yalon. Itulah anak-anak Bica, puteri Firaun yang telah dikawini Mered. Perempuan ini melahirkan Miryam, Samai dan Yisbah, bapa Estemoa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 18, 'Isteri Mered, perempuan Yehuda itu, melahirkan Yered, bapa Gedor, dan Heber, bapa Sokho, dan Yekutiel, bapa Zanoah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 19, 'Anak-anak isteri Hodia, saudara perempuan Naham, ialah Abu Kehila, orang Garmi itu, dan Estemoa, orang Maakha itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 20, 'Anak-anak Simon ialah Amnon, Rina, Benhanan dan Tilon. Anak-anak Yisei ialah Zohet dan Ben-Zohet.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 21, 'Keturunan Sela, anak Yehuda, ialah Er, bapa Lekha, dan Lada, bapa Maresa, dan kaum-kaum para pengusaha kain lenan halus di Bet-Asybea,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 22, 'lalu Yokim dan orang-orang Kozeba, lagi Yoas dan Saraf yang menguasai Moab dan kemudian pulang ke Betlehem; ?riwayat-riwayat ini tua.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 23, 'Mereka ini adalah tukang-tukang periuk yang diam di Netaim dan Gedera; mereka diam di sana dan bekerja untuk raja.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 24, 'Anak-anak Simeon ialah Nemuel, Yamin, Yarib, Zerah dan Saul;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 25, 'anak orang ini ialah Salum; anak orang ini ialah Mibsam; anak orang ini ialah Misma.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 26, 'Keturunan Misma ialah Hamuel, anaknya; anak orang ini ialah Zakur; anak orang ini ialah Simei.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 27, 'Simei mempunyai enam belas orang anak laki-laki dan enam orang anak perempuan; tetapi saudara-saudaranya tidak mempunyai banyak anak; seluruh kaum mereka tidak bertambah banyak seperti bani Yehuda.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 28, 'Mereka diam di Bersyeba, Molada, Hazar-Sual,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 29, 'Bilha, Ezem, Tolad,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 30, 'Betuel, Horma, Ziklag,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 31, 'Bet-Markabot, Hazar-Susim, Bet-Biri dan di Saaraim. Itulah kota-kota mereka sampai Daud menjadi raja.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 32, 'Dan desa-desanya ialah Etam, Ain, Rimon, Tokhen dan Asan, lima perkampungan;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 33, 'juga segala desanya yang di sekitar perkampungan-perkampungan itu sampai ke Baal. Itulah tempat-tempat kediaman mereka dan mereka mempunyai silsilahnya sendiri.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 34, 'Dan Mesobab, Yamlekh, Yosa bin Amazia,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 35, 'Yoel, Yehu bin Yosibya bin Seraya bin Asiel,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 36, 'Elyoenai, Yaakoba, Yesohaya, Asaya, Adiel, Yesimiel, Benaya,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 37, 'Ziza bin Sifei bin Alon bin Yedaya bin Simri bin Semaya?', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 38, 'orang-orang ini yang disebutkan dengan nama-namanya adalah pemimpin-pemimpin di antara kaum-kaum mereka. Keluarga-keluarga mereka makin bertambah banyak.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 39, 'Oleh sebab itu mereka pindah ke arah Gedor sampai ke sebelah timur lembah untuk mencari padang rumput bagi kambing domba mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 40, 'Mereka menemui padang rumput yang gemuk dan baik; negeri itu luas, aman dan sentosa; orang-orang yang diam di sana sebelum mereka berasal dari Ham.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 41, 'Orang-orang yang namanya tertulis ini datang dalam zaman Hizkia, raja Yehuda, dan memusnahkan kemah-kemah orang Ham dan orang Meunim yang terdapat di sana dan menumpas mereka; demikianlah sampai hari ini. Kemudian mereka menduduki tempat orang-orang itu, sebab di sana ada padang rumput bagi kambing domba mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 42, 'Dan sebagian dari mereka, dari bani Simeon, sebanyak lima ratus orang, pindah ke pegunungan Seir. Sebagai kepala mereka ialah Pelaca, Nearya, Refaya dan Uziel, anak-anak Yisei.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 4, 43, 'Mereka membinasakan sisa orang Amalek yang telah meluputkan diri. Lalu mereka diam di sana sampai hari ini.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 1, 'Anak-anak Ruben, anak sulung Israel. Dialah anak sulung, tetapi karena ia telah melanggar kesucian petiduran ayahnya, maka hak kesulungannya diberikan kepada keturunan dari Yusuf, anak Israel juga, sekalipun tidak tercatat dalam silsilah sebagai anak sulung.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 2, 'Memang Yehudalah yang melebihi saudara-saudaranya, bahkan salah seorang dari antaranya menjadi raja, tetapi hak sulung itu ada pada Yusuf.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 3, 'Anak-anak Ruben, anak sulung Israel, ialah Henokh, Palu, Hezron dan Karmi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 4, 'Keturunan Yoel ialah Semaya, anaknya; anak orang ini ialah Gog, anak orang ini ialah Simei;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 5, 'anak orang ini ialah Mikha; anak orang ini ialah Reaya; anak orang ini ialah Baal;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 6, 'anak orang ini ialah Beera yang diangkut ke dalam pembuangan oleh Tilgat-Pilneser, raja Asyur; dialah pemimpin orang Ruben.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 7, 'Saudara-saudaranya menurut kaum-kaumnya, seperti tercatat dalam silsilah menurut keturunan mereka, ialah Yeiel, kepala, lalu Zakharia,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 8, 'dan Bela bin Azas bin Sema bin Yoel; dialah yang diam di Aroer dan wilayahnya sampai ke Nebo dan Baal-Meon.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 9, 'Dan ke sebelah timur wilayahnya sampai ke pinggir padang gurun yang terbentang mulai dari sungai Efrat, sebab ternak mereka telah bertambah banyak di tanah Gilead.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 10, 'Di zaman Saul mereka melakukan perang melawan orang Hagri; setelah orang-orang ini jatuh ke dalam tangan mereka, maka mereka diam di kemah-kemah orang-orang itu di seluruh sisi timur Gilead.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 11, 'Bani Gad diam berbatasan dengan mereka di tanah Basan sampai Salkha.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 12, 'Yoel adalah kepala dan Safam orang kedua; juga Yaenai dan Safat diam di Basan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 13, 'Saudara-saudara mereka menurut puak-puak mereka ialah Mikhael, Mesulam, Syeba, Yorai, Yakan, Ziya dan Eber, tujuh orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 14, 'Itulah anak-anak Abihail bin Huri bin Yaroah bin Gilead bin Mikhael bin Yesisai bin Yahdo bin Bus.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 15, 'Ahi bin Abdiel bin Guni ialah salah seorang kepala puak mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 16, 'Mereka diam di Gilead, di Basan, dan di segala anak kotanya dan di segala tanah penggembalaan Saron sampai ke ujung-ujungnya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 17, 'Mereka sekalian dicatat dalam silsilah pada zaman Yotam, raja Yehuda, dan pada zaman Yerobeam, raja Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 18, 'Dari bani Ruben, orang Gad dan setengah suku Manasye ada empat puluh empat ribu tujuh ratus enam puluh orang yang sanggup berperang, orang-orang yang tangkas, yang dapat memanggul perisai dan pedang dan melentur busur panah, yang terlatih dalam bertempur.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 19, 'Mereka itu melakukan perang melawan orang Hagri, Yetur, Nafish dan Nodab.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 20, 'Mereka mendapat bantuan melawan orang-orang itu, sehingga orang Hagri itu dengan semua orang yang mengikutinya menyerahkan diri ke dalam tangan mereka, sebab mereka telah berseru kepada Allah dalam pertempuran itu. Maka Ia mengabulkan permintaan mereka, sebab mereka percaya kepada-Nya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 21, 'Mereka mengangkut ternak orang-orang itu sebagai jarahan: untanya lima puluh ribu ekor, kambing domba dua ratus lima puluh ribu ekor dan keledai dua ribu ekor, juga manusia seratus ribu jiwa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 22, 'Banyak orang yang tewas karena mati terbunuh, sebab pertempuran itu adalah dari pada Allah. Lalu mereka menduduki tempat orang-orang itu sampai waktu pembuangan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 23, 'Setengah suku Manasye diam di negeri itu mulai dari Basan sampai Baal-Hermon, Senir dan gunung Hermon. Mereka sudah banyak jumlahnya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 24, 'Inilah para kepala puak-puak mereka: Hefer, Yisei, Eliel, Azriel, Yeremia, Hodawya dan Yahdiel, orang-orang pahlawan yang gagah perkasa, orang-orang yang kenamaan, para kepala puak-puak mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 25, 'Tetapi ketika mereka berubah setia terhadap Allah nenek moyang mereka dan berzinah dengan mengikuti segala allah bangsa-bangsa negeri yang telah dimusnahkan Allah dari depan mereka,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 5, 26, 'maka Allah Israel menggerakkan hati Pul, yakni Tilgat-Pilneser, raja Asyur, lalu raja itu mengangkut mereka ke dalam pembuangan, yaitu orang Ruben, orang Gad dan setengah suku Manasye. Ia membawa mereka ke Halah, Habor, Hara dan sungai negeri Gozan; demikianlah mereka ada di sana sampai hari ini.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 1, 'Anak-anak Lewi ialah Gerson, Kehat dan Merari.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 2, 'Anak-anak Kehat ialah Amram, Yizhar, Hebron dan Uziel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 3, 'Anak-anak Amram ialah Harun, Musa dan Miryam. Anak-anak Harun ialah Nadab, Abihu, Eleazar dan Itamar.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 4, 'Eleazar memperanakkan Pinehas; Pinehas memperanakkan Abisua;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 5, 'Abisua memperanakkan Buki; Buki memperanakkan Uzi;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 6, 'Uzi memperanakkan Zerahya; Zerahya memperanakkan Merayot;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 7, 'Merayot memperanakkan Amarya; Amarya memperanakkan Ahitub;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 8, 'Ahitub memperanakkan Zadok; Zadok memperanakkan Ahimaas;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 9, 'Ahimaas memperanakkan Azarya; Azarya memperanakkan Yohanan;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 10, 'Yohanan memperanakkan Azarya; dialah yang memegang jabatan imam di Bait Suci yang didirikan Salomo di Yerusalem.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 11, 'Azarya memperanakkan Amarya; Amarya memperanakkan Ahitub;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 12, 'Ahitub memperanakkan Zadok; Zadok memperanakkan Salum;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 13, 'Salum memperanakkan Hilkia; Hilkia memperanakkan Azarya;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 14, 'Azarya memperanakkan Seraya; Seraya memperanakkan Yozadak;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 15, 'Yozadak turut diangkut ketika TUHAN membiarkan orang Yehuda dan Yerusalem diangkut ke dalam pembuangan oleh Nebukadnezar.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 16, 'Anak-anak Lewi ialah Gerson, Kehat dan Merari.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 17, 'Inilah nama anak-anak Gerson: Libni dan Simei.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 18, 'Anak-anak Kehat ialah Amram, Yizhar, Hebron dan Uziel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 19, 'Anak-anak Merari ialah Mahli dan Musi. Inilah kaum-kaum suku Lewi dalam puak-puak mereka:', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 20, 'dari pada Gerson ialah Libni, anaknya, dan anak orang ini ialah Yahat, dan anak orang ini ialah Zima,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 21, 'dan anak orang ini ialah Yoah, dan anak orang ini ialah Ido, dan anak orang ini ialah Zerah, dan anak orang ini ialah Yeatrai.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 22, 'Keturunan Kehat ialah Aminadab, anaknya, dan anak orang ini ialah Korah, dan anak orang ini ialah Asir,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 23, 'dan anak orang ini ialah Elkana, dan anak orang ini ialah Ebyasaf, dan anak orang ini ialah Asir,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 24, 'dan anak orang ini ialah Tahat, dan anak orang ini ialah Uriel, dan anak orang ini ialah Uzia, dan anak orang ini ialah Saul.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 25, 'Anak-anak Elkana ialah Amasai dan Ahimot,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 26, 'dan anak orang ini ialah Elkana, dan anak orang ini ialah Zofai, dan anak orang ini ialah Nahat,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 27, 'dan anak orang ini ialah Eliab, dan anak orang ini ialah Yeroham, dan anak orang ini ialah Elkana.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 28, 'Anak-anak Samuel ialah Yoel, anak sulung dan anak yang kedua ialah Abia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 29, 'Keturunan Merari ialah Mahli, dan anak orang ini ialah Libni, anak orang ini ialah Simei, dan anak orang ini ialah Uza,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 30, 'dan anak orang ini ialah Simea, dan anak orang ini ialah Hagia, dan anak orang ini ialah Asaya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 31, 'Inilah orang-orang yang ditugaskan oleh Daud memimpin nyanyian di rumah TUHAN sejak tabut itu mendapat tempat perhentian.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 32, 'Di hadapan Kemah Suci, yakni Kemah Pertemuan, mereka melayani sebagai penyanyi sampai Salomo mendirikan rumah TUHAN di Yerusalem. Mereka melakukan tugas jabatannya sesuai dengan peraturannya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 33, 'Inilah orang-orang yang memegang tugas itu dengan anak-anak mereka: dari bani Kehat ialah Heman, penyanyi itu, anak Yoel bin Samuel', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 34, 'bin Elkana bin Yeroham bin Eliel bin Toah', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 35, 'bin Zuf bin Elkana bin Mahat bin Amasai', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 36, 'bin Elkana bin Yoel bin Azaria bin Zefanya', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 37, 'bin Tahat bin Asir bin Ebyasaf bin Korah', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 38, 'bin Yizhar bin Kehat bin Lewi bin Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 39, 'Kemudian di sebelah kanannya berdiri Asaf, saudara sesukunya, yaitu Asaf bin Berekhya bin Simea', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 40, 'bin Mikhael bin Baaseya bin Malkia', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 41, 'bin Etai bin Zerah bin Adaya', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 42, 'bin Etan bin Zima bin Simei', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 43, 'bin Yahat bin Gerson bin Lewi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 44, 'Di sebelah kiri berdiri dari bani Merari, saudara-saudara sesuku mereka, Etan bin Kisi bin Abdi bin Malukh', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 45, 'bin Hasabya bin Amazia bin Hilkia', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 46, 'bin Amzi bin Bani bin Semer', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 47, 'bin Mahli bin Musi bin Merari bin Lewi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 48, 'Saudara-saudara sesuku mereka, orang-orang Lewi yang lain, diserahkan melakukan segala pekerjaan di Kemah Suci, rumah Allah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 49, 'Tetapi Harun dan anak-anaknya berkewajiban membakar korban di atas mezbah korban bakaran dan di atas mezbah pembakaran ukupan, dan melakukan segala pekerjaan di tempat maha kudus serta mengadakan pendamaian bagi orang Israel, tepat seperti yang diperintahkan Musa, hamba Allah itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 50, 'Inilah keturunan Harun: Eleazar, anaknya, dan anak orang ini ialah Pinehas, dan anak orang ini ialah Abisua,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 51, 'dan anak orang ini ialah Buki, dan anak orang ini ialah Uzi, dan anak orang ini ialah Zerahya', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 52, 'dan anak orang ini ialah Merayot, dan anak orang ini ialah Amarya, dan anak orang ini ialah Ahitub,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 53, 'dan anak orang ini ialah Zadok, dan anak orang ini ialah Ahimaas.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 54, 'Inilah tempat-tempat kediaman mereka menurut tempat-tempat perkemahan mereka di daerah mereka: kepada keturunan Harun yang termasuk kaum orang Kehat?karena bagi merekalah undian yang pertama?', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 55, 'kepada mereka diberikan Hebron di tanah Yehuda dengan tanah-tanah penggembalaan di sekelilingnya,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 56, 'tetapi tanah ladang kota tadi dengan desa-desanya telah diberikan kepada Kaleb bin Yefune.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 57, 'Kepada keturunan Harun diberikan Hebron kota perlindungan itu, kemudian Libna dengan tanah-tanah penggembalaannya, dan Yatir, lalu Estemoa dengan tanah-tanah penggembalaannya;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 58, 'Hilen dengan tanah-tanah penggembalaannya, Debir dengan tanah-tanah penggembalaannya;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 59, 'Asan dengan tanah-tanah penggembalaannya, dan Bet-Semes dengan tanah-tanah penggembalaannya;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 6, 60, 'dan dari suku Benyamin: Geba dengan tanah-tanah penggembalaannya, Alemet dengan tanah-tanah penggembalaannya dan Anatot dengan tanah-tanah penggembalaannya. Seluruhnya kota-kota mereka ada tiga belas yang dibagikan di antara kaum-kaum mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 1, 'Anak-anak Isakhar ialah Tola dan Pua, Yasub dan Simron, empat orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 2, 'Anak-anak Tola ialah Uzi, Refaya, Yeriel, Yahmai, Yibsam dan Samuel, kepala-kepala puak turunan Tola, pahlawan-pahlawan yang gagah perkasa; menurut daftar keturunan mereka jumlahnya di zaman Daud ada dua puluh dua ribu enam ratus orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 3, 'Keturunan Uzi ialah Yizrahya dan anak-anak Yizrahya ialah Mikhael, Obaja, Yoel dan Yisia, lima orang, semuanya mereka adalah kepala-kepala.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 4, 'Di bawah mereka itu, menurut daftar keturunan dan menurut puak mereka, ada pasukan-pasukan tentara tiga puluh enam ribu orang, sebab isteri dan anak-anak mereka banyak.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 5, 'Saudara-saudara sesuku mereka dari segala kaum Isakhar, pahlawan-pahlawan yang gagah perkasa, semuanya ada delapan puluh tujuh ribu orang yang terdaftar dalam silsilah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 6, 'Anak-anak Benyamin ialah Bela, Bekher dan Yediael, tiga orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 7, 'Anak-anak Bela ialah Ezbon, Uzi, Uziel, Yerimot dan Iri, lima orang, kepala-kepala puak, pahlawan-pahlawan yang gagah perkasa; mereka yang terdaftar dalam silsilah ada dua puluh dua ribu tiga puluh empat orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 8, 'Anak-anak Bekher ialah Zemira, Yoas, Eliezer, Elyoenai, Omri, Yeremot, Abia, Anatot dan Alemet; sekaliannya itu ialah anak-anak Bekher.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 9, 'Mereka yang terdaftar dalam silsilah, menurut keturunan mereka, sebagai kepala-kepala puak mereka, pahlawan-pahlawan yang gagah perkasa, ada dua puluh ribu dua ratus orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 10, 'Keturunan Yediael ialah Bilhan dan anak-anak Bilhan ialah Yeush, Benyamin, Ehud, Kenaana, Zetan, Tarsis dan Ahisahar.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 11, 'Sekaliannya itu ialah keturunan Yediael, kepala-kepala puak mereka, pahlawan-pahlawan yang gagah perkasa; orang-orang yang sanggup berperang ada tujuh belas ribu dua ratus.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 12, 'Dan Supim dan Hupim ialah keturunan Ir; Husim ialah keturunan Aher.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 13, 'Anak-anak Naftali ialah Yahziel, Guni, Yezer dan Salum, anak-anaknya dari Bilha.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 14, 'Keturunan Manasye ialah Asriel yang dilahirkan oleh gundiknya, perempuan Aram itu; perempuan ini melahirkan Makhir, bapa Gilead.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 15, 'Makhir mengambil seorang isteri bagi Hupim dan Supim; nama saudaranya perempuan ialah Maakha. Nama anak yang kedua ialah Zelafead. Zelafead hanya mempunyai anak-anak perempuan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 16, 'Tetapi Maakha, isteri Makhir, melahirkan seorang anak laki-laki dan menamainya Peresh; nama saudaranya laki-laki ialah Seres dan anak-anak orang ini ialah Ulam dan Rekem.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 17, 'Keturunan Ulam ialah Bedan. Itulah keturunan Gilead bin Makhir bin Manasye.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 18, 'Saudaranya perempuan, Molekhet, melahirkan Isyhod, Abiezer dan Mahla.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 19, 'Anak-anak Semida ialah Ahyan, Sekhem, Likhi dan Aniam.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 20, 'Keturunan Efraim ialah Sutelah, dan anak orang ini ialah Bered, dan anak orang ini ialah Tahat, dan anak orang ini ialah Elada, dan anak orang ini ialah Tahat,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 21, 'dan anak orang ini ialah Zabad, dan anak orang ini ialah Sutelah, kemudian Ezer dan Elad. Mereka dibunuh oleh orang-orang Gat yang lahir di negeri itu, sebab mereka pergi merampas ternak orang-orang itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 22, 'Efraim, ayah mereka, berkabung berhari-hari lamanya, sehingga saudara-saudaranya datang untuk menghiburkan dia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 23, 'Sesudah itu ia bersetubuh dengan isterinya, lalu mengandunglah perempuan itu dan melahirkan seorang anak laki-laki. Ia menamainya Beria, sebab malapetaka telah menimpa keluarganya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 24, 'Anaknya perempuan ialah Seera yang telah mendirikan Bet-Horon-Hilir dan Bet-Horon-Hulu serta Uzen-Seera.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 25, 'Anak laki-laki Beria ialah Refah, lalu Resef; anak orang ini ialah Telah, dan anak orang ini ialah Tahan,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 26, 'dan anak orang ini ialah Ladan, dan anak orang ini ialah Amihud, dan anak orang ini ialah Elisama,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 27, 'dan anak orang ini ialah Nun, dan anak orang ini ialah Yosua.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 28, 'Tanah milik mereka dan tempat kediaman mereka ialah Betel dengan segala anak kotanya, Naaran di sebelah timur dan Gezer dengan segala anak kotanya di sebelah barat, kemudian Sikhem dengan segala anak kotanya sampai Aya dengan segala anak kotanya,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 29, 'dan pada perbatasan bani Manasye: Bet-Sean dengan segala anak kotanya, juga Taanakh dengan segala anak kotanya, Megido dengan segala anak kotanya, Dor dengan segala anak kotanya. Di tempat-tempat itulah keturunan Yusuf bin Israel diam.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 30, 'Anak-anak Asyer ialah Yimna, Yiswa, Yiswi dan Beria; Serah ialah saudara perempuan mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 31, 'Anak-anak Beria ialah Heber dan Malkiel; dialah bapa Birzait.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 32, 'Heber memperanakkan Yaflet, Somer dan Hotam serta Sua, saudara perempuan mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 33, 'Anak-anak Yaflet ialah Pasakh, Bimhab dan Asywat. Itulah anak-anak Yaflet.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 34, 'Anak-anak Semer ialah Ahi, Rohga, Yehuba dan Aram.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 35, 'Anak-anak Helem, saudaranya laki-laki, ialah Zofah, Yimna, Seles dan Amal.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 36, 'Anak-anak Zofah ialah Suah, Harnefer, Syual, Beri dan Yimra,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 37, 'Bezer, Hod, Sama, Silsa, Yitran dan Beera.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 38, 'Anak-anak Yeter ialah Yefune, Pispa dan Ara.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 39, 'Anak-anak Ula ialah Arah, Haniel dan Rizya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 7, 40, 'Itulah sekaliannya keturunan Asyer, kepala-kepala puak mereka, pahlawan-pahlawan gagah perkasa yang terpilih, pemimpin-pemimpin utama. Jumlah yang terdaftar dalam silsilah mereka sebagai pasukan perang ada dua puluh enam ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 1, 'Benyamin memperanakkan Bela, anak sulungnya, Asybel, anak yang kedua, Ahrah, anak yang ketiga,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 2, 'Noha, anak yang keempat dan Rafa, anak yang kelima.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 3, 'Anak-anak Bela ialah Adar, Gera, Abihud,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 4, 'Abisua, Naaman, Ahoah,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 5, 'Gera, Sefufan dan Huram.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 6, 'Inilah anak-anak Ehud; mereka ini adalah kepala-kepala puak penduduk Geba yang diangkut ke dalam pembuangan ke Manahat;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 7, 'Naaman, Ahia dan Gera mengangkut mereka ke dalam pembuangan; dia memperanakkan Uza dan Ahihud.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 8, 'Saharaim mendapat anak di daerah Moab, sesudah diusirnya Husim dan Baara, isteri-isterinya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 9, 'Ia mendapat anak dari Hodesh, isterinya, yakni Yobab, Zibya, Mesa, Malkam,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 10, 'Yeus, Sokhya dan Mirma; itulah anak-anaknya, kepala-kepala puak;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 11, 'sebelum itu dari Husim ia telah mendapat anak, yakni Abitub dan Elpaal.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 12, 'Anak-anak Elpaal ialah Eber, Misam dan Semed; dia ini mendirikan kota Ono dan kota Lod dengan segala anak kotanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 13, 'Beria dan Sema adalah kepala-kepala puak penduduk Ayalon; mereka telah menghalau penduduk Gat.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 14, 'Ahyo, Sasak, Yeremot,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 15, 'Zebaja, Arad, Eder,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 16, 'Mikhael, Yispa dan Yoha ialah anak-anak Beria.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 17, 'Zebaja, Mesulam, Hizki, Heber,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 18, 'Yismerai, Yizlia dan Yobab ialah anak-anak Elpaal.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 19, 'Yakim, Zikhri, Zabdi,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 20, 'Elyoenai, Ziletai, Eliel,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 21, 'Adaya, Beraya dan Simrat ialah anak-anak Simei.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 22, 'Yispan, Eber, Eliel,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 23, 'Abdon, Zikhri, Hanan,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 24, 'Hananya, Elam, Antotia,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 25, 'Yifdeya dan Pnuel ialah anak-anak Sasak.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 26, 'Samserai, Seharya, Atalya,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 27, 'Yaaresya, Elia dan Zikhri ialah anak-anak Yeroham.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 28, 'Itulah para kepala puak, para kepala menurut keturunan mereka; mereka ini diam di Yerusalem.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 29, 'Tetapi di Gibeon diam bapa Gibeon, yakni Yeiel, dan nama isterinya ialah Maakha.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 30, 'Anak sulungnya ialah Abdon, lalu Zur, Kish, Baal, Nadab,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 31, 'Gedor, Ahyo, Zekher', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 32, 'dan Miklot yang memperanakkan Simea. Juga mereka ini pergi diam berdekatan dengan saudara-saudara mereka di Yerusalem bersama-sama saudara mereka yang lain.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 33, 'Ner memperanakkan Kish; Kish memperanakkan Saul; Saul memperanakkan Yonatan, Malkisua, Abinadab dan Esybaal.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 34, 'Anak Yonatan ialah Meribaal dan Meribaal memperanakkan Mikha.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 35, 'Anak Mikha ialah Piton, Melekh, Tarea dan Ahas.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 36, 'Ahas memperanakkan Yoada; Yoada memperanakkan Alemet, Azmawet dan Zimri; Zimri memperanakkan Moza.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 37, 'Moza memperanakkan Bina; anak orang ini ialah Rafa, dan anak orang ini ialah Elasa, dan anak orang ini ialah Azel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 38, 'Azel mempunyai enam orang anak, dan inilah nama-nama mereka: Azrikam, Bokhru, Ismael, Searya, Obaja dan Hanan. Itulah sekaliannya anak-anak Azel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 39, 'Anak-anak Esek, saudaranya, ialah Ulam, anak sulungnya, lalu Yeush, anak yang kedua, dan Elifelet, anak yang ketiga.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 8, 40, 'Anak-anak Ulam itu adalah orang-orang berani, pahlawan-pahlawan yang gagah perkasa, pemanah-pemanah; anak dan cucu mereka banyak: seratus lima puluh orang. Mereka semuanya itu termasuk bani Benyamin.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 1, 'Seluruh orang Israel telah terdaftar dalam silsilah; mereka tertulis dalam kitab raja-raja Israel, sedang orang Yehuda telah diangkut ke dalam pembuangan ke Babel oleh karena perbuatan mereka yang tidak setia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 2, 'Dan orang-orang yang mula-mula menetap kembali di tanah-tanah milik mereka, di kota-kota mereka, ialah orang Israel awam, para imam, orang-orang Lewi dan para budak di bait Allah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 3, 'Di Yerusalem tinggal orang-orang dari bani Yehuda, dari bani Benyamin, dari bani Efraim dan Manasye:', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 4, 'Utai bin Amihud bin Omri bin Imri bin Bani, dari keturunan Peres bin Yehuda.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 5, 'Dan dari orang Syela ialah Asaya, anak yang sulung, dengan anak-anaknya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 6, 'Dari keturunan Zerah ialah Yeuel dengan sanak saudaranya, enam ratus sembilan puluh orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 7, 'Dari bani Benyamin ialah Salu bin Mesulam bin Hodawya bin Hasenua,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 8, 'Yibnea bin Yeroham, Ela bin Uzi bin Mikhri dan Mesulam bin Sefaca bin Rehuel bin Yibnia', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 9, 'dengan sanak saudara mereka menurut keturunan mereka, sembilan ratus lima puluh enam orang. Semua orang itu adalah kepala puak.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 10, 'Dari para imam ialah Yedaya, Yoyarib, Yakhin,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 11, 'Azarya bin Hilkia bin Mesulam bin Zadok bin Merayot bin Ahitub, pemuka rumah Allah,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 12, 'lalu Adaya bin Yeroham bin Pasyhur bin Malkia, dan Masai bin Adiel bin Yahzera bin Mesulam bin Mesilemit bin Imer,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 13, 'dengan sanak saudara mereka, kepala-kepala puak, seribu tujuh ratus enam puluh orang, orang-orang tangkas untuk menyelenggarakan ibadah di rumah Allah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 14, 'Dari orang-orang Lewi ialah Semaya bin Hasub bin Azrikam bin Hasabya, dari keturunan Merari;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 15, 'lalu Bakbakar, Heresh, Galal dan Matanya bin Mikha bin Zikhri bin Asaf,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 16, 'serta Obaja bin Semaya bin Galal bin Yedutun dan Berekhya bin Asa bin Elkana yang diam di desa-desa orang Netofa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 17, 'Penunggu-penunggu pintu gerbang ialah Salum, Akub, Talmon dan Ahiman, dengan sanak saudara mereka; Salum ialah kepala.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 18, 'Sampai sekarang mereka ada di pintu gerbang raja di sebelah timur. Merekalah penunggu-penunggu pintu gerbang perkemahan bani Lewi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 19, 'Salum bin Kore bin Ebyasaf bin Korah dan saudara-saudara sepuaknya, yakni orang-orang Korah, mempunyai tugas jabatan sebagai penjaga-penjaga ambang pintu Kemah, seperti bapa-bapa mereka bertugas di perkemahan TUHAN sebagai penjaga-penjaga pintu masuk.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 20, 'Pinehas bin Eleazar mengepalai mereka sebelumnya. TUHAN kiranya menyertai dia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 21, 'Zakharia bin Meselemya adalah penunggu pintu Kemah Pertemuan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 22, 'Mereka semuanya yang terpilih menjadi penunggu ambang pintu ada dua ratus dua belas orang. Mereka telah terdaftar dalam silsilah di desa-desa mereka. Daud dan Samuel, pelihat itu, mengangkat mereka dalam jabatan itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 23, 'Mereka dan anak-anak mereka bertugas menjaga pintu-pintu gerbang rumah TUHAN, yakni Bait Kemah itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 24, 'Ke arah empat mata angin ditempatkan penunggu-penunggu pintu gerbang itu, yakni ke arah timur, barat, utara dan selatan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 25, 'Dan saudara-saudara mereka yang tinggal di desa-desa mereka, pada waktu-waktu tertentu harus masuk selama tujuh hari untuk bekerja bersama-sama mereka,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 26, 'sedang keempat kepala penunggu pintu gerbang itu memegang jabatan tetap. Mereka adalah orang Lewi dan mengawasi bilik-bilik serta perbendaharaan rumah Allah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 27, 'Mereka bermalam di sekitar rumah Allah itu sebab mereka bertanggung jawab atas penjagaan dan harus membuka pintu setiap pagi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 28, 'Sebagian dari mereka mengurus perkakas ibadah: mereka menghitung perkakas itu pada waktu dimasukkan dan dikeluarkan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 29, 'Sebagian dari mereka ditugaskan mengurus perabotan, yakni segala perabotan tempat kudus, dan mengurus tepung yang terbaik, anggur, minyak, kemenyan dan rempah-rempah,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 30, 'sedangkan beberapa orang imam menyediakan campuran rempah-rempah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 31, 'Matica, salah seorang Lewi, anak sulung Salum, orang Korah itu, mendapat tugas tetap untuk mengolah roti.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 32, 'Dan sebagian dari anak-anak orang Kehat, yakni dari sanak saudara mereka, mengurus roti sajian untuk disediakan setiap hari Sabat.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 33, 'Dan inilah para penyanyi, kepala-kepala puak orang Lewi, yang diam di bilik-bilik dan bebas dari pekerjaan lain, sebab siang dan malam mereka sibuk dengan pekerjaannya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 34, 'Itulah para kepala puak orang Lewi, para kepala, menurut keturunan mereka; mereka ini diam di Yerusalem.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 35, 'Di Gibeon diam bapa Gibeon, yakni Yeiel, dan nama isterinya ialah Maakha.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 36, 'Anak sulungnya ialah Abdon, lalu Zur, Kish, Baal, Ner, Nadab,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 37, 'Gedor, Ahyo, Zakharia dan Miklot.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 38, 'Miklot memperanakkan Simeam. Juga mereka ini pergi diam berdekatan dengan saudara-saudara mereka di Yerusalem bersama-sama saudara mereka yang lain.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 39, 'Ner memperanakkan Kish; Kish memperanakkan Saul; Saul memperanakkan Yonatan, Malkisua, Abinadab dan Esybaal.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 40, 'Anak Yonatan ialah Meribaal, dan Meribaal memperanakkan Mikha.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 41, 'Anak Mikha ialah Piton, Melekh, Tahrea dan Ahas.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 42, 'Ahas memperanakkan Yaera; Yaera memperanakkan Alemet, Azmawet dan Zimri; Zimri memperanakkan Moza.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 43, 'Moza memperanakkan Bina, dan anak orang ini ialah Refaya, dan anak orang ini ialah Elasa, dan anak orang ini ialah Azel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 9, 44, 'Azel mempunyai enam orang anak dan inilah nama-nama mereka: Azrikam, Bokhru, Ismael, Searya, Obaja dan Hanan. Itulah anak-anak Azel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 1, 'Orang Filistin berperang melawan orang Israel. Orang-orang Israel melarikan diri dari hadapan orang Filistin dan banyak yang mati terbunuh di pegunungan Gilboa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 2, 'Orang Filistin terus mengejar Saul dan anak-anaknya dan menewaskan Yonatan, Abinadab dan Malkisua, anak-anak Saul.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 3, 'Kemudian makin beratlah pertempuran itu bagi Saul; para pemanah menjumpainya dan melukainya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 4, 'Lalu berkatalah Saul kepada pembawa senjatanya: "Hunuslah pedangmu dan tikamlah aku, supaya jangan datang orang-orang yang tidak bersunat ini memperlakukan aku sebagai permainan." Tetapi pembawa senjatanya tidak mau, karena ia sangat segan. Kemudian Saul mengambil pedang itu dan menjatuhkan dirinya ke atasnya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 5, 'Ketika pembawa senjatanya melihat, bahwa Saul telah mati, iapun menjatuhkan dirinya ke atas pedangnya, lalu mati.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 6, 'Jadi Saul, ketiga anaknya dan segenap keluarganya sama-sama mati.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 7, 'Ketika dilihat seluruh orang Israel yang di lembah, bahwa tentara telah melarikan diri, dan bahwa Saul serta anak-anaknya sudah mati, maka mereka meninggalkan kota-kota mereka lalu melarikan diri juga; kemudian datanglah orang Filistin dan menetap di sana.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 8, 'Ketika keesokan harinya orang Filistin datang merampasi orang-orang yang mati terbunuh itu, didapati mereka Saul dan anak-anaknya tergelimpang di pegunungan Gilboa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 9, 'Mereka merampasinya dan mengambil kepala Saul dan senjata-senjatanya, lalu menyuruh orang berkeliling di negeri orang Filistin untuk menyampaikan kabar itu kepada berhala-berhala mereka dan kepada rakyat.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 10, 'Kemudian mereka menaruh senjata-senjata Saul di kuil allah mereka, tetapi batu kepalanya dipakukan mereka di rumah Dagon.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 11, 'Ketika seluruh Yabesh-Gilead mendengar tentang segala yang telah dilakukan orang Filistin terhadap Saul,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 12, 'maka bersiaplah segenap orang gagah perkasa, lalu pergi mengambil mayat Saul dan mayat anak-anaknya. Mereka membawanya ke Yabesh dan menguburkan tulang-tulang mereka di bawah pohon besar, di Yabesh. Sesudah itu berpuasalah mereka tujuh hari lamanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 13, 'Demikianlah Saul mati karena perbuatannya yang tidak setia terhadap TUHAN, oleh karena ia tidak berpegang pada firman TUHAN, dan juga karena ia telah meminta petunjuk dari arwah,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 10, 14, 'dan tidak meminta petunjuk TUHAN. Sebab itu TUHAN membunuh dia dan menyerahkan jabatan raja itu kepada Daud bin Isai.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 1, 'Lalu berkumpullah seluruh Israel kepada Daud di Hebron dan berkata: "Ketahuilah, kami ini darah dagingmu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 2, 'Telah lama, ketika Saul memerintah, engkaulah yang memimpin segala gerakan orang Israel. Dan TUHAN, Allahmu, telah berfirman kepadamu: Engkaulah yang harus menggembalakan umat-Ku Israel, dan engkaulah yang menjadi raja atas umat-Ku Israel."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 3, 'Maka datanglah semua tua-tua Israel menghadap raja di Hebron, lalu Daud mengadakan perjanjian dengan mereka di Hebron di hadapan TUHAN, kemudian mereka mengurapi Daud menjadi raja atas Israel, seperti yang difirmankan TUHAN dengan perantaraan Samuel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 4, 'Lalu Daud dengan seluruh orang Israel pergi ke Yerusalem; itulah Yebus, dan di sana orang Yebus adalah penduduk negeri itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 5, 'Penduduk Yebus berkata kepada Daud: "Engkau tidak sanggup masuk ke mari." Tetapi Daud merebut kubu pertahanan Sion, yaitu kota Daud.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 6, 'Daud telah berkata: "Siapa lebih dahulu memukul kalah orang Yebus, ia akan menjadi kepala dan pemimpin." Lalu Yoab, anak Zeruya, yang menyerang lebih dahulu, maka ia menjadi kepala.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 7, 'Lalu Daud menetap di kubu pertahanan itu, sebab itu orang menamainya: Kota Daud.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 8, 'Ia memperkuat kota itu sekelilingnya, mulai dari Milo, bahkan sekelilingnya seluruhnya, sedang Yoab membangun kembali selebihnya dari kota itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 9, 'Lalu makin lama makin besarlah kuasa Daud, sebab TUHAN semesta alam menyertainya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 10, 'Inilah kepala-kepala para pahlawan yang mengiringi Daud, yang telah memberi dukungan yang kuat kepadanya, bersama-sama seluruh Israel, dalam mencapai kedudukan raja dan yang mengangkat dia sebagai raja, seperti yang difirmankan TUHAN mengenai Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 11, 'Inilah daftar para pahlawan yang mengiringi Daud: Yasobam bin Hakhmoni, kepala triwira; ia mengayunkan tombaknya melawan tiga ratus orang yang tertikam mati dalam satu pertempuran.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 12, 'Dan sesudah dia, Eleazar anak Dodo, orang Ahohi itu; ia termasuk ketiga pahlawan itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 13, 'Ia ada bersama-sama Daud di Pas-Damim, ketika orang Filistin berkumpul di sana untuk berperang. Ada sebidang tanah ladang penuh jelai di sana; ketika tentara melarikan diri dari hadapan orang Filistin,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 14, 'maka berdirilah mereka di tengah-tengah ladang itu; mereka dapat mempertahankannya dan memukul kalah orang Filistin. Demikianlah diberikan TUHAN kemenangan yang besar.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 15, 'Sekali datanglah tiga orang dari ketiga puluh kepala ke gunung batu mendapatkan Daud dekat gua Adulam, sedang tentara orang Filistin berkemah di lembah Refaim.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 16, 'Pada waktu itu Daud ada di dalam kubu gunung dan pasukan pendudukan orang Filistin pada waktu itu ada di Betlehem.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 17, 'Lalu timbullah keinginan pada Daud, dan ia berkata: "Sekiranya ada orang yang memberi aku minum air dari perigi Betlehem yang ada dekat pintu gerbang!"', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 18, 'Lalu ketiga orang itu menerobos perkemahan orang Filistin, mereka menimba air dari perigi Betlehem yang ada dekat pintu gerbang, mengangkatnya dan membawanya kepada Daud. Tetapi Daud tidak mau meminumnya, melainkan mempersembahkannya sebagai korban curahan kepada TUHAN,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 19, 'katanya: "Jauhlah dari padaku, ya Allah, untuk berbuat demikian! Patutkah aku meminum darah taruhan nyawa orang-orang ini? Sebab dengan mempertaruhkan nyawanya mereka membawanya." Dan tidak mau ia meminumnya. Itulah yang dilakukan ketiga pahlawan itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 20, 'Abisai, adik Yoab, dialah kepala ketiga puluh orang itu. Dan dialah yang mengayunkan tombaknya melawan tiga ratus orang yang mati ditikamnya; ia mendapat nama di antara ketiga puluh orang itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 21, 'Di antara ketiga puluh orang itu ia paling dihormati. Memang ia menjadi pemimpin mereka, tetapi ia tidak dapat menyamai triwira itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 22, 'Selanjutnya Benaya bin Yoyada, anak seorang yang gagah perkasa, yang besar jasanya, yang berasal dari Kabzeel; ia menewaskan kedua pahlawan besar dari Moab. Juga pernah ia turun ke dalam lobang dan membunuh seekor singa pada suatu hari bersalju.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 23, 'Pula ia membunuh seorang Mesir, seorang yang tinggi perawakannya lima hasta tingginya; di tangan orang Mesir itu ada tombak seperti pesa tukang tenun, tetapi ia mendatanginya dengan tongkat, merampas tombak itu dari tangan orang Mesir itu, lalu membunuh orang itu dengan tombaknya sendiri.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 24, 'Itulah yang diperbuat Benaya bin Yoyada; ia mendapat nama di antara ketiga puluh pahlawan itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 25, 'Sesungguhnya, di antara ketiga puluh orang itu ia paling dihormati, tetapi ia tidak dapat menyamai triwira. Dan Daud mengangkat dia mengepalai pengawalnya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 26, 'Pahlawan-pahlawan yang gagah perkasa ialah juga Asael, saudara Yoab, selanjutnya Elhanan bin Dodo, dari Betlehem;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 27, 'Samot, orang Harod; Heles, orang Peloni;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 28, 'Ira anak Ikesh orang Tekoa; Abiezer, orang Anatot;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 29, 'Sibkhai, orang Husa; Ilai, orang Ahohi;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 30, 'Maharai, orang Netofa; Heled bin Baana, orang Netofa;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 31, 'Itai bin ribai, dari Gibea orang Benyamin; Benaya, orang Piraton;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 32, 'Hurai dari lembah-lembah Gaas; Abiel, orang Bet-Araba;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 33, 'Azmawet, orang Bahurim; Elyahba, orang Saalbon;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 34, 'Hasyem orang Gizon; Yonatan bin Sage, orang Harari;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 35, 'Ahiam bin Sakhar, orang Harari; Elifal bin Ur;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 36, 'Hefer, orang Mekherati; Ahia, orang Peloni;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 37, 'Hezro, orang Karmel; Naarai bin Esbai;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 38, 'Yoel, saudara Natan; Mibhar bin Hagri;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 39, 'Zelek, orang Amon; Naharai, orang Beerot, pembawa senjata Yoab anak Zeruya;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 40, 'Ira, orang Yetri; Gareb, orang Yetri;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 41, 'Uria, orang Het; Zabad bin Ahlai;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 42, 'Adina anak Siza orang Ruben, kepala orang-orang Ruben dan beserta dia ada tiga puluh orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 43, 'Hanan bin Maakha; Yosafat, orang Mitni;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 44, 'Uzia, orang Asytarot; Syama dan Yeiel, anak-anak Hotam orang Aroer;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 45, 'Yediael bin Simri, dan Yoha, saudaranya, orang Tizi;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 46, 'Eliel, orang Mahawim; Yeribai dan Yosawya, anak-anak Elnaam; Yitma, orang Moab;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 11, 47, 'Eliel, Obed dan Yaasiel, orang Mezobaya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 1, 'Inilah orang-orang yang datang kepada Daud di Ziklag, selama ia harus menyingkir karena Saul bin Kish. Merekapun termasuk pahlawan-pahlawan yang membantu dia dalam peperangan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 2, 'Mereka bersenjatakan panah, dan sanggup melontarkan batu dan menembakkan anak-anak panah dari busur dengan tangan kanan atau tangan kiri. Mereka itu dari saudara-saudara sesuku Saul, dari orang Benyamin:', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 3, 'Abiezer, kepala, dan Yoas, anak-anak Semaa orang Gibea; Yeziel dan Pelet, anak-anak Azmawet, Berakha dan Yehu, orang Anatot;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 4, 'Yismaya, orang Gibeon, seorang pahlawan di antara ketiga puluh orang itu, yang mengepalai tiga puluh orang; Yeremia, Yehaziel, Yohanan dan Yozabad, orang Gedera;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 5, 'Eluzai, Yerimot, Bealya, Semarya dan Sefaca, orang Harufi;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 6, 'Elkana, Yisia, Azareel, Yoezer dan Yasobam, orang-orang Korah;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 7, 'Yoela, Zebaja, anak-anak Yeroham, dari Gedor.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 8, 'Juga dari orang Gad ada yang memisahkan diri dan pergi kepada Daud ke kubu di padang gurun, yakni pahlawan-pahlawan yang gagah perkasa, orang-orang yang sanggup berperang, yang pandai menggunakan perisai dan tombak, dan rupa mereka seperti singa dan cepatnya seperti kijang di atas pegunungan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 9, 'Ezer, kepala, Obaja, orang kedua; Eliab, orang ketiga;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 10, 'Mismana, orang keempat; Yeremia, orang kelima;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 11, 'Atai, orang keenam; Eliel, orang ketujuh;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 12, 'Yohanan, orang kedelapan; Elzabad, orang kesembilan;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 13, 'Yeremia, orang kesepuluh; Makhbanai, orang kesebelas.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 14, 'Mereka itulah dari bani Gad, kepala-kepala pasukan; satu orang yang paling kecil sanggup melawan seratus orang, dan yang paling besar sanggup melawan seribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 15, 'Mereka itulah yang menyeberangi sungai Yordan di bulan pertama, sekalipun sungai itu meluap sepanjang tepinya dan merekalah yang menghalau seluruh penduduk lembah ke sebelah timur dan ke sebelah barat.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 16, 'Sebagian dari bani Benyamin dan Yehuda datang kepada Daud di kubu itu,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 17, 'lalu keluarlah Daud menyongsong mereka. Berkatalah ia kepada mereka: "Jika kamu datang kepadaku dengan maksud damai untuk membantu aku, maka aku rela bersekutu dengan kamu, tetapi jika untuk menyerahkan aku dengan tipu muslihat kepada lawanku, sedang aku tidak melakukan kelaliman, maka biarlah Allah nenek moyang kita melihat itu dan menghukum kamu."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 18, 'Lalu Roh menguasai Amasai, kepala ketiga puluh orang itu: Kami ini bagimu, hai Daud, dan pada pihakmu, hai anak Isai! Sejahtera, sejahtera bagimu dan sejahtera bagi penolongmu, sebab yang menolong engkau ialah Allahmu! Kemudian Daud menyambut mereka dan mengangkat mereka menjadi kepala pasukan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 19, 'Juga dari Manasye ada yang menyeberang memihak kepada Daud, ketika ia bersama-sama orang Filistin memerangi Saul. Sebenarnya ia tidak menolong mereka, sebab setelah mengambil keputusan raja-raja kota orang Filistin itu menyuruh dia pergi, katanya: "Mungkin, dengan taruhan kepala kita, ia menyeberang memihak kepada tuannya, Saul."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 20, 'Pada perjalanannya ke Ziklag sebagian dari suku Manasye: Adnah, Yozabad, Yediael, Mikhael, Yozabad, Elihu dan Ziletai, kepala-kepala pasukan seribu suku Manasye menyeberang memihak kepadanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 21, 'Mereka ini membantu Daud melawan gerombolan, sebab mereka semua adalah pahlawan-pahlawan yang gagah perkasa dan kepala dalam tentara.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 22, 'Dari hari ke hari orang datang kepada Daud untuk membantu dia sehingga mereka menjadi tentara yang besar, seperti bala tentara Allah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 23, 'Inilah jumlah pasukan bersenjata untuk berperang yang datang kepada Daud di Hebron untuk menyerahkan jabatan raja dari pada Saul kepada Daud, sesuai dengan titah TUHAN.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 24, 'Bani Yehuda yang mengangkat perisai dan tombak ada enam ribu delapan ratus orang yang siap untuk berperang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 25, 'Dari bani Simeon pahlawan-pahlawan yang gagah perkasa untuk berperang ada tujuh ribu seratus orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 26, 'Dari bani Lewi ada empat ribu enam ratus orang,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 27, 'ditambah dengan Yoyada, pemimpin kaum Harun dan bersama-sama dia ada tiga ribu tujuh ratus orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 28, 'selanjutnya Zadok, seorang pahlawan muda yang gagah perkasa dengan dua puluh dua orang pemimpin dari puaknya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 29, 'Dari bani Benyamin, saudara-saudara sesuku Saul, ada tiga ribu orang; sampai pada waktu itu kebanyakan dari mereka masih tetap patuh kepada keluarga Saul.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 30, 'Dari bani Efraim dua puluh ribu delapan ratus orang pahlawan yang gagah perkasa, orang-orang yang kenamaan di antara puak-puak mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 31, 'Dari suku Manasye, suku yang setengah itu ada delapan belas ribu orang yang ditunjuk dengan disebut namanya untuk pergi mengangkat Daud menjadi raja.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 32, 'Dari bani Isakhar orang-orang yang mempunyai pengertian tentang saat-saat yang baik, sehingga mereka mengetahui apa yang harus diperbuat orang Israel: dua ratus orang kepala dengan segala saudara sesukunya yang di bawah perintah mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 33, 'Dari Zebulon orang-orang yang sanggup berperang, yang pandai berperang dengan berbagai-bagai senjata: lima puluh ribu orang, yang siap memberi bantuan dengan tidak bercabang hati.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 34, 'Dari Naftali seribu orang pemimpin dan bersama-sama mereka tiga puluh tujuh ribu orang yang membawa perisai dan tombak.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 35, 'Dari orang Dan orang-orang yang siap untuk berperang: dua puluh delapan ribu enam ratus orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 36, 'Dari Asyer orang-orang yang sanggup dan pandai untuk berperang: empat puluh ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 37, 'Dari seberang sungai Yordan, yakni dari orang Ruben, orang Gad dan setengah suku Manasye yang lain, orang-orang yang membawa berbagai-bagai senjata perang: seratus dua puluh ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 38, 'Sekaliannya itu, prajurit-prajurit, orang-orang dalam barisan tempur, datang ke Hebron dengan tulus hati untuk mengangkat Daud menjadi raja atas seluruh Israel; memang juga seluruh orang Israel yang lain dengan bulat hati hendak mengangkat Daud menjadi raja.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 39, 'Mereka tinggal di sana bersama-sama Daud tiga hari lamanya, makan dan minum, sebab saudara-saudara mereka menyajikan makanan bagi mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 12, 40, 'Juga orang-orang yang tinggal dekat mereka, bahkan dari Isakhar, Zebulon dan Naftali, membawa makanan dengan memakai keledai, unta, bagal dan lembu, yakni bahan makanan tepung, kue ara dan kue kismis, anggur dan minyak, lembu sapi dan kambing domba, dalam jumlah besar, sebab ada sukacita di Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 1, 'Daud berunding dengan pemimpin-pemimpin pasukan seribu dan pasukan seratus dan dengan semua pemuka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 2, 'Berkatalah Daud kepada seluruh jemaah Israel: "Jika kamu anggap baik dan jika diperkenankan TUHAN, Allah kita, baiklah kita menyuruh orang kepada saudara-saudara kita yang masih tinggal di daerah-daerah orang Israel, dan di samping itu kepada para imam dan orang-orang Lewi yang ada di kota-kota yang dikelilingi tanah penggembalaan mereka, supaya mereka berkumpul kepada kita.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 3, 'Dan baiklah kita memindahkan tabut Allah kita ke tempat kita, sebab pada zaman Saul kita tidak mengindahkannya."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 4, 'Maka seluruh jemaah itu berkata, bahwa mereka akan berbuat demikian, sebab usul itu dianggap baik oleh segenap bangsa itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 5, 'Lalu Daud mengumpulkan semua orang Israel dari sungai Sikhor di Mesir sampai ke jalan yang menuju Hamat, untuk menjemput tabut Allah dari Kiryat-Yearim.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 6, 'Lalu Daud dan segenap orang Israel berangkat ke Baala, ke Kiryat-Yearim, yang termasuk wilayah Yehuda, untuk mengangkut dari sana tabut Allah, yang disebut dengan nama TUHAN yang bertakhta di atas kerubim.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 7, 'Mereka menaikkan tabut Allah itu ke dalam kereta yang baru dari rumah Abinadab, sedang Uza dan Ahyo mengantarkan kereta itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 8, 'Daud dan seluruh orang Israel menari-nari di hadapan Allah dengan sekuat tenaga, diiringi nyanyian, kecapi, gambus, rebana, ceracap dan nafiri.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 9, 'Ketika mereka sampai ke tempat pengirikan Kidon, maka Uza mengulurkan tangannya memegang tabut itu, karena lembu-lembu itu tergelincir.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 10, 'Maka bangkitlah murka TUHAN terhadap Uza, lalu Ia membunuh dia oleh karena Uza telah mengulurkan tangannya kepada tabut itu; ia mati di sana di hadapan Allah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 11, 'Daud menjadi marah, karena TUHAN telah menyambar Uza demikian hebatnya; maka tempat itu disebut orang Peres-Uza sampai sekarang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 12, 'Pada waktu itu Daud menjadi takut kepada Allah, lalu katanya: "Bagaimanakah aku dapat membawa tabut Allah itu ke tempatku?"', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 13, 'Sebab itu Daud tidak mau memindahkan tabut itu ke tempatnya, ke kota Daud, tetapi Daud menyimpang dan membawanya ke rumah Obed-Edom, orang Gat itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 13, 14, 'Tiga bulan lamanya tabut Allah itu tinggal pada keluarga Obed-Edom di rumahnya dan TUHAN memberkati keluarga Obed-Edom dan segala yang dipunyainya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 1, 'Hiram, raja negeri Tirus, mengirim utusan kepada Daud dan kayu aras, tukang-tukang batu dan tukang-tukang kayu untuk mendirikan sebuah istana baginya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 2, 'Lalu tahulah Daud, bahwa TUHAN telah menegakkan dia sebagai raja atas Israel, sebab martabat pemerintahannya terangkat tinggi oleh karena Israel umat-Nya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 3, 'Daud mengambil lagi beberapa isteri di Yerusalem, dan ia memperanakkan lagi anak-anak lelaki dan perempuan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 4, 'Inilah nama anak-anak yang lahir bagi dia di Yerusalem: Syamua, Sobab, Natan, Salomo,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 5, 'Yibhar, Elisua, Elpelet,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 6, 'Nogah, Nefeg, Yafia,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 7, 'Elisama, Beelyada dan Elifelet.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 8, 'Ketika didengar orang Filistin, bahwa Daud telah diurapi menjadi raja atas seluruh Israel, maka majulah semua orang Filistin untuk menangkap Daud. Tetapi Daud mendengar hal itu, lalu majulah ia menghadapi mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 9, 'Ketika orang Filistin itu datang dan mengadakan penyerbuan di lembah Refaim,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 10, 'bertanyalah Daud kepada Allah: "Apakah aku harus maju melawan orang Filistin itu dan akan Kauserahkankah mereka ke dalam tanganku?" TUHAN menjawab: "Majulah, Aku akan menyerahkan mereka ke dalam tanganmu."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 11, 'Lalu majulah ia ke Baal-Perasim, dan Daud memukul mereka kalah di sana. Berkatalah Daud: "Allah telah menerobos musuhku dengan perantaraanku seperti air menerobos." Sebab itu orang menamakan tempat itu Baal-Perasim.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 12, 'Orang Filistin itu meninggalkan para allahnya di sana, lalu orang Israel membakarnya habis atas perintah Daud.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 13, 'Ketika orang Filistin menyerbu sekali lagi di lembah itu,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 14, 'maka bertanyalah lagi Daud kepada Allah, lalu Allah menjawab: "Janganlah maju di belakang mereka, tetapi buatlah gerakan lingkaran terhadap mereka, sehingga engkau dapat menyerang mereka dari jurusan pohon-pohon kertau.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 15, 'Dan bila engkau mendengar bunyi derap langkah di puncak pohon-pohon kertau itu, maka haruslah engkau keluar bertempur, sebab Allah telah keluar berperang di depanmu untuk memukul kalah tentara orang Filistin."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 16, 'Dan Daud berbuat seperti yang diperintahkan Allah kepadanya, maka mereka memukul kalah tentara orang Filistin, mulai dari Gibeon sampai Gezer.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 14, 17, 'Lalu termasyhurlah nama Daud di segala negeri, dan TUHAN mendatangkan rasa takut kepadanya atas segala bangsa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 1, 'Daud membuat bagi dirinya gedung-gedung di kota Daud, lalu ia menyiapkan tempat bagi tabut Allah dan membentangkan kemah untuk itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 2, 'Ketika itu berkatalah Daud: "Janganlah ada yang mengangkat tabut Allah selain dari orang Lewi, sebab merekalah yang dipilih TUHAN untuk mengangkat tabut TUHAN dan untuk menyelenggarakannya sampai selama-lamanya."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 3, 'Kemudian Daud mengumpulkan segenap Israel ke Yerusalem untuk mengangkut tabut TUHAN ke tempat yang telah disiapkannya untuk itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 4, 'Daud mengumpulkan bani Harun dan orang Lewi:', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 5, 'dari bani Kehat: Uriel, seorang pemimpin, dan saudara-saudara sepuaknya: seratus dua puluh orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 6, 'dari bani Merari: Asaya, seorang pemimpin, dan saudara-saudara sepuaknya: dua ratus dua puluh orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 7, 'dari bani Gerson: Yoel, seorang pemimpin, dan saudara-saudara sepuaknya: seratus tiga puluh orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 8, 'dari bani Elsafan: Semaya, seorang pemimpin, dan saudara-saudara sepuaknya: dua ratus orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 9, 'dari bani Hebron: Eliel, seorang pemimpin, dan saudara-saudara sepuaknya: delapan puluh orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 10, 'dari bani Uziel: Aminadab, seorang pemimpin, dan saudara-saudara sepuaknya: seratus dua belas orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 11, 'Lalu Daud memanggil Zadok dan Abyatar, imam-imam itu, dan orang-orang Lewi, yakni Uriel, Asaya, Yoel, Semaya, Eliel dan Aminadab,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 12, 'dan berkata kepada mereka: "Hai kamu ini, para kepala puak dari orang Lewi, kuduskanlah dirimu, kamu ini dan saudara-saudara sepuakmu, supaya kamu mengangkut tabut TUHAN, Allah Israel, ke tempat yang telah kusiapkan untuk itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 13, 'Sebab oleh karena pada pertama kali kamu tidak hadir, maka TUHAN, Allah kita, telah menyambar di tengah-tengah kita, sebab kita tidak meminta petunjuk-Nya seperti seharusnya."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 14, 'Jadi para imam dan orang-orang Lewi menguduskan dirinya untuk mengangkut tabut TUHAN, Allah Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 15, 'Kemudian bani Lewi mengangkat tabut Allah itu dengan gandar pengusung di atas bahu mereka, seperti yang diperintahkan Musa, sesuai dengan firman TUHAN.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 16, 'Daud memerintahkan para kepala orang Lewi itu, supaya mereka menyuruh berdiri saudara-saudara sepuak mereka, yakni para penyanyi, dengan membawa alat-alat musik seperti gambus, kecapi dan ceracap, untuk memperdengarkan dengan nyaring lagu-lagu gembira.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 17, 'Maka orang Lewi itu menyuruh berdiri Heman bin Yoel; dan dari saudara-saudara sepuaknya: Asaf bin Berekhya; dari bani Merari, saudara-saudara sepuak mereka: Etan bin Kusaya;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 18, 'dan bersama-sama mereka itu saudara-saudara mereka dari tingkat kedua: Zakharia, Yaaziel, Semiramot, Yehiel, Uni, Eliab, Benaya, Maaseya, Matica, Elifele, Mikneya, dan Obed-Edom serta Yeiel, para penunggu pintu gerbang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 19, 'Para penyanyi, yakni Heman, Asaf dan Etan harus memperdengarkan lagu dengan ceracap tembaga.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 20, 'Zakharia, Aziel, Semiramot, Yehiel, Uni, Eliab, Maaseya, Benaya harus memainkan gambus yang tinggi nadanya,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 21, 'sedang Matica, Elifele, Mikneya, Obed-Edom, Yeiel dan Azazya harus memainkan kecapi yang delapan nada lebih rendah tingkatnya untuk mengiringi nyanyian.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 22, 'Kenanya, pemimpin orang Lewi, mendapat tugas pengangkutan; ia mengepalai pengangkutan, sebab ia paham dalam hal itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 23, 'Berekhya dan Elkana adalah penunggu pintu pada tabut;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 24, 'dan Sebanya, Yosafat, Netaneel, Amasai, Zakharia, Benaya dan Eliezer, yakni imam-imam itu, meniup nafiri di hadapan tabut Allah, sedang Obed-Edom dan Yehia adalah penunggu pintu pada tabut itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 25, 'Maka Daud dan para tua-tua Israel dan para pemimpin pasukan seribu pergi untuk mengangkut tabut perjanjian TUHAN itu dari rumah Obed-Edom dengan sukacita.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 26, 'Dan oleh karena Allah menolong orang Lewi yang mengangkat tabut perjanjian TUHAN itu, maka dipersembahkanlah tujuh ekor lembu jantan dan tujuh ekor domba jantan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 27, 'Daud memakai jubah dari kain lenan halus, juga segala orang Lewi yang mengangkat tabut itu dan para penyanyi, dan Kenanya yang mengepalai pengangkutan dan para penyanyi. Daud juga memakai baju efod dari kain lenan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 28, 'Seluruh orang Israel mengangkut tabut perjanjian TUHAN itu dengan diiringi sorak dan bunyi sangkakala, nafiri dan ceracap, sambil memperdengarkan permainan gambus dan kecapi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 15, 29, 'Ketika tabut perjanjian TUHAN itu sampai ke kota Daud, maka Mikhal, anak perempuan Saul, menjenguk dari jendela, lalu melihat raja Daud melompat-lompat dan menari-nari. Sebab itu ia memandang rendah Daud dalam hatinya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 1, 'Tabut Allah itu dibawa masuk, lalu diletakkan di tengah-tengah kemah yang dipasang Daud untuk itu, kemudian mereka mempersembahkan korban bakaran dan korban keselamatan di hadapan Allah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 2, 'Setelah Daud selesai mempersembahkan korban bakaran dan korban keselamatan, diberkatinyalah bangsa itu demi nama TUHAN.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 3, 'Lalu dibagikannya kepada setiap orang Israel, baik laki-laki maupun perempuan, kepada masing-masing sekeping roti, sekerat daging dan sepotong kue kismis.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 4, 'Juga diangkatnya dari orang Lewi itu beberapa orang sebagai pelayan di hadapan tabut TUHAN untuk memasyhurkan TUHAN, Allah Israel dan menyanyikan syukur dan puji-pujian bagi-Nya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 5, 'Kepala ialah Asaf dan sebagai orang kedua ialah Zakharia; lalu Yeiel, Semiramot, Yehiel, Matica, Eliab, Benaya, Obed-Edom dan Yeiel yang harus memainkan gambus dan kecapi, sedang Asaf harus memainkan ceracap', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 6, 'dan Benaya serta Yahaziel, imam-imam itu, selalu harus meniup nafiri di hadapan tabut perjanjian Allah itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 7, 'Kemudian pada hari itu juga, maka Daud untuk pertama kali menyuruh Asaf dan saudara-saudara sepuaknya menyanyikan syukur bagi TUHAN:', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 8, 'Bersyukurlah kepada TUHAN, panggillah nama-Nya, perkenalkanlah perbuatan-Nya di antara bangsa-bangsa!', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 9, 'Bernyanyilah bagi-Nya, bermazmurlah bagi-Nya, percakapkanlah segala perbuatan-Nya yang ajaib!', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 10, 'Bermegahlah di dalam nama-Nya yang kudus, biarlah bersukahati orang-orang yang mencari TUHAN!', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 11, 'Carilah TUHAN dan kekuatan-Nya, carilah wajah-Nya selalu!', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 12, 'Ingatlah perbuatan-perbuatan ajaib yang dilakukan-Nya, mujizat-mujizat-Ny dan penghukuman-penghukuman yang diucapkan-Nya,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 13, 'hai anak cucu Israel, hamba-Nya, hai anak-anak Yakub, orang-orang pilihan-Nya!', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 14, 'Dialah TUHAN, Allah kita, di seluruh bumi berlaku penghukuman-Nya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 15, 'Ia ingat untuk selama-lamanya akan perjanjian-Nya, akan firman yang diperintahkan-Nya kepada seribu angkatan,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 16, 'yang diikat-Nya dengan Abraham, dan akan sumpah-Nya kepada Ishak,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 17, 'diadakan-Nya bagi Yakub menjadi ketetapan, bagi Israel menjadi perjanjian kekal,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 18, 'firman-Nya: "Kepadamu akan Kuberi tanah Kanaan sebagai milik pusaka yang ditentukan bagimu."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 19, 'Ketika jumlah mereka tidak seberapa, sedikit saja, dan mereka orang-orang asing di sana,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 20, 'dan mengembara dari bangsa yang satu ke bangsa yang lain, dan dari kerajaan yang satu ke suku bangsa yang lain,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 21, 'Ia tidak membiarkan siapapun memeras mereka; dihukum-Nya raja-raja oleh karena mereka:', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 22, '"Jangan mengusik orang-orang yang Kuurapi, dan jangan berbuat jahat terhadap nabi-nabi-Ku!"', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 23, 'Bernyanyilah bagi TUHAN, hai segenap bumi, kabarkanlah keselamatan yang dari pada-Nya dari hari ke hari.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 24, 'Ceritakanlah kemuliaan-Nya di antara bangsa-bangsa dan perbuatan-perbuata yang ajaib di antara segala suku bangsa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 25, 'Sebab besar TUHAN dan terpuji sangat, dan lebih dahsyat Ia dari pada segala allah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 26, 'Sebab segala allah bangsa-bangsa adalah berhala, tetapi Tuhanlah yang menjadikan langit.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 27, 'Keagungan dan semarak ada di hadapan-Nya, kekuatan dan sukacita ada di tempat-Nya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 28, 'Kepada TUHAN, hai suku-suku bangsa, kepada TUHAN sajalah kemuliaan dan kekuatan!', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 29, 'Berilah kepada TUHAN kemuliaan nama-Nya, bawalah persembahan dan masuklah menghadap Dia! Sujudlah menyembah kepada TUHAN dengan berhiaskan kekudusan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 30, 'Gemetarlah di hadapan-Nya hai segenap bumi; sungguh tegak dunia, tidak bergoyang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 31, 'Biarlah langit bersukacita dan bumi bersorak-sorak, biarlah orang berkata di antara bangsa-bangsa: "TUHAN itu Raja!"', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 32, 'Biarlah gemuruh laut serta isinya, biarlah beria-ria padang dan segala yang di atasnya,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 33, 'maka pohon-pohon di hutan bersorak-sorai di hadapan TUHAN, sebab Ia datang untuk menghakimi bumi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 34, 'Bersyukurlah kepada TUHAN, sebab Ia baik! Bahwasanya untuk selama-lamanya kasih setia-Nya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 35, 'Dan katakanlah: "Selamatkanlah kami, ya TUHAN Allah, Penyelamat kami, dan kumpulkanlah dan lepaskanlah kami dari antara bangsa-bangsa, supaya kami bersyukur kepada nama-Mu yang kudus, dan bermegah dalam puji-pujian kepada-Mu."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 36, 'Terpujilah TUHAN, Allah Israel, dari selama-lamanya sampai selama-lamanya. Maka seluruh umat mengatakan: "Amin! Pujilah TUHAN!"', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 37, 'Lalu Daud meninggalkan di sana di hadapan tabut perjanjian TUHAN itu Asaf dan saudara-saudara sepuaknya untuk tetap melayani di hadapan tabut itu seperti yang patut dilakukan setiap hari;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 38, 'juga Obed-Edom dan saudara-saudara sepuaknya yang enam puluh delapan orang itu; Obed-Edom bin Yedutun dan Hosa adalah penunggu-penunggu pintu gerbang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 39, 'Tetapi Zadok, imam itu, dan saudara-saudara sepuaknya, para imam, ditinggalkannya di hadapan Kemah Suci TUHAN di bukit pengorbanan yang di Gibeon,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 40, 'supaya pagi dan petang tetap dipersembahkan korban bakaran kepada TUHAN di atas mezbah korban bakaran, dan supaya dikerjakan segala yang tertulis dalam Taurat TUHAN yang diperintahkan-Nya kepada orang Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 41, 'Dan bersama-sama mereka ikut Heman dan Yedutun dan selebihnya dari orang-orang yang terpilih, yang ditunjuk dengan disebut namanya untuk menyanyikan: "Syukur bagi TUHAN. Bahwasanya untuk selama-lamanya kasih setia-Nya."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 42, 'Pada Heman dan Yedutun itu ada nafiri dan ceracap untuk para pemain, juga alat-alat musik pengiring nyanyian untuk Allah. Dan anak-anak Yedutun harus menjaga pintu gerbang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 16, 43, 'Sesudah itu pergilah seluruh bangsa itu masing-masing ke rumahnya, dan Daud pulang untuk memberi salam kepada seisi rumahnya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 1, 'Setelah Daud menetap di rumahnya, berkatalah ia kepada nabi Natan: "Lihatlah, aku ini diam dalam rumah dari kayu aras, padahal tabut perjanjian TUHAN itu ada di bawah tenda-tenda."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 2, 'Lalu berkatalah Natan kepada Daud: "Lakukanlah segala sesuatu yang dikandung hatimu, sebab Allah menyertai engkau."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 3, 'Tetapi pada malam itu juga datanglah firman Allah kepada Natan, demikian:', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 4, '"Pergilah, katakanlah kepada hamba-Ku Daud: Beginilah firman TUHAN: Bukanlah engkau yang akan mendirikan rumah bagi-Ku untuk didiami.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 5, 'Aku tidak pernah diam dalam rumah sejak Aku menuntun orang Israel keluar sampai hari ini, tetapi Aku mengembara dari kemah ke kemah, dan dari kediaman ke kediaman.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 6, 'Selama Aku mengembara bersama-sama seluruh orang Israel, pernahkah Aku mengucapkan firman kepada salah seorang hakim orang Israel, yang Kuperintahkan menggembalakan umat-Ku, demikian: Mengapa kamu tidak mendirikan bagi-Ku rumah dari kayu aras?', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 7, 'Oleh sebab itu, beginilah kaukatakan kepada hamba-Ku Daud: Beginilah firman TUHAN semesta alam: Akulah yang mengambil engkau dari padang, ketika menggiring kambing domba, untuk menjadi raja atas umat-Ku Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 8, 'Aku telah menyertai engkau di segala tempat yang kaujalani dan telah melenyapkan segala musuhmu dari depanmu. Aku akan membuat namamu seperti nama orang-orang besar yang ada di bumi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 9, 'Aku akan menentukan tempat bagi umat-Ku Israel dan akan menanamkannya, sehingga ia dapat diam di tempatnya sendiri dengan tidak lagi dikejutkan dan tidak pula ditekan oleh orang-orang lalim seperti dahulu,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 10, 'sejak Aku mengangkat hakim-hakim atas umat-Ku Israel. Aku akan menundukkan segala musuhmu. Juga Aku beritahukan kepadamu: TUHAN akan membangun suatu keturunan bagimu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 11, 'Apabila umurmu sudah genap untuk pergi mengikuti nenek moyangmu, maka Aku akan membangkitkan keturunanmu yang kemudian, salah seorang anakmu sendiri, dan Aku akan mengokohkan kerajaannya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 12, 'Dialah yang akan mendirikan rumah bagi-Ku dan Aku akan mengokohkan takhtanya untuk selama-lamanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 13, 'Aku akan menjadi Bapanya, dan ia akan menjadi anak-Ku. Tetapi kasih setia-Ku tidak akan Kuhilangkan dari padanya seperti yang Kuhilangkan dari pada orang yang mendahului engkau.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 14, 'Dan Aku akan menegakkan dia dalam rumah-Ku dan dalam kerajaan-Ku untuk selama-lamanya dan takhtanya akan kokoh untuk selama-lamanya."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 15, 'Tepat seperti perkataan ini dan tepat seperti penglihatan ini Natan berbicara kepada Daud.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 16, 'Lalu masuklah raja Daud ke dalam, kemudian duduklah ia di hadapan TUHAN sambil berkata: "Siapakah aku ini, ya TUHAN Allah, dan siapakah keluargaku, sehingga Engkau membawa aku sampai sedemikian ini?', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 17, 'Dan hal ini masih kurang di mata-Mu, ya Allah; sebab itu Engkau telah berfirman juga tentang keluarga hamba-Mu ini dalam masa yang masih jauh dan telah memperlihatkan kepadaku serentetan manusia yang akan datang, ya TUHAN Allah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 18, 'Apakah lagi yang dapat ditambahkan Daud kepada-Mu dalam hal Engkau memuliakan hamba-Mu ini? Bukankah Engkau yang mengenal hamba-Mu ini?', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 19, 'Ya TUHAN, oleh karena hamba-Mu ini dan menurut hati-Mu Engkau telah melakukan segala perkara yang besar ini dengan memberitahukan segala perkara yang besar itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 20, 'Ya TUHAN, tidak ada yang sama seperti Engkau dan tidak ada Allah selain Engkau menurut segala yang kami tangkap dengan telinga kami.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 21, 'Dan bangsa manakah di bumi seperti umat-Mu Israel, yang Allahnya pergi membebaskannya menjadi umat-Nya, untuk mendapat nama bagi-Mu dengan perbuatan-perbuatan yang besar dan dahsyat, dan dengan menghalau bangsa-bangsa dari depan umat-Mu yang telah Kaubebaskan dari Mesir?', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 22, 'Engkau telah membuat umat-Mu Israel menjadi umat-Mu untuk selama-lamanya dan Engkau, ya TUHAN, menjadi Allah mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 23, 'Dan sekarang, ya TUHAN, diteguhkanlah untuk selama-lamanya janji yang Kauucapkan mengenai hamba-Mu ini dan mengenai keluarganya dan lakukanlah seperti yang Kaujanjikan itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 24, 'Maka nama-Mu akan menjadi teguh dan besar untuk selama-lamanya, sehingga orang berkata: TUHAN semesta alam, Allah Israel adalah Allah bagi orang Israel; maka keluarga hamba-Mu Daud akan tetap kokoh di hadapan-Mu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 25, 'Sebab Engkau, ya Allahku, telah menyatakan kepada hamba-Mu ini, bahwa Engkau akan membangun keturunan baginya. Itulah sebabnya hamba-Mu ini telah memberanikan diri untuk memanjatkan doa ke hadapan-Mu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 26, 'Oleh sebab itu, ya TUHAN, Engkaulah Allah dan telah menjanjikan perkara yang baik ini kepada hamba-Mu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 17, 27, 'Kiranya Engkau sekarang berkenan memberkati keluarga hamba-Mu ini, supaya tetap ada di hadapan-Mu untuk selama-lamanya. Sebab apa yang Engkau berkati, ya TUHAN, diberkati untuk selama-lamanya."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 1, 'Sesudah itu Daud memukul kalah orang Filistin dan menundukkan mereka; lalu ia merebut Gat dan segala anak kotanya dari tangan orang Filistin.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 2, 'Dan Daud memukul kalah orang Moab, sehingga orang Moab takluk kepadanya dan harus mempersembahkan upeti.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 3, 'Selanjutnya Daud memukul kalah Hadadezer, raja Zoba, dekat Hamat, ketika ia pergi menegakkan kekuasaannya pada sungai Efrat.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 4, 'Daud merebut dari padanya seribu kereta, tujuh ribu orang pasukan berkuda dan dua puluh ribu orang pasukan berjalan kaki, lalu Daud menyuruh memotong urat keting segala kuda kereta, tetapi dengan meninggalkan seratus ekor kuda kereta.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 5, 'Lalu orang Aram dari Damsyik datang menolong Hadadezer, raja Zoba, tetapi dari antara orang Aram itu Daud menewaskan dua puluh dua ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 6, 'Kemudian Daud menempatkan pasukan-pasukan pendudukan di daerah orang Aram dari Damsyik, dan orang Aram itu menjadi budak Daud yang harus mempersembahkan upeti. TUHAN memberi kemenangan kepada Daud ke manapun ia pergi berperang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 7, 'Sesudah itu Daud mengangkut perisai-perisai emas yang dipakai oleh orang-orang Hadadezer, lalu membawanya ke Yerusalem.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 8, 'Dan dari Tibhat dan dari Kun, yaitu kota-kotanya Hadadezer, Daud mengangkut amat banyak tembaga; dari padanya Salomo membuat "laut" tembaga, tiang-tiang dan perlengkapan tembaga.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 9, 'Ketika didengar Tou, raja Hamat, bahwa Daud telah memukul kalah seluruh tentara Hadadezer, raja Zoba,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 10, 'maka ia mengutus Hadoram, anaknya, kepada raja Daud untuk menyampaikan salam dan mengucapkan selamat kepadanya, karena ia telah berperang melawan Hadadezer dan memukul dia kalah, sebab Hadadezer sering memerangi Tou. Dan Hadoram membawa pelbagai barang-barang emas, perak dan tembaga.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 11, 'Juga barang-barang ini dikhususkan raja Daud bagi TUHAN, bersama-sama perak dan emas yang diangkutnya dari segala bangsa, yakni dari orang Edom, dari orang Moab, dari bani Amon, dari orang Filistin dan dari orang Amalek.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 12, 'Abisai, anak Zeruya, menewaskan delapan belas ribu orang Edom di Lembah Asin.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 13, 'Lalu ia menempatkan pasukan-pasukan pendudukan di Edom, sehingga seluruh Edom diperbudak oleh Daud. TUHAN memberi kemenangan kepada Daud ke manapun ia pergi berperang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 14, 'Demikianlah Daud telah memerintah atas seluruh Israel, dan menegakkan keadilan dan kebenaran bagi seluruh bangsanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 15, 'Yoab, anak Zeruya, menjadi panglima; Yosafat bin Ahilud menjadi bendahara;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 16, 'Zadok bin Ahitub dan Ahimelekh bin Abyatar menjadi imam; Sausa menjadi panitera;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 18, 17, 'Benaya bin Yoyada menjadi panglima orang Kreti dan orang Pleti; dan anak-anak Daud adalah orang-orang utama yang diperbantukan kepada raja.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 1, 'Sesudah itu matilah Nahas, raja bani Amon, lalu anaknya menjadi raja menggantikan dia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 2, 'Lalu berkatalah Daud: "Aku akan menunjukkan persahabatan kepada Hanun bin Nahas, sebab ayahnya telah menunjukkan persahabatan kepadaku." Sebab itu Daud mengirim utusan untuk menyampaikan pesan turut berdukacita kepadanya karena kematian ayahnya. Tetapi ketika pegawai-pegawai Daud sampai ke negeri bani Amon itu, kepada Hanun, untuk menyampaikan pesan turut berdukacita kepadanya,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 3, 'berkatalah pemuka-pemuka bani Amon itu kepada Hanun: "Apakah menurut anggapanmu Daud hendak menghormati ayahmu, karena ia telah mengutus kepadamu orang-orang yang menyampaikan pesan turut berdukacita? Bukankah dengan maksud untuk menyelidik, untuk mengintai dan menghancurkan negeri ini maka pegawai-pegawainya datang kepadamu?"', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 4, 'Lalu Hanun menyuruh menangkap pegawai-pegawai Daud itu, disuruhnya mencukur mereka dan memotong pakaian mereka pada bagian tengah sampai pangkal paha mereka, kemudian dilepasnya mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 5, 'Ketika mereka berjalan pulang, diberitahukan kepada Daud tentang orang-orang itu, lalu disuruhnya orang menemui mereka, sebab orang-orang itu sangat dipermalukan. Raja berkata: "Tinggallah di Yerikho sampai janggutmu itu tumbuh, kemudian datanglah kembali."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 6, 'Setelah dilihat bani Amon, bahwa mereka telah membuat dirinya dibenci oleh Daud, maka Hanun dan bani Amon itu mengirim seribu talenta perak untuk menyewa kereta dan orang-orang berkuda dari Aram-Mesopotamia, dari Aram-Maakha dan dari Aram-Zoba.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 7, 'Mereka menyewa tiga puluh dua ribu kereta, serta raja negeri Maakha dengan tentaranya, yang datang berkemah dekat Medeba. Juga bani Amon itu berkumpul dari kota-kota mereka dan datang untuk berperang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 8, 'Ketika Daud mendengar hal itu, disuruhnyalah Yoab maju dengan segenap tentara dan pahlawan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 9, 'Lalu bani Amon maju, diaturnya barisan perangnya di depan pintu kota, sedang raja-raja yang ikut datang ada tersendiri di padang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 10, 'Ketika Yoab melihat, bahwa serangan itu mengancam dia dari depan dan dari belakang, maka dipilihnyalah sebagian dari orang pilihan Israel, lalu ia mengatur barisan mereka berhadapan dengan orang Aram itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 11, 'Selebihnya dari rakyat itu ditempatkannya di bawah pimpinan Abisai, adiknya, dan mereka mengatur barisannya berhadapan dengan bani Amon itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 12, 'Lalu berkatalah Yoab: "Jika orang Aram itu lebih kuat dari padaku, maka haruslah engkau menolong aku, tetapi jika bani Amon itu lebih kuat dari padamu, maka aku akan menolong engkau.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 13, 'Kuatkanlah hatimu dan marilah kita menguatkan hati untuk bangsa kita dan untuk kota-kota Allah kita. TUHAN kiranya melakukan yang baik di mata-Nya."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 14, 'Lalu Yoab dan tentara yang bersama-sama dengan dia maju menghadapi orang Aram itu untuk berperang dan orang-orang itu melarikan diri dari hadapannya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 15, 'Ketika bani Amon melihat, bahwa orang Aram sudah melarikan diri, maka merekapun larilah dari hadapan Abisai, adik Yoab, dan masuk ke dalam kota. Sesudah itu Yoab pulang ke Yerusalem.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 16, 'Ketika orang Aram melihat, bahwa mereka telah terpukul kalah oleh orang Israel, maka mereka mengirim utusan-utusan dan menyuruh orang Aram yang di seberang sungai Efrat maju berperang di bawah pimpinan Sofakh, panglima tentara Hadadezer.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 17, 'Setelah hal itu diberitahukan kepada Daud, maka dikumpulkannya seluruh orang Israel, diseberanginya sungai Yordan, lalu sampai ke dekat mereka, dan diaturnya barisannya melawan mereka. Ketika Daud mengatur barisannya berhadapan dengan orang Aram itu untuk berperang, maka mereka bertempur melawan dia,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 18, 'tetapi orang Aram itu lari dari hadapan orang Israel, dan Daud membunuh dari orang Aram itu tujuh ribu ekor kuda kereta dan empat puluh ribu orang pasukan berjalan kaki; juga Sofakh, panglima tentara itu, dibunuhnya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 19, 19, 'Ketika dilihat orang-orang yang takluk kepada Hadadezer, bahwa mereka telah terpukul kalah oleh orang Israel, maka mereka mengadakan perdamaian dengan Daud dan takluk kepadanya; sesudah itu orang Aram tidak mau lagi memberi pertolongan kepada bani Amon.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 20, 1, 'Pada pergantian tahun, pada waktu raja-raja biasanya maju berperang, maka Yoab membawa keluar bala tentaranya, lalu ia memusnahkan negeri bani Amon, kemudian ia maju dan mengepung kota Raba, sedang Daud sendiri tinggal di Yerusalem. Yoab memukul kalah Raba dan meruntuhkannya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 20, 2, 'Sesudah itu Daud mengambil mahkota dari kepala raja mereka, beratnya ternyata setalenta emas, bertatahkan sebuah batu permata yang mahal dan itu dikenakan pada kepala Daud. Juga diangkutnya banyak sekali jarahan dari kota itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 20, 3, 'Penduduk kota itu diangkutnya dan dipaksanya bekerja dengan gergaji, penggerek besi dan kapak. Demikianlah juga diperlakukan Daud segala kota bani Amon. Sesudah itu pulanglah Daud dengan seluruh tentara ke Yerusalem.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 20, 4, 'Sesudah itu timbullah pertempuran melawan orang Filistin di Gezer; pada waktu itu Sibkhai, orang Husa, memukul kalah Sipai, seorang dari keturunan raksasa, dan mereka ditundukkan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 20, 5, 'Maka terjadilah lagi pertempuran melawan orang Filistin, lalu Elhanan bin Yair menewaskan Lahmi, saudara Goliat, orang Gat itu, yang gagang tombaknya seperti pesa tukang tenun.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 20, 6, 'Lalu terjadi lagi pertempuran di Gat; dan di sana ada seorang yang tinggi perawakannya, yang tangannya dan kakinya masing-masing berjari enam: dua puluh empat seluruhnya; juga orang ini termasuk keturunan raksasa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 20, 7, 'Ia mengolok-olok orang Israel, maka Yonatan, anak Simea kakak Daud, menewaskannya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 20, 8, 'Orang-orang ini termasuk keturunan raksasa di Gat; mereka tewas oleh tangan Daud dan oleh tangan orang-orangnya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 1, 'Iblis bangkit melawan orang Israel dan ia membujuk Daud untuk menghitung orang Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 2, 'Lalu berkatalah Daud kepada Yoab dan kepada para pemuka rakyat: "Pergilah, hitunglah orang Israel dari Bersyeba sampai Dan, dan bawalah hasilnya kepadaku, supaya aku tahu jumlah mereka."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 3, 'Lalu berkatalah Yoab: "Kiranya TUHAN menambahi rakyat-Nya seratus kali lipat dari pada yang ada sekarang. Ya tuanku raja, bukankah mereka sekalian, hamba-hamba tuanku? Mengapa tuanku menuntut hal ini? Mengapa orang Israel harus menanggung kesalahan oleh karena hal itu?"', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 4, 'Namun titah raja itu terpaksa diikuti oleh Yoab, maka pergilah Yoab menjelajahi seluruh Israel, kemudian kembali ke Yerusalem.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 5, 'Lalu Yoab memberitahukan kepada Daud hasil pendaftaran rakyat. Di antara seluruh orang Israel ada sejuta seratus ribu orang yang dapat memegang pedang, dan orang Yehuda ada empat ratus tujuh puluh ribu orang yang dapat memegang pedang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 6, 'Orang Lewi dan Benyamin tidak dimasukkannya dalam pendaftaran, sebab titah raja itu dianggap keji oleh Yoab.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 7, 'Tetapi hal itu jahat di mata Allah, sebab itu dihajar-Nya orang Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 8, 'Lalu berkatalah Daud kepada Allah: "Aku telah sangat berdosa karena melakukan hal ini; maka sekarang, jauhkanlah kiranya kesalahan hamba-Mu, sebab perbuatanku itu sangat bodoh."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 9, 'Tetapi berfirmanlah TUHAN kepada Gad, pelihat Daud:', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 10, '"Pergilah, katakanlah kepada Daud: Beginilah firman TUHAN: tiga perkara Kuhadapkan kepadamu; pilihlah salah satu dari padanya, maka Aku akan melakukannya kepadamu."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 11, 'Kemudian datanglah Gad kepada Daud, lalu berkatalah ia kepadanya: "Beginilah firman TUHAN: Haruslah engkau memilih:', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 12, 'tiga tahun kelaparan atau tiga bulan lamanya melarikan diri dari hadapan lawanmu, sedang pedang musuhmu menyusul engkau, atau tiga hari pedang TUHAN, yakni penyakit sampar, ada di negeri ini, dan malaikat TUHAN mendatangkan kemusnahan di seluruh daerah orang Israel. Maka sekarang, timbanglah jawab apa yang harus kusampaikan kepada Yang mengutus aku."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 13, 'Lalu berkatalah Daud kepada Gad: "Sangat susah hatiku, biarlah kiranya aku jatuh ke dalam tangan TUHAN, sebab sangat besar kasih sayang-Nya; tetapi janganlah aku jatuh ke dalam tangan manusia."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 14, 'Jadi TUHAN mendatangkan penyakit sampar kepada orang Israel, maka tewaslah dari orang Israel tujuh puluh ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 15, 'Pula Allah mengutus malaikat ke Yerusalem untuk memusnahkannya, dan ketika hendak dimusnahkannya, maka TUHAN melihatnya, lalu menyesallah Ia karena malapetaka yang hendak didatangkan-Nya itu, lalu berfirmanlah Ia kepada malaikat pemusnah itu: "Cukup! Turunkanlah sekarang tanganmu itu!" Pada waktu itu malaikat TUHAN itu sedang berdiri dekat tempat pengirikan Ornan, orang Yebus.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 16, 'Ketika Daud mengangkat mukanya, maka dilihatnyalah malaikat TUHAN berdiri di antara bumi dan langit, dengan di tangannya pedang terhunus yang diacungkan ke atas Yerusalem. Lalu dengan berpakaian kain kabung sujudlah Daud dan para tua-tua.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 17, 'Dan berkatalah Daud kepada Allah: "Bukankah aku ini yang menyuruh menghitung rakyat dan aku sendirilah yang telah berdosa dan yang melakukan kejahatan, tetapi domba-domba ini, apakah yang dilakukan mereka? Ya TUHAN, Allahku, biarlah kiranya tangan-Mu menimpa aku dan kaum keluargaku, tetapi janganlah tulah menimpa umat-Mu."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 18, 'Kemudian malaikat TUHAN menyuruh Gad mengatakan kepada Daud, bahwa Daud harus pergi untuk mendirikan mezbah bagi TUHAN di tempat pengirikan Ornan, orang Yebus itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 19, 'Lalu pergilah Daud, sesuai dengan perkataan Gad yang diucapkannya demi nama TUHAN.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 20, 'Ornan sedang mengirik gandum; ketika ia memalingkan diri, dilihatnyalah malaikat itu; keempat anaknya yang bersama-sama dengan dia menyembunyikan diri.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 21, 'Ketika Daud sampai kepada Ornan, maka Ornan mengangkat mukanya dan melihat Daud, lalu keluarlah ia dari tempat pengirikan, kemudian sujudlah ia kepada Daud dengan mukanya ke tanah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 22, 'Berkatalah Daud kepada Ornan: "Berikanlah kepadaku tempat pengirikan ini, supaya aku mendirikan di sini mezbah bagi TUHAN; baiklah berikan itu kepadaku dengan harga penuh, supaya tulah ini berhenti menimpa rakyat."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 23, 'Jawab Ornan kepada Daud: "Ambillah, dan baiklah tuanku raja melakukan apa yang dipandangnya baik. Lihatlah, aku berikan lembu ini untuk korban bakaran dan eretan-eretan pengirik ini untuk kayu bakar dan gandum untuk korban sajian, semuanya itu kuberikan."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 24, 'Tetapi berkatalah raja Daud kepada Ornan: "Bukan begitu, melainkan aku mau membelinya dengan harga penuh, sebab aku tidak mau mengambil milikmu untuk TUHAN dan tidak mau mempersembahkan korban bakaran dengan tidak membayar apa-apa."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 25, 'Maka Daud memberikan kepada Ornan sebagai bayaran tempat itu emas seberat enam ratus syikal.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 26, 'Lalu Daud mendirikan di sana mezbah bagi TUHAN, mempersembahkan korban bakaran dan korban keselamatan dan memanggil TUHAN. Maka TUHAN menjawab dia dengan menurunkan api dari langit ke atas mezbah korban bakaran itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 27, 'Lalu berfirmanlah TUHAN kepada malaikat itu supaya dikembalikannya pedangnya ke dalam sarungnya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 28, 'Pada waktu itu juga Daud mempersembahkan korban di sana, ketika ia melihat, bahwa TUHAN telah menjawab dia di tempat pengirikan Ornan, orang Yebus itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 29, 'Kemah Suci, yang dibuat Musa di padang gurun, dan mezbah korban bakaran pada waktu itu ada di bukit pengorbanan di Gibeon,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 21, 30, 'tetapi Daud tidak berani pergi ke sana berhadapan dengan Allah untuk menanyakan petunjuk-Nya, sebab ia takut kepada pedang malaikat TUHAN itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 1, 'Lalu berkatalah Daud: "Di sinilah rumah TUHAN, Allah kita, dan di sinilah mezbah untuk korban bakaran orang Israel."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 2, 'Daud menyuruh mengumpulkan orang-orang asing yang ada di negeri orang Israel, lalu ditempatkannya tukang-tukang untuk memahat batu-batu pahat yang akan dipakai untuk mendirikan rumah Allah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 3, 'Selanjutnya Daud menyediakan sangat banyak besi untuk paku-paku bagi daun pintu gerbang dan bagi tupai-tupai, juga sangat banyak tembaga yang tidak tertimbang beratnya,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 4, 'dan kayu aras yang tidak terbilang banyaknya, sebab orang Sidon dan orang Tirus membawa sangat banyak kayu aras bagi Daud.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 5, 'Karena pikir Daud: "Salomo, anakku, masih muda dan kurang berpengalaman, dan rumah yang harus didirikannya bagi TUHAN haruslah luar biasa besarnya sehingga menjadi kenamaan dan termasyhur di segala negeri; sebab itu baiklah aku mengadakan persediaan baginya!" Lalu Daud membuat sangat banyak persediaan sebelum ia mati.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 6, 'Kemudian dipanggilnya Salomo, anaknya, dan diberinya perintah kepadanya untuk mendirikan rumah bagi TUHAN, Allah Israel,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 7, 'kata Daud kepada Salomo: "Anakku, aku sendiri bermaksud hendak mendirikan rumah bagi nama TUHAN, Allahku,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 8, 'tetapi firman TUHAN datang kepadaku, demikian: Telah kautumpahkan sangat banyak darah dan telah kaulakukan peperangan yang besar; engkau tidak akan mendirikan rumah bagi nama-Ku, sebab sudah banyak darah kautumpahkan ke tanah di hadapan-Ku.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 9, 'Sesungguhnya, seorang anak laki-laki akan lahir bagimu; ia akan menjadi seorang yang dikaruniai keamanan. Aku akan mengaruniakan keamanan kepadanya dari segala musuhnya di sekeliling. Ia akan bernama Salomo; sejahtera dan sentosa akan Kuberikan atas Israel pada zamannya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 10, 'Dialah yang akan mendirikan rumah bagi nama-Ku dan dialah yang akan menjadi anak-Ku dan Aku akan menjadi Bapanya; Aku akan mengokohkan takhta kerajaannya atas Israel sampai selama-lamanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 11, 'Maka sekarang, hai anakku, TUHAN kiranya menyertai engkau, sehingga engkau berhasil mendirikan rumah TUHAN, Allahmu, seperti yang difirmankan-Nya mengenai engkau.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 12, 'Hanya, TUHAN kiranya memberikan kepadamu akal budi dan pengertian dan membuat engkau menjadi pemegang perintah atas Israel, supaya engkau memelihara Taurat TUHAN, Allahmu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 13, 'Maka engkau akan berhasil, jika engkau melakukan dengan setia ketetapan-ketetapan dan hukum-hukum yang diperintahkan TUHAN kepada Musa untuk orang Israel. Kuatkan dan teguhkanlah hatimu, janganlah takut dan janganlah tawar hati.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 14, 'Sesungguhnya, sekalipun dalam kesusahan, aku telah menyediakan untuk rumah TUHAN itu seratus ribu talenta emas dan sejuta talenta perak dan sangat banyak tembaga dan besi, sehingga beratnya tidak tertimbang; juga aku telah menyediakan kayu dan batu. Tetapi baiklah engkau menambahnya lagi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 15, 'Lagipula engkau mempunyai sangat banyak pekerja, yakni pemahat-pemahat batu, tukang-tukang batu dan kayu dan orang-orang yang ahli dalam segala macam pekerjaan', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 16, 'emas, perak, tembaga dan besi, yang tidak terhitung banyaknya. Mulailah bekerja! TUHAN kiranya menyertai engkau!"', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 17, 'Dan Daud memberi perintah kepada segala pembesar Israel itu untuk memberi bantuan kepada Salomo, anaknya, katanya:', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 18, '"Bukankah TUHAN, Allahmu, menyertai kamu dan telah mengaruniakan keamanan kepadamu ke segala penjuru. Sungguh, Ia telah menyerahkan penduduk negeri ini ke dalam tanganku, sehingga negeri ini takluk ke hadapan TUHAN dan kepada umat-Nya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 22, 19, 'Maka sekarang, arahkanlah hati dan jiwamu untuk mencari TUHAN, Allahmu. Mulailah mendirikan tempat kudus TUHAN, Allah, supaya tabut perjanjian TUHAN dan perkakas kudus Allah dapat dibawa masuk ke dalam rumah yang didirikan bagi nama TUHAN."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 1, 'Setelah Daud menjadi tua dan lanjut umur, maka diangkatnya Salomo menjadi raja atas Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 2, 'Ia mengumpulkan segala pembesar Israel, juga para imam dan orang-orang Lewi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 3, 'Lalu dihitunglah orang-orang Lewi, yang berumur tiga puluh tahun ke atas, dan jumlah orang-orang mereka, dihitung satu demi satu, ada tiga puluh delapan ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 4, '?"Dari orang-orang ini dua puluh empat ribu orang harus mengawasi pekerjaan di rumah TUHAN; enam ribu orang harus menjadi pengatur dan hakim;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 5, 'empat ribu orang menjadi penunggu pintu gerbang; dan empat ribu orang menjadi pemuji TUHAN dengan alat-alat musik yang telah kubuat untuk melagukan puji-pujian," kata Daud.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 6, 'Juga Daud membagi-bagi mereka dalam rombongan menurut anak-anak Lewi, yakni Gerson, Kehat dan Merari.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 7, 'Termasuk orang Gerson ialah Ladan dan Simei.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 8, 'Anak-anak Ladan ialah Yehiel, seorang kepala, serta Zetam dan Yoel, tiga orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 9, 'Anak-anak Simei ialah Selomit, Haziel dan Haran, tiga orang; orang-orang inilah yang menjadi kepala puak Ladan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 10, 'Anak-anak Simei ialah Yahat, Ziza, Yeush dan Beria; itulah anak-anak Simei, empat orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 11, 'Yahat ialah kepala dan Ziza orang kedua, tetapi Yeush dan Beria tidak mempunyai banyak anak, maka mereka merupakan hanya satu puak dengan satu jabatan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 12, 'Anak-anak Kehat ialah Amram, Yizhar, Hebron dan Uziel, empat orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 13, 'Anak-anak Amram ialah Harun dan Musa; Harun ditunjuk untuk mengurus apa yang maha kudus, dia dan keturunannya, sampai selama-lamanya, untuk membakar korban di hadapan TUHAN, untuk melayani Dia dan untuk memberi berkat demi nama-Nya, sampai selama-lamanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 14, 'Anak-anak Musa, abdi Allah itu, digolongkan kepada suku Lewi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 15, 'Anak-anak Musa ialah Gersom dan Eliezer.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 16, 'Anak Gersom ialah Sebuel, seorang kepala.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 17, 'Anak Eliezer ialah Rehabya, seorang kepala; Eliezer tidak mempunyai anak-anak lain, tetapi anak-anak Rehabya luar biasa banyaknya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 18, 'Anak Yizhar ialah Selomit, seorang kepala.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 19, 'Anak-anak Hebron ialah Yeria, seorang kepala, Amarya, anak yang kedua, Yahaziel, anak yang ketiga dan Yekameam, anak yang keempat.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 20, 'Anak-anak Uziel ialah Mikha, seorang kepala, dan Yisia, anak yang kedua.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 21, 'Anak-anak Merari ialah Mahli dan Musi. Anak-anak Mahli ialah Eleazar dan Kish.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 22, 'Ketika Eleazar mati, ia tidak mempunyai anak laki-laki, hanya anak perempuan, lalu anak-anak Kish, saudara sepupu mereka, mengambil mereka menjadi isteri.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 23, 'Anak-anak Musi ialah Mahli, Eder dan Yeremot, tiga orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 24, 'Itulah bani Lewi menurut puak mereka, kepala-kepala puak mereka, pada waktu mereka dicatat seorang-seorang sesuai dengan bilangan nama mereka, orang demi orang, yang berumur dua puluh tahun atau lebih, merekalah yang harus melakukan pekerjaan untuk ibadah di rumah TUHAN.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 25, 'Sebab Daud telah berkata: "TUHAN, Allah Israel, telah mengaruniakan keamanan kepada umat-Nya, dan Ia diam di Yerusalem sampai selama-lamanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 26, 'Dengan demikian tidak usah lagi orang Lewi mengangkat Bait Suci dan segala perkakas yang dipakai untuk ibadah di situ." ?', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 27, 'Sebab sesuai dengan titah Daud yang belakangan, mereka yang didaftarkan dari anak-anak Lewi ialah yang berumur dua puluh tahun ke atas. ?', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 28, '"Tugas mereka ialah membantu anak-anak Harun untuk menyelenggarakan ibadah di rumah TUHAN, mengawasi pelataran, bilik-bilik dan pentahiran segala barang kudus serta melakukan pekerjaan yang berhubungan dengan ibadah di rumah Allah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 29, 'Juga mereka harus menyediakan sajian dan tepung yang terbaik untuk korban sajian, roti tipis yang tidak beragi, apa yang dipanggang di atas panggangan, apa yang teraduk dan segala sukatan dan ukuran.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 30, 'Selanjutnya mereka bertugas menyanyikan syukur dan puji-pujian bagi TUHAN setiap pagi, demikian juga pada waktu petang', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 31, 'dan pada waktu mempersembahkan segala korban bakaran kepada TUHAN, pada hari-hari Sabat, bulan-bulan baru, dan hari-hari raya, menurut jumlah yang sesuai dengan peraturan yang berlaku bagi mereka, sebagai tugas tetap di hadapan TUHAN.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 23, 32, 'Mereka harus melakukan pemeliharaan Kemah Pertemuan serta tempat kudus dan harus melayani anak-anak Harun, saudara-saudara mereka, untuk menyelenggarakan ibadah di rumah TUHAN."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 1, 'Inilah rombongan-rombongan anak-anak Harun. Anak-anak Harun ialah Nadab, Abihu, Eleazar dan Itamar.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 2, 'Tetapi Nadab dan Abihu mati lebih dahulu dari pada ayah mereka dengan tidak mempunyai anak laki-laki, maka yang memegang jabatan imam ialah Eleazar dan Itamar.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 3, 'Daud, bersama-sama Zadok dari bani Eleazar dan Ahimelekh dari bani Itamar, membagi-bagi mereka menurut jabatan mereka dalam penyelenggaraan ibadah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 4, 'Lalu ternyata bahwa di antara keturunan Eleazar ada lebih banyak kepala kaum dari pada di antara keturunan Itamar, sebab itu orang membagi-bagi mereka sebagai berikut: untuk bani Eleazar enam belas orang kepala puak, tetapi untuk bani Itamar delapan orang kepala puak.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 5, 'Dan orang membagi-bagi mereka dengan membuang undi tanpa mengadakan perbedaan, sebab ada "pemimpin-pemimpin kudus" dan "pemimpin-pemimpin Allah", baik di antara keturunan Eleazar maupun di antara keturunan Itamar.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 6, 'Dan Semaya bin Netaneel, panitera itu, seorang Lewi, menulis nama mereka di depan raja, di depan pembesar-pembesar, imam Zadok, Ahimelekh bin Abyatar dan di depan kepala-kepala puak para imam dan orang Lewi; setiap kali satu puak diambil dari Eleazar, dan demikian pula satu puak dari Itamar.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 7, 'Undian yang pertama jatuh pada Yoyarib; yang kedua pada Yedaya;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 8, 'yang ketiga pada Harim; yang keempat pada Seorim;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 9, 'yang kelima pada Malkia; yang keenam pada Miyamin;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 10, 'yang ketujuh pada Hakos; yang kedelapan pada Abia;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 11, 'yang kesembilan pada Yesua; yang kesepuluh pada Sekhanya;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 12, 'yang kesebelas pada Elyasib; yang kedua belas pada Yakim;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 13, 'yang ketiga belas pada Hupa; yang keempat belas pada Yesebeab;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 14, 'yang kelima belas pada Bilga; yang keenam belas pada Imer;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 15, 'yang ketujuh belas pada Hezir; yang kedelapan belas pada Hapizes;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 16, 'yang kesembilan belas pada Petahya; yang kedua puluh pada Yehezkel;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 17, 'yang kedua puluh satu pada Yakhin; yang kedua puluh dua pada Gamul;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 18, 'yang kedua puluh tiga pada Delaya; yang kedua puluh empat pada Maazya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 19, 'Itulah jabatan mereka dalam menyelenggarakan ibadah setelah mereka masuk rumah TUHAN, sesuai dengan peraturan yang diberikan kepada mereka dengan perantaraan Harun, bapa leluhur mereka, seperti yang diperintahkan kepadanya oleh TUHAN, Allah Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 20, 'Golongan yang masih tinggal dari bani Lewi, dari anak-anak Amram ialah Subael, dari anak-anak Subael ialah Yehdeya;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 21, 'dari anak-anak Rehabya ialah Yisia, seorang kepala;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 22, 'dari orang Yizhar ialah Selomot; dari anak-anak Selomot ialah Yahat.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 23, 'Anak-anak Hebron ialah Yeria, seorang kepala, Amarya, anak yang kedua, Yahaziel, anak yang ketiga, dan Yekameam, anak yang keempat.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 24, 'Anak Uziel ialah Mikha; dari anak-anak Mikha ialah Samir.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 25, 'Saudara Mikha ialah Yisia; dari anak-anak Yisia ialah Zakharia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 26, 'Keturunan Merari ialah Mahli dan Musi, juga anak-anak Yaazia, anaknya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 27, 'Keturunan Merari dari pihak Yaazia, anaknya, ialah Syoham, Zakur dan Hibri.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 28, 'Dari Mahli ialah Eleazar; dia ini tidak mempunyai anak.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 29, 'Dari Kish: anak Kish, yakni Yerahmeel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 30, 'Anak-anak Musi ialah Mahli, Eder dan Yerimot. Itulah bani Lewi menurut puak mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 24, 31, 'Mereka inipun, sama seperti saudara-saudara sesuku mereka, anak-anak Harun, membuang undi di depan raja Daud, di depan Zadok, Ahimelekh dan para kepala puak, para imam dan orang Lewi. Dalam hal ini seorang kepala puak sama dengan saudaranya yang terkecil.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 1, 'Selanjutnya untuk ibadah Daud dan para panglima menunjuk anak-anak Asaf, anak-anak Heman dan anak-anak Yedutun. Mereka bernubuat dengan diiringi kecapi, gambus dan ceracap. Daftar orang-orang yang bekerja dalam ibadah ini ialah yang berikut:', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 2, 'dari anak-anak Asaf ialah Zakur, Yusuf, Netanya dan Asarela, anak-anak Asaf di bawah pimpinan Asaf, yang bernubuat dengan petunjuk raja.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 3, 'Dari Yedutun ialah anak-anak Yedutun: Gedalya, Zeri, Yesaya, Simei, Hasabya dan Matica, enam orang, di bawah pimpinan ayah mereka, Yedutun, yang bernubuat dengan diiringi kecapi pada waktu menyanyikan syukur dan puji-pujian bagi TUHAN.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 4, 'Dari Heman ialah anak-anak Heman: Bukia, Matanya, Uziel, Sebuel, Yerimot, Hananya, Hanani, Eliata, Gidalti, Romamti-Ezer, Yosbekasa, Maloti, Hotir dan Mahaziot.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 5, 'Mereka ini sekalian adalah anak-anak Heman, pelihat raja, menurut janji Allah untuk meninggikan tanduk kekuatannya; sebab Allah telah memberikan kepada Heman empat belas orang anak laki-laki dan tiga orang anak perempuan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 6, 'Mereka ini sekalian berada di bawah pimpinan ayah mereka pada waktu menyanyikan nyanyian di rumah TUHAN dengan diiringi ceracap, gambus dan kecapi untuk ibadah di rumah Allah dengan petunjuk raja. Demikianlah keadaan bani Asaf, Yedutun dan Heman.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 7, 'Jumlah mereka bersama-sama saudara-saudara mereka yang telah dilatih bernyanyi untuk TUHAN?mereka sekalian adalah ahli seni?ada dua ratus delapan puluh delapan orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 8, 'Tua dan muda, guru dan murid, membuang undi mengenai tugasnya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 9, 'Lalu jatuhlah undian yang pertama pada Yusuf, orang Asaf; undian yang kedua pada Gedalya dengan saudara-saudaranya dan anak-anaknya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 10, 'undian yang ketiga pada Zakur, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 11, 'undian yang keempat pada Yizri, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 12, 'undian yang kelima pada Netanya, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 13, 'undian yang keenam pada Bukia, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 14, 'undian yang ketujuh pada Yesarela, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 15, 'undian yang kedelapan pada Yesaya, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 16, 'undian yang kesembilan pada Matanya, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 17, 'undian yang kesepuluh pada Simei, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 18, 'undian yang kesebelas pada Azareel, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 19, 'undian yang kedua belas pada Hasabya, anak-anaknya dan saudara-saudaranya dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 20, 'undian yang ketiga belas pada Subael, anak-anaknya dan saudara-saudaranya dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 21, 'undian yang keempat belas pada Matica, anak-anaknya dan saudara-saudarany dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 22, 'undian yang kelima belas pada Yeremot, anak-anaknya dan saudara-saudarany dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 23, 'undian yang keenam belas pada Hananya, anak-anaknya dan saudara-saudarany dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 24, 'undian yang ketujuh belas pada Yosbekasa, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 25, 'undian yang kedelapan belas pada Hanani, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 26, 'undian yang kesembilan belas pada Maloti, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 27, 'undian yang kedua puluh pada Eliata, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 28, 'undian yang kedua puluh satu pada Hotir, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 29, 'undian yang kedua puluh dua pada Gidalti, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 30, 'undian yang kedua puluh tiga pada Mahaziot, anak-anaknya dan saudara-saudaranya, dua belas orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 25, 31, 'undian yang kedua puluh empat pada Romamti-Ezer, anak-anaknya dan saudara-saudaranya, dua belas orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 1, 'Tentang rombongan para penunggu pintu: dari orang Korah ialah Meselemya bin Kore dari keturunan Ebyasaf.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 2, 'Meselemya mempunyai anak-anak, yakni Zakharia, anak sulung, Yediael, anak yang kedua, Zebaja, anak yang ketiga, Yatniel, anak yang keempat,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 3, 'Elam, anak yang kelima, Yohanan, anak yang keenam, Elyoenai, anak yang ketujuh.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 4, 'Obed-Edom mempunyai anak-anak, yakni Semaya, anak sulung, Yozabad, anak yang kedua, Yoah, anak yang ketiga, Sakhar, anak yang keempat, Netaneel, anak yang kelima,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 5, 'Amiel, anak yang keenam, Isakhar, anak yang ketujuh dan Peuletai, anak yang kedelapan, sebab Allah telah memberkati dia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 6, 'Bagi Semaya, anak Obed-Edom itu, lahir anak-anak. Mereka memegang pemerintahan di antara puak mereka, sebab mereka itu adalah pahlawan-pahlawan yang gagah perkasa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 7, 'Anak-anak Semaya ialah Otni, Refael, Obed dan Elzabad serta saudara-saudaranya, yakni Elihu dan Semakhya, orang-orang gagah perkasa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 8, 'Mereka sekalian adalah dari keturunan Obed-Edom, yakni mereka sendiri, anak-anak mereka dan saudara-saudara mereka, masing-masing orang yang gagah perkasa, cakap untuk pekerjaan itu, enam puluh dua orang jumlahnya dari Obed-Edom.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 9, 'Dan Meselemya mempunyai delapan belas orang anak dan saudara, orang-orang yang gagah perkasa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 10, 'Hosa dari bani Merari mempunyai anak-anak, yakni Simri, seorang kepala?sebab sekalipun ia bukan anak sulung, tetapi ayahnya mengangkat dia menjadi kepala?', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 11, 'Hilkia, anak yang kedua, Tebalya, anak yang ketiga dan Zakharia, anak yang keempat. Semua anak dan saudara Hosa itu ada tiga belas orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 12, 'Rombongan-rombongan para penunggu pintu itu, yang dibagi menurut kepala kaum, mempunyai tugas melayani di rumah TUHAN, sama seperti saudara-saudara sesuku mereka.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 13, 'Untuk setiap pintu gerbang mereka membuang undi, menurut puak-puak mereka, baik puak yang kecil maupun puak yang besar.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 14, 'Undian untuk pintu timur jatuh pada Selemya; selanjutnya mereka membuang undi bagi Zakharia, anaknya, seorang penasihat yang berakal budi, lalu jatuhlah undiannya untuk pintu utara.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 15, 'Bagi Obed-Edom ialah pintu selatan dan bagi anak-anaknya gudang perlengkapan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 16, 'Bagi Supim dan Hosa ialah pintu barat beserta Pintu Gerbang Syalekhet di jalan raya tanjakan. Penjaga yang satu ditaruh berdampingan dengan penjaga yang lain.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 17, 'Di sebelah timur ada enam orang setiap hari, di sebelah utara ada empat orang setiap hari, di sebelah selatan ada empat orang setiap hari, tetapi pada gudang perlengkapan selalu ada dua orang;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 18, 'pada Parbar di sebelah barat: empat orang di jalan raya dan dua orang pada Parbar.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 19, 'Itulah rombongan-rombongan para penunggu pintu dari bani Korah dan dari bani Merari.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 20, 'Orang-orang Lewi, saudara-saudara sesuku mereka, yang mengawasi perbendaharaan rumah Allah dan yang mengawasi perbendaharaan barang-barang kudus;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 21, 'bani Ladan, yakni keturunan Gerson melalui Ladan, mempunyai orang-orang Yehiel sebagai kepala puak.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 22, 'Keturunan Yehiel, yakni Zetam dan Yoel, saudaranya, mengawasi perbendaharaan rumah TUHAN.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 23, 'Dari orang Amram, orang Yizhar, orang Hebron dan orang Uziel', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 24, 'adalah Sebuel bin Gersom bin Musa yang menjadi kepala perbendaharaan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 25, 'Sanak saudara Sebuel melalui Eliezer ialah Rehabya, anak Eliezer, dan Yesaya, anak Rehabya, dan Yoram, anak Yesaya, dan Zikhri, anak Yoram, dan Selomit, anak Zikhri.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 26, 'Selomit ini beserta sanak saudaranya mengawasi perbendaharaan barang-barang kudus yang telah dikuduskan oleh raja Daud dan oleh para kepala puak dan para pemimpin pasukan seribu dan pasukan seratus dan para panglima.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 27, 'Mereka telah menguduskannya dari rampasan perang untuk menyemarakkan rumah TUHAN.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 28, 'Juga segala yang dikuduskan oleh Samuel, pelihat itu, oleh Saul bin Kish, oleh Abner bin Ner dan oleh Yoab, anak Zeruya, ya segala barang yang dikuduskan ada di bawah pengawasan Selomit beserta sanak saudaranya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 29, 'Dari orang Yizhar adalah Kenanya beserta anak-anaknya yang diserahi tugas luar di Israel, yaitu menjadi pengatur dan hakim.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 30, 'Dari orang Hebron adalah Hasabya beserta sanak saudaranya, orang-orang gagah perkasa, seribu tujuh ratus orang jumlahnya, yang diserahi urusan pemerintahan Israel di sebelah barat sungai Yordan dalam segala urusan untuk TUHAN dan segala pekerjaan untuk raja.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 31, 'Dari orang Hebron adalah Yeria yang menjadi kepala. Tentang orang Hebron, mengenai keturunannya dan puaknya, dalam tahun keempat puluh zaman pemerintahan Daud diadakan penyelidikan tentang mereka dan ternyata, bahwa di antara mereka ada pahlawan-pahlawan yang gagah perkasa di Yaezer-Gilead.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 26, 32, 'Sanak saudara Yeria, orang-orang yang gagah perkasa, kepala-kepala puak ada dua ribu tujuh ratus orang. Mereka itu diangkat raja Daud mengawasi orang Ruben, orang Gad dan suku Manasye yang setengah itu dalam segala perkara untuk Allah dan segala perkara untuk raja.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 1, 'Adapun orang Israel, inilah daftar para kepala puak, para panglima pasukan seribu dan pasukan seratus dan para pengatur yang melayani raja dalam segala hal mengenai rombongan orang-orang yang bertugas dan libur, bulan demi bulan, sepanjang tahun. Setiap rombongan berjumlah dua puluh empat ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 2, 'Yang mengepalai rombongan pertama untuk bulan pertama ialah Yasobam bin Zabdiel dan dalam rombongannya ada dua puluh empat ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 3, 'Ia dari bani Peres dan mengepalai semua panglima untuk bulan yang pertama.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 4, 'Yang mengepalai rombongan bulan yang kedua ialah Dodai, orang Ahohi, sedang pemimpin rombongannya yang berjumlah dua puluh empat ribu orang, adalah Miklot.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 5, 'Panglima yang ketiga untuk bulan yang ketiga ialah Benaya, anak imam kepala Yoyada, dan dalam rombongannya ada dua puluh empat ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 6, 'Benaya ini adalah seorang dari ketiga puluh pahlawan dan mengepalai ketiga puluh orang itu, tetapi yang memegang pimpinan rombongannya ialah Amizabad, anaknya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 7, 'Yang keempat untuk bulan yang keempat ialah Asael, saudara Yoab, kemudian ia digantikan oleh Zebaja, anaknya, dan dalam rombongannya ada dua puluh empat ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 8, 'Yang kelima untuk bulan yang kelima ialah Samhut orang Yizrah, panglima itu, dan dalam rombongannya ada dua puluh empat ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 9, 'Yang keenam untuk bulan yang keenam ialah Ira anak Ikesh orang Tekoa dan dalam rombongannya ada dua puluh empat ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 10, 'Yang ketujuh untuk bulan yang ketujuh ialah Heles, orang Peloni, dari bani Efraim, dan dalam rombongannya ada dua puluh empat ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 11, 'Yang kedelapan untuk bulan yang kedelapan ialah Sibkhai, orang Husa dari orang Zerah itu, dan dalam rombongannya ada dua puluh empat ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 12, 'Yang kesembilan untuk bulan yang kesembilan ialah Abiezer, orang Anatot itu, dari bani Benyamin, dan dalam rombongannya ada dua puluh empat ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 13, 'Yang kesepuluh untuk bulan yang kesepuluh ialah Maharai, orang Netofa dari orang Zerah itu, dan dalam rombongannya ada dua puluh empat ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 14, 'Yang kesebelas untuk bulan yang kesebelas ialah Benaya, orang Piraton, dari bani Efraim, dan dalam rombongannya ada dua puluh empat ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 15, 'Yang kedua belas untuk bulan yang kedua belas ialah Heldai, orang Netofa itu, keturunan Otniel, dan dalam rombongannya ada dua puluh empat ribu orang.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 16, 'Yang mengepalai suku-suku Israel: untuk orang Ruben ialah Eliezer bin Zikhri sebagai pemimpin; untuk orang Simeon ialah Sefaca bin Maakha;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 17, 'untuk suku Lewi ialah Hasabya bin Kemuel; untuk keturunan Harun ialah Zadok;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 18, 'untuk suku Yehuda ialah Elihu, salah seorang saudara Daud; untuk suku Isakhar ialah Omri bin Mikhael;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 19, 'untuk suku Zebulon ialah Yismaya bin Obaja; untuk suku Naftali ialah Yerimot bin Azriel;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 20, 'untuk bani Efraim ialah Hosea bin Azazya; untuk setengah suku Manasye ialah Yoel bin Pedaya;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 21, 'untuk setengah suku Manasye yang di Gilead ialah Yido bin Zakharia; untuk suku Benyamin ialah Yaasiel bin Abner;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 22, 'untuk suku Dan ialah Azareel bin Yeroham. Itulah para kepala suku-suku Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 23, 'Daud tidak menghitung jumlah orang-orang yang berumur dua puluh tahun ke bawah, sebab TUHAN telah menjanjikan untuk membuat orang Israel sebanyak bintang-bintang di langit.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 24, 'Memang Yoab, anak Zeruya, telah mulai menghitung, tetapi ia tidak menyelesaikannya, sebab oleh karena hal itu orang Israel tertimpa murka; dengan demikian jumlah mereka tidak dibukukan dalam kitab sejarah raja Daud.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 25, 'Yang mengawasi persediaan raja ialah Azmawet bin Adiel dan yang mengawasi persediaan di luar kota, di kota-kota, di desa-desa dan di dalam menara-menara lumbung ialah Yonatan bin Uzia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 26, 'Yang mengawasi para pekerja di ladang yang harus mengusahakan tanah ialah Ezri bin Kelub.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 27, 'Yang mengawasi kebun-kebun anggur ialah Simei, orang Rama. Yang mengawasi hasil kebun anggur untuk persediaan anggur ialah Zabdi, orang Syifmi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 28, 'Yang mengawasi pohon-pohon zaitun dan pohon-pohon ara di Daerah Bukit ialah Baal-Hanan, orang Gederi; yang mengawasi persediaan minyak ialah Yoas.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 29, 'Yang mengawasi lembu sapi yang digembalakan di tanah Saron ialah Sitrai, orang Saron; yang mengawasi lembu sapi di lembah-lembah ialah Safat bin Adlai.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 30, 'Yang mengawasi unta-unta ialah Obil, orang Ismael; yang mengawasi keledai-keledai betina ialah Yehdeya, orang Meronot.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 31, 'Yang mengawasi kambing domba ialah Yazis, orang Hagri. Mereka ini sekalian ialah para pengawas harta milik raja Daud.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 32, 'Yonatan, saudara ayah Daud, adalah penasihat; dia seorang cerdas dan ahli kitab. Yehiel bin Hakhmoni membantu anak-anak raja.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 33, 'Ahitofel adalah penasihat raja; Husai, orang Arki, adalah sahabat raja.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 27, 34, 'Yang menggantikan Ahitofel kemudian ialah Yoyada bin Benaya dan Abyatar. Panglima raja ialah Yoab.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 1, 'Daud mengumpulkan di Yerusalem segala pembesar Israel, yakni para kepala suku, para pemimpin rombongan orang-orang yang melayani raja, para kepala pasukan seribu dan kepala pasukan seratus, serta para kepala harta benda dan ternak kepunyaan raja dan anak-anaknya; bersama-sama mereka juga para pegawai istana dan para perwira dan semua pahlawan yang gagah perkasa.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 2, 'Lalu berdirilah raja Daud dan berkata: "Dengarlah, hai saudara-saudaraku dan bangsaku! Aku bermaksud hendak mendirikan rumah perhentian untuk tabut perjanjian TUHAN dan untuk tumpuan kaki Allah kita; juga aku telah membuat persediaan untuk mendirikannya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 3, 'Tetapi Allah telah berfirman kepadaku: Engkau tidak akan mendirikan rumah bagi nama-Ku, sebab engkau ini seorang prajurit dan telah menumpahkan darah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 4, 'Namun TUHAN, Allah Israel, telah memilih aku dari antara segenap puakku untuk menjadi raja atas Israel selama-lamanya; sebab Ia telah memilih Yehuda menjadi pemimpin, dan puakku dari antara kaum Yehuda, dan dari antara anak-anak ayahku Ia berkenan kepadaku untuk mengangkat aku sebagai raja atas seluruh Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 5, 'Dan dari antara anak-anakku sekalian?sebab banyak anak telah dikaruniakan TUHAN kepadaku?Ia telah memilih anakku Salomo untuk duduk di atas takhta pemerintahan TUHAN atas Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 6, 'Ia telah berfirman kepadaku: Salomo, anakmu, dialah yang akan mendirikan rumah-Ku dan pelataran-Ku sebab Aku telah memilih dia menjadi anak-Ku dan Aku akan menjadi bapanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 7, 'Dan Aku akan mengokohkan kerajaannya sampai selama-lamanya, jika ia bertekun melakukan segala perintah dan peraturan-Ku seperti sekarang ini.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 8, 'Maka sekarang, di depan mata seluruh Israel, jemaah TUHAN, dan dengan didengar Allah kita, aku berkata kepadamu: Peliharalah dan tuntutlah segala perintah TUHAN, Allahmu, supaya kamu tetap menduduki negeri yang baik ini dan mewariskannya sampai selama-lamanya kepada anak-anakmu yang kemudian.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 9, 'Dan engkau, anakku Salomo, kenallah Allahnya ayahmu dan beribadahlah kepada-Nya dengan tulus ikhlas dan dengan rela hati, sebab TUHAN menyelidiki segala hati dan mengerti segala niat dan cita-cita. Jika engkau mencari Dia, maka Ia berkenan ditemui olehmu, tetapi jika engkau meninggalkan Dia maka Ia akan membuang engkau untuk selamanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 10, 'Camkanlah sekarang, sebab TUHAN telah memilih engkau untuk mendirikan sebuah rumah menjadi tempat kudus. Kuatkanlah hatimu dan lakukanlah itu."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 11, 'Lalu Daud menyerahkan kepada Salomo, anaknya, rencana bangunan dari balai Bait Suci dan ruangan-ruangannya, dari perbendaharaannya, kamar-kamar atas dan kamar-kamar dalamnya, serta dari ruangan untuk tutup pendamaian.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 12, 'Selanjutnya rencana dari segala yang dipikirkannya mengenai pelataran rumah TUHAN, dan bilik-bilik di sekelilingnya, mengenai perbendaharaan-perbendaharaan rumah Allah dan perbendaharaan-perbendaharaan barang-barang kudus;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 13, 'mengenai rombongan-rombongan para imam dan para orang Lewi dan mengenai segala pekerjaan untuk ibadah di rumah TUHAN dan segala perkakas untuk ibadah di rumah TUHAN.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 14, 'Juga ia memberikan emas seberat yang diperlukan untuk segala perkakas pada tiap-tiap ibadah; dan diberikannya perak seberat yang diperlukan untuk segala perkakas perak pada tiap-tiap ibadah,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 15, 'yakni sejumlah emas untuk kandil-kandil emas dan lampu-lampunya yang dari emas, seberat yang diperlukan tiap-tiap kandil dan lampu-lampunya, dan perak untuk kandil perak seberat yang diperlukan perak untuk satu kandil dan lampu-lampunya, sesuai dengan pemakaian tiap-tiap kandil dalam ibadah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 16, 'Kemudian diberikannya sejumlah emas untuk meja-meja roti sajian, meja demi meja, dan perak untuk meja-meja dari perak;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 17, 'selanjutnya emas murni untuk garpu-garpu, dan bokor-bokor penyiraman dan kendi-kendi, juga untuk piala-piala dari emas seberat yang diperlukan untuk tiap-tiap piala, dan perak untuk piala dari perak seberat yang diperlukan untuk tiap-tiap piala;', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 18, 'juga emas yang disucikan untuk mezbah pembakaran ukupan seberat yang diperlukan dan emas untuk pembentukan kereta yang menjadi tumpangan kedua kerub, yang mengembangkan sayapnya sambil menudungi tabut perjanjian TUHAN.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 19, 'Semuanya itu terdapat dalam tulisan yang diilhamkan kepadaku oleh TUHAN, yang berisi petunjuk tentang segala pelaksanaan rencana itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 20, 'Lalu berkatalah Daud kepada Salomo, anaknya: "Kuatkan dan teguhkanlah hatimu, dan lakukanlah itu; janganlah takut dan janganlah tawar hati, sebab TUHAN Allah, Allahku, menyertai engkau. Ia tidak akan membiarkan dan meninggalkan engkau sampai segala pekerjaan untuk ibadah di rumah Allah selesai.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 28, 21, 'Sesungguhnya, rombongan para imam dan para orang Lewi ada untuk melakukan segala ibadah di rumah Allah, dan ada beberapa sukarelawan yang ahli dalam setiap tugas yang dapat membantu engkau. Juga para pemimpin dan seluruh rakyat ini sepenuhnya ada di bawah perintahmu."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 1, 'Berkatalah raja Daud kepada segenap jemaah itu: "Salomo, anakku yang satu-satunya dipilih Allah adalah masih muda dan kurang berpengalaman, sedang pekerjaan ini besar, sebab bukanlah untuk manusia bait itu, melainkan untuk TUHAN Allah.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 2, 'Dengan segenap kemampuan aku telah mengadakan persediaan untuk rumah Allahku, yakni emas untuk barang-barang emas, perak untuk barang-barang perak, tembaga untuk barang-barang tembaga, besi untuk barang-barang besi, dan kayu untuk barang-barang kayu, batu permata syoham dan permata tatahan, batu hitam dan batu permata yang berwarna-warna, dan segala macam batu mahal-mahal dan sangat banyak pualam.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 3, 'Lagipula oleh karena cintaku kepada rumah Allahku, maka sebagai tambahan pada segala yang telah kusediakan bagi rumah kudus, aku dengan ini memberikan kepada rumah Allahku dari emas dan perak kepunyaanku sendiri', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 4, 'tiga ribu talenta emas dari emas Ofir dan tujuh ribu talenta perak murni untuk menyalut dinding ruangan,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 5, 'yakni emas untuk barang-barang emas dan perak untuk barang-barang perak dan untuk segala yang dikerjakan oleh tukang-tukang. Maka siapakah pada hari ini yang rela memberikan persembahan kepada TUHAN?"', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 6, 'Lalu para kepala puak dan para kepala suku Israel dan para kepala pasukan seribu dan pasukan seratus dan para pemimpin pekerjaan untuk raja menyatakan kerelaannya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 7, 'Mereka menyerahkan untuk ibadah di rumah Allah lima ribu talenta emas dan sepuluh ribu dirham, sepuluh ribu talenta perak dan delapan belas ribu talenta tembaga serta seratus ribu talenta besi.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 8, 'Siapa yang mempunyai batu permata menyerahkannya kepada Yehiel, orang Gerson itu, untuk perbendaharaan rumah TUHAN.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 9, 'Bangsa itu bersukacita karena kerelaan mereka masing-masing, sebab dengan tulus hati mereka memberikan persembahan sukarela kepada TUHAN; juga raja Daud sangat bersukacita.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 10, 'Lalu Daud memuji TUHAN di depan mata segenap jemaah itu. Berkatalah Daud: "Terpujilah Engkau, ya TUHAN, Allahnya bapa kami Israel, dari selama-lamanya sampai selama-lamanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 11, 'Ya TUHAN, punya-Mulah kebesaran dan kejayaan, kehormatan, kemasyhuran dan keagungan, ya, segala-galanya yang ada di langit dan di bumi! Ya TUHAN, punya-Mulah kerajaan dan Engkau yang tertinggi itu melebihi segala-galanya sebagai kepala.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 12, 'Sebab kekayaan dan kemuliaan berasal dari pada-Mu dan Engkaulah yang berkuasa atas segala-galanya; dalam tangan-Mulah kekuatan dan kejayaan; dalam tangan-Mulah kuasa membesarkan dan mengokohkan segala-galanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 13, 'Sekarang, ya Allah kami, kami bersyukur kepada-Mu dan memuji nama-Mu yang agung itu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 14, 'Sebab siapakah aku ini dan siapakah bangsaku, sehingga kami mampu memberikan persembahan sukarela seperti ini? Sebab dari pada-Mulah segala-galanya dan dari tangan-Mu sendirilah persembahan yang kami berikan kepada-Mu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 15, 'Sebab kami adalah orang asing di hadapan-Mu dan orang pendatang sama seperti semua nenek moyang kami; sebagai bayang-bayang hari-hari kami di atas bumi dan tidak ada harapan.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 16, 'Ya TUHAN, Allah kami, segala kelimpahan bahan-bahan yang kami sediakan ini untuk mendirikan bagi-Mu rumah bagi nama-Mu yang kudus adalah dari tangan-Mu sendiri dan punya-Mulah segala-galanya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 17, 'Aku tahu, ya Allahku, bahwa Engkau adalah penguji hati dan berkenan kepada keikhlasan, maka akupun mempersembahkan semuanya itu dengan sukarela dan tulus ikhlas. Dan sekarang, umat-Mu yang hadir di sini telah kulihat memberikan persembahan sukarela kepada-Mu dengan sukacita.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 18, 'Ya TUHAN, Allah Abraham, Ishak dan Israel, bapa-bapa kami, peliharalah untuk selama-lamanya kecenderungan hati umat-Mu yang demikian ini dan tetaplah tujukan hati mereka kepada-Mu.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 19, 'Dan kepada Salomo, anakku, berikanlah hati yang tulus sehingga ia berpegang pada segala perintah-Mu dan peringatan-Mu dan ketetapan-Mu, melakukan segala-galanya dan mendirikan bait yang persiapannya telah kulakukan."', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 20, 'Kemudian berkatalah Daud kepada segenap jemaah itu: "Pujilah kiranya TUHAN, Allahmu!" Maka segenap jemaah itu memuji TUHAN, Allah nenek moyang mereka, kemudian mereka berlutut dan sujud kepada TUHAN dan kepada raja.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 21, 'Keesokan harinya mereka mempersembahkan korban sembelihan dan korban bakaran kepada TUHAN, yakni seribu ekor lembu, seribu ekor domba jantan dan seribu ekor domba muda, dengan korban-korban curahannya dan sangat banyak korban sembelihan demi seluruh Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 22, 'Lalu mereka makan dan minum pada hari itu di hadapan TUHAN dengan sukacita yang besar, kemudian menyatakan untuk kedua kalinya Salomo, anak Daud, sebagai raja dan mengurapi dia bagi TUHAN sebagai raja dan Zadok sebagai imam.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 23, 'Kemudian duduklah Salomo sebagai raja menggantikan Daud, ayahnya, di atas takhta yang ditetapkan TUHAN; ia mendapat kemujuran, sehingga setiap orang Israel mendengarkan perkataannya.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 24, 'Lalu semua pemimpin dan pahlawan, juga semua anak raja Daud mengakui kekuasaan raja Salomo.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 25, 'TUHAN membuat Salomo luar biasa besar di mata seluruh orang Israel dan mengaruniakan kepadanya keagungan kerajaan seperti tidak pernah ada pada semua raja sebelum dia yang memerintah atas Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 26, 'Demikianlah Daud bin Isai telah memerintah atas seluruh Israel.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 27, 'Ia memerintah atas orang Israel selama empat puluh tahun; di Hebron ia memerintah tujuh tahun dan di Yerusalem ia memerintah tiga puluh tiga tahun.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 28, 'Kemudian matilah ia pada waktu telah putih rambutnya, lanjut umurnya, penuh kekayaan dan kemuliaan, kemudian naik rajalah Salomo, anaknya, menggantikan dia.', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 29, 'Sesungguhnya, riwayat raja Daud dari awal sampai akhir tertulis dalam riwayat Samuel, pelihat itu, dan dalam riwayat nabi Natan, dan dalam riwayat Gad, pelihat itu,', 'id', 'TB'),
  ('13', '1taw', '1 Tawarikh', 29, 30, 'beserta segala hidupnya sebagai raja dan kepahlawanannya dan keadaan zaman yang dialaminya dan dialami Israel dan segala kerajaan di negeri-negeri lain.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 1, 'Salomo, anak Daud, menjadi kuat dalam kedudukannya sebagai raja; TUHAN, Allahnya, menyertai dia dan menjadikan kekuasaannya luar biasa besarnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 2, 'Salomo memberi perintah kepada seluruh Israel, kepada kepala-kepala pasukan seribu dan pasukan seratus, kepada para hakim dan kepada semua pemimpin di seluruh Israel, yakni para kepala puak.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 3, 'Lalu pergilah Salomo bersama-sama dengan segenap jemaah itu ke bukit pengorbanan yang di Gibeon, sebab di situlah Kemah Pertemuan Allah yang dibuat Musa, hamba TUHAN itu, di padang gurun.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 4, '?Tetapi Daud telah mengangkut tabut Allah dari Kiryat-Yearim ke tempat yang disiapkannya bagi tabut itu, ?sebab ia telah memasang kemah untuk tabut itu di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 5, 'Namun mezbah tembaga yang dibuat Bezaleel bin Uri bin Hur masih ada di sana di depan Kemah Suci TUHAN. Maka ke sanalah Salomo dan jemaah itu meminta petunjuk TUHAN.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 6, 'Salomo mempersembahkan korban di sana di hadapan TUHAN di atas mezbah tembaga yang di depan Kemah Pertemuan itu; ia mempersembahkan seribu korban bakaran di atasnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 7, 'Pada malam itu juga Allah menampakkan diri kepada Salomo dan berfirman kepadanya: "Mintalah apa yang hendak Kuberikan kepadamu."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 8, 'Berkatalah Salomo kepada Allah: "Engkaulah yang telah menunjukkan kasih setia-Mu yang besar kepada Daud, ayahku, dan telah mengangkat aku menjadi raja menggantikan dia.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 9, 'Maka sekarang, ya TUHAN Allah, tunjukkanlah keteguhan janji-Mu kepada Daud, ayahku, sebab Engkaulah yang telah mengangkat aku menjadi raja atas suatu bangsa yang banyaknya seperti debu tanah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 10, 'Berilah sekarang kepadaku hikmat dan pengertian, supaya aku dapat keluar dan masuk sebagai pemimpin bangsa ini, sebab siapakah yang dapat menghakimi umat-Mu yang besar ini?"', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 11, 'Berfirmanlah Allah kepada Salomo: "Oleh karena itu yang kauingini dan engkau tidak meminta kekayaan, harta benda, kemuliaan atau nyawa pembencimu, dan juga tidak meminta umur panjang, tetapi sebaliknya engkau meminta kebijaksanaan dan pengertian untuk dapat menghakimi umat-Ku yang atasnya Aku telah merajakan engkau,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 12, 'maka kebijaksanaan dan pengertian itu diberikan kepadamu; selain itu Aku berikan kepadamu kekayaan, harta benda dan kemuliaan, sebagaimana belum pernah ada pada raja-raja sebelum engkau dan tidak akan ada pada raja-raja sesudah engkau."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 13, 'Lalu pulanglah Salomo dari bukit pengorbanan yang di Gibeon itu, dari depan Kemah Pertemuan, ke Yerusalem dan ia memerintah atas Israel.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 14, 'Salomo mengumpulkan juga kereta-kereta dan orang-orang berkuda, sehingga ia mempunyai seribu empat ratus kereta dan dua belas ribu orang berkuda, yang semuanya ditempatkan dalam kota-kota kereta dan dekat raja di Yerusalem.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 15, 'Raja membuat banyaknya emas dan perak di Yerusalem sama seperti batu, dan banyaknya pohon kayu aras sama seperti pohon ara yang tumbuh di Daerah Bukit.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 16, 'Kuda untuk Salomo didatangkan dari Misraim dan dari Kewe; saudagar-saudagar raja membelinya dari Kewe dengan harga pasar.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 1, 17, 'Sebuah kereta yang didatangkan dari Misraim berharga sampai enam ratus syikal perak, dan seekor kuda sampai seratus lima puluh syikal; dan begitu juga melalui mereka dikeluarkan semuanya itu kepada semua raja orang Het dan kepada raja-raja Aram.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 1, 'Salomo memerintahkan untuk mendirikan suatu rumah bagi nama TUHAN dan suatu istana kerajaan bagi dirinya sendiri.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 2, 'Dan Salomo mengerahkan tujuh puluh ribu kuli, delapan puluh ribu tukang pahat di pegunungan, dan tiga ribu enam ratus mandur untuk mengawasi mereka itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 3, 'Lalu Salomo mengutus orang kepada Huram, raja negeri Tirus, dengan pesan: "Perbuatlah terhadap aku seperti yang kauperbuat terhadap ayahku Daud, ketika engkau mengirim kayu aras kepadanya, sehingga ia dapat mendirikan baginya suatu istana untuk tinggal di situ.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 4, 'Ketahuilah, aku hendak mendirikan sebuah rumah bagi nama TUHAN, Allahku, untuk menguduskannya bagi Dia, supaya di hadapan-Nya dibakar ukupan dari wangi-wangian, tetap diatur roti sajian dan dipersembahkan korban bakaran pada waktu pagi dan pada waktu petang, pada hari-hari Sabat dan bulan-bulan baru, dan pada perayaan-perayaan yang ditetapkan TUHAN, Allah kami, sebab semuanya itu adalah kewajiban orang Israel untuk selama-lamanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 5, 'Dan rumah yang hendak kudirikan itu harus besar, sebab Allah kami lebih besar dari segala allah.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 6, 'Tetapi siapa yang mampu mendirikan suatu rumah bagi Dia, sedangkan langit, bahkan langit yang mengatasi segala langitpun tidak dapat memuat Dia? Dan siapakah aku ini, sehingga aku hendak mendirikan suatu rumah bagi Dia, kecuali sebagai tempat untuk membakar korban di hadapan-Nya?', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 7, 'Maka sekarang, kirimlah kepadaku seorang yang ahli mengerjakan emas, perak, tembaga, besi, kain ungu muda, kain kirmizi, kain ungu tua, dan yang juga pandai membuat ukiran, untuk membantu para ahli yang ada padaku di Yehuda dan di Yerusalem, yang telah ditunjuk ayahku Daud.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 8, 'Kirim juga kepadaku kayu aras, sanobar dan cendana dari gunung Libanon, sebab aku tahu, bahwa hamba-hambamu pandai menebang pohon dari Libanon. Dalam pada itu hamba-hambaku akan membantu hamba-hambamu', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 9, 'untuk menyediakan bagiku sejumlah besar kayu, sebab rumah yang hendak kudirikan itu harus besar dan mentakjubkan.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 10, 'Dan untuk tukang-tukang yang menebang pohon kuberikan gandum dua puluh ribu kor, jelai dua puluh ribu kor, anggur dua puluh ribu bat dan minyak dua puluh ribu bat, sebagai bahan makanan bagi hamba-hambamu itu."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 11, 'Dan Huram, raja negeri Tirus, mengirim surat balasan kepada Salomo, yang berbunyi: "Karena TUHAN mengasihi umat-Nya, Ia telah mengangkat engkau menjadi raja atas mereka."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 12, 'Lalu Huram melanjutkan: "Terpujilah TUHAN, Allah orang Israel, yang menjadikan langit dan bumi, karena Ia telah memberikan kepada raja Daud seorang anak yang bijaksana, penuh akal budi dan pengertian, yang akan mendirikan suatu rumah bagi TUHAN dan suatu istana kerajaan bagi dirinya sendiri!', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 13, 'Maka sekarang aku mengirim seorang ahli, yang penuh pengertian, yakni Huram Abi,', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 14, 'anak seorang perempuan dari bani Dan, sedang ayahnya orang Tirus. Ia pandai mengerjakan emas, perak, tembaga, besi, batu, kayu, kain ungu muda, kain ungu tua, lenan halus dan kain kirmizi, dan juga pandai membuat segala jenis ukiran dan segala jenis rancangan yang ditugaskan kepadanya dengan dibantu oleh ahli-ahlimu dan oleh ahli-ahli ayahmu, tuanku Daud.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 15, 'Baiklah sekarang tuanku kirim kepada hamba-hamba tuanku gandum dan jelai, minyak dan anggur yang telah tuanku sebutkan itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 16, 'Dan kami akan menebang kayu dari gunung Libanon sebanyak engkau perlukan dan membawanya kepadamu dengan rakit-rakit melalui laut sampai ke Yafo, dan engkau dapat mengangkutnya ke Yerusalem."', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 17, 'Lalu Salomo menghitung semua orang asing yang laki-laki yang ada di negeri Israel sama seperti yang pernah dilakukan Daud, ayahnya. Maka terdapatlah seratus lima puluh tiga ribu enam ratus orang.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 2, 18, 'Dan dari antara mereka, tujuh puluh ribu orang dijadikannya kuli, delapan puluh ribu orang tukang pahat di pegunungan, dan tiga ribu enam ratus orang mandur yang harus menyuruh orang-orang itu bekerja.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 1, 'Salomo mulai mendirikan rumah TUHAN di Yerusalem di gunung Moria, di mana TUHAN menampakkan diri kepada Daud, ayahnya, di tempat yang ditetapkan Daud, yakni di tempat pengirikan Ornan, orang Yebus itu.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 2, 'Ia mulai mendirikan rumah itu dalam bulan yang kedua, pada tahun keempat pemerintahannya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 3, 'Inilah ukuran dasar yang dipakai Salomo untuk mendirikan rumah Allah: panjangnya enam puluh hasta, menurut ukuran hasta yang lama dan lebarnya dua puluh hasta.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 4, 'Balai di sebelah depan ruang besar rumah itu, panjangnya dua puluh hasta, menurut lebar rumah itu, dan tingginya seratus dua puluh hasta. Balai itu dilapisinya dari dalam dengan emas murni.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 5, 'Ruang besar dipapaninya dengan kayu sanobar. Kayu itu disaputnya dengan emas tua; kemudian dipasangnya pohon korma dan untaian rantai di atasnya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 6, 'Ruang itu dilapisinya juga dengan batu permata yang mahal-mahal sebagai perhiasan, sedang emasnya emas Parwaim.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 7, 'Demikianlah ruang itu, balok-baloknya, ambang-ambangnya, dinding-dindingnya dan pintu-pintunya disaputnya dengan emas dan pada dinding-dindingnya diukirkannya kerub.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 8, 'Kemudian ia membuat ruang maha kudus; panjangnya dua puluh hasta, menurut lebar rumah itu, dan lebarnya dua puluh hasta juga. Lalu ia menyaputnya dengan emas tua seberat enam ratus talenta;', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 9, 'berat paku-paku lima puluh syikal emas. Juga kamar-kamar atas disaputnya dengan emas.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 10, 'Ia membuat dua kerub berupa pahatan di ruang maha kudus dan melapisinya dengan emas.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 11, 'Sayap kerub-kerub itu seluruhnya dua puluh hasta panjangnya; sayap yang sebelah kerub yang satu lima hasta panjangnya dan menyentuh dinding ruang, sedang sayapnya yang sebelah lagi juga lima hasta panjangnya dan menyentuh sayap kerub yang lain.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 12, 'Begitu pula sayap kerub yang lain itu lima hasta panjangnya dan menyentuh dinding ruang, sedang sayapnya yang sebelah lagi juga lima hasta panjangnya dan bersentuhan dengan sayap kerub yang pertama.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 13, 'Jadi sayap kedua kerub itu membentang sepanjang dua puluh hasta, sedang kedua kerub itu berdiri di atas kakinya dan menghadap ruang besar.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 14, 'Kemudian ia membuat tabirnya dari kain ungu tua, kain ungu muda, kain kirmizi dan lenan halus, dan menggambarkan kerubim padanya.', 'id', 'TB'),
  ('14', '2taw', '2 Tawarikh', 3, 15, 'Di depan rumah itu dibuatnya dua tiang, yang tingginya tiga puluh lima hasta, dengan ganja di kepalanya masing-masing setinggi lima hasta.', 'id', 'TB')
